\subsection{Lazy addition in finite precision arithmetic}

A floating-point number $\xi$ represented with a precision$^\ast$ $p$ in base 2 is written
\footnote{$^\ast$ In the MPFR library, \eqref{equ:prec} is said to have precision $p+1$.}
\begin{equation} 
\label{equ:prec}
\xi = \pm 2^{n} \times 0.1\xi_1\xi_2 \ldots \xi_p  
\end{equation}
where the \textit{bits} $\xi_i \in \{0,1\}$ for $i \in \ii{1}{p} \defequal  [1, p] \cap \Z$.
The number $n\in \Z \cup \{-\infty\}$ is called the \textit{exponent} of~$\xi$.
By convention, $n=-\infty$ when $\xi=0$.
The smallest representable increment of $|\xi|$ is
\begin{equation}
\ulp(\xi) \defequal  2^{n} \times 0.00 \ldots 01 = 2^{n-p-1} \,.
\end{equation}
The name stands for \textit{unit in the last place}.
To ensure a unique representation of all real numbers we always assume a rounding to the
nearest representable number and choose a rounding away from zero at the tie.

\medskip
A key observation for additions in finite precision $p$ is that
\begin{equation}\label{equ:sum}
\xi+\eta = 
\begin{cases}
\xi & \text{if } n > m + p + 2,\\
\eta & \text{if } m > n + p + 2,
\end{cases}
\end{equation}
where $n$ and $m$ are the respective exponents of $\xi$ and $\eta$.
This means that by simply reading the values of $n$ and $m$ and comparing them to $p$,
we can avoid costly operations, especially if computing one of the terms $\xi$ or $\eta$ 
requires additional steps as is the case when they are monomials $a_k z^k$.

\subsection{Scale of a complex number}\label{par:scale}

Let us define the \textit{scale} of a number $z \in \C^*$ by
\begin{equation}
\label{equ:dsz}
s(z) \defequal  1+ \lfloor \log_2 |z| \rfloor \in\Z \,,
\end{equation}
where $\lfloor \alpha \rfloor$ is the floor of $\alpha$.
By convention,~$s(0) \defequal  -\infty$.
The scale is a logarithmic representation of the order of magnitude of $z$.
For example, with the notations of~\eqref{equ:prec}, one has $s(\xi) = n$, \ie 
for floating-point numbers, the scale coincides with the exponent;
moreover
\begin{equation}\label{def:ulp}
\ulp(\xi)=2^{s(\xi)-p-1} \,.
\end{equation}
In general, $s(z)=\sigma$ if and only if $\sigma\in\Z$ and
\begin{equation}\label{eq:sigma}
2^{\sigma-1}\leq |z|<2^\sigma \,.
\end{equation} 
In particular, for $z=x+iy\in\C^\ast$, one has $\frac{1}{2}\leq |z|2^{-\max(s(x),s(y))} < \sqrt{2}<2$,
thus
\begin{equation}\label{equ:sz}
s(z) \in \max\{s(\Re z),s(\Im z)\} +\{0,1\} \,.
\end{equation}
For example $s(3+2i)=2=s(3)$ and $s(3+3i)=3=s(3)+1$.

\bigskip
As $\lfloor\alpha+\beta\rfloor\in\lfloor\alpha\rfloor+\lfloor\beta\rfloor+\{0,1\}$ and $1+\lfloor\alpha\rfloor-\alpha\in(0,1]$,
we claim the following bounds.
\begin{lemma}
For any  $z, z' \in \C$ and $n\in\Z$, one has~:
\begin{eqnarray}
s(2^n z) & = & n+s(z) \label{eq:exact2pow}\\
\label{equ:sp}
s(zz') - s(z) - s(z') & \in & \{-1, 0\}, \\
\label{equ:sn}
s(z^n) - n\log_2|z|  & \in & (0,1], \\
\label{equ:ss}
s(z \pm z') & \leq &\max\{s(z),s(z')\} + 1
\end{eqnarray}
and, for a family $z_1,\ldots,z_N\in\C$~:
\begin{equation}\label{equ:bs}
s\left(\sum_{j=1}^N z_j \right) \leq \max_{1\leq j\leq N} s(z_j) + s(N) \,.
\end{equation}
\end{lemma}
\noindent%
Due to the cancelation of significant bits, the scale of a sum may be much smaller (even~$-\infty$) than
the largest scale of the terms involved. 

\proof
The identity~\eqref{eq:exact2pow} is immediate.
For $s(z)=\sigma$, $s(z')=\sigma'$, one has $2^{\sigma+\sigma'-2}\leq |zz'|<2^{\sigma+\sigma'}$
and~\eqref{equ:sp} follows from~\eqref{eq:sigma}.
The estimate~\eqref{equ:sn} follows from $|z^n| = 2^{n\log_2|z|}$ \ie
$s(z^n) = 1+\lfloor n\log_2|z|\rfloor$.
For sums, we write $|z\pm z'|\leq 2\max\{|z|,|z'|\}<2^{1+\max\{s(z),s(z')\}}$ hence~\eqref{equ:ss}.
For $N$ terms, \eqref{equ:bs} follows from:
\[
\left|\sum z_j\right|\leq N \max |z_j| < 2^{\max s(z_j) + \log_2 N} < 2^{\max s(z_j) + \lfloor\log_2 N\rfloor+1} \,.
\]
For the last inequality, note that we could use the ceiling function $\lceil \log_2 N\rceil$ instead of~$s(N)$ for a slightly tighter estimate
when $N$ is a power of 2.
\qed


\subsection{Equivalence and adjacency modulo finite precision}\label{par:equivModP}

The topology induced by finite precision arithmetic is surprisingly subtle.
In this subsection, we introduce three distinct binary relations that express the \emph{proximity}
between a floating-point number and a real or complex number. The complex case is even more subtle
and is dealt with last.

\begin{definition}
For $x,y \in \R$ we use the notation $x =_p y$ to say that $x$ and $y$ have the same representation
as floating-point numbers with precision $p \in \N^*$. 
\end{definition}

\begin{figure}[H]
\begin{center}
\setlength{\unitlength}{1cm}
\includegraphics[width=12cm]{ulp1.png}
\begin{picture}(0, 0)(12.1,0)
	\put(4.1,1.1){\footnotesize $a$}
	\put(4.76,1.1){\footnotesize $b$}
	\put(5.9,1.1){\footnotesize $c$}
	\put(12.25,0.84){\footnotesize $=_p$}
	\put(12.25,0.39){\footnotesize $=_{p-1}$}
\end{picture}
\captionsetup{width=.9\linewidth}
\caption{\label{fig:ulp}%
On the first line, three examples of equivalence classes for~$=_p$ are grayed out.
On the second line, examples of classes for~$=_{p-1}$ illustrate how the grid gets thinned out when
one bit of precision is dropped. Note in particular how the equivalence class of odd numbers (left) gets split.
}\end{center}
\end{figure}

\noindent
It is an equivalence relation; the equivalence class of
a floating-point number $\xi>0$ is
\begin{equation}\label{eq:class_modp}
\{y\in\R \,;\, y=_p \xi\} = \left[ \xi-\frac{1}{2}\ulp(\xi-\ulp(\xi)); \xi+\frac{1}{2}\ulp(\xi) \right).
\end{equation}
In general, the equivalence class~\eqref{eq:class_modp} of a floating-point $\xi>0$ is the interval
\[\textstyle
\left[\xi-\frac{1}{2}\ulp(\xi), \xi+\frac{1}{2}\ulp(\xi) \right).
\]
An exception occurs at scale turnover where the class is asymmetric. For example,
the consecutive numbers $a=2^n(1-2^{-p-1})=2^n\times 0.111\ldots11$,
$b=2^n=2^{n+1}\times 0.100\ldots00$ and $c=2^n(1+2^{-p})=2^{n+1}\times 0.100\ldots01$ satisfy
$\ulp(b)=c-b$ and $\ulp(a)=b-a=\frac{1}{2}\ulp(b)$
thus the equivalence class of $b$ is $[b-\frac{1}{4}\ulp(b),b+\frac{1}{2}\ulp(b))$.
Note that $b-\ulp(b)=2^n(1-2^{-p})$ and $\ulp(b-\ulp(b))=\ulp(a)$.
See Figure~\ref{fig:ulp}.
When $\xi<0$, the usual convention \textit{rounding away from zero at the tie}
implies that the interval~\eqref{eq:class_modp}  is flipped over and the $\pm$ signs must be reversed.

\bigskip
We say that equivalence classes for $=_p$ are \textit{adjacent} if their respective
closures in~$\R$ have a non-empty intersection. The corresponding floating-point numbers
are called adjacent too.
\begin{definition}
For $x,y \in \R$, we denote by $x \simeq_p y$ if the floating-point representations of~$x$ and~$y$ with $p$~bits
are identical or adjacent.
\end{definition}
\noindent
Though not transitive because of the obvious overlap between the sets of real numbers that are adjacent
to consecutive floating-point numbers, this relation is symmetric and simplifies the handling of scale turnover.
For example, one can always find real points that are arbitrarily close to one another
but whose floating-point representations are distinct; these points are however adjacent. See Figure~\ref{fig:ulp2}.

