\begin{proof}
As $f$ is a concave function, it is continuous, it is differentiable almost everywhere, and its derivative is decreasing.
Even when the derivative is not continuous at a point, it necessarily has left and right limits.
Therefore it has at most a countable number of jump points.

Let us first construct the segment $[A(\tau)B(\tau)]$.
For any $\tau\in\R$, the concave function~$f(x)-\tau x$ presents a maximum $m_\tau$ in~$[0,1]$,
which is reached on some non-empty compact sub-interval $J_\tau\subset [0,1]$ (usually a singleton).
The function $f(x)-\tau x$ is monotone on each of the connected components of  $[0,1]\backslash J_\tau$.
As a consequence, the set
\[
I(\tau,\delta)=\{x\in[0,1] \,;\, f(x)-\tau x \geq m_\tau-\delta\}
\]
is an interval increasing in $\delta$ that contains $J_\tau=I(\tau,0)$.
Let us define
\begin{equation}\label{eq:defxLxR}
\begin{gathered}
x_L(\tau) \defequal  \inf I(\tau,\delta)\,,
\qquad
x_R(\tau) \defequal  \sup I(\tau,\delta)\,.
\end{gathered}
\end{equation}
For any $x_0 \in J_\tau$, one has $m_\tau=f(x_0)-\tau x_0$ and the line of equation~$y=y_\tau(x)$ with
\[
y_\tau(x) \defequal  f(x_0) -\delta  +  \tau(x-x_0)  = \tau x + (m_\tau -\delta)
\]
does not depend on the actual choice of $x_0$ within $J_\tau$.
Let us define
\begin{equation}\label{defAB}
A(\tau) = (x_L(\tau), y_\tau(x_L(\tau)))\,, \qquad B(\tau) = (x_R(\tau), y_\tau(x_R(\tau)))\,.
\end{equation}
By definition~\eqref{eq:defxLxR}, for all $x\in[x_L(\tau), x_R(\tau)]=I(\tau,\delta)$,
one has $f(x) +\delta \geq m_\tau + \tau x \geq f(x)$,
thus the segment~$[A(\tau)B(\tau)]$ is of slope $\tau$ and is included in $S(f,\delta)$. 

\bigskip
Conversely, any segment~$[AB]$ of slope~$\tau$ included in $S(f,\delta)$ is supported
by a line of equation $y=\tau x+\beta$ and must satisfy (denoting by $x_A$, $x_B$ the abscissa of $A$ and $B$)
\begin{equation}\label{eq:constrain}
\forall x\in [x_A,x_B], \qquad
f(x) \geq \tau x+ \beta \geq f(x)-\delta \quad\ie\quad \beta+\delta \geq f(x)-\tau x\geq \beta\,.
\end{equation}
Let us show that $x_B-x_A \leq x_R(\tau)-x_L(\tau)$. 

\smallskip
If $\beta\geq m_\tau-\delta$ (\ie $[AB]$ is above $[A(\tau)B(\tau)]$) then
$f(x_A)-\tau x_A \geq \beta \geq m_\tau-\delta$;
the monotony of $f(x)-\tau x$ outside~$J_\tau$ and the definition of $x_L(\tau)$
imply $x_L(\tau)\leq x_A$.
Similarly, one has $x_B\leq x_R(\tau)$.
In other words, one has
\[
[x_A,x_B] \subset [x_L(\tau), x_R(\tau)]\,.
\]
If $\beta<m_\tau-\delta$, the constraint~\eqref{eq:constrain}
cannot be satisfied for $x\in J_\tau$ because
\[
\forall x\in J_\tau, \quad f(x)-\tau x = m_\tau > \beta+\delta\,,
\]
thus $[x_A,x_B]$ is a subset of~$[0,1]\backslash J_\tau$.
The concavity of $f(x)-\tau x$ implies that one can increase $x_B-x_A$ by shifting the interval towards $J_\tau$.
More precisely, let us assume for example that $[x_A,x_B]$ is on the right side of $J_\tau$ and that
$x_R(\tau)<1$ (otherwise nothing needs to be proved).
The inclusion $[AB]\subset S(f,\delta)$ implies
\begin{equation}\label{tech01}
f(x_A)-\tau x_A-\delta \leq \beta \leq f(x_B)-\tau x_B\,.
\end{equation}
The function $\tau-f'$ is defined almost everywhere and is positive and increasing
on the right-hand side of $J_\tau$. The inequality~\eqref{tech01} can thus be rephrased
\[
\int_{x_A}^{x_B} \tau-f'(x) dx \leq  \delta\,.
\]
Similarly, for any $x_0\in J_\tau$, one has $ f(x_0) -\tau x_0=m_\tau$ and  $x_R(\tau)<1$ 
implies :
\[
\int_{x_0}^{x_R(\tau)} \tau-f'(x) dx = m_\tau - \left(f(x_R) - \tau x_R(\tau)\right)= \delta\,.
\]
If $x_A \geq x_R(\tau)$ then the smaller integrand on $[x_0,x_R(\tau)]$ implies $x_R(\tau)-x_0\geq x_B-x_A$.
If~$x_A< x_R(\tau)$, the integrals on $[x_A,x_R(\tau)]$ cancel out, therefore
\[
 \int_{x_R(\tau)}^{x_B}  \tau-f'(x) dx \leq \int_{x_0}^{x_A}  \tau-f'(x) dx
\]
and thus $x_A-x_0\geq x_B-x_R(\tau)$. In both cases, $x_R(\tau)-x_L(\tau) \geq x_R(\tau)-x_0 \geq x_B-x_A$.

This proves that the maximal length is obtained for $\beta=m_\tau-\delta$.
As the values of the projection of $A,B$ on the $x$-axis are unique, the equations~\eqref{eq:defxLxR}-\eqref{defAB} ensure
that the segment~$[A(\tau)B(\tau)]$ is unique.
\end{proof}


The quantity that interests us for Theorem \ref{thm:conc} is obviously related to this first geometric construction.
\begin{lemma} 
\label{lemma:conc-change-of-var} With the notations of Theorem \ref{thm:conc}, we have
\begin{equation}
\int_{ - \frac \pi 2}^{\frac \pi 2} L(f, \delta, \theta ) \cos \theta  \, d\theta  =
\int_{-\infty}^{+\infty} \frac{x_R(y) - x_L(y)}{1+y^2} \, dy\,.
\end{equation}
We also have
\begin{equation}
\int_{ - \frac \pi 2}^{\frac \pi 2} L(f, \delta, \theta ) \cos^2 \theta  \, d\theta  =
\int_{-\infty}^{+\infty} \frac{x_R(y) - x_L(y)}{(1+y^2)^{3/2}} \, dy
\end{equation}
and for any positive measurable weight $\omega$ on $\left[-\frac{\pi}{2},\frac{\pi}{2}\right]$ :
\begin{equation}
\int_{ - \frac \pi 2}^{\frac \pi 2} L(f, \delta, \theta ) \, \omega(\theta)  \, d\theta  =
\int_{-\infty}^{+\infty} \frac{x_R(y) - x_L(y)}{\sqrt{1+y^2}} \:  \omega(\arctan y)\, dy\,.
\end{equation}
\end{lemma}
\begin{proof}
The definition~\eqref{defAB} ensures that the length of the projection on the $x$-axis
of the segment $[A(\tau)B(\tau)]$ is $L(f, \delta, \theta ) \cos \theta  = x_R(\tan \theta) - x_L(\tan \theta )$.
The identities are then obtained by the change of variable~$y=\tan \theta .$
\end{proof}

\subsection{A second geometric construction based on the graph of $f'$}
We are now going to provide a second geometric construction of $x_L(\tau)$, $x_R(\tau)$.
We consider the graph of $f'$ and we complete it to a continuous curve in the following way.
At a jump point we add the vertical segment that joins the left and the right limits.
If~$f'(0^+)<\infty$ then we add the half-line $\{0\}\times [f'(0^+), \infty)$.
Similarly, if~$f'(1^-)>-\infty,$ we add the half-line~$\{1\}\times (-\infty, f'(1^-)]$.
We thus obtain a continuous curve, which we denote by $\gamma_{f'}$,
that contains the graph of $f'$, whose projection on the $x$-axis contains $]0,1[$ and is included in $[0,1]$
and whose projection on the $y$-axis is $\R$.

\medskip
Let us introduce
\[
\Gamma_{f'}^\pm \defequal  \left\{ (x,y)\in [0,1]\times\R \,;\, \exists y' \text{ such that } \pm(y-y')\geq0 \text{ and } (x,y')\in\gamma_{f'}\right\}\,.
\]
The sets $\Gamma_{f'}^\pm$ are the closed subsets of the strip $[0,1]\times\R$ that are respectively above and below $\gamma_{f'}$.
For every $y_0\in \R$ we consider
\[
x_0^- \defequal  \min \left\{x\in [0,1] \,;\, (x,y_0)\in \gamma_{f'} \right\}
\quad\text{and}\quad
x_0^+ \defequal  \max \left\{x\in [0,1] \,;\, (x,y_0)\in \gamma_{f'} \right\}\,.
\]
The segment $\{(x,y_0) \,;\, x_0^- \leq x \leq x_0^+\}$ is the intersection between $\gamma_{f'}$
and the horizontal line $y=y_0$ ; it reduces to a point when $x_0^+=x_0^-$.
We now build a family of ``triangles'' whose hypotenuse rests on $\gamma_{f'}$ and that
collapse on the segment $[x_0^-,x_0^+]\times\{y_0\}$ (see Figure~\ref{fig:gamma-f'}). For $x\in[0,1]$, let
\[
T_{f'}(y_0;x) \defequal  \begin{cases}
\Gamma_{f'}^- \cap \left\{(x',y) \,;\, x\leq x'\leq x_0^- \text{ and } y\geq y_0 \right\} & \text{if }x<x_0^-,\\
\{x,y_0\} & \text{if }x\in [x_0^-,x_0^+],\\
\Gamma_{f'}^+ \cap \left\{(x',y) \,;\, x_0^+\leq x'\leq x \text{ and } y\leq y_0 \right\} & \text{if }x>x_0^+.
\end{cases}
\]
The continuity of $\gamma_{f'}$ implies that the area $|T_{f'}(y_0; x)|$ of this triangle
is a continuous function of $x$ and the monotonicity of $f'$ implies that the area vanishes
along $[x_0^-,x_0^+]$  and is respectively strictly decreasing on $[0,x_0^-]$ and strictly increasing on $[x_0^+,1]$.


\medskip
We are interested in the two points where either
the area of the triangle equals $\delta$ or the triangle hits
the edge of the strip:
\begin{align*}
\widetilde{x_L}(y_0) &\defequal  \inf\left\{ x\in [0,x_0^-] \,;\, |T_{f'}(y_0; x)| \leq \delta\right\}\,,\\[1pt]
\widetilde{x_R}(y_0) &\defequal  \sup\left\{ x\in [x_0^+,1] \,;\, |T_{f'}(y_0; x)| \leq \delta\right\}\,.
\end{align*}
Let us prove that $\widetilde{x_L}(y_0) = x_L(y_0)$ and $\widetilde{x_R}(y_0) = x_R(y_0)$, \ie they are the same values
as the ones defined by \eqref{eq:defxLxR}. Using elementary calculus, we know that the area of the triangle is
\[
|T_{f'}(y_0;x)| =
\begin{cases}
\displaystyle\int_{x}^{x_0^-} \left( f'(x) - y_0\right) dx = -(x_0^--x) y_0 +f(x_0^-) - f(x) & \text{if } x<x_0^-,\\[1.5ex]
\displaystyle\int_{x_0^+}^{x} \left( y_0-f'(x) \right) dx = (x-x_0^+) y_0 +f(x_0^+) - f(x)& \text{if } x>x_0^+.
\end{cases}
\]
The conditions defining $\widetilde{x_L}(y_0)$ and $\widetilde{x_R}(y_0)$ thus boil down to
\[
x\in [\widetilde{x_L}(y_0), \widetilde{x_R}(y_0)] 
\quad\Longleftrightarrow\quad
f(x) -  y_0 x \geq f(x_0^\pm) -y_0 x_0^\pm   - \delta \,.
\]
Note that, by definition, $f(x)- y_0x$ is constant on $[x_0^-,x_0^+]$ and one recovers~\eqref{eq:defxLxR}
with $\tau =y_0$, $m_\tau= f(x_0^\pm) -y_0 x_0^\pm$ and $[x_0^-,x_0^+]=J_\tau$ from the proof
of Lemma~\ref{lemma:segment-tangent}.

\bigskip
