The curve $\gamma_{f'}$ can only enter the square on its left or upper side and
can only leave the square on its right or bottom side,
as seen in Figure~\ref{fig:sqDiag} (right). 
In all 4 cases, one has
\begin{align*}
Q(y',y)\cap \Gamma_{f'}^-  &\subset T_{f'}(y'; x_L(y')) \,,\\
Q(y',y)\cap \Gamma_{f'}^+ &\subset T_{f'}(y;x_R(y)) \,,
\end{align*}
thus $Q(y',y)\subset T_{f'}(y'; x_L(y')) \cup T_{f'}(y;x_R(y))$.
As this is a measurably disjoint union of 2~triangles of area at most $\delta$ (the area of $\gamma_{f'}$ is zero),
the area of the square $Q(y',y)$ is smaller than 
or equal to $2\delta$ and consequently its diagonal is smaller than or equal to~$2\sqrt{\delta}$. 
\end{proof}


From this point on, the idea is to use Fubini's theorem to slice the strip
between the curves $\gamma_L$ and $\gamma_R$ along the first diagonal.
In this direction, according to Lemma~\ref{lemma:est-diagonal}, the girth does not exceed $2\sqrt{\delta}$
and the decay of the integrands will ensure the integrability.
We prepare this computation by a suitable change of variable.

\begin{lemma}\label{lemma:cgt-var45}
Let us denote by $\Omega$ the strip between the curves $\gamma_L$ and $\gamma_R$.  One has
\begin{equation}\label{eq:cgt-var45-Omega} 
\int_{ - \frac \pi 2}^{\frac \pi 2} L(f, \delta, \theta ) \cos \theta  \, d\theta   =
\iint_{\Omega} \frac{dxdy}{1+y^2} =
\iint_{\Omega'} \frac{dx_1dx_2}{1+\frac{1}{2}(x_1-x_2)^2} \,,
\end{equation}
\begin{equation}\label{eq:cgt-var45-Omega-bis} 
\int_{ - \frac \pi 2}^{\frac \pi 2} L(f, \delta, \theta ) \cos^2 \theta  \, d\theta   =
\iint_{\Omega} \frac{dxdy}{(1+y^2)^{3/2}} =
\iint_{\Omega'} \frac{dx_1dx_2}{\left(1+\frac{1}{2}(x_1-x_2)^2\right)^{3/2}} \,,
\end{equation}
where $\Omega'=R_{\pi/4} \left(\Omega\right)$ is the image of $\Omega$ by the 
rotation of angle $\pi/4$ that maps $(1/2,0)$ to the origin. 
More generally, for any positive weight $\omega \in L^1_{\text{loc}}\left(-\frac{\pi}{2},\frac{\pi}{2}\right)$
such that $\omega\left(\pm(\frac{\pi}{2}-t)\right)\leq C \left|\ln t\right|^{-\beta}$ with $\beta>1$ as $t\to0^+$, one has
\begin{equation}\label{eq:cgt-var45-Omega-ter}
\int_{ - \frac \pi 2}^{\frac \pi 2} L(f, \delta, \theta ) \, \omega(\theta)  \, d\theta 
=\iint_{\Omega} \frac{\omega(\arctan y)}{\sqrt{1+y^2}}  \, dxdy
=\iint_{\Omega'} \frac{\omega\left(\arctan \frac{x_2-x_1}{\sqrt{2}}\right)}{\sqrt{1+\frac{1}{2}(x_1-x_2)^2}}  \, dx_1dx_2 \,.
\end{equation}
\end{lemma}


\begin{proof} 
In view of Lemma \ref{lemma:conc-change-of-var}
and the geometric construction above (and because $x_R$ and~$x_L$ are continuous), we can re-write the integral 
with Fubini's theorem, which gives the first identities.
The change of variable is the composition of a translation by $(-1/2,0)$
that moves the domain $\Omega$ into the strip $[-1/2, 1/2] \times \R$
followed by a rotation around the origin of angle $\frac{\pi}{4}$.
We denote by $\Omega'$ the image of $\Omega$ by this isometry (see Figure~\ref{fig:Omega'}).
The new coordinates $(x_1,x_2)\in\Omega'$ are thus related to the old ones by
\[
x=\frac{1}{2} + \frac{1}{\sqrt{2}}(x_1 + x_2)
\qquad\text{and}\qquad 
y=\frac{1}{\sqrt{2}}(x_2-x_1) \,.
\]
The Jacobian determinant is obviously equal to $1$.
For~\eqref{eq:cgt-var45-Omega-ter}, the assumption on the weight $\omega$ ensures that $\omega(\arctan y)\leq C \ln^{-\beta} |y|$
at infinity, which in turn ensures the integrability thanks to Bertrand's criterion.
\end{proof}

\begin{remark}
In Section~\ref{sect:algo}, we apply~\eqref{eq:cgt-var45-Omega-ter} with a bounded regular even weight that decreases
away from zero and vanishes at the endpoints~$\pm\pi/2$.
In particular, the assumption will be satisfied because $\omega\left(\frac{\pi}{2}-t\right)\leq C |t| \ll \left|\ln t\right|^{-2}$ as $t\to0$.
\end{remark}

\subsection{Proof of the upper bounds in Theorems \ref{thm:conc} and~\ref{thm:conc2}}
Using the previous lemmas we can now prove the upper bounds stated in Theorems~\ref{thm:conc} and~\ref{thm:conc2}.
As $\Omega$ is a subset of $[0,1]\times\R$, 
$\Omega'$ lies between the lines $(\pm\frac{\sqrt 2}{2}, 0) + \R\cdot(1,-1)$.
Therefore, 
\[
\forall (x_1, x_2)\in \Omega',\qquad
-\frac{\sqrt 2}{2}-x_1 \leq x_2 \leq \frac{\sqrt 2}{2} -x_1\,.
\]
Consequently, 
\begin{equation}\label{est:hOmega}
-2\left(\frac{\sqrt 2}{4} +x_1\right) \leq x_2-x_1 \leq 2\left(\frac{\sqrt 2}{4} -x_1\right) .
\end{equation}
Moreover, Lemma \ref{lemma:est-diagonal} ensures that for every $x_1\in \R$, the length of any vertical section
of $\Omega'$ is bounded in the following way:
\begin{equation}
\label{est:section1-Omega}
\forall x_1\in\R,\qquad
\left| \{x_2 \,;\, (x_1, x_2)\in \Omega'\} \right| \leq 2\sqrt{\delta}\,.
\end{equation}

