We now split $\Omega'$ into three parts $\Omega'=\Omega'_\text{I} \cup \Omega'_{\text{II}} \cup \Omega'_\text{III}$ with
\[
\Omega'_\text{I} = \Omega' \cap \left\{x_1\leq -\frac{\sqrt{2}}{4}\right\},
\quad
\Omega'_\text{II} = \Omega' \cap \left\{x_1\geq \frac{\sqrt{2}}{4}\right\}
\quad\text{and}\quad
\Omega'_\text{III} = \Omega' \cap \left\{-\frac{\sqrt{2}}{4}<x_1<\frac{\sqrt{2}}{4}\right\}\,.
\]
On $\Omega'_\text{I}$ we have $\frac{\sqrt{2}}{4} +x_1\leq 0$ and all the terms that appear in the estimate~\eqref{est:hOmega}
are positive. Taking the square of the left-hand side gives $1+2\left(x_1+\frac{\sqrt 2}{4}\right)^2 \leq 1+\frac{1}{2}(x_2-x_1)^2$
and therefore 
\[
\iint_{\Omega'_\text{I}} \frac{dx_1dx_2}{1+\frac{1}{2} (x_1-x_2)^2}  \leq
\iint_{\Omega'_\text{I}} \frac{dx_1dx_2}{1+2\left(x_1+\frac{\sqrt 2}{4}\right)^2}\cdotp
\]
Notice that the function to integrate on the right-hand side does not depend on $x_2$.
Using Fubini's theorem and the estimate~\eqref{est:section1-Omega} we have
\[
\iint_{\Omega'_\text{I}} \frac{dx_1dx_2}{1+\frac{1}{2} (x_1-x_2)^2}  \leq
2\sqrt{\delta}\int_{-\infty}^{-\frac{\sqrt 2}{4}} \frac{dx_1}{1+2\left(x_1+\frac{\sqrt 2}{4}\right)^2} \,\cdotp
\]
With a change of variable $t=\frac{1}{2}+\sqrt{2}x_1$ we obtain 
\begin{equation}
\label{est:Omega'_I}
\iint_{\Omega'_\text{I}} \frac{dx_1dx_2}{1+\frac{1}{2} (x_1-x_2)^2}  \leq
\frac{\pi}{\sqrt{2}} \, \sqrt{\delta} \,.
\end{equation}
On $\Omega'_\text{II}$ we have that $\frac{\sqrt{2}}{4} -x_1\leq 0$ and a similar computation to the one on $\Omega'_\text{I}$
leads to 
\begin{equation}\label{est:Omega'_II}
\iint_{\Omega'_\text{II}} \frac{ dx_1dx_2}{1+\frac{1}{2} (x_1-x_2)^2} \leq
2\sqrt{\delta} \int_{\frac{\sqrt 2}{4}}^{\infty} \frac{dx_1}{1+2\left(x_1-\frac{\sqrt 2}{4}\right)^2}
=\frac{\pi}{\sqrt{2}} \, \sqrt{\delta} \,.
\end{equation}
On $\Omega'_\text{III}$, the decay of the integrand is negligible so we use $\frac{1}{1+\frac{1}{2} (x_1-x_2)^2}\leq 1$.
The geometric estimate~\eqref{est:section1-Omega} of the length of the vertical slices provides
\begin{equation}\label{est:Omega'_III}
\iint_{\Omega'_\text{III}} \frac{ dx_1dx_2}{1+\frac{1}{2} (x_1-x_2)^2} \leq
2\sqrt{\delta} \times 2\frac{\sqrt{2}}{4} = \sqrt{2\delta}\,.
\end{equation}
We put together the estimates \eqref{est:Omega'_I}, \eqref{est:Omega'_II}, \eqref{est:Omega'_III} 
 into the expressions given by Lemma~\ref{lemma:cgt-var45} and conclude that 
\[
\int_{ - \frac \pi 2}^{\frac \pi 2} L(f, \delta, \theta ) \cos \theta  \, d\theta  \leq (1+\pi)\sqrt{ 2 \delta} \,.
\]
Normalizing by $1/\pi$ gives~\eqref{main_estim} with the numerical constant $\frac{1+\pi}{\pi} \sqrt{2}\approx 1.86437$.
A similar computation can be performed for the second integral:
\begin{align*}
\int_{ - \frac \pi 2}^{\frac \pi 2} L(f, \delta, \theta ) \cos^2 \theta  \, d\theta  &= 
\iint_{\Omega'_\text{I} \cup \Omega'_\text{II} \cup \Omega'_\text{III}} \frac{dx_1dx_2}{\left(1+\frac{1}{2}(x_1-x_2)^2\right)^{3/2}}
\\
&\leq 2\sqrt{\delta}\left(
2\times \int_{\frac{\sqrt 2}{4}}^{\infty} \frac{dx_1}{\left(1+2\left(x_1-\frac{\sqrt 2}{4}\right)^2\right)^{3/2}}
+2\times \frac{\sqrt{2}}{4}
\right).
\end{align*}
The right-hand side is equal to $3\sqrt{2\delta}\approx \pi \times 1.35047\sqrt{\delta}$, as claimed by~\eqref{main_estim_bis}.

\medskip
Similarly, for a general even and positive weight function~$\omega$ on~$\left(-\frac{\pi}{2},\frac{\pi}{2}\right)$
that is decreasing on $[0,\pi/2)$, thanks to~\eqref{est:hOmega}, one has on $\Omega'_\text{I}\cup \Omega'_\text{II}$:
\[
\omega\left(\arctan \frac{x_2-x_1}{\sqrt{2}}\right) \leq \omega\left(\arctan\left( \frac{1}{2}-\sqrt{2}\, |x_1| \right)\right).
\]
The estimate~\eqref{main_estim_ter} follows immediately, provided
that the constant~\eqref{main_estim_ter_techsupport} is finite (\eg under the assumptions stated in Lemma~\ref{lemma:cgt-var45},
which are recalled in Theorem~\ref{thm:conc2}).
One can easily check that this estimate boils down to the previous~\eqref{main_estim} when $\omega(\theta)=\cos\theta$
and to~\eqref{main_estim_bis} when~$\omega(\theta)=\cos^2\theta$.

\subsection{Proof of the lower bounds in Theorem \ref{thm:conc}}\label{par:thmconcLower}

We end this section with computations on particular cases that 
assert the quasi-optimality of the constants from Theorem \ref{thm:conc}.
The best (\ie highest) lower bound is given by the second example, however the others
are instructive for getting a feel for which cases are the least favorable to our algorithm (see Section~\ref{sect:algo}).

\paragraph{Example 1 :} If $f(x)=ax+b$ for some $a,b\in \R$, then $S(f, \delta)$ is a parallelogram.
Let us introduce $\alpha = \arctan(a)$ and $\theta _0, \theta _1\in (0,\frac{\pi}{2})$ the geometric angles that
the diagonals make with the long sides of the parallelogram. 
Let us reason with $a\geq0$ as in Figure~\ref{fig:exemple1}.

