For $\theta \in (0, \theta _0)$ both ends of the longest segment $[AB]\subset S(f,\delta)$ of slope $\theta $
belong to the graph of $f$ and $[AB]$ is tangent to the graph of $f-\delta$.
As before, let $(x_\theta ,f(x_\theta )-\delta)$ denote the point where $[AB]$ is tangent to the graph of $f-\delta$
and $x_A$, $x_B$ the first coordinate of the endpoints.
Then $f'(x_\theta )=\tan \theta $ gives  $x_\theta =\frac{1}{2}-\frac{\tan \theta }{2a}$  
and the equation of $[AB]$ implies that $x_A$, $x_B$ satisfy
\[
a\left(x-\frac{1}{2}\right)^2 + \left(x-\frac{1}{2}\right) \tan \theta   +\frac{\tan^2 \theta }{4a}-\delta =0\,.
\]
The difference $x_B -x_A=L(f, \delta, \theta ) \cos \theta $
is thus given by $x_R-x_L = \sqrt{\Delta}/a$ with $\Delta =4a\delta$.
Using a similar estimate on $[-\theta _0,0]$ one gets the lower bounds
\[
\frac{1}{\pi}\int_{ - \frac \pi 2}^{\frac \pi 2} L(f, \delta, \theta ) \cos \theta  \, d\theta 
\geq \frac{2}{\pi} \int_0^{\theta _0} 2\sqrt \frac{\delta}{a}  \, d\theta  
= \frac{4\sqrt{\delta}}{\pi \sqrt a}  \arctan(a-2\sqrt{a\delta})\,,
\]
\[
\frac{1}{\pi}\int_{ - \frac \pi 2}^{\frac \pi 2} L(f, \delta, \theta ) \cos^2 \theta  \, d\theta 
\geq \frac{4\sqrt{\delta}}{\pi \sqrt a} \int_0^{\theta _0} \cos\theta   \, d\theta  
= \frac{4\sqrt{\delta}}{\pi \sqrt a}  \frac{a-2\sqrt{a\delta}}{\sqrt{1+(a-2\sqrt{a\delta})^2}}\,\cdotp
\]
Notice that for $\delta=a/4$ the right-hand side vanishes. For $\delta \ll a/4$, both bounds
are of order $\sqrt{\delta}$.
The first constant is approximately $\frac{4 \arctan(a)}{\pi \sqrt a}$,
whose maximum is $1.02288$ for $a\simeq 1.39175$. The second constant
becomes $\frac{4\sqrt{a}}{\pi(1+a^2)}$, whose maximum is $0.72559$ and is obtained
for $a\simeq 0.57735$.


\begin{remark}
The case $a=1/2$ in Example~3 corresponds to $f''(x)\equiv \textendash1$ for which
the estimate from Lemma~\ref{lemma:est-diagonal} is optimal (see Figure~\ref{fig:sqDiag}).
However, this example does not saturate the inequalities~\eqref{main_estim}-\eqref{main_estim_bis}.
\end{remark}

\section{Index of notations}\label{app:index}
We provide here a short index of our notations. By default, we use the American standard names, notations and spellings.

{\small
\paragraph{Numbers}
\begin{description}[itemsep=-0.3ex, labelsep=0pt, align=left]
\item $z=a+ib\in\C$ : complex numbers (with $a,b\in\R$).
\item $\lfloor\cdot\rfloor$ and $\lceil\cdot\rceil$ : resp.~floor and ceiling functions (round down/up to the next integer).
\item $\ln x$ :  natural logarithm.
\item $\log_b x = \frac{\ln x}{\ln b}$ : base-$b$ logarithm (for complexity, the default base is $b=2$). 
\item $x\simeq y$ : the numbers $x$ and $y$ have a similar order of magnitude (used colloquially).
\item $y\lesssim y$ : the order of magnitude of $x$ is smaller than or equal to that of $ys$ (used colloquially).
\end{description}

\paragraph{Asymptotic estimates} The asymptotic parameter $\sigma\to\sigma^\ast$ can be continuous or discrete and is given from context;
the signs (or complex phase) of $A,B$ are irrelevant.
\begin{description}[itemsep=-0.3ex, labelsep=0pt, align=left]
\item $A=O(B)$ : there exists a bounded function $C(\sigma)$ such that  $A(\sigma)=C(\sigma)B(\sigma)$.
\item $A\ll B$ : there exists a function $\varepsilon(\sigma)$ that tends to zero, such that $A(\sigma)=\varepsilon(\sigma) B(\sigma)$.
\end{description}

\paragraph{Sets}
\begin{description}[itemsep=-0.3ex, labelsep=0pt, align=left]
\item $\ii{m}{n}=\{m,m+1,\ldots,n-1,n\}$ : integer interval $[m,n]\cap\Z$.
\item $[a,b)$ : real-line interval, semi-open on the right side.
\item $\CC=\C\cup\{\infty\}$ : Riemann Sphere.
\item $\RR=\R\cup\{\infty\}$ : compaction of $\R$ into a circle.
\item $\# E$ : cardinal of a finite set.
\item $|E|$ : Lebesgue measure of a measurable set $E\subset\R^n$.
\end{description}

\paragraph{Polynomials}
\begin{description}[itemsep=-0.3ex, labelsep=0pt, align=left]
\item $\mathbb{K}[X]$ : set of polynomials with coefficients in the field $\mathbb{K}$ (typically $\R$ or $\C$).
\item $\mathbb{K}[[X]]$ : set of formal series with coefficients in the field $\mathbb{K}$.
\end{description}

\paragraph{Complexity} (see page~\pageref{def:complexity})
\begin{description}[itemsep=-0.3ex, labelsep=0pt, align=left]
\item $\eval_d$ : arithmetic complexity of evaluating a polynomial of degree $d$.
\item $\eval_d(k)$ : arithmetic complexity of $k$ polynomial evaluations of degree $d$.
\item $\eval_d(k,p)$ : bit complexity of evaluating a polynomial of degree $d$ on $k$ evaluation points with a fixed precision of $p$ bits
for all intermediary computations.
\item $M(p)$ : bit complexity of one multiply-add of two floating-point numbers with precision $p$.
\end{description}

\paragraph{Floating-point numbers} (see page~\pageref{equ:prec})
\begin{description}[itemsep=-0.3ex, labelsep=0pt, align=left]
\item $\xi = \pm 2^{n} \times 0.1\xi_1\xi_2 \ldots \xi_p$ : bit presentation of a floating point number.
\item $\ulp(\xi)$ : unit in the last place (smallest increment possible of the $p$-bit number $|\xi|$).
\end{description}

\paragraph{Floating-point representations of real and complex numbers} (see Section~\ref{par:equivModP})
\begin{description}[itemsep=-0.3ex, labelsep=0pt, align=left]
\item $s(z)$ : scale of a complex number (page~\pageref{equ:dsz}).
\item $x =_p y$ : $x,y\in\R$ have the same floating-point representation with precision $p \in \N^*$.
\item $x \simeq_p y$ : the $p$-bit floating-point representations of $x,y\in\R$ are identical or adjacent.
\item $z \approx_p z'$ : $z,z'\in\C$ have similar $p$-bits representations,
reduced by phase-shift invariance; see~\eqref{equ:eqpComplex}.
\end{description}

\paragraph{Concave geometry} (see Section~\ref{sect:analyse})
\begin{description}[itemsep=-0.3ex, labelsep=0pt, align=left]
\item subgraph : for a concave function $f$, region of the $(x,y)$-plane such that $y\leq f(x)$.
%% \item epigraph : for a concave function $f$, region of the $(x,y)$-plane such that $y\geq f(x)$.
\item $S(f,\delta)$ : edge of the subgraph of $f$ of (vertical) thickness $\delta$.
\item $L(f, \delta, \theta)$ : maximal length of a segment of slope $\tan \theta $ contained in the strip $S(f, \delta)$.
\item Equation \eqref{eq:def_f_from_Ep} : definition of $f$ and $\delta$ in the FPE Algorithm application case.
\end{description}

\paragraph{FPE Algorithm} (see Section~\ref{sect:algo})
\begin{description}[itemsep=-0.3ex, labelsep=0pt, align=left]
\item $E_P:\ii{0}{d} \rightarrow \Z \cup \{-\infty\}$ : scales of the coefficients of the polynomial $P$.
\item $\ep:[0,d] \rightarrow \R \cup \{-\infty\}$ : concave cover of~$E_P$.
\item $\lambda = \log_2 |z| = -\tan \theta$ : dyadic scale of the evaluation point $z$.
\item $G_p$, $B_p$ : list of a-priori good (resp. ignored) coefficients for a given precision $p$.
\item $\ell$, $r$ : left/right edges to further reduce $G_p$ for a given $\lambda$.
\item $Q_\lambda(z)$ : reduced polynomial produced by the FPE algorithm.
\item $\A_p$ : new algorithm proposed in this article, for computations with a fixed precision $p$.
\item $\avg_{\CC}$ : average operator for $z$ uniformly distributed over $\CC$.
\item $\avg_{\RR}$ : average operator for $z$ uniformly distributed over $\RR$.
\item $\avg_{D(0,1)}$ : average operator for $z$ uniformly distributed over the unit complex disk.
\end{description}

}%small

