\begin{theorem}[Polynomial-Time Solvability for $\ell_{p > 0}$]
For any $\ell_p$ norm with $p > 0$, \hfr can be solved in polynomial time, even with additional linear constraints (e.g.~upper/lower bounds) or weighted objectives. For $p>1$, the solution is unique. Specifically:
\begin{enumerate}
    \item For $p=1$ (MAE), \hfr reduces to linear programming
    \item For $p=2$ (MSE), \hfr reduces to quadratic programming
    \item For general $p > 0$, \hfr can be solved via convex optimization
\end{enumerate}
\end{theorem}

%For more specialised losses like Huber loss, we can still achieve polynomial time solutions. 
\begin{theorem}[Generalized Loss Functions]
Consider loss functions of form:
$L(\mathbf{x}, \mathbf{y}) = \sum_{i=1}^n f(|x_i - y_i|)$.
For strictly convex, continuously differentiable $f$ with $f(0)=0$, \hfr has a unique solution computable in polynomial time, even with additional linear constraints (e.g.~upper/lower bounds) or weighted objectives.

\end{theorem}
\begin{theorem}[Runtime Lower Bound] \label{thm:lower-bound}
Any algorithm to solve \hfr on networks with $m$ edges and $n$ nodes requires $\Omega(m \log n)$ comparisons, even for the $\ell_2$ loss function.
\end{theorem}
