\subsection{Relationship to MinT}

The state-of-the-art MinT reconciles forecasts on tree based hierarchies by minimizing the trace of the reconciled forecast error ($n \times n$) covariance matrix. We show that \fr can be viewed as a special case where the weight matrix corresponds to the network structure, allowing significant computational improvements and generalisation to complex networks.

% [NOTATION CHANGES]
% - Matrices in bold: $\mathbf{S}$, $\mathbf{W}$, $\boldsymbol{\Sigma}$
% - Vectors in bold: $\hat{\mathbf{y}}$, $\tilde{\mathbf{y}}$, $\mathbf{b}$
% - Problems labeled as (P₁), (P₂) for clarity
\begin{theorem}[MinT Equivalence]
Let $\mathbf{S} \in \mathbb{R}^{n\times m}$ be a hierarchical aggregation matrix and $\mathbf{W} \in \mathbb{R}^{n\times n}$ be a symmetric positive definite matrix. For any base forecast $\hat{\mathbf{y}}$ and target aggregation values $\mathbf{b}$, the following optimization problems:

$(P_1):
 \min_{\tilde{\mathbf{y}}} (\tilde{\mathbf{y}} - \hat{\mathbf{y}})^T \mathbf{W} (\tilde{\mathbf{y}} - \hat{\mathbf{y}}) \quad \text{subject to} \quad \mathbf{S}\tilde{\mathbf{y}} = \mathbf{b} $

$(P_2):
 \min_{\tilde{\mathbf{y}}} (\tilde{\mathbf{y}} - \hat{\mathbf{y}})^T \boldsymbol{\Sigma}^{-1} (\tilde{\mathbf{y}} - \hat{\mathbf{y}}) \quad \text{subject to} \quad \mathbf{S}\tilde{\mathbf{y}} = \mathbf{b} $

where $\boldsymbol{\Sigma}$ is the forecast error covariance matrix, have the following properties:
\begin{enumerate}
    \item Both problems have a unique solution of the form: 
    $ \tilde{\mathbf{y}} = \hat{\mathbf{y}} - \mathbf{W}^{-1}\mathbf{S}^T(\mathbf{S}\mathbf{W}^{-1}\mathbf{S}^T)^{-1}(\mathbf{S}\hat{\mathbf{y}} - \mathbf{b}) $.
    \item When $\mathbf{W} = \boldsymbol{\Sigma}^{-1}$, the problems $(P_1)$ and $(P_2)$ are equivalent.
    \item \fr is a special case where $\mathbf{W} = \mathbf{I}$ and $\mathbf{S} = \begin{pmatrix} \mathbf{V} \\ \mathbf{E} \\ \mathbf{I} \end{pmatrix}$ with $\mathbf{V}$ as vertex-path incidence matrix, $\mathbf{E}$ as edge-path incidence matrix, and $\mathbf{I}$ as identity matrix for paths.
\end{enumerate}
\end{theorem}



% [After MinT Equivalence theorem and proofs]

\begin{corollary}[Computational Complexity of \fr and MinT]
Let $G=(V,E,\mathcal{P})$ be a network with $|V| = n$ vertices and $|E| = m$ edges where $m \in [n-1, n^2]$. Then:
\begin{enumerate}
    \item For sparse networks i.e. $m = O(n)$: \fr has $O(n^2 \log n)$, MinT has $O(n^3)$ operations.    
    \item For dense networks i.e. $m = O(n^2)$: both have $O(n^4)$ operations.
\end{enumerate}
%\fr preserves network flow properties without requiring explicit path enumeration.
\end{corollary}

