\section{Properties of the \hfr Formulation and the \fr Framework} \label{app:props}


\subsection{Hardness of \hfr}


\begin{theorem}[NP-Hardness for $\ell_0$]
Minimizing the loss of the $\|\cdot\|_0$ norm in \hfr is NP-hard, where for $\mathbf{x} \in \mathbb{R}^n$:
\[ \|\mathbf{x}\|_0 = |\{i : x_i \neq 0\}| \]
\end{theorem}

% [For appendix: Full proof]
\begin{proof}
We prove the claim by reduction from Exact-1-in-3-SAT. Given an instance with $n$ variables and $m$ clauses where each clause is of the form $(l_{j,1} \lor l_{j,2} \lor l_{j,3})$, we construct a forecast reconciliation instance as follows:

For each variable $x_i$ in the SAT instance, create a forecast variable $x_i$. For each clause $(l_{j,1} \lor l_{j,2} \lor l_{j,3})$, create a linear equation:
\[ (-1)^{\alpha_1}x_{j,1} + (-1)^{\alpha_2}x_{j,2} + (-1)^{\alpha_3}x_{j,3} + \sigma_j = 1 \]
where $\alpha_i = 0$ if $l_{j,i}$ is positive, and $\alpha_i = 1$ if $l_{j,i}$ is negative.

If there exists a variable assignment satisfying Exact-1-in-3-SAT, then setting $\sigma_j = 0$ for all $j$ gives reconciled forecasts with zero $\ell_0$ loss. Conversely, any reconciliation with zero $\ell_0$ loss must have $\sigma_j = 0$ for all $j$, implying a satisfying assignment for the original Exact-1-in-3-SAT instance.
\end{proof}

% [NOTATION CHANGES from original]
% - Added vector notation for forecasts
% - Standardized subscripts
