\begin{theorem}[Polynomial-Time Solvability]
For any $\ell_p$ norm with $p > 0$, \hfr can be solved in polynomial time. Specifically:
\begin{enumerate}
    \item For $p=1$ (MAE), \hfr reduces to linear programming
    \item For $p=2$ (MSE), \hfr reduces to quadratic programming
    \item For general $p > 0$, \hfr can be solved via convex optimization
\end{enumerate}
This holds even with additional linear constraints such as upper/lower bounds or weighted objectives.
\end{theorem}

\begin{proof}
For MSE and RMSE, we can find an optimal solution in polynomial time by quadratic programming – note that the optimal solution to MSE is also an optimal solution to RMSE as the square root function is monotone. Similarly, an optimal solution to MAE can be found in polynomial time by linear programming.

For MSE, RMSE, MAE and their weighted versions, the set of constraints consists of the aggregation constraints and optional box constraints:
\begin{align*}
\tilde{\mathbf{y}} &= \mathbf{S}\tilde{\mathbf{b}} \\
\tilde{\mathbf{y}} &\leq \mathbf{u} \\
\tilde{\mathbf{y}} &\geq \boldsymbol{\ell}
\end{align*}
which are linear constraints forming a convex set, with $\tilde{\mathbf{y}} \in \mathbb{R}^n$ as continuous decision variables.
We introduce slack variables to measure the absolute error:
\begin{align*}
\mathbf{s}_{\mathcal{P}} &\geq \hat{\mathbf{y}}_{\mathcal{P}} - \tilde{\mathbf{y}}_{\mathcal{P}} \quad \forall P \in \mathcal{P} \\
\mathbf{s}_{\mathcal{P}} &\geq \tilde{\mathbf{y}}_{\mathcal{P}} - \hat{\mathbf{y}}_{\mathcal{P}} \quad \forall P \in \mathcal{P} \\
\mathbf{s}_E &\geq \hat{\mathbf{y}}_E - \tilde{\mathbf{y}}_E \quad \forall e \in E \\
\mathbf{s}_E &\geq \tilde{\mathbf{y}}_E - \hat{\mathbf{y}}_E \quad \forall e \in E \\
\mathbf{s}_V &\geq \hat{\mathbf{y}}_V - \tilde{\mathbf{y}}_V \quad \forall v \in V \\
\mathbf{s}_V &\geq \tilde{\mathbf{y}}_V - \hat{\mathbf{y}}_V \quad \forall v \in V
\end{align*}

Flow conservation constraints are maintained:
\begin{align*}
\sum_{P \in \mathcal{P}:e \in P} \tilde{\mathbf{y}}_P &= \tilde{\mathbf{y}}_e \quad \forall e \in E \\
\sum_{P \in \mathcal{P}:v \in P} \tilde{\mathbf{y}}_P &= \tilde{\mathbf{y}}_v \quad \forall v \in V
\end{align*}

For weighted MSE, the objective function is:
\[ \min \sum_{P \in \mathcal{P}} w_P \mathbf{s}_P^2 + \sum_{e \in E} w_e \mathbf{s}_e^2 + \sum_{v \in V} w_v \mathbf{s}_v^2 \]

Let $\mathbf{y} = [\tilde{\mathbf{y}}^T, \mathbf{s}^T]^T$ be the vector of variables extended by the slack variables, and $\mathbf{w}$ be the vector of weights. Then we can define the positive semi-definite matrix $\mathbf{Q} = (q_{ij})$ by:
\[ q_{ij} = \begin{cases}
0 & \text{if } i \neq j \text{ or } i < |V| + |E| + |\mathcal{P}| \\
w_{i-|V|-|E|-|\mathcal{P}|} & \text{otherwise}
\end{cases} \]

The objective for weighted MSE can be written as $\mathbf{y}^T\mathbf{Q}\mathbf{y}$, which can be solved efficiently by quadratic programming.

For weighted MAE, we have the linear objective:
\[ \min \sum_{P \in \mathcal{P}} w_P \mathbf{s}_P + \sum_{e \in E} w_e \mathbf{s}_e + \sum_{v \in V} w_v \mathbf{s}_v \]
which proves the claim.
\end{proof}

\begin{theorem}[General Loss Function Reconciliation]
Let $L: \mathbb{R}^n \times \mathbb{R}^n \to \mathbb{R}_+$ be a loss function satisfying:
\[ L(\mathbf{x}, \mathbf{y}) = \sum_{i=1}^n f(|x_i - y_i|) \]
where $f: \mathbb{R}_+ \to \mathbb{R}_+$ is strictly convex, continuously differentiable, and satisfies $f(0) = 0$. Then:

\begin{enumerate}
    \item The FlowRec optimization problem has a unique solution
    \item This solution can be computed in polynomial time via interior point methods
    \item The solution preserves flow conservation
\end{enumerate}
\end{theorem}

\begin{proof}
The optimization problem becomes:
\[ \min_{\tilde{\mathbf{y}}} \sum_{i=1}^n f(|\tilde{y}_i - \hat{y}_i|) \text{ subject to } \mathbf{S}\tilde{\mathbf{y}} = \mathbf{b} \]

The objective is strictly convex as a sum of strictly convex functions composed with norms. The constraints form a polyhedral set. Therefore:

\begin{itemize}
\item Uniqueness follows from strict convexity and the convexity of the constraint set.

\item The KKT conditions give:
\[ \nabla f(|\tilde{y}_i - \hat{y}_i|) \text{sign}(\tilde{y}_i - \hat{y}_i) + \mathbf{S}^T\boldsymbol{\lambda} = 0 \]
\[ \mathbf{S}\tilde{\mathbf{y}} = \mathbf{b} \]

These form a monotone system solvable by interior point methods in polynomial time.

\item Flow conservation follows from the constraint $\mathbf{S}\tilde{\mathbf{y}} = \mathbf{b}$.
\end{itemize}
\end{proof}
% [After MinT Equivalence theorem and proofs]

\begin{theorem}[Runtime Lower Bound]
Any algorithm that computes exact reconciled forecasts on networks with $m$ edges and $n$ nodes requires $\Omega(m \log n)$ comparisons, even for the $\ell_2$ loss function.
\end{theorem}

\begin{proof}
We prove this by reduction from the problem of sorting $n$ numbers, which is known to require $\Omega(n \log n)$ comparisons in the comparison model.

Given a set of $n$ numbers $x_1,\ldots,x_n$ to sort, we construct the following network $G=(V,E)$:

\begin{enumerate}
    \item Vertices $V = \{s,t\} \cup \{v_1,\ldots,v_n\}$, where $s$ is a source and $t$ is a sink.
    \item Edges $E = \{(s,v_i),(v_i,t) : i \in \{1,\ldots,n\}\}$
    \item For each $i \in \{1,\ldots,n\}$, define a path $P_i = (s,v_i,t)$
\end{enumerate}

Now, set the base forecasts as follows:
\begin{itemize}
    \item $\hat{\mathbf{y}}_{P_i,T+h|T} = x_i$ for $i \in \{1,\ldots,n\}$
    \item $\hat{\mathbf{y}}_{s,T+h|T} = \sum_{i=1}^n x_i$
    \item $\hat{\mathbf{y}}_{t,T+h|T} = \sum_{i=1}^n x_i$
    \item $\hat{\mathbf{y}}_{v_i,T+h|T} = x_i$ for $i \in \{1,\ldots,n\}$
\end{itemize}

Consider the flow conservation constraints in this network:
\begin{align*}
    \tilde{\mathbf{y}}_{s,T+h|T} &= \sum_{i=1}^n \tilde{\mathbf{y}}_{P_i,T+h|T} \\
    \tilde{\mathbf{y}}_{t,T+h|T} &= \sum_{i=1}^n \tilde{\mathbf{y}}_{P_i,T+h|T} \\
    \tilde{\mathbf{y}}_{v_i,T+h|T} &= \tilde{\mathbf{y}}_{P_i,T+h|T} \quad \text{for } i \in \{1,\ldots,n\}
\end{align*}

To minimize the $\ell_2$ loss while satisfying these constraints, the reconciled forecasts must have:
\begin{itemize}
    \item $\tilde{\mathbf{y}}_{s,T+h|T} = \tilde{\mathbf{y}}_{t,T+h|T} = \sum_{i=1}^n x_i$
    \item $\tilde{\mathbf{y}}_{P_i,T+h|T} = \tilde{\mathbf{y}}_{v_i,T+h|T}$ for all $i$
\end{itemize}

Moreover, to satisfy flow conservation, we must have:
\[
    \tilde{\mathbf{y}}_{P_1,T+h|T} \leq \tilde{\mathbf{y}}_{P_2,T+h|T} \leq \cdots \leq \tilde{\mathbf{y}}_{P_n,T+h|T}
\]

This ordering is necessary because any other ordering would violate flow conservation at some intermediate node $v_i$.

Therefore, computing the exact reconciled forecasts implicitly requires sorting the values $x_1,\ldots,x_n$. Since sorting requires $\Omega(n \log n)$ comparisons, and our construction has $m = \Theta(n)$ edges, we obtain a lower bound of $\Omega(m \log n)$ comparisons for the reconciliation problem.

Note that this lower bound holds even for the $\ell_2$ loss function, as the optimal reconciliation in this case coincides with the sorted order of the input values.
\end{proof}


