%     \[ \|\tilde{\mathbf{y}}^{(k+1)}_{\varepsilon} - \tilde{\mathbf{y}}^*_{\varepsilon}\|_2 \leq (1-\alpha\mu)\|\tilde{\mathbf{y}}^{(k)}_{\varepsilon} - \tilde{\mathbf{y}}^*_{\varepsilon}\|_2 \]
%     \item This geometric convergence rate implies $O(\log(\frac{1}{\varepsilon}))$ iterations to reach error $\varepsilon$
% \end{enumerate}

% \end{proof}

\begin{theorem}[Approximate Forecast Reconciliation]
Let $G=(V,E,\mathcal{P})$ be a network with base forecasts $\hat{\mathbf{y}}_{T+h|T}$ optimized for the $\ell_2$ norm. For accuracy threshold $\varepsilon > 0$, there exists an $\varepsilon$-relaxed reconciliation $\tilde{\mathbf{y}}_{\varepsilon,T+h|T}$ satisfying:
\[ \left|\sum_{P \in \mathcal{P}:e \in P} \tilde{\mathbf{y}}_{\varepsilon,P,T+h|T} - \tilde{\mathbf{y}}_{\varepsilon,e,T+h|T}\right| \leq \varepsilon \quad \forall e \in E \]
with bounded deviation from exact reconciliation:
\[ \|\tilde{\mathbf{y}}_{\varepsilon,T+h|T} - \tilde{\mathbf{y}}_{T+h|T}\|_2 \leq \sqrt{\varepsilon|E|}\|\tilde{\mathbf{y}}_{T+h|T}\|_2 \]
\end{theorem}

\begin{proof}
Consider the relaxed optimization:
\[ \min_{\tilde{\mathbf{y}}_{\varepsilon,T+h|T}} \|\tilde{\mathbf{y}}_{\varepsilon,T+h|T} - \hat{\mathbf{y}}_{T+h|T}\|_2^2 \]
subject to:
\[ -\varepsilon \leq \sum_{P \in \mathcal{P}:e \in P} \tilde{\mathbf{y}}_{\varepsilon,P,T+h|T} - \tilde{\mathbf{y}}_{\varepsilon,e,T+h|T} \leq \varepsilon \quad \forall e \in E \]

The Lagrangian is:
\begin{align*}
\mathcal{L}(\tilde{\mathbf{y}}_{\varepsilon}, \boldsymbol{\lambda}^+, \boldsymbol{\lambda}^-) = &\|\tilde{\mathbf{y}}_{\varepsilon,T+h|T} - \hat{\mathbf{y}}_{T+h|T}\|_2^2 + \\
&\sum_{e \in E} \lambda_e^+(\sum_{P \in \mathcal{P}:e \in P} \tilde{\mathbf{y}}_{\varepsilon,P,T+h|T} - \tilde{\mathbf{y}}_{\varepsilon,e,T+h|T} - \varepsilon) + \\
&\sum_{e \in E} \lambda_e^-(-\sum_{P \in \mathcal{P}:e \in P} \tilde{\mathbf{y}}_{\varepsilon,P,T+h|T} + \tilde{\mathbf{y}}_{\varepsilon,e,T+h|T} - \varepsilon)
\end{align*}

The KKT conditions imply that for each edge $e \in E$, either the flow conservation constraint is exactly satisfied or the violation equals $\pm\varepsilon$. Let $\mathcal{E}_\varepsilon$ be the set of edges where the maximum violation occurs. Then:
\[ \|\tilde{\mathbf{y}}_{\varepsilon,T+h|T} - \tilde{\mathbf{y}}_{T+h|T}\|_2^2 = \sum_{e \in \mathcal{E}_\varepsilon} (\pm\varepsilon)^2 \leq \varepsilon^2|E| \]

Moreover:
\[ \|\tilde{\mathbf{y}}_{\varepsilon,T+h|T} - \hat{\mathbf{y}}_{T+h|T}\|_2^2 \leq \|\tilde{\mathbf{y}}_{T+h|T} - \hat{\mathbf{y}}_{T+h|T}\|_2^2 + \varepsilon^2|E| \]
The bound follows from the triangle inequality.
\end{proof}

This result shows that by allowing small violations of flow conservation, we can obtain solutions with provably bounded deviation from exact reconciliation. The error bound $\sqrt{\varepsilon|E|}$ provides precise guidance for setting $\varepsilon$ based on application requirements.

\begin{theorem}[Computational Efficiency of Approximate Reconciliation]
The $\varepsilon$-relaxed solution can be computed in $O(m \log(\frac{1}{\varepsilon}) \log n)$ time using $O(m)$ memory, where $m = |E|$ and $n = |V|$.
\end{theorem}

\begin{proof}
The problem is strongly convex due to the quadratic objective. The gradient of the Lagrangian at any point can be computed in $O(m)$ operations. For step size $\alpha$, projected gradient descent satisfies:
\[ \|\tilde{\mathbf{y}}^{(k+1)}_{\varepsilon,T+h|T} - \tilde{\mathbf{y}}^*_{\varepsilon,T+h|T}\|_2 \leq (1-\alpha\mu)\|\tilde{\mathbf{y}}^{(k)}_{\varepsilon,T+h|T} - \tilde{\mathbf{y}}^*_{\varepsilon,T+h|T}\|_2 \]
where $\mu = 2$ is the strong convexity parameter.

This geometric convergence implies $O(\log(\frac{1}{\varepsilon}))$ iterations to reach error $\varepsilon$. Each iteration requires:
\begin{enumerate}
    \item Gradient computation: $O(m)$
    \item Projection onto box constraints: $O(m)$
    \item Line search: $O(\log n)$ using binary search
\end{enumerate}

The total complexity follows. Memory requirements are $O(m)$ to store the current solution and gradient.
\end{proof}

This result provides practitioners with a principled way to trade off computational efficiency against forecast coherence. The error bound $\sqrt{\varepsilon|E|}$ gives precise guidance for setting $\varepsilon$ based on application requirements. Moreover, the $O(m \log(\frac{1}{\varepsilon}) \log n)$ runtime represents a significant improvement over MinT's $O(n^3)$, particularly for sparse networks where $m \ll n^2$.

