%     \text{DA}(IC) \leq \text{DA}(DBP) \leq \text{DA}(defLET) \label{eqn:compDA} \\ 
%     \text{RT}(IC) \leq \text{RT}(DBP) \leq \text{RT}(defLET) \label{eqn:compRT}
