\section{ \texorpdfstring{The Flexible LET Model and \\ Problem Description}{Problem Description}}
\label{section_fLET}

This section reviews the flexible LET model~\cite{kirsch2006evolution, Biondi2018AchievingPM, autosar_timing_extensions22} where tasks can read input and write output at times different from those specified in equation~\eqref{eq_read_write_standard_let}:
\begin{definition}[Virtual offset, $O_i$]
\label{def_virtual_offset}
    For each job $J_{i,q_i}$ of a periodic task $\tau_i$, both its release time and the time it reads its input, $re_{J_{i,q_i}}$, is delayed from $q_iT_i$ to $ O_i + q_iT_i$, where $ O_i \geq 0$.
\end{definition}
\begin{definition}[Virtual deadline, $D_i$]
\label{def_virtual_deadline}
     For each job $J_{i,q_i}$ of a periodic task $\tau_i$, both its deadline and the time to write its output, $wr_{J_{i,q_i}}$, is moved forward from $q_iT_i+D_i^{org}$ to $q_iT_i+D_i$, where $O_i \leq D_i \leq D_i^{org}$.
\end{definition}
In the flexible LET model, all jobs of the same task share the same virtual offset and virtual deadline, ensuring deterministic reading and writing times.

\subsection{fLET vs Alternative Communication Mechanism}
% Fig.~\ref{Fig_LET_fLET_IC_Example} compares the schedules of different communication protocols in Example~\ref{Example_setup}.
Compared to alternative methods, such as default LET and implicit communication (both are used in AUTOSAR~\cite{Tang2023ComparingCP}), fLET shows significant potential in optimizing various performance metrics while still preserving its deterministic advantages. However, realizing these benefits of the flexible LET model depends on finding an optimal set of virtual offsets and virtual deadlines, which is the central focus of this paper.
% We do not show DBP because implicit communication is proven to outperform it. 

\subsection{fLET Optimization Problem Descriptions}
This paper aims to find virtual offsets and virtual deadlines to minimize the worst-case data age (or reaction time):
\begin{equation}
\label{obj_overall}
    \min_{\boldsymbol{O},\boldsymbol{D}} \sum_{\mathcal{C} \in \boldsymbol{\mathcal{C}}} \max \boldsymbol{\mathcal{F}}_{\mathcal{C}}(\boldsymbol{O},\boldsymbol{D})
\end{equation}
where $\boldsymbol{O}$ and $\boldsymbol{D}$ denote the virtual offset and virtual deadline for all the tasks in the task set $\boldsymbol{\tau}$; $\boldsymbol{\mathcal{F}}_{\mathcal{C}}$ denotes the length of all the immediate forward or backward job chains. 

Another important metric considered in this paper is the worst-case time disparity and jitter:
\begin{align}
    \min_{\boldsymbol{O},\boldsymbol{D}} \sum_{\mathcal{M} \in \boldsymbol{\mathcal{M}}} 
    & \max \boldsymbol{\mathcal{F}}_{\mathcal{M}}(\boldsymbol{O},\boldsymbol{D}) + \nonumber \\ 
    &  \omega(\max \boldsymbol{\mathcal{F}}_{\mathcal{M}}(\boldsymbol{O},\boldsymbol{D}) - \min \boldsymbol{\mathcal{F}}_{\mathcal{M}}(\boldsymbol{O},\boldsymbol{D}))    
\label{obj_overall_sf}
\end{align}
where $\mathcal{M}$ denotes a ``merge'' that includes a sink task and multiple source tasks that the sink task depends on, $\boldsymbol{\mathcal{F}}_{\mathcal{M}}$ follows Definition~\ref{def_sf}, $\omega$ is the weight of the jitter term. 

Both the optimization problems~\eqref{obj_overall} and~\eqref{obj_overall_sf} are subject to the schedulability constraints:
\begin{equation}
\label{schedulability_test_fLET}
    \forall \tau_i \in \boldsymbol{\tau}, 0 \leq O_i, \ O_i+R_i \leq D_i,\ D_i \leq D_i^{org}
\end{equation}
where $R_i$ denotes the worst-case response time for task $\tau_i$. 

