\subsection{Motivation}
Directly solving the problem~\eqref{obj_overall} and \eqref{obj_overall_sf} is challenging due to the nonlinear and non-continuous nature of these problems, which require iterating through all virtual offset and virtual deadline combinations to find the optimal solution. 
Therefore, this section introduces a new concept, \textit{communication pattern}, which succinctly describes the communication among tasks. 
We then reformulate the problem~\eqref{obj_overall} and~\eqref{obj_overall_sf} to find the optimal communication pattern. 
Operations related to the communication patterns are summarized in \tabref{symbol operations}.

Searching for the communication patterns is easier than value combinations because they have a much smaller solution space. 
Furthermore, efficient feasibility analysis and symbolic operations are available to reduce unnecessary computation substantially.
This method improves both performance and efficiency than the state-of-art~\cite{Martinez2018AnalyticalCO}.

\subsection{Edge Communication Patterns (ECP)}
In the flexible LET model, all the jobs of the same task have the same virtual offset and virtual deadline. 
Therefore, for any edge $E= \tau_i \rightarrow \tau_j$, it is sufficient to focus on jobs within a super-period $H^s$ (the least common multiple of $T_i$ and $T_j$, \cite{Verucchi2020LatencyAwareGO}) to describe the possible reading/writing relationships. 

\begin{definition}[Job map]
\label{def: job map}
    A job map is a mapping from one job $J_{i, q_i}$ in a set to another job $J_{j,q_j}$ in another set.
\end{definition}

\begin{definition}[Edge last-reading pattern, $ELP$]
    Consider an edge $E= \tau_i \rightarrow \tau_j$. For any job $J_{j, q_j}$ where $0 \leq q_j < H^s/T_j \}$, the edge last-reading pattern $ELP$ is a job map which specifies which job of $\tau_i$ is $J_{j, q_j}$'s last-reading job.
\end{definition}
\begin{definition}[Edge first-reacting pattern, $EFP$]
    Consider an edge $E= \tau_i \rightarrow \tau_j$. For any job $J_{i, q_i}$ where $ 0 \leq q_i < H^s/T_i \}$, the edge first-reacting pattern $EFP$ is a job map which specifies which job of $\tau_j$ is $J_{i, q_i}$'s first-reacting job.
\end{definition}

An edge $E$ could have multiple ELPs or EFPs. We use $\boldsymbol{ELP}_{E}(i)$ ($\boldsymbol{EFP}_{E}(i)$) to denote the \ith ELP (EFP) of $E$. Both ELP and EFP are considered ECP.

Consider an edge $E= \tau_i \rightarrow \tau_j$, a job $J_{j, q_j}$ and its last-reading job $J_{i, \overleftarrow{q_j}}$, we can use \defref{last_reading_job} to get:
\begin{equation}
\label{last_reading_job_ineq}
    D_i+ \overleftarrow{q_j} T_i \leq O_j+q_jT_j <D_i+ (\overleftarrow{q_j}+1) T_i 
\end{equation}
Therefore, ELPs can be described by linear inequalities:
\begin{definition}[ELP inequalities]
\label{def: elp inequalities}
    Given an edge $E= \tau_i \rightarrow \tau_j$ and an ELP, the ELP inequalities are the intersection of the linear inequalities (\defref{last_reading_job}) of all the jobs $J_{j, q_j} \in \boldsymbol{J}_j =\{ {J_{j, q_j} | 0 \leq q_j < H^s/T_j} \}$ and their last-reading jobs:
    \begin{equation}
    \mathcal{I}_{ELP} = \mathcal{I}^{LR}_0 \cap  ... \ \mathcal{I}_{q_j}^{LR} ...   \cap  \mathcal{I}^{LR}_{H^s/T_j-1}
    \label{eq_ecp_fr}
\end{equation}
\end{definition}
\noindent where $\mathcal{I}^{LR}_{q_j}$ is the linear inequality~\eqref{last_reading_job_ineq} between $J_{j, q_j}$ and its last-reading job specified by the ELP.
The symbol $ \cap $ denotes that the two linear inequalities must be \textit{both} satisfied. 
Notice that Equation~\eqref{eq_ecp_fr} can be merged into two linear inequalities since all the $\mathcal{I}_{q_j}^{LR}$ depends on the same two variables (\ie $O_j$ and $D_i$).
Similarly, EFP inequalities can be obtained based on first-reacting jobs.


\begin{Example}
    Consider the edge $E_1= \tau_1 \rightarrow \tau_2$ in Example~\ref{Example_setup}. Suppose $J_{2,0}$ and $J_{2,1}$'s last-reading jobs are $J_{1,-1}$ and $J_{1,0}$, respectively, then the linear inequalities associated with the two jobs are
    $D_1-20 \leq O_2 <D_1+0$ and $D_1 \leq O_2 + 10 <D_1+20$.
    Since these inequalities have to hold together, we can merge them into one set of inequalities by taking the intersection $D_1 -10 \leq O_2 < D_1$.
\end{Example}

\noindent \textbf{Usage.} ELPs are used for optimizing data age or time disparity, whereas EFPs are used for optimizing reaction time.


\begin{definition}[Feasibility]
    An ELP (EFP) is feasible if there exists a set of virtual offset and virtual deadline assignments that satisfy its inequality constraints (\defref{elp inequalities}) and schedulability constraints~\eqref{schedulability_test_fLET}.
\end{definition}


\begin{Example}
Consider the edge $E_0:\tau_0 \rightarrow \tau_1$ in example~\ref{Example_setup} and an ELP which specifies $J_{1,0}$'s last-reading job to be $J_{0,3}$. 
It is infeasible because there are no solutions which can satisfy the following inequalities:
\begin{equation*}
    R_0 \leq D_0, D_0 +15 \leq O_1  < D_0+20,
    O_1+R_1 \leq D_1
\end{equation*}
where $R_0=1$, $R_1=5$ based on RM.
\end{Example}

The following lemmas provide the necessary conditions for an edge communication pattern to be feasible.

\begin{lemma}
\label{lemma_two_task_Reading_pattern_inequality}
Consider a feasible ELP of an edge $\tau_i \rightarrow \tau_j$ and two jobs $J_{j,q_u}$ and $J_{j,q_w}$ where $q_u < q_w$, their last-reading jobs specified by the ELP, $J_{i, \overleftarrow{q_u}}$ and $J_{i, \overleftarrow{q_w}}$, satisfy:
    $\overleftarrow{q_u} \leq \overleftarrow{q_w}$.
\end{lemma}
\begin{proof}
    If $\overleftarrow{q_u} > \overleftarrow{q_w}$, then $J_{i,\overleftarrow{q_w}}$ cannot become $J_{j,q_w}$'s last reading job because $J_{j,q_w}$ could read from $J_{i,\overleftarrow{q_u}}$ since $wr_{J_{i,\overleftarrow{q_w}}} < wr_{J_{i,\overleftarrow{q_u}}} < re_{J_{j,q_u}} <re_{J_{j,q_w}}$. This causes a contradiction.
\end{proof}

\begin{lemma}
\label{lemma_two_task_Reacting_pattern_inequality}
Consider a feasible EFP of an edge $\tau_i \rightarrow \tau_j$ and two jobs $J_{i,q_u}$ and $J_{i,q_w}$
where $q_u < q_w$, their first-reacting jobs specified by the EFP, $J_{j, \overrightarrow{q_u}}$ and $J_{j, \overrightarrow{q_w}}$, satisfy $\overrightarrow{q_u} \leq \overrightarrow{q_w}$.
\end{lemma}
\begin{proof}
    The proof is similar to that of Lemma~\ref{lemma_two_task_Reading_pattern_inequality}.
\end{proof}

