\subsection{Evaluating Graph Communication Pattern}
\label{section_evaluate_gcp}

\begin{definition}[Graph last-reading pattern evaluation]
\label{def: glp evaluate}
    A GLP's evaluation, denoted $\hat{\mathcal{F}}_{\boldsymbol{GLP}}$, is the optimal objective function values obtained by solving an optimization problem (e.g., \eqref{obj_overall} or~\eqref{obj_overall_sf}) with extra schedulability constraints and linear constraints specified by $\boldsymbol{GLP}$.
\end{definition}
For example, if the objective function is given by~\eqref{obj_overall}, then:
\begin{align}
 \label{eq_def_f_g}
\hat{\mathcal{F}}_{\boldsymbol{GLP}} &= 
    \min_{\boldsymbol{O},\boldsymbol{D}}
    \sum_{\mathcal{C} \in \boldsymbol{\mathcal{C}}}
     \max \boldsymbol{\mathcal{F}}_{\mathcal{C}}(\boldsymbol{O},\boldsymbol{D})
\end{align}
\begin{equation}
    \forall \tau_i \in \boldsymbol{\tau}, 0 \leq O_i, \ O_i+R_i \leq D_i,\ D_i \leq D_i^{org}
\label{schedulability_constraint_gcp_eval}
\end{equation}
\begin{equation}
\forall E_k \in \boldsymbol{E},\  \mathcal{I}_{\boldsymbol{GLP}(E_k)}
\end{equation}
\noindent where $\mathcal{I}_{\boldsymbol{GLP}(E_k)}$ denotes the linear inequality constraint~\eqref{eq_ecp_fr} of the edge last-reading pattern $\boldsymbol{GLP}(E_k)$.
GFP's evaluation is defined similarly.

\begin{Example}
\label{example_evaluate_gcp}
    Continue with Example~\ref{Example_setup} and we will evaluate $\glp =\{\elp_{E_0}(0)$,
    $\boldsymbol{ELP}_{E_1}(1)$,
   $\boldsymbol{ELP}_{E_2}(0)\}$ with only \textbf{one} cause-effect chains $\mathcal{C}_0$. Consider a hyper-period of 20 (without considering $\tau_3$), $\tau_2$ has two jobs: $J_{2,0}$ and $J_{2,1}$. All the immediate backward job chains have been decided by $\boldsymbol{GLP}$: 
    $J_{0,-2} \rightarrow  J_{1,-1}  \rightarrow J_{2,0}$,
    $J_{0,2} \rightarrow  J_{1,0}  \rightarrow J_{2,1}$.
    The objective function becomes:
    \begin{align}\min_{\boldsymbol{O},\boldsymbol{D}} \ &
        (\max (wr_{J_{2,0}}-re_{J_{0,-2}}, \ wr_{J_{2,1}}-re_{J_{0,2}} ))
        \label{obj_example}
    \end{align}
    where the reading and writing times are given by Definition~\ref{def_virtual_offset} and~\ref{def_virtual_deadline}. The objective~\eqref{obj_example} can be converted into linear functions with extra artificial variables~\cite{Chen2010AppliedIP}: $a=wr_{J_{2,0}}-re_{J_{0,-2}}$, $b=wr_{J_{2,1}}-re_{J_{0,2}}$, $c=\max (a, b)$:
     \begin{align}
        \min_{\boldsymbol{O},\boldsymbol{D}} \ & c \\
        c \geq a,\  c &  \geq b
    \end{align}
    The ELP constraints of $\boldsymbol{GLP}$ are adopted from Table~\ref{DA_TCP_example}:
    \begin{align}
        D_0+10  &\leq O_1 < D_0  +15 \\
        D_1 -10  &\leq O_2 < D_1  \\
        D_3  &\leq O_1 < D_3 +8
    \end{align}
    The schedulability constraints~\eqref{schedulability_constraint_gcp_eval} remain the same. The optimal solutions of the LP above is $\boldsymbol{O}=\{0,11,6,0\}$, $\boldsymbol{D}=\{1,16,9,40\}$, 
$\hat{\mathcal{F}}_{\boldsymbol{GLP}}=19$.
\end{Example}

\begin{lemma}
\label{lemma_min_max_lp}
    Consider a min-max optimization problem 
    \begin{equation}
        \min_{\textbf{x}} \max (f_1(\textbf{x}), ..., f_n(\textbf{x}))
    \end{equation}
    where $f_i(\textbf{x})$ are linear functions. The problem above can be transformed into a linear programming (LP) problem by introducing extra continuous variables for each $f_i(\textbf{x})$.
\end{lemma}
Lemma~\ref{lemma_min_max_lp} shows that evaluating GLPs is usually equivalent to LP.
An example of how to perform the transformation is shown in Example~\ref{example_evaluate_gcp}. 
% More can be found in~\cite{Chen2010AppliedIP}.

% Given a GLP (GFP), evaluating it (\defref{glp evaluate}) is simple because all the immediate backward (forward) job chains are uniquely decided. Therefore, the objective functions~\eqref{obj_overall} and \eqref{obj_overall_sf} can be transformed into linear functions. 
\begin{theorem}
\label{theorem_glp_lp}
    Evaluating a GLP when the objective function is data age or time disparity is equivalent to solving an LP.
\end{theorem}
\begin{proof}
Since the schedulability constraints~\eqref{schedulability_constraint_gcp_eval} and all the ELP constraints (\defref{elp inequalities}) are linear, we will focus on the objective function in the proof.
Given a GLP, all the immediate backward job chains are uniquely decided. Therefore, the data age of each immediate backward job chain is a linear function of $\textbf{O}$ and $\textbf{D}$ (Definition~\ref{def_length_job_chain}). 

As for time disparity, equation~\eqref{time_disparity_def} can be transformed into linear functions by introducing two continuous artificial variables: $a=\max_{J \in \boldsymbol{J}^{lr,s} }wr_J$, $b=\min_{J \in \boldsymbol{J}^{lr,s}} wr_J$ with extra linear constraints:
    \begin{equation}
        \forall J \in \boldsymbol{J}^{lr,s}, a \geq wr_J, \ b \leq wr_J
    \end{equation}

    The theorem is proved after combining with Lemma~\ref{lemma_min_max_lp}.
\end{proof}

\begin{theorem}
    Evaluating a GFP when the objective function is reaction time is equivalent to solving an LP.
\end{theorem}
\begin{proof}
    Skipped because it is similar to Theorem~\ref{theorem_glp_lp}.
\end{proof}

