\subsection{Comparing Edge Communication Patterns}
\label{section_compare_ecp}
\begin{definition}[ELP Comparison, smaller, $\preccurlyeq $]
\label{def: elp comp}
    Consider two edge last-reading patterns \elpmore{k}{u} and $\boldsymbol{ELP}_{E_k}(w)$ for an edge $E_k=\tau_i \rightarrow \tau_j$. For any job $J_{j,q_j}$, if the job index of its last-reading job in $\boldsymbol{ELP}_{E_k}(u)$ is always less than or equal to those in $\boldsymbol{ELP}_{E_k}(w)$, then $\boldsymbol{ELP}_{E_k}(u) \preccurlyeq \boldsymbol{ELP}_{E_k}(w)$. 
\end{definition}
\begin{definition}[GLP Comparison, smaller, $\preccurlyeq $]
\label{def: glp comp}
    If, for each edge $E_k$, the ELPs of two GLPs satisfy $\boldsymbol{GLP}_{u}(E_k) \preccurlyeq \boldsymbol{GLP}_{w}(E_k)$, then $\boldsymbol{GLP}_{u} 
\preccurlyeq \boldsymbol{GLP}_{w}$.
\end{definition}

Similarly, we can define the comparison for EFP and GFP, except we compare the job index of first-reacting jobs. 


\begin{Example}
    Consider the edge last-reading patterns in Table~\ref{DA_TCP_example}. We have $ \boldsymbol{ELP}_{E_1}(2)$ $\preccurlyeq$ $\boldsymbol{ELP}_{E_1}(1)$ $\preccurlyeq $ $\boldsymbol{ELP}_{E_1}(0)$. 
    However, consider two imaginary ELPs:
    \begin{itemize}
    \item $\boldsymbol{ELP}_{E_1}(3): 
   \{J(1,0)\rightarrow J(2,0), 
    J(1,2) \rightarrow J(2,1)\}$    
    \item $\boldsymbol{ELP}_{E_1}(4):\{J(1,1) \rightarrow J(2,0), 
    J(1,1) \rightarrow J(2,1)\}$
    \end{itemize}
    then neither $\boldsymbol{ELP}_{E_1}(3) \preccurlyeq \boldsymbol{ELP}_{E_1}(4)$ nor $\boldsymbol{ELP}_{E_1}(4) \preccurlyeq \boldsymbol{ELP}_{E_1}(3)$ holds. (Note $\boldsymbol{ELP}_{E_1}(3)$ and $\boldsymbol{ELP}_{E_1}(4)$ are only used for illustration and do not exist in Example~\ref{Example_setup}).
\end{Example}

\subsection{Identifying Non-optimal GLPs (GFPs)}
% Some GLPs (GFPs) are likely to be non-optimal and can be detected by the following theorems.
\begin{theorem}
\label{theorem_DA_chain}
Consider a cause effect chain $\mathcal{C}:\tau_0 \rightarrow ... \rightarrow  \tau_n$ and two feasible graph last-reading patterns $\boldsymbol{GLP}_{u} \preccurlyeq \boldsymbol{GLP}_{w}$.
For any job $J_{n, q_n}$, denote $\tau_0$'s job in $J_{n, q_n}$'s immediate backward job chain in $\boldsymbol{GLP}_{u}$ and $\boldsymbol{GLP}_{w}$ as $J_{0, q^u_0}$ and $J_{0, q^w_0}$, then $q^u_0\leq q^w_0$.
\end{theorem}
\begin{proof}
We prove the theorem by induction. 
Following \defref{glp comp}, the theorem holds when $\mathcal{C}$ has only two tasks.
Next, we assume the theorem holds for the cause-effect chain $\tau_i \rightarrow ... \rightarrow \tau_n$, and prove that it holds for $\tau_{i-1} \rightarrow ... \rightarrow \tau_n$.

Let's denote a job $J_{n,q_n}$'s last reading job at task $\tau_{i}$ under $\boldsymbol{GLP}_{u}$ and $\boldsymbol{GLP}_{w}$ as $J_{i, q^u_i }$ and $J_{i, q^w_i }$. We know
$q^u_i \leq q^w_i $ based on the induction assumption. 
Next, at task $\tau_{i-1}$, let's denote 
the last-reading job of $J_{i, q^u_i}$ under $\boldsymbol{GLP}_{u}$ as $J_{i-1, \overleftarrow{q}^u_i}$,
the last-reading job of $J_{i, q^w_i}$ under $\boldsymbol{GLP}_{u}$ as $J_{i-1, \overleftarrow{q}^{wu}_i}$,
the last-reading job of $J_{i, q^w_i}$ under $\boldsymbol{GLP}_{w}$ as $J_{i-1, \overleftarrow{q}^w_i}$. 
Then we have $\overleftarrow{q}^u_i \leq \overleftarrow{q}^{wu}_i $ from Lemma~\ref{lemma_two_task_Reading_pattern_inequality}, and $\overleftarrow{q}^{wu}_i \leq \overleftarrow{q}^w_i $ from the assumption that $\boldsymbol{GLP}_{u} \preccurlyeq \boldsymbol{GLP}_{w}$ and \defref{elp comp}. Therefore, $\overleftarrow{q}^u_i \leq \overleftarrow{q}^w_i$, which proves the induction.
\end{proof}

\begin{theorem}
\label{theorem_RT_chain}
Consider a cause-effect chain $\mathcal{C}:\tau_0 \rightarrow ... \rightarrow  \tau_n$, and two feasible graph first-reacting patterns $\boldsymbol{GFP}_{u} 
\preccurlyeq \boldsymbol{GFP}_{w}$.
Now consider a job $J_{0, q_0}$ of $\tau_0$, 
denote $\tau_n$'s job in $J_{0, q_0}$'s immediate forward job chain in $\boldsymbol{GFP}_{u}$ and $\boldsymbol{GFP}_{w}$ as $J_{n, q_n^u}$ and $J_{n, q_n^w}$, then $q_n^u \leq q_n^w$.
\end{theorem}
\begin{proof}
    Skipped because it is similar to Theorem~\ref{theorem_DA_chain}.
\end{proof}

\begin{lemma}
\label{theorem_compare_mn_bound}
Continue with Theorem~\ref{theorem_DA_chain}, denote the immediate backward job chain that terminates at $J_{n,q_n}$ in $\boldsymbol{GLP}_u$ and $\boldsymbol{GLP}_w$ as $\mathcal{C}^J_u$ and $\mathcal{C}^J_w$. Then we have $\text{Len}(\mathcal{C}^J_w) -\text{Len}(\mathcal{C}^J_u) \leq B_{\mathcal{C}}$, where $B_{\mathcal{C}}\leq T_n + T_0$.
\end{lemma}
\begin{proof}
Let's first introduce the related notations:
\begin{align}
  \text{Len}(\mathcal{C}^J_w) 
  = &wr^w_{J_{n,q_n}} - re^w_{J_{0,q_0^w}} \\ 
    \text{Len}(\mathcal{C}^J_u) =
    & wr^u_{J_{n,q_n}} - re^u_{J_{0,q_0^u}}\\
    \text{Len}(\mathcal{C}^J_w) -\text{Len}(\mathcal{C}^J_u) 
    = &(wr^w_{J_{n,q_n}}-wr^u_{J_{n,q_n}}) + \\ 
    &-(re^w_{J_{0,q_0^w}} - re^u_{J_{0,q_0^u}})
\end{align}
    Since $\boldsymbol{GLP}_u$ and $\boldsymbol{GLP}_w$ are feasible and $q_0^u \leq q_0^w$, we know $re^u_{J_{0, q_0^u}} < re^w_{J_{0, q_0^w}}$ if $q_0^u < q_0^w$, 
    and $|re^w_{J_{0, q_0^w}} - re^u_{J_{0, q_0^u}} | \leq T_0$ if $q_0^u = q_0^w$. Similarly, $wr^w_{J_{n,q_n}}-wr^u_{J_{n,q_n}} \leq T_n$. Therefore, $\text{Len}(\mathcal{C}^J_w) -\text{Len}(\mathcal{C}^J_u) \leq T_n+T_0$.
\end{proof}
% The bound $B_{\mathcal{C}}$ above can be improved if response time analysis is available based on the proof process.

\begin{theorem}
\label{theorem_bound_single_chain}
Continue with Theorem~\ref{theorem_DA_chain},  the worst-case data age of $\boldsymbol{GLP}_u$ cannot be smaller than $\boldsymbol{GLP}_w$ by more than $B_{\mathcal{C}}$.
\end{theorem}
\begin{proof}
    % Since Lemma~\ref{theorem_compare_mn_bound} holds for each immediate backward job chain, it also holds for the longest one. 
    Let's use two vectors $\textbf{U}$ and $\textbf{W}$ to denote the length of the immediate backward job chains in $\boldsymbol{GLP}_u$ and $\boldsymbol{GLP}_w$, respectively. For any job $J_{n, q_n}$, let's use $\textbf{U}_{q_n}$ and $\textbf{W}_{q_n}$ to denote the length of the job chains that terminate at $J_{n, q_n}$. Following Lemma~\ref{theorem_DA_chain}, we have $\textbf{W}_{q_n} - \textbf{U}_{q_n} \leq B_{\mathcal{C}}$.
    Next, let's denote the index of the longest job chain in $\textbf{U}$ and $\textbf{W}$ as $k_u$ and $k_w$. Then we have $\Delta = \textbf{U}_{k_u} - \textbf{U}_{k_w} \geq 0$. Therefore,
    \begin{equation}
        \textbf{W}_{k_w}-\textbf{U}_{k_u} = \textbf{W}_{k_w}-(\textbf{U}_{k_w} + \Delta ) \leq  B_{\mathcal{C}} - \Delta \leq  B_{\mathcal{C}}
    \end{equation}
\end{proof}
\begin{theorem}
\label{theorem_bound_multi_chain}
    Consider a DAG with multiple cause-effect chains, then Theorem~\ref{theorem_DA_chain} and~\ref{theorem_bound_single_chain} hold for each cause-effect chain.
\end{theorem}
\begin{proof}
    Because the derivation of the performance bound of each cause-effect chain does not interfere with each other.
\end{proof}


\begin{Example}
In Example~\ref{Example_setup}, consider two graph last-reading patterns $\boldsymbol{GLP}_u = \{ \boldsymbol{ELP}_{E_0}(0),
    \boldsymbol{ELP}_{E_1}(1),
    \boldsymbol{ELP}_{E_2}(1)\}$ and  
    $\boldsymbol{GLP}_w = \{\boldsymbol{ELP}_{E_0}(0),
    \boldsymbol{ELP}_{E_1}(1),
    \boldsymbol{ELP}_{E_2}(0)\}$. 
    We have $\boldsymbol{GLP}_u \preccurlyeq \boldsymbol{GLP}_w$ following \defref{glp comp}. 
    Hence, based on Theorem~\ref{theorem_bound_single_chain},
    \glpevalOneindex{w} (\ie the data age after optimization) is guaranteed to be smaller or no larger than $B_{\mathcal{C}}$ (Lemma~\ref{theorem_compare_mn_bound}) when compared to \glpevalOneindex{u}. 
\end{Example}


\subsection{Skip Partial Graph Communication Patterns}
Next, we generalize Theorem~\ref{theorem_DA_chain} to partial graph communicating patterns.
When evaluating a partial GLP's data age, we only consider the partial cause-effect chains formulated by the edges contained in the partial GLP. If the partial cause-effect chain does not include the source task of the complete chain, we consider its data age to be 0.
\begin{Example}
Consider a cause-effect chain 
$\tau_0 \rightarrow \tau_1 \rightarrow \tau_2$ 
and two partial GLPs $\boldsymbol{pGLP}_1=\{ \boldsymbol{ELP}_{E_0}(1) \}$ and $\boldsymbol{pGLP}_2=\{\boldsymbol{ELP}_{E_1}(2) \}$,
then the data age evaluation of $\boldsymbol{pGLP}_1$ only considers the cause-effect chain $\tau_0 \rightarrow \tau_1$. The data age of $\boldsymbol{pGLP}_2$ is 0 because it does not contain the source task $\tau_0$.
\end{Example}

\begin{theorem}
\label{theorem_partial_dart_chain}
    Theorem~\ref{theorem_DA_chain} applies to partial graph communication patterns.
\end{theorem}
\begin{proof}
    Skipped due to being similar to Theorem~\ref{theorem_DA_chain}.
\end{proof}

\begin{definition}[Contain, $\subset$]
\label{def: contain}
    Consider two partial GLPs $\boldsymbol{pGLP}_u$ and $\boldsymbol{pGLP}_w$. We say $\boldsymbol{pGLP}_w$ contains $\boldsymbol{pGLP}_u$, denoted as $\boldsymbol{pGLP}_u \subset \boldsymbol{pGLP}_w$, if:
    \begin{equation*}
        \forall \boldsymbol{pGLP}_u(E_k) \in \boldsymbol{pGLP}_u,  \ \boldsymbol{pGLP}_u(E_k)=\boldsymbol{pGLP}_w(E_k)
    \end{equation*}
\end{definition}
\begin{Example}
    Consider three partial graph last-reading patterns $\boldsymbol{pGLP}_u = \{ \boldsymbol{ELP}_{E_0}(0)\}$, $\boldsymbol{pGLP}_w = \{ \boldsymbol{ELP}_{E_0}(0),$
    $\boldsymbol{ELP}_{E_1}(1)\}$ and $\boldsymbol{pGLP}_k = \{ \boldsymbol{ELP}_{E_0}(1)\}$. Then $\boldsymbol{pGLP}_w$ contains $\boldsymbol{pGLP}_u$, but does not contain $\boldsymbol{pGLP}_k$.
\end{Example}

% Here is another set of theorems that allows us to skip some non-optimal partial graph communication patterns.
\begin{theorem}
\label{incomplete_chain_worse_theorem}
    Consider two sub-chains $\mathcal{C}_{1}=\tau_0 \rightarrow ... \rightarrow \tau_k$ and $\mathcal{C}_{2}=\tau_{k+1} \rightarrow ... \rightarrow \tau_n$ of a cause-effect chain $\mathcal{C}=\mathcal{C}_{1} \rightarrow \mathcal{C}_{2}$. 
    Given the same task set schedule, the worst-case data age of $\mathcal{C}_{1}$ is no larger than $\mathcal{C}$.
\end{theorem}
\begin{proof}
    This theorem can be proved following the compositional theorem and its generalization in G{\"u}nzel~\etal~\cite{Gnzel2021TimingAO}.
\end{proof}

\begin{theorem}
\label{theorem_partial_gcp}
Consider two partial GLPs $\boldsymbol{pGLP}_u \subset \boldsymbol{pGLP}_w$, the maximum data age evaluated in $\boldsymbol{pGLP}_w$ (following \defref{glp evaluate}) is no less than $\boldsymbol{pGLP}_u$.
\end{theorem}
\begin{proof}
    Direct results of Theorem~\ref{incomplete_chain_worse_theorem} because the cause-effect chains in $\boldsymbol{pGLP}_w$ have more tasks.
\end{proof}


\subsection{DART-specific Symbolic Optimization Algorithm}
\label{section_dart_symbopt}
The theorems above can be summarized as follows:
\begin{corollary}
\label{theormSummary}
Consider an optimization problem that minimizes data age.
A partial GLP $\boldsymbol{pGLP}_i$ and all the other partial GLPs that contain $\boldsymbol{pGLP}_i$ can be skipped if one of the evaluated partial GLP $\boldsymbol{pGLP}_j$ satisfies (\cref{theorem_partial_dart_chain,incomplete_chain_worse_theorem,theorem_partial_gcp}): 
\begin{itemize}
    \item $\boldsymbol{pGLP}_j$'s evaluation is smaller than $\boldsymbol{pGLP}_i$;
    \item $\boldsymbol{pGLP}_i$ is smaller than $\boldsymbol{pGLP}_j$ (\defref{glp comp});
\end{itemize} 
\end{corollary}

\noindent \textbf{ELP Enumeration Order.} 
ELPs need to be ordered appropriately to fully utilize the symbolic operations.
When selecting edges to add to GLPs, select the edges that are closer to the source tasks first. 
After selecting an edge, first add its largest ELP (follow \defref{elp comp}) into the GLP when minimizing data age (smallest EFP first for reaction time optimization). 

\noindent \textbf{Pseudocode.} The pseudocode for data age minimization problem is shown in Algorithm~\ref{alg_opt_skipped}.
The vector $\textbf{best\_yet\_obj}$ denotes the worst-case data age of each cause-effect chain evaluated by the best-known GLP. 
In \alglineref{GetBestPossibleObj}, the implementation of the function $\textbf{GetBestPossibleObj}$ follows \defref{glp evaluate} except only considering the sub-chains contained in $\textbf{P}_{ite}$.
The $\geq$ operator in \alglineref{compareBestYetObj} requires element-wise greater than to hold.
In \alglineref{worsePatterns}, $\textbf{worsePatterns}$ is implemented as a First-In-First-Out queue, because recently visited GLPs have more common ELPs with the next GLP, increasing the likelihood of triggering the skip conditions in Corollary~\ref{theormSummary}. 
The capacity size is experimentally set to 50: a larger capacity incurs more computation overhead when a communication pattern cannot be skipped, while a smaller size implies fewer skipped patterns.
In \alglineref{RemoveWorseELP}, the function \textbf{RemoveWorseELP} removes an unvisited ELP from $\textbf{ELP}\_\textbf{Set}$ if adding the ELP to $\textbf{P}_{ite}$ will make $\textbf{P}_{ite}$ perform worse (evaluated by Corollary~\ref{theormSummary}) than at least one partial GLP in $\textbf{worse}\_\textbf{patterns}$. This function significantly speeds up symbolic optimization by allowing the skipping of partial GLPs, eliminating the need to visit and evaluate all partial and complete GLPs that contained the skipped partial GLP.

\begin{algorithm}[ht!]
\SetAlgoLined
\SetKwInOut{a}{b}
\caption{\textbf{GLPSymbOpt}}
\label{alg_opt_skipped}

\KwIn{ DAG $\textbf{G} = (\boldsymbol{\tau}, \textbf{E})$, GLP $\textbf{P}_{ite}=\{ \}$, $\textbf{best\_yet\_obj}=\{Inf,...,Inf\}$, $\textbf{worsePatterns}=\{ \}$, unvisited$\_$Edge $E$=$\textbf{E}(0)$}
\KwOut{$\textbf{best\_yet\_obj}$}
\If{$\textbf{P}_{ite}$ is complete}{
Solve problem~\eqref{eq_def_f_g} and Update $\textbf{best\_yet\_obj}$\\
\Return 
}

$\textbf{ELP$\_$Set} = \textbf{GetAllELP}(E)$\\
% $\textbf{ELP$\_$Set} = \textbf{ExcludeInfeasibleELPs}(\textbf{ELP$\_$Set}, \textbf{P}_{ite} )$

% \For{$( ELP \ \textbf{in} \ \textbf{ELP$\_$Set})$}
\While{$\textbf{ELP$\_$Set} \text{ is not empty}$}
{
    $ELP=\textbf{ELP$\_$Set.}\textbf{Pop\_front()}$\\
    $\textbf{P}_{ite}\textbf{.}\textbf{Insert}(ELP)$ \\
    \If{$\textbf{P}_{ite}$ is feasible 
    } 
    { 
         $\textbf{obj}= \textbf{GetBestPossibleObj}(\textbf{P}_{ite}) $ \label{line: GetBestPossibleObj} \\
        \eIf{$\textbf{obj} \ \boldsymbol{\geq} \textbf{best\_yet\_obj} $ \label{line: compareBestYetObj} } 
        {
            $\textbf{worsePatterns}\textbf{.}\textbf{push\_back}(\textbf{P}_{ite})$ \label{line: worsePatterns} \\
            \If{$\textbf{worsePatterns}\textbf{.}\textbf{size()} > 50$}{           \textbf{worsePatterns}\textbf{.}\textbf{pop$\_$front()}
            }

        }
        {
            $\textbf{GLPSymbOpt}(\textbf{G}, \textbf{P}_{ite}, \textbf{best\_yet\_obj}$, $\textbf{worsePatterns}, \textbf{NextUnvisitedEdge}(\textbf{P}_{ite}))$
        }

        $\textbf{ELP$\_$Set}\textbf{.}\textbf{RemoveWorseELP}(\textbf{worsePatterns})$  \label{line: RemoveWorseELP}  
    }
    $\textbf{P}_{ite}\textbf{.}\textbf{Erase}(ELP)$ \\
}
\end{algorithm}
\begin{Example}
    In Example~\ref{Example_setup}, the edge iteration order is $E_0 \rightarrow E_2 \rightarrow E_1$ because $E_0$ and $E_2$ contain the source tasks in cause-effect chains. 
    The first GLP to evaluate is $\boldsymbol{GLP}_0=$ $\{\boldsymbol{ELP}_{E_0}(0),$$
    \boldsymbol{ELP}_{E_2}(0),$$
    \boldsymbol{ELP}_{E_1}(0)\}$, which is infeasible; The second GLP to try is $\boldsymbol{GLP}_1$= $\{\boldsymbol{ELP}_{E_0}(0),$ $\boldsymbol{ELP}_{E_2}(0),$$\boldsymbol{ELP}_{E_1}(1)\}$, which is feasible. Therefore, any GLPs smaller than $\boldsymbol{GLP}_1$ will be skipped based on Theorem~\ref{theorem_bound_single_chain}.
    After that, only 3 GLPs have to be evaluated: 
    $\boldsymbol{GLP}_2=$ 
    $\{$\elpmore{0}{1}, \elpmore{2}{0}, \elpmore{1}{0}$\}$, 
    $\boldsymbol{GLP}_3=\{$\elpmore{0}{0}, \elpmore{2}{1}, \elpmore{1}{0}$\}$
    and $\boldsymbol{GLP}_4$$=\{$\elpmore{0}{1}, \elpmore{2}{1}, \elpmore{1}{0}$\}$.
    However, neither is feasible. 
    As a result, the number of complete GLPs to evaluate decreases from 36 in Example~\ref{example_gcp_bf} to only 1, although there are 4 infeasible GLPs to skip.
\end{Example}


\begin{theorem}
 \label{theorem_skip_perf_bound}
 The difference between solutions found by Algorithm~\ref{alg_opt_skipped} and the optimal solution to problem~\ref{obj_overall} is upper-bounded by $\sum_{\mathcal{C} \in \boldsymbol{\mathcal{C}}} B_{\mathcal{C}}$, where $B_{\mathcal{C}}$ is given by Lemma~\ref{theorem_compare_mn_bound}.
\end{theorem}
\begin{proof}
We prove the theorem under data age optimization. Reaction time optimization can be performed similarly.
    Let's denote the optimal GLP found by Algorithm~\ref{alg_opt_skipped} as $\boldsymbol{GLP}^{Alg\ref{alg_opt_skipped}*}$, the optimal GLP to problem~\ref{obj_overall} as $\boldsymbol{GLP}^{*}$. Furthermore, we divide all the possible complete GLPs into two sets: $\boldsymbol{S}^{eval}$ and $\boldsymbol{S}^{skip}$, which denote the complete GLPs evaluated during Algorithm~\ref{alg_opt_skipped} and those skipped. We know $\boldsymbol{GLP}^{Alg\ref{alg_opt_skipped}*} \in \boldsymbol{S}^{eval}$. If $\boldsymbol{GLP}^{*} \in \boldsymbol{S}^{eval}$, then Algorithm~\ref{alg_opt_skipped} finds the optimal solutions because Algorithm~\ref{alg_opt_skipped} will select the best GLPs within $\boldsymbol{S}^{eval}$.

    If $\boldsymbol{GLP}^{*} \in \boldsymbol{S}^{skip}$, then $\boldsymbol{GLP}^{*}$ is skipped either based on Theorem~\ref{theorem_bound_single_chain} (performance bound is provided by Theorem~\ref{theorem_bound_multi_chain}), or based on \alglineref{worsePatterns} in Algorithm~\ref{alg_opt_skipped} ($\boldsymbol{GLP}^{*}$ cannot achieve better performance than $\boldsymbol{GLP}^{Alg\ref{alg_opt_skipped}*}$). Therefore, the theorem is proved. 
    % \dong{Not clear for the latter case.}
\end{proof}


\subsection{Computation Efficiency}
A simple worst-case complexity analysis when optimizing the data age or time disparity is given as follows:
\begin{equation}
    O(\textbf{E})= {\textstyle \prod_{E \in \boldsymbol{E}}} \ |\textbf{ELP}_{E}|
\end{equation}
where $ \boldsymbol{E}$ denotes the edges that appear in the objective function, $|\cdot|$ denotes the size of a set. 
Reaction time optimization has a similar complexity.
The analysis is pessimistic because it is difficult to analyze the improvements brought by the symbolic operation or the back-tracking algorithms, though they can usually bring significant speed-up. 
% If the system has a high utilization, the backtracking algorithm is expected to run much faster because only a few GCPs are feasible.


\section{Generalizations and Limitations}
\label{section_application}
\subsection{Sporadic Tasks Optimization}

Our optimization algorithms can work with cause-effect chains that contain sporadic tasks, \ie tasks released non-periodically.
With the help of the compositional theorem proposed in~\cite{Gnzel2021TimingAO}, the cause-effect chain can be separated into several sub-chains where some sub-chains do not contain periodic tasks. The sub-chains with only periodic tasks can still be optimized with the algorithm proposed in this paper. However, notice that evaluating and optimizing time disparity for sporadic tasks may not be easily applicable.

\subsection{Other Objective Functions and Schedulability Analysis}
\label{section_more_application_schedulability}

The backtracking algorithm in Section~\ref{section_opt_skip} works with many types of objective functions and their combination. 
If these objective functions can be transformed into linear functions such as DART, then optimality is guaranteed with good runtime speed; 
otherwise, the algorithm may still be applicable (e.g., time disparity jitter), though without the optimality guarantee. 
In the latter case, nonlinear optimization algorithms~\cite{Wang2023RTAS, Wang2024AGA} may also be considered.
% The symbolic optimization algorithm in Section~\ref{section_optimization} only provides bounded suboptimality when the objective function only contains data age or reaction time.


\subsection{Pessimistic RTA and Second Step Optimization}
\label{sec: limitation_solution}
It is difficult to directly adopt the exact schedulability analysis~\cite{Tindell1994ADDINGTT, Palencia1998SchedulabilityAF, Redell2002CalculatingEW} when optimizing the virtual offset and virtual deadline because of their discrete and nonlinear forms. Therefore, we can only guarantee optimality with the schedulability analysis method used during optimization.

A potential solution is performing a second optimization step to optimize only the virtual offset based on the exact response time. 
The exact response time only depends on the virtual offset and can usually be easily obtained. Therefore, we can utilize the exact response time to optimize the virtual deadline to improve performance further.
A limitation is that it can only find optimal solutions within the current GCP constraints.
Therefore, in experiments, we utilize the heuristic proposed in Maia~\etal~\cite{Maia2023ReducingEL} for the second optimization step if the objective functions are reaction time or data age; 
we can optimize the virtual deadline following \defref{glp evaluate} for time disparity and jitter optimization.

% weaker platform-independent property (let's keep the commented text there)
% Notice: this is not our optimization algorithm's limitation
% fLET provides a weaker ``platform-independent'' guarantee than the standard LET because finding the optimal virtual offset and virtual deadline relies on schedulability analysis, and so also relies on computation platforms.
% However, since the optimization process of fLET is usually performed based on pessimistic schedulability analysis, it provides some ``robustness'' on platform configurations, i.e., when computation platforms become faster or not too slow, the results can still be adopted if the system passes the exact schedulability test.





\section{Experimental Results and Discussion}
\label{experiment_section}
The optimization framework was implemented in C++ and tested on a computing cluster (AMD EPYC 7702 CPU). 
The following baseline methods are roughly ordered from least to most effective based on some experiment performance:
\begin{itemize}[leftmargin=*]
    \item DefLET, the default LET model.
    \item Martinez18, an offset optimization method~\cite{Martinez2018AnalyticalCO} for LET.
    \item Bradatsch16, it shrinks the length of LET interval to the worst-case response time; the offset is $0$~\cite{Bradatsch2016DataAD}.
    \item Implicit, implicit communication following~\cite{Hamann2017CommunicationCD}.
    % \item Martinez18$\_$Alg1, following the LET model used in~\cite{Martinez2018AnalyticalCO}, but optimized by Algorithm~\ref{alg_opt_skipped}.
    \item Maia23, it uses the smallest relative start time and biggest relative finish time of each task as the LET interval~\cite{Maia2023ReducingEL}. 
    We did not compare their JLD optimization algorithm because it changes the scheduling algorithm.
    \item fLET$\_$GCP\_Enum, from Section \ref{section_opt_bf}.
    \item fLET$\_$GCP\_Backtracking\_LP, from Section~\ref{section_opt_skip}. 
    \item fLET$\_$GCP\_SymbOpt, Algorithm~\ref{alg_opt_skipped}.
    \item fLET$\_$GCP\_Extra, from \secref{limitation_solution}.
\end{itemize}
All the involved LP problems are solved by CPLEX~\cite{cplex2009v12}. The full experiments can be reproduced following the repository: \href{https://github.com/zephyr06/LET_OPT}{$\text{https:github.com/zephyr06/LET\_OPT}$}.

\emph{DBP is not included in our comparison, as it is proven to perform worse than implicit communication theoretically~\cite{Tang2023ComparingCP}.}

In experiments, the task set is scheduled by the rate-monotonic algorithm. 
% A safe response time analysis (RTA). 
A safe response time analysis (RTA) is used to obtain the response time $R_i$ for task $\tau_i$~\cite{Joseph1986FindingRT}:
\begin{equation}
    R_i = C_i +\sum_{j \in \text{hp}(i)} \ceil{\frac{R_i}{T_j}}{C_j}
    \label{rta_LL}
\end{equation}
where $\text{hp}(i)$ denotes the tasks with higher priority than $\tau_i$. 

The time limit for optimizing one task set is 1000 seconds. If not time out, Martinez18 finds optimal offset assignments; fLET\_GCP optimization algorithms find the optimal virtual offset and virtual deadline with respect to the RTA~\eqref{rta_LL}.

To maximize the chance of finding a feasible solution within a limited time, the GCP optimization algorithms first evaluate the GCP of the default LET; after that, they follow the searching order mentioned in Section~\ref{section_dart_symbopt}.

