\begin{Definition}[Transitive closure]
    For any set of inferences $\mathbb{L}$, the transitive closure of $\mathbb{L}$, noted $T(\mathbb{L})$, is the least set $\mathbb{L}' \supseteq \mathbb{L}$ such that: 
    $$ \text{If} \ (\exists\Delta \neq \emptyset) \ \Delta \Rightarrow \phi \in \mathbb{L}' \ \text{and} \ (\forall\delta \in \Delta) \ \Gamma \Rightarrow \delta \in \mathbb{L}', \ \text{then} \ \Gamma \Rightarrow \phi \in \mathbb{L}'.$$
\end{Definition}


\noindent
We need to ensure that the operator is a closure operator.\footnote{A function $C: \mathcal{P}(A) \to \mathcal{P}(A)$ is said to be a closure operator on $A$ if
\begin{itemize}
\itemsep0em
    \item[--] For all $X \subseteq A$, $X \subseteq C(X)$,
    \item[--] For all $X, Y \subseteq A$, if $X \subseteq Y$, then $C(X) \subseteq C(Y)$,
    \item[--] For all $X \subseteq A$, $CC(X)=C(X)$.
\end{itemize}} This is guaranteed by the following fact.

\begin{fact}
$T$ is a closure operator.
\end{fact}
\begin{proof}
\quad
    \begin{itemize}
        \item[--] The inclusion $\mathbb{L} \subseteq T(\mathbb{L})$ for all $\mathbb{L}$ follows directly from the definition of transitive closure.

    \item[--] Turning to the monotonicity of $T$, assume that $\mathbb{L} \subseteq \mathbb{L}'$. Then $\mathbb{L} \subseteq \mathbb{L}' \subseteq T(\mathbb{L}')$. So, $T(\mathbb{L}')$ is an extension of $\mathbb{L}$ such that for all $\Delta \neq \emptyset, \text{if} \ \Delta \Rightarrow \phi \in T(\mathbb{L}') \ \text{and} \ \Gamma \Rightarrow \delta \in T(\mathbb{L}') \ \text{for all} \ \delta \in \Delta, \ \text{then} \ \Gamma \Rightarrow \phi \in T(\mathbb{L}')$. By definition, $T(\mathbb{L})$ is the least extension of $\mathbb{L}$ satisfying such a property, so $T(\mathbb{L}) \subseteq T(\mathbb{L}')$.


    %Let $T(\mathbb{L}_2)$ the transitive closure of $\mathbb{L}_2$. Since $\mathbb{L}_1 \subseteq \mathbb{L}_2$, $$\text{for all} \ \Delta \neq \emptyset, \text{if} \ \Delta \Rightarrow \phi \in \mathbb{L}' \ \text{and} \ \Gamma \Rightarrow \delta \in \mathbb{L}' \ \text{for all} \ \delta \in \Delta, \ \text{then} \ \Gamma \Rightarrow \phi \in \mathbb{L}'.$$

    \medskip

   \item[--] To show that $T(T(\mathbb{L}))=T(\mathbb{L})$, it suffices to establish the left-to-right inclusion, as the reverse direction follows directly from the previously proven fact that $\mathbb{L} \subseteq T(\mathbb{L})$ for all $\mathbb{L}$. 
   Trivially, $T(\mathbb{L})$ is an extension of itself and is such that for all $\Delta \neq \emptyset, \text{if} \ \Delta \Rightarrow \phi \in T(\mathbb{L}) \ \text{and} \ \Gamma \Rightarrow \delta \in T(\mathbb{L}) \ \text{for all} \ \delta \in \Delta, \ \text{then} \ \Gamma \Rightarrow \phi \in T(\mathbb{L})$. Now, by definition, $T(T(\mathbb{L}))$ is the least extension of $T(\mathbb{L})$ with such a property, hence $T(T(\mathbb{L})) \subseteq T(\mathbb{L})$.
    \end{itemize}
\end{proof}


\begin{Definition}[Dual transitive closure]
    For any set of inferences $\mathbb{L}$, the dual transitive closure of $\mathbb{L}$, noted $T^d(\mathbb{L})$, is the greatest set $\mathbb{L}' \subseteq \mathbb{L}$ such that:
    $$ \text{If} \ (\exists\Delta \neq \emptyset) \ \Delta \Rightarrow \phi \not\in \mathbb{L}' \ \text{and} \ (\forall\delta \in \Delta) \ \Gamma \Rightarrow \delta \not\in \mathbb{L}', \ \text{then} \ \Gamma \Rightarrow \phi \not\in \mathbb{L}'.$$
\end{Definition}


Next, we show in what sense this notion of dual transitive closure is dual to the notion of transitive closure. The proposition hereinafter eventually expresses the duality of the transitive closure operator and the dual transitive closure operator. The two operators are interdefinable through the set-theoretical notion of absolute complement.

\begin{proposition}\label{prp:duaTr}
    \begin{align*}
    T^{d}(\mathbb{L}) &= \overline{T(\overline{\mathbb{L}})}\\
    T(\mathbb{L}) &= \overline{T^{d}(\overline{\mathbb{L}})}.
    \end{align*}
\end{proposition}

\begin{proof}
For any set of inferences $\mathbb{L}$, let $P(\mathbb{L})$ express that if $(\exists\Delta \neq \emptyset) \ \Delta \Rightarrow \phi \in \mathbb{L}$ and $(\forall\delta \in \Delta) \ \Gamma \Rightarrow \delta \in \mathbb{L}$, it follows that $\Gamma \Rightarrow \phi \in \mathbb{L}$.  

Starting with the first identity, by definition, $T(\overline{\mathbb{L}})$ is the least element of the set  
\[
\lbrace \mathbb{L}' \mid \overline{\mathbb{L}} \subseteq \mathbb{L}', \ P(\mathbb{L}') \rbrace.
\]  
Equivalently, $\overline{T(\overline{\mathbb{L}})}$ is the greatest element of  
\[
\lbrace \overline{\mathbb{L}'} \mid \overline{\mathbb{L}} \subseteq \mathbb{L}', \ P(\mathbb{L}') \rbrace,
\]  
which coincides with  
\[
\lbrace \mathbb{L}'' \mid \mathbb{L}'' \subseteq \mathbb{L}, \ P(\overline{\mathbb{L}''}) \rbrace.
\]  
That is, $\overline{T(\overline{\mathbb{L}})}$ is the largest subset $\mathbb{L}''$ of $\mathbb{L}$ such that if $(\exists\Delta \neq \emptyset) \ \Delta \Rightarrow \phi \not\in \mathbb{L}''$ and $(\forall\delta \in \Delta) \ \Gamma \Rightarrow \delta \not\in \mathbb{L}''$, then $\Gamma \Rightarrow \phi \not\in \mathbb{L}''$.
Therefore, we conclude that $T^d(\mathbb{L}) = \overline{T(\overline{\mathbb{L}})}$. The other identity can be proved similarly.
\end{proof}

\enlargethispage{15pt}

It can now be checked that $T^d$ is an \textit{interior operator}.\footnote{A function $I: \mathcal{P}(A) \to \mathcal{P}(A)$ is an interior operator if it satisfies
\begin{itemize}
\itemsep0em
    \item[--] For all $X \subseteq A$, $I(X) \subseteq X$,
    \item[--] For all $X, Y \subseteq A$, if $X \subseteq Y$, then $I(X) \subseteq I(Y)$,
    \item[--] For all $X \subseteq A$, $II(X)=I(X)$.
\end{itemize}}

\begin{fact}
    $T^{d}$ is an interior operator.
\end{fact}
\begin{proof}
\quad
    \begin{itemize}
        \item[--] Since $T$ is a closure operator, $\overline{\mathbb{L}} \subseteq T(\overline{\mathbb{L}})$, and thus $T^{d}(\mathbb{L}) = \overline {T(\overline{\mathbb{L}})} \subseteq \overline{\overline{\mathbb{L}}} = \mathbb{L}$ by Proposition \ref{prp:duaTr}.
        \item[--] Assume $\mathbb{L} \subseteq \mathbb{L}'$. Then $\overline{\mathbb{L}'} \subseteq \overline{\mathbb{L}}$, so $T(\overline{\mathbb{L}'}) \subseteq T(\overline{\mathbb{L}})$ since $T$ is a closure operator, and hence $T^{d}(\mathbb{L}) = \overline{T(\overline{\mathbb{L}})} \subseteq \overline{T(\overline{\mathbb{L}'})} = T^{d}(\mathbb{L}')$ by Proposition \ref{prp:duaTr}.
        \item[--] Since $T$ is a closure operator, $T(\overline{\mathbb{L}}) \subseteq T(T(\overline{\mathbb{L}}))$, so $\overline{T(T(\overline{\mathbb{L}}))} \subseteq \overline{T(\overline{\mathbb{L}})}$. But by Proposition \ref{prp:duaTr}, $T^{d}(T^{d}(\mathbb{L})) = \overline{T(\overline{T^{d}(\mathbb{L})})} = \overline{T(T(\overline{\mathbb{L}}))}$, therefore $T^{d}(T^{d}(\mathbb{L})) \subseteq \overline{T(\overline{\mathbb{L}})} = T^{d}(\mathbb{L})$. 
    \end{itemize}
\end{proof}

With these definitions and facts at our disposal, we are equipped to offer an exact characterization of $\mathbb{ST}$ as the transitive closure of $\mathbb{SS} \cup \mathbb{TT}$, and $\mathbb{TS}$ as the dual transitive closure of $\mathbb{SS} \cap \mathbb{TT}$.

\section{Characterization of $\mathbb{ST}$ and $\mathbb{TS}$}\label{c}

Our aim in this section is to characterize $\mathbf{st}$- and $\mathbf{ts}$-logics by combining $\mathbf{ss}$- and $\mathbf{tt}$-logics. We first establish that the union of $\mathbb{SS}$ and $\mathbb{TT}$ does not yield $\mathbb{ST}$. We then prove that the transitive closure of their union actually coincides with $\mathbb{ST}$ (and hence with $\mathbb{CL}$). A dual version of this result is then proved for the characterization of $\mathbf{ts}$-logics: their set of valid inferences is obtained by applying the dual transitive closure to the intersection of the sets of $\mathbf{tt}$- and $\mathbf{ss}$-valid inferences.
Importantly, all the results in this section assume that the sets of inferences are defined using \textit{BNM} schemes, possibly different from one logic to another. We start by restating the following results  proven in \cite{da2023three}:

\begin{theorem}[\citealp{da2023three}]\label{thm:cl=st}
For every BNM scheme, $\mathbb{ST} = \mathbb{CL}$.
\end{theorem}

\begin{theorem}[\citealp{da2023three}]\label{thm:empty=st}
For every BNM scheme, $\mathbb{TS} = \emptyset$.
\end{theorem}

The first theorem shows that any $\bf{st}$-logic based on a BNM scheme collapses with classical logic. The second one that any $\bf{ts}$-logic based on a BNM scheme is empty (i.e. invalidate every inference). 

We now show that the union of the sets of inferences $\mathbb{SS}$ and $\mathbb{TT}$, obtained from the $\mathbf{ss}$ and $\mathbf{tt}$ standards, differs from $\mathbb{ST}$. To establish this, we provide a counterexample: an inference that is $\mathsf{ST}$-valid but neither $\mathsf{SS}$- nor $\mathsf{TT}$-valid. First, we state the following relation between these sets.

\begin{fact}\label{fct:subs}
    Let $\mathbb{SS}, \mathbb{TT}$ and $\mathbb{ST}$ be defined by (possibly different) BNM schemes. Then
    \begin{itemize}
    \itemsep0em
        \item $\mathbb{SS}, \mathbb{TT} \subseteq \mathbb{ST}$,
        \item $\mathbb{SS}$ and $\mathbb{TT}$ are incomparable.
    \end{itemize}
\end{fact}
\begin{proof}
For the first bullet, take any BNM-valuation such that $v(p)=\sfrac{1}{2}$ and $v(r)=0$. It's easy to notice that $v\nvDash_{\bf{tt}} p \wedge \neg p \Rightarrow r$ and $v\nvDash_{\bf{ss}} \Rightarrow p \vee \neg p $.\footnote{Notice that for every BNM scheme, if $v(p)=\sfrac{1}{2}$ then $v(\neg p)=\sfrac{1}{2}$, and if $v(p)=v(q)=\sfrac{1}{2}$, then $v(p\wedge q)=v(p\vee q)=\sfrac{1}{2}$.} However, both inferences are classically valid, and thus by Theorem \ref{thm:cl=st} they are in $\mathbb{ST}$.

