	\caption{Number of scenarios (out of $100$) where each approach produces the route with the optimal MAI.}
	\label{tab:LHKvsEnforced}
	\begin{tabular}{c|c|cc|c}
		\toprule
		& \textbf{Scenario} & \textbf{Enforced} & \textbf{LHK} & \textbf{Hybrid}\\
		\midrule
		\multirow{3}{*}{\emph{8-node}} &	 \emph{Grid} & 37 & 49 & 66 \\
		&	 \emph{Cluster} & 53 & 50 & 74 \\
		&	 \emph{Outlier} & 45 & 78 & 86 \\
		\midrule
		\multirow{3}{*}{\emph{20-node}} &	 \emph{Grid} & 2 & 28 & 30 \\
		&	 \emph{Cluster} & 5 & 48 & 50 \\
		&	 \emph{Outlier} & 6 & 78 & 78 \\
		\bottomrule
	\end{tabular}
