To account for potential non-linear relationships, we strengthen our notions of correlation in both our assumptions and our conclusions.
The precise definitions are provided in \Cref{sec:non_separable}, but loosely speaking, $\Corr(L^2(X),L^2(Y))$ denotes the maximum correlation between any two functions where one is a function of $X$ and the other is a function of $Y$.
The analog of \Cref{lemma:multilinear} in this more general setting is the following lemma.
\begin{lemma}\label{lemma:nonseparable}
Suppose $\set{(X_i,Y_i):i\in[n]}$ are mutually independent, where for some $0\leq\rho\leq1$, we have $\Corr(L^2(X_i),L^2(Y_i))\leq\rho$ for all $i$.
If $f:\R^n\to\R$ satisfies $\E[f(X)^2],\E[f(Y)^2]<\infty$ and
\begin{equation}\label{eq:lemma_nonseparable_condition}
    \Corr(L^2(f(X)),L^2(X_1)+\cdots+L^2(X_n)),\Corr(L^2(f(Y)),L^2(Y_1)+\cdots+L^2(Y_n))\leq\sqrt{1-\varepsilon}
\end{equation}
for some $\varepsilon>0$, then
\[ \Corr(L^2(f(X)),L^2(f(Y))) \leq (1-\varepsilon)\rho+\varepsilon\rho^2. \]
\end{lemma}
In \Cref{subsec:hierarchical_nonseparable}, we justify why \eqref{eq:lemma_nonseparable_condition} is the natural analog of the condition $d(f,\Lin)\geq\varepsilon$ in \Cref{lemma:multilinear}.
\begin{remark}\label{remark:correlation_construction_L2}
It is straightforward to check that the construction in \Cref{remark:correlation_construction} still satisfies the stronger condition $\Corr(L^2(X_i),L^2(Y_i))=\rho$: letting $Z_i$ be an independent copy of $X_i$ such that $Y_i=X_i$ with probability $\rho$ and $Y_i=Z_i$ otherwise, we have, for $f\in L^2(X_i)$ and $g\in L^2(Y_i)$ normalized so that $\E[f]=\E[g]=0$ and $\E[f^2]=\E[g^2]=1$, by the Cauchy--Schwarz inequality
\[ \Corr(f(X_i),g(Y_i)) = \rho\E[f(X_i)g(X_i)]+(1-\rho)\E[f(X_i)g(Z_i)] \leq \rho\cdot1 + (1-\rho)\cdot0 = \rho, \]
where equality is achieved when $f=g$ as functions $\R\to\R$.
\end{remark}
Using \Cref{lemma:nonseparable}, we obtain the following general version of \Cref{theorem:multilinear}.
\begin{theorem}\label{theorem:nonseparable}
    Suppose $\set{(X_i,Y_i):i\in[n]}$ are mutually independent, where for some $0\leq\rho<1$, we have $\Corr(L^2(X_i),L^2(Y_i))\leq\rho$ for all $i$.
    If $f:\R^n\to\R$ is a hierarchical function of depth $d$ and non-separability $\varepsilon>0$ in both $L^2(X)$ and $L^2(Y)$, then for any $\delta<\varepsilon$,
    \[ \Corr(L^2(f(X)),L^2(f(Y)))\leq (1-\delta)^{d-C_{\varepsilon,\delta}\log\paren{\frac{1}{1-\rho}}} \]
    for some constant $C_{\varepsilon,\delta}>0$ depending only on $\varepsilon$ and $\delta$.
\end{theorem}

\subsection{Applications}
\Cref{theorem:multilinear} immediately implies a low-degree bound on a hierarchical multilinear function---in particular we get that the correlation $M$ of such a function $f$ with a degree-$D$ polynomial is bounded by
\begin{equation}\label{eq:low_degree_multilinear}
    M \leq \rho^{-D/2}(1-\delta)^{d/2-C_{\varepsilon,\delta}\log\paren{\frac{1}{1-\rho}}},
\end{equation}
for any $\rho\in(0,1)$; see \Cref{lemma:low_degree_multilinear}.
Taking $\rho=1-e^{-cd}$ for some small $c\in\paren{0,\frac{1}{2C_{\varepsilon,\delta}}}$, we get a degree bound that is exponential in the circuit depth, i.e., in order to get $M=\Omega(1)$ correlation, one requires $D=e^{\Omega(d)}$.
% In the special case $\varepsilon = 1$, we obtain a degree bound that is exponential in the depth, i.e., $M=\Omega(1)$ requires $D=\Omega(2^d)$; see \Cref{remark:multilinear_epsilon1}.

% The results of~\cite{ABCKLRZ:22} imply that for functions as above, in their setting of fully connected neural networks and their initialization, the complexity of learning the function using their version of gradient descent is proportional exponential in the depth of the circuit.
% In the special case where all functions are resilient, i.e., have $0$ correlation with linear function, the lower bound becomes doubly exponential in the depth, i.e., exponential in the input size.

In the Boolean setting, which is contained in our framework of multilinear functions, using the results of Dachman-Soled, Feldman, Tan, Wan and Wimmer~\cite{dachman2014approximate}, the bound \eqref{eq:low_degree_multilinear} implies super-polynomial lower bounds for Statistical Query (SQ) agnostic learning of concept classes based on hierarchical multilinear functions.
We refer readers to \cite{dachman2014approximate} for background on agnostic learning in the SQ model.
\begin{theorem}\label{theorem:sq_learning_Boolean}
    For any constant $\varepsilon>0$, for any hierarchical multilinear function $f:\set{-1,1}^{n^{1/3}}\to[-1,1]$ of depth $d=\Theta(\log n)$ and non-linearity $\varepsilon$, let $\mc C$ be the concept class of functions $g:\set{-1,1}^n\to[-1,1]$ for which there exist distinct $i_1,\dots,i_{n^{1/3}}\in[n]$ such that $g(x)=f(x_{i_1},\dots,x_{i_{n^{1/3}}})$ for all $x$.
    Then any SQ algorithm for agnostically learning $\mc C$ with excess error of at most $\frac{1}{2}-o(1)$ has complexity at least $n^{\Omega\paren{\frac{\log n}{\log\log(n)}}}$.
\end{theorem}

Analogously, \Cref{theorem:nonseparable} immediately implies a low-degree bound on hierarchical functions, similar to \eqref{eq:low_degree_multilinear}.
The correlation $M$ of such a function $f$ with a function of Efron--Stein degree at most $D$ (see \Cref{subsec:Efron_Stein} for precise definitions), i.e., a sum of functions that each depend on at most $D$ of the $n$ variables, is bounded by
\begin{equation}\label{eq:low_degree_general}
    M \leq \rho^{-D/2}(1-\delta)^{d/2-C_{\varepsilon,\delta}\log\paren{\frac{1}{1-\rho}}};
\end{equation}
see \Cref{lemma:low_degree_general}.
As before, this implies a degree bound exponential in depth.
%We conjecture that the lower bounds of Abbe, Bengio, Cornacchiam, Kleinberg, Lotfi, Raghu and Zhang~\cite{ABCKLRZ:22} should extend in the appropriate setup and leave this for future work. 

When our inputs are Gaussian, using the results of Diakonikolas, Kane, Pittas and Zarifis~\cite{diakonikolas2021optimality}, \Cref{theorem:nonseparable} implies super-exponential lower bounds for agnostic learning in the SQ model for concept classes based on hierarchical functions.
\begin{theorem}\label{theorem:sq_learning_Gaussian}
    Fix an arbitrary constant $\varepsilon>0$.
    Let positive integers $n$ and $m$ satisfy $m\leq n^\alpha$ for any constant $\alpha<\frac{1}{2}$.
    For any hierarchical multilinear function $f:\R^m\to\set{\pm1}$ of depth $d=\Theta(\log n)$ and non-separability $\varepsilon$ in $L^2(X)$, where $X\sim\mc N(0,I_m)$ is a $m$-dimensional spherical Gaussian of unit variance, let $\mc C$ be the concept class consisting of the functions of the form $F(x)=f(Px)$, where $P\in\R^{m\times n}$ is any matrix satisfying $PP^T=I_m$.
    Then there exists constant $c=c_\varepsilon>0$ such that any SQ learning algorithm that agnostically learns $\mc C$ over $\mc N(0,I_n)$ to $L^2$-error $\operatorname{OPT}+\frac{1}{8}-o(1)$ either requires queries with tolerance at most $n^{-\Omega(n^c)}$ or makes at least $2^{n^{\Omega(1)}}$ queries.
\end{theorem}

Our final application is for learning such functions using stochastic gradient descent on fully connected deep neural networks. 
The results of~\cite{ABCKLRZ:22} which build on~\cite{AbbeSandon:20} imply that for functions as above, in their setting of fully connected neural networks and their initialization, the complexity of learning the function using their version of gradient descent is proportional exponential in the depth of the circuit.
In the special case where all functions are resilient, i.e., have $0$ correlation with linear function, the lower bound becomes doubly exponential in the depth, i.e., exponential in the input size.
More formally, \cite[Theorem 1]{ABCKLRZ:22} immediately implies the following.
\begin{corollary}
Let $f : \{-1,1\}^n \to \{-1,1\}$ be a hierarchical multilinear function of non-linearity $\eps>0$ and depth $d = \Omega(\log n)$ that is balanced, i.e., $\E[f(X)]=0$ where $X\sim\Unif(\set{-1,1}^n)$.
Let $\bar{f}$ be the $2n$-extension of $f$, given by 
$\bar{f}(x_1,\ldots,x_{2n}) = f(x_1,\ldots,x_n)$.
Consider a fully connected neural network of size $E$ with initialization that is target
agnostic in the sense that it is invariant under permutations of the inputs. 
Let $f^{(t)}_{\mathrm{NN}}$ denote the output of noisy-GD with gradient range $A$, batch-size $b$, learning rate $\gamma$, and noise scale $\sigma$ (see \cite[Definition 8]{ABCKLRZ:22}) after $t$ time steps. Then, if $1 - \rho \leq 0.25$  and $b$ is sufficiently large, then for any $\delta < \eps$ the generalization error is at least 
$
0.5 - o(1)$ as long as 
\[
\gamma t \sqrt{E} A (1-\delta)^{d-C_{\eps,\delta} \log(\frac{1}{1-\rho})}  \ll \sigma. 
\] 
In the case where $\eps = 1$, we get generalization error at least $0.5 - o(1)$ as long as 
$\gamma t \sqrt{E} A \rho^{2^{d-2}} \ll \sigma$.
\end{corollary}
Note that the bound in the case $\eps < 1$ is polynomial in $n$, while we get super-polynomial lower bound in the case where $\eps = 1$ (see  \cref{remark:multilinear_epsilon1} below).

We conjecture that the lower bounds of Abbe, Bengio, Cornacchiam, Kleinberg, Lotfi, Raghu and Zhang~\cite{ABCKLRZ:22} should extend in a straightforward way to other product spaces.
