\section{Theoretical and Experimental Details on H-SCALE}
\label{sec:Hscale}

\subsection{Proof of the Augmented Discriminative Power}

We formally demonstrate how combining mean and standard deviation pooling enhances the contrastive alignment of variable-length sequence pairs, improving the expressive and discriminative power of our hybrid InfoNCE loss.

\paragraph{Setup.}
Let two modalities be represented as sequences:
\[
\mathbf{X} = [\mathbf{x}_1, \dots, \mathbf{x}_{T_X}], \quad \mathbf{Y} = [\mathbf{y}_1, \dots, \mathbf{y}_{T_Y}]
\]
where $\mathbf{x}_t \in \mathbb{R}^{d_1}$, $\mathbf{y}_t \in \mathbb{R}^{d_2}$.

Let $f(\cdot)$ and $g(\cdot)$ be encoders that output contextual embeddings in $\mathbb{R}^d$:
\[
\mathbf{H}_X = [f(\mathbf{x}_1), \dots, f(\mathbf{x}_{T_X})] \in \mathbb{R}^{T_X \times d}, \quad
\mathbf{H}_Y = [g(\mathbf{y}_1), \dots, g(\mathbf{y}_{T_Y})] \in \mathbb{R}^{T_Y \times d}
\]

We define pooled statistics:
\[
\bm{\mu}_X = \frac{1}{T_X} \sum_{t=1}^{T_X} \mathbf{h}_t^X, \quad
\bm{\mu}_Y = \frac{1}{T_Y} \sum_{t=1}^{T_Y} \mathbf{h}_t^Y
\]
\[
\bm{\sigma}_X = \sqrt{ \frac{1}{T_X} \sum_{t=1}^{T_X} (\mathbf{h}_t^X - \bm{\mu}_X)^2 }, \quad
\bm{\sigma}_Y = \sqrt{ \frac{1}{T_Y} \sum_{t=1}^{T_Y} (\mathbf{h}_t^Y - \bm{\mu}_Y)^2 }
\]

Define hybrid vectors as concatenations:
\[
\mathbf{z}_X = \text{concat}(\bm{\mu}_X, \bm{\sigma}_X), \quad
\mathbf{z}_Y = \text{concat}(\bm{\mu}_Y, \bm{\sigma}_Y)
\]

\paragraph{Hybrid InfoNCE Loss.}
Let $\text{sim}(\cdot, \cdot)$ be a similarity function (e.g., cosine or dot product), $\tau > 0$ a temperature parameter, and $\{(\mathbf{X}_i, \mathbf{Y}_i)\}_{i=1}^N$ a batch of aligned pairs.

We define:
\[
\mathcal{L}_{\text{InfoNCE}}^{(i)} = -\log \frac{
\exp\left(\text{sim}(\mathbf{z}_X^{(i)}, \mathbf{z}_Y^{(i)}) / \tau\right)
}{
\sum\limits_{j=1}^{N} \exp\left(\text{sim}(\mathbf{z}_X^{(i)}, \mathbf{z}_Y^{(j)}) / \tau\right)
}
\]

Averaged over the batch:
\[
\mathcal{L}_{\text{total}} = \frac{1}{N} \sum_{i=1}^{N} \mathcal{L}_{\text{InfoNCE}}^{(i)}
\]

Alternatively, we consider separate terms for mean and std-pooled contrast:

\[
\mathcal{L}_{\mu}^{(i)} = -\log \frac{
\exp\left(\text{sim}(\bm{\mu}_X^{(i)}, \bm{\mu}_Y^{(i)}) / \tau\right)
}{
\sum\limits_{j=1}^{N} \exp\left(\text{sim}(\bm{\mu}_X^{(i)}, \bm{\mu}_Y^{(j)}) / \tau\right)
}
\]

\[
\mathcal{L}_{\sigma}^{(i)} = -\log \frac{
\exp\left(\text{sim}(\bm{\sigma}_X^{(i)}, \bm{\sigma}_Y^{(i)}) / \tau\right)
}{
\sum\limits_{j=1}^{N} \exp\left(\text{sim}(\bm{\sigma}_X^{(i)}, \bm{\sigma}_Y^{(j)}) / \tau\right)
}
\]

Combined:
\[
\mathcal{L}^{(i)} = \mathcal{L}_{\mu}^{(i)} + \lambda \cdot \mathcal{L}_{\sigma}^{(i)}, \quad \lambda \in \mathbb{R}_{+}
\]

\paragraph{Distributional Separability.}
Let $\mathbf{H}_X^{(1)} \sim P_X^{(1)}$, $\mathbf{H}_X^{(2)} \sim P_X^{(2)}$ denote two sequence embeddings from different protein classes.

Let $\Sigma_X^{(i)} = \text{diag}(\bm{\sigma}_X^{(i)} \bm{\sigma}_X^{(i)\top})$ be diagonal covariance approximations.

A lower bound on the KL divergence between distributions is:
\[
D_{\text{KL}}\left(P_X^{(1)} \| P_X^{(2)}\right) \geq \frac{1}{2} \left(
\|\bm{\mu}_X^{(1)} - \bm{\mu}_X^{(2)}\|^2_{\Sigma^{-1}} + \frac{1}{2} \text{tr}\left(
\Sigma_X^{(1)} \Sigma_X^{(2)-1} + \Sigma_X^{(2)} \Sigma_X^{(1)-1} - 2I
\right)
\right)
\]

Notably:
- If $\bm{\mu}_X^{(1)} = \bm{\mu}_X^{(2)}$ but $\bm{\sigma}_X^{(1)} \neq \bm{\sigma}_X^{(2)}$, then:
\[
D_{\text{KL}} \geq \frac{1}{4} \left(
\text{tr}\left(\Sigma_X^{(1)} \Sigma_X^{(2)-1}\right) + \text{tr}\left(\Sigma_X^{(2)} \Sigma_X^{(1)-1}\right) - 2d
\right) > 0
\]
indicating discriminative separation purely from variance statistics.

\paragraph{Fisher-Rao Geometry.}
The squared Fisher-Rao distance between two distributions is:
\[
d_{\text{FR}}^2 = \|\bm{\mu}_X^{(1)} - \bm{\mu}_X^{(2)}\|_2^2 + \frac{1}{2} \left\| \Sigma_X^{(1)-1/2} \Sigma_X^{(2)1/2} - \Sigma_X^{(2)-1/2} \Sigma_X^{(1)1/2} \right\|_F^2
\]
This shows second-order (variance) features contribute additively and quadratically to distributional distance.

\paragraph{Gradient Signal Diversity.}
Assuming smooth encoders, the magnitude of gradient updates from each term is:
\[
\left\|\nabla_{\theta}\mathcal{L}_{\mu}^{(i)}\right\| \leq \frac{1}{\tau} \mathbb{E}\left[\|\bm{\mu}_X^{(i)} - \bm{\mu}_X^{(j)}\| \right]
\]
\[
\left\|\nabla_{\theta}\mathcal{L}_{\sigma}^{(i)}\right\| \leq \frac{1}{\tau} \mathbb{E}\left[\| \log \bm{\sigma}_X^{(i)} - \log \bm{\sigma}_X^{(j)} \| \right]
\]

These directions are complementary when:
\[
\text{span}\left\{\bm{\mu}_X^{(i)} - \bm{\mu}_X^{(j)}\right\} \perp \text{span}\left\{ \log \bm{\sigma}_X^{(i)} - \log \bm{\sigma}_X^{(j)} \right\}
\]
In such cases, variance-based terms enable discriminative training even when mean vectors are degenerate.

\paragraph{Conclusion.}
The hybrid representation:
\[
\mathbf{z} = \text{concat}(\bm{\mu}, \bm{\sigma})
\]
captures both first-order and second-order statistics of sequences, improving separability and gradient flow in contrastive training. This formally justifies the enhanced alignment and generalization observed in our hybrid InfoNCE strategy.



