%=========================================================================
\subsection{Loss Functions}
\label{subsec:loss}

\noindent \textbf{Task-specific terms.}
Given that we have access to the ground-truth action sequence from expert demonstrations, the task-specific loss is straightforward, such as cross-entropy loss or mean squared error loss. Here, we denoted as $\mathcal{L}_\texttt{task}$, and its concrete form is determined by the tasks.

\noindent \textbf{Wavelet-related terms.}
Different from the conventional manually designed $P$, $U$, $\hat{P}$, and $\hat{U}$ that can achieve frequency decomposition effects, these learnable networks need optimization to form a valid lifting scheme. Specifically, the approximation stream primarily captures the low-frequency components, which represent the coarse information or the general trend of the data, thus, we enforce each even/approximation stream has the same \textit{local} average as its corresponding stream in the upper scale:
%
\begin{equation}
    \mathcal{L}_\texttt{approx} = \sum_{i=t}^{t+N}\text{Smooth}_{L_1}(\mathcal{C}(A_s^{l}) - A_s^{l+1})\enspace,
\end{equation}
%
where $\mathcal{C}(\cdot)$ denotes \textit{causal moving average}, as shown in the left-bottom panel in Figure~\ref{fig:design}. The detail stream should, on the one hand, preserve high-frequency components, and on the other hand, not overpower the approximation stream. Following~\cite{huang2022adaptive}, we adopt the loss as:
%
\begin{equation}
    \mathcal{L}_\texttt{detail} = \sum_{i=t}^{t+N}\text{Smooth}_{L_1}(A_d^l)\enspace.
\end{equation}
%
The total loss for optimization is the sum of all the three above loss terms:
%
\begin{equation}
    \mathcal{L} = \mathcal{L}_\texttt{approx} + \alpha \mathcal{L}_\texttt{approx} + \beta \mathcal{L}_\texttt{detail}\enspace,
\end{equation}
%
where $\alpha$ and $\beta$ balance the weights of the last two terms.


