\section{Training Objective}\label{app:obj}
As mentioned in the main paper, we build LM-SPT on top of SpeechTokenizer~\cite{zhang2024speechtokenizer}, and thus adopt the same set of training objectives.
The only difference is that, due to our use of a split RVQ architecture following Mimi~\cite{moshi}, which requires applying the commitment loss separately to the semantic and acoustic codebooks.
In addition to the semantic distillation loss defined in \eqref{eq:distill}, the generator is optimized with five additional loss terms: reconstruction loss, generator loss, discriminative loss, feature matching loss, and commitment loss.

In both SpeechTokenizer~\cite{zhang2024speechtokenizer} and Mimi~\cite{moshi} baselines, semantic distillation is implemented as a cosine similarity maximization loss, following the formulation used in \cite{zhang2024speechtokenizer}.
These models use different SSL teachers: HuBERT \cite{hubert} for SpeechTokenizer and WavLM \cite{wavlm} for Mimi.

\paragraph{Reconstruction loss}
Reconstruction loss consists of two components: a time domain loss $\mathcal{L}_{\text{t}}$ and a frequency domain loss $\mathcal{L}_{\text{f}}$.
In the time domain, an L1 loss is applied between the original waveform \(x\) and reconstructed waveform \(\hat{x}\), i.e., $\mathcal{L}_{\text{t}} = \| x - \hat{x} \|_{1}$. In the frequency domain, L1 and L2 losses over the mel-spectrogram using several time scales as follows: $\mathcal{L}_{\text{f}} = \sum_{i \in e} \Bigl( \| M_i(x) - M_i(\hat{x}) \|_{1}
+ \| M_i(x) - M_i(\hat{x}) \|_{2} \Bigr)$, where \(M_i(\cdot)\) denotes a 64-band Mel spectrogram with window size \(2^i\) and hop size \(2^{i-2}\), $e=5,\dots,11$ is the set of scales.

% \begin{align}
%     \mathcal{L}_{\text{time}} = \| x - \hat{x} \|_{1}
% \end{align}

% \begin{align}
%     \mathcal{L}_{\text{freq}} = \sum_{i=5}^{11} \Bigl( \| M_i(x) - M_i(\hat{x}) \|_{1}
%     + \| M_i(x) - M_i(\hat{x}) \|_{2} \Bigr),
% \end{align}
% where \(M_i(\cdot)\) denotes a 64-band Mel spectrogram with window size \(2^i\) and hop size \(2^{i-2}\).

\paragraph{Generator and Discriminative loss} 
Discriminative loss employs three types of discriminators: a multi-scale STFT-based discriminator, a multi-period discriminator, and a multi scale discriminator.
It is formulated as a hinge loss over the logits from multiple discriminators to promote perceptual quality.
The generator loss $\mathcal{L}_{\text{g}}$ and discriminator loss $\mathcal{L}_{D}$ are computed by averaging over all $K$ discriminators, following the standard adversarial setup:
\begin{align*}
    \mathcal{L}_{g} = \frac{1}{K}\sum_{k=1}^K \max(1 - D_k(\hat{x}),0),
\end{align*}
\begin{align*}
    \mathcal{L}_{D} = \frac{1}{K}\sum_{k=1}^K \bigl[\max(1 - D_k(x),0)
    + \max(1 + D_k(\hat{x}),0)\bigr],
\end{align*}
% \begin{align*}
%     \mathcal{L}_{\text{adv}} = \frac{1}{K}\sum_{k=1}^K \max\bigl(1 - D_k(\hat{x}),\,0\bigr),
% \end{align*}
where \(D_k\) stands for each discriminator’s score.

\paragraph{Feature matching loss}
For stable GAN training, a feature matching loss $\mathcal{L}_{\text{feat}}$ for the generator is computed as follow:
\begin{align*}
    \mathcal{L}_{\text{feat}} = \frac{1}{KL} \sum_{k=1}^K \sum_{\ell=1}^L
    \frac{\lVert D_k^{(\ell)}(x) - D_k^{(\ell)}(\hat{x})\rVert_{1}}
    {\mathbb{E}\bigl[\lVert D_k^{(\ell)}(x)\rVert_{1}\bigr]},
\end{align*}

where \(D_k^{(\ell)}\) is the \(\ell\)-th layer output of discriminator \(k\), and $L$ is the number of layers in discriminators.

\paragraph{Commitment loss}
In the split‐RVQ architecture, we penalize the deviation of both semantic and acoustic encoder outputs from their respective quantized codebook vectors:
\begin{align*}
    \mathcal{L}_{\text{com}}
    = \sum_{i=1}^{N^{q}_{\text{sem}}}
    \bigl\lVert z^{i}_{\text{sem}} - z^{q,i}_{\text{sem}}\bigr\rVert_{2}^{2}
    \;+\;
    \sum_{j=1}^{N^{q}_{\text{ac}}}
    \bigl\lVert z^{j}_{\text{ac}} - z^{q,j}_{\text{ac}}\bigr\rVert_{2}^{2},
\end{align*}
where \(z^{i}_{\text{sem}}\) and \(z^{q,i}_{\text{sem}}\) (for \(i=1,\dots,N^{q}_{\text{sem}}\)) are the pre- and post-quantization vectors associated with the semantic codebook, and \(z^{j}_{\text{ac}}\), \(z^{q,j}_{\text{ac}}\) (for \(j=1,\dots,N^{q}_{\text{ac}}\)) those associated with the acoustic codebook.


\paragraph{Generator Loss}
We train LM-SPT by minimizing a weighted sum of its constituent loss components:
\begin{align*}
    \mathcal{L}_G 
    &= \lambda_{\text{t}}\,\mathcal{L}_{\text{t}}
      + \lambda_{\text{f}}\,\mathcal{L}_{\text{f}}
      + 
      \lambda_{g}\,\mathcal{L}_{g}
      % + \lambda_{\text{adv}}\,\mathcal{L}_{\text{adv}}
      + \lambda_{\text{feat}}\,\mathcal{L}_{\text{feat}}
      + \lambda_{\text{com}}\,\mathcal{L}_{\text{com}}
      + \lambda_{\text{distill}}\,\mathcal{L}_{\text{distill}}.
\end{align*}
The hyperparameters are presented in \autoref{tab:hparams_train}.
