	\section{Structural properties of the Line Traveling Salesman Problem with collaboration} \label{sec:characterisingOpt}

	We propose a number of structural results that will be useful for proving the correctness of the algorithms that follow. Specifically, we show that there exists an optimal solution that has a very specific structure.

	\begin{lemma}\label{lemma:orderPreservingNoProc}
		If there are zero-processing times and only deadlines and if the instance is feasible, there exists an optimal solution for the CLTSP, such that for any clients \(a, a'\in L\) or \(a, a'\in R\) with \( |s(a)| < |s(a')|\) we have \(t(a) < t(a')\). In other words, the solution is order-preserving.
	\end{lemma}
	\begin{proof}
		Assume the instance is feasible and consider an optimal solution \( (t,x) \) and assume it is not order-preserving. 
		Assume there exists a client \(a \in R\), such that there exists an \(a' \in R\) with \( s(a) < s(a')\) and \(t(a) > t(a')\).  
		Consider lines \(f(t) = s(a) - vt\) and \(g(t) = s(a') - vt\).
		For the rendezvous to be reachable by \(a'\), it must hold that \(g(t(a')) \leq x(a')\).
		But then the trajectory of the server must cross \(f(t)\) at some point \( (\bar{t},\bar{x})\), where \(\bar{t} < t(a')\) and \(\bar{x} < x(a')\).

		Define solution \( (t',x')\) with \((t'(a), x'(a)) = (\bar{t},\bar{x})\) and \((t'(a''), x'(a'')) = (t(a''), x(a''))\) for all other \(a'' \in A\).
		Observe that both solutions have the same trajectory and therefore all rendezvous are reachable by the server and the clients.
		Further, we know that \(t'(a) \leq t(a) \leq d(a)\) for all \(a\in A\) and thus  \( (t',x')\) is feasible.
		It follows that \( (t',x')\) is again an optimal solution and we know that \(t'(a') > t'(a)\). If there exists a client \(a \in L\), such that there exists an \(a' \in L\) with \( s(a) > s(a')\) and \(t(a) > t(a')\), a symmetric procedure is used. Repeating this procedure for all relevant elements, results in a solution that satisfies the condition stated in the lemma.
	\end{proof}

	\begin{lemma}\label{lemma:orderPreservingGenProc}
		If there are general processing times and no time constraints, then there exists an optimal solution for the CLTSP, such that for any clients \(a, a'\in L\) or \(a, a'\in R\) with \( |s(a)| < |s(a')|\) we have \(t(a) < t(a')\). In other words, the solution is order-preserving.
	\end{lemma}
	\begin{proof}
        Observe that there always exists an optimal solution.
		Consider an optimal solution \( (t,x) \). 
		Assume there exists a client \(a \in R\), such that there exists an \(a' \in R\) with \( s(a) < s(a')\) and \(t(a) > t(a')\).  
        If there do not exist such clients, we are done.
		Consider lines \(f(t) = s(a) - vt\) and \(g(t) = s(a') - vt\).
		But then the trajectory of the server must cross \(f(t)\) at some point \( (\bar{t},\bar{x})\), where \(\bar{t} < t(a')\) and \(\bar{x} < x(a')\).

		Define solution \( (t',x')\) by defining \((t'(a), x'(a)) = (\bar{t}, \bar{x})\) and for all \(a'' \in A \setminus \{a\}\) 
		\[
		(t'(a''), x'(a'')) =
		\begin{cases} 
			(t(a'') + \tau(a), x(a'')), & \text{if } t(a') < t(a'') < t(a), \\
			(t(a''), x(a'')), & \text{otherwise}.
		\end{cases}
		\]
		Observe that, by construction, all rendezvous are reachable by the server and the clients.
		It follows that \( (t',x')\) is again an optimal solution and we know that \(t'(a') > t'(a)\). If there exists a client \(a \in L\), such that there exists an \(a' \in L\) with \( s(a) > s(a')\) and \(t(a) > t(a')\), a symmetric procedure is used. Repeating this procedure for all relevant elements, results in a solution that satisfies the condition stated in the lemma.
	\end{proof}

	\begin{lemma}\label{lemma:waitFreeServer}
		If there are general processing times and only deadlines and clients are slow and if the instance is feasible, then given an optimal solution \((t, x)\) for the CLTSP, we have that \(t_{i} = c_{i-1} + |x_{i} - x_{i-1}|\) for all \(1 \leq i \leq n+1\). In other words, the server is wait-free. 
	\end{lemma}
	\begin{proof}
		The argument is illustrated in Figure~\ref{fig:proofWaitFree1}. Assume the instance is feasible. Consider an optimal solution \( (t, x)\) and assume that there exists an \( i \geq 1 \) such that \( t_i > c_{i-1} + |x_i - x_{i-1}| \). 
        If there does not exist such a rendezvous, we are done. Let \( a = \sigma_{i} \), and denote the position of \( a \) at time \( c_{i-1} \) as \( s'(a)\). We may assume that \(s'(a)\geq x_{i-1}\). Consider solution \((t',x')\) by defining \(\sigma' = \sigma\) and for all \(j\),
		\[
		(t'_j, x'_j) =
		\begin{cases} 
			\left(c_{i-1} + (s'(a) - x_{i-1})/(1+v), x_i + (s'(a) - x_{i-1})/(1+v)\right), & \text{if } j = i,\\
			(t_j, x_j), & \text{otherwise.}
		\end{cases}
		\]
		Observe that, by construction, every rendezvous is reachable by the clients. Further, we know that \(t'_i \leq t_i\) and \(x'_i \leq x_i\). 
        Since \((t_i, x_i)\) is reachable by \(a\), we know that \(c_i \geq t'_i + (x_i - x'_i)/{v} + \tau(a)\). Thus, in solution \((t',x')\) the server can process \(a\) at position \(x_i\) in time \( t'_i + x_i - x'_i + \tau(a) < t_i + (x_i - x'_i)/{v} + \tau(a) \leq c_i\) using that \(v < 1\) and \(x_i - x'_i \geq 0\) and \(t'_i \leq t_i\). This implies that every rendezvous is reachable by the server. 
		Further, we know that \(t'(a) \leq t(a) \leq d(a)\) for all \(a\in A\) and thus  \( (t',x')\) is feasible.
		It follows that \( (t',x')\) is again an optimal solution and we know that the rendezvous with \(a\) is wait-free. Repeating this procedure for all relevant elements results in a solution that satisfies the condition stated in the lemma.
