\section{Nonlinear Responses in Memristive Edges} \label{app:edge}
\begin{figure*}
	\centering
	\includegraphics[width=0.45\linewidth]{figs/jnv_scatter_dynam.png}
	\includegraphics[width=0.45\linewidth]{figs/jnv_scatter_nonlin.png}
