\begin{lemma} \label{lemma:ineq} Let $\mathcal{A}, \mathcal{B}$ be two regular convex sets in which $\mathcal{A} \cap \mathcal{B} = \emptyset$. Let $(a_0^*,b_0^*)$ be any pair of points that 
achieves the smallest (true) Euclidean distance between them. Then:
\begin{equation}
    E^{\mathcal{B}}(a_0^*) \geq \Lambda^{\mathcal{A},\mathcal{B}} \geq \min_a \Lambda(a,a)
\end{equation}
\noindent in which we borrowed the definition of $\Lambda(a,b)$ from the proof of Lemma \ref{lemma:gt}.
\end{lemma}



\begin{proof}
    We apply the game-theoretic/optimization interpretation of $\Lambda^{\mathcal{A},\mathcal{B}}$ from Lemma \ref{lemma:gt}. For the leftmost inequality, since $\Lambda^{\mathcal{A},\mathcal{B}} = \min_a \Lambda^{\mathcal{B}}(a)$, then $\Lambda^{\mathcal{A},\mathcal{B}} \leq  \Lambda^{\mathcal{B}}(a)$ for any $a$. Take $a =  a_0^*$. In this case, we have
    \begin{equation}
         \Lambda^{\mathcal{B}}(a_0^*) = \Lambda(a^*_0,b^{\circ}(a_0^*))
    \end{equation}
    \noindent in which, according to Lemma \ref{lemma:gt}, $b^{\circ}(a_0^*)$ is such that $\Pi^{\mathcal{A}}(b^{\circ}(a_0^*)) = a_0^*$. Note that, since $a_0^* \in \mathcal{A}$, $b^{\circ}(a_0^*) = a_0^*$ is a solution to this equation (See Proposition \ref{prop:simple}). Furthermore, from Lemma \ref{lemma:inv}, $\Pi^{\mathcal{A}}$ is injective, and thus  $\Pi^{\mathcal{A}}(b^{\circ}(a_0^*)) = a_0^*$ implies $b^{\circ}(a_0^*) = a_0^*$. Hence:
    \begin{equation}
         \Lambda^{\mathcal{B}}(a_0^*) = \Lambda(a^*_0,a^*_0) = E^{\mathcal{A}}(a_0^*) + E^{\mathcal{B}}(a_0^*)-\frac{\|a_0^*-a_0^*\|^2}{2}
    \end{equation}    
    \noindent which is equal to $E^{\mathcal{B}}(a_0^*)$ since $E^{\mathcal{A}}(a_0^*)=0$ (once $a_0^* \in \mathcal{A}$, see Property (4) of Definition \ref{def:kp2s}).

    For the rightmost inequality, note that $\Lambda^{\mathcal{B}}(a) = \max_b \Lambda(a,b) \geq \Lambda(a,b)$ for all $b$. Take $b(a) = a$, and thus $\Lambda^{\mathcal{B}}(a)  \geq \Lambda(a,a)$ for any $a$. Taking the minimum in $a$ in both sides and recalling Lemma \ref{lemma:gt}, the result follows.
\end{proof}


\noindent \textbf{Proof of Proposition \ref{prop:pos}}:

\underline{Proof of positivity:} We utilize the definitions of $\Lambda(a,b)$ and $\Lambda^{\mathcal{B}}(a)$ from the proof of Lemma \ref{lemma:gt}. From the rightmost inequality in Lemma \ref{lemma:ineq}, $\Lambda^{\mathcal{A},\mathcal{B}} \geq \min_a \Lambda(a,a)$. But $\Lambda(a,a) = E^{\mathcal{A}}(a) + E^{\mathcal{B}}(a)$, and this is nonnegative (Property (1) of Definition \ref{def:kp2s}). Furthermore, $E^{\mathcal{A}}(a) + E^{\mathcal{B}}(a)$ can be $0$ only if $E^{\mathcal{A}}(a) = E^{\mathcal{B}}(a) = 0$  (Property (1) together with Property (4) of Definition \ref{def:kp2s}). This implies that a point $a$ such that  $a \in \mathcal{A}$ and $a \in \mathcal{B}$ should exist, that is, $\mathcal{A} \cap \mathcal{B} \not= \emptyset$.


\underline{Proof of going to zero when $\mathcal{A} \cap \mathcal{B} \not= \emptyset$:} in that case, we start by using  the leftmost inequality in Lemma \ref{lemma:ineq}. As the two objects tend to overlap, the point $a_0^*$, that is always inside $\mathcal{A}$, tends to get closer to $\mathcal{B}$ as well (since, by definition, $a_0^*$, is the closest point in $\mathcal{A}$ to $\mathcal{B}$). But when $a_0^* \in \mathcal{B}$, we have that $E^{\mathcal{B}}(a_0^*) = 0$ (Proposition \ref{prop:simple}). Finally, $E^{\mathcal{B}}$ is continuous (since it is $k$ times differentiable, $k \geq 2$ from Property (3) in Definition \ref{def:kp2s}). Hence, from both inequalities in Lemma \ref{lemma:ineq}, $\Lambda^{\mathcal{A},\mathcal{B}}$ is squeezed from the left (due to this argument) and from the right (see the ``Proof of positivity'' above) to $0$. And the result follows.
$\square$



\textbf{Proof of Proposition \ref{prop:diff}}: 

\underline{Part I:} we start by showing that if $\tau$ is such that $\mathcal{A}(\tau) \cap \mathcal{B}(\tau) = \emptyset$ and $a^*(\tau)$ is a limit point of \eqref{eq:gam}, that is, $a^*(\tau) = \Pi^{\mathcal{A}(\tau)}\big(\Pi^{\mathcal{B}(\tau)}\big(a^*(\tau)\big)\big)$, then $a^*(\tau)$ is $k$-times differentiable. The proof is by induction.

Let $F(p,\tau) = \Pi^{\mathcal{A}(\tau)}\big(\Pi^{\mathcal{B}(\tau)}\big(p\big)\big)$ and thus the fixed point equation is $a^*(\tau) = F\big(a^*(\tau),\tau\big)$. Let $M(\tau) = I_{n \times n}-\frac{\partial F}{\partial p}(a^*(\tau),\tau)$.  Differentiate $a^*(\tau) = F\big(a^*(\tau),\tau\big)$ $k$-times. We obtain an equation of the form:

\begin{equation}
   M(\tau)\frac{d^{k}a^*}{d\tau^{k}}(\tau) = G\Big(a^*(\tau),\frac{da^*}{d\tau}(\tau),..., \frac{d^{k-1}a^*}{d\tau^{k-1}}(\tau),\tau\Big)
\end{equation}

\noindent in which the function $G: \mathbb{R}^n \times \mathbb{R}^n \times ... \times  \mathbb{R}^n \times \mathbb{R} \mapsto \mathbb{R}^n$ is continuous in all its arguments, because the functions $E^{\mathcal{A(\tau)}}(p)$, $B^{\mathcal{A(\tau)}}(p)$ are $k$ times differentiable on $p$ (Property (3) in Definition \ref{def:kp2s}) and also in $\tau$ because the transformations $T_A(p,\tau), T_B(p,\tau)$ were assumed to be $k$ times differentiable. 

We proceed by noting that it is established, in the proof of Lemma \ref{lemma:cont}, that $\|\frac{\partial F}{\partial p}(a^*(\tau),\tau)\| < 1$ as long as $\mathcal{A} \cap \mathcal{B} = \emptyset$. Hence \(M(\tau)\) is invertible and consequently:

\begin{equation}
   \frac{d^{k}a^*}{d\tau^{k}}(\tau) = M(\tau)^{-1}G\Big(a^*(\tau),\frac{da^*}{d\tau}(\tau),..., \frac{d^{k-1}a^*}{d\tau^{k-1}}(\tau),\tau\Big).
\end{equation}

\noindent which shows that $\frac{d^{k}a^*}{d\tau^{k}}(\tau)$ is continuous as long as $\frac{d^{m}a^*}{d\tau^{m}}(\tau)$ is continuous for $m=0,..,k-1$.  The base case of the induction, the continuity of $a^*(\tau)$ on $\tau$, comes from the fact that the map $F(p,\tau)$ is contractive as long as $\mathcal{A}(\tau) \cap \mathcal{B}(\tau) = \emptyset$ (see \cite{beldzinski2022dependence}).

\underline{Part II:} we need to prove that $b^*(\tau) = \Pi^{\mathcal{B}(\tau)}(a^*(\tau))$ is also $k$ times differentiable. The proof is analogous to the one in Part I, by differentiating this equation $k$ times in $\tau$.

\underline{Part III:} for the final part, we note that the $k^{th}$ derivative $\Lambda^{\mathcal{A}(\tau),\mathcal{B}(\tau)}$ involves the $k^{th}$ derivatives of the functions $E^{\mathcal{A}(\tau)}(p)$ and $E^{\mathcal{B}(\tau)}(p)$ on $p$ and $\tau$. These  are continuous (from Property (3) in Definition \ref{def:kp2s} for $p$ and also in $\tau$ because the transformations $T_A(p,\tau), T_B(p,\tau)$ were assumed to be $k$ times differentiable). Finally, it also depends ont the $k^{th}$ derivatives of $a^*(\tau)$ and $b^*(\tau)$ on $\tau$, which were established to be continuous in Part I and Part II, respectively. $\square$






\begin{lemma} \label{lemma:ABsum} Let $A, B : \mathbb{R}^n \mapsto \mathbb{R}$ be two functions that are at least twice differentiable, in which $A$ is strictly convex everywhere and $B$ is convex everywhere. Furthermore, suppose that $B \geq 0$ and that $A$ and $B$ do not vanish simultaneously. Then:
\begin{equation}
    C(p) = A(p) + \sqrt{ A(p)^2 + B(p)^2}
\end{equation}
\noindent is strictly convex in the set $\mathcal{P} = \{p \in \mathbb{R}^n \ | \ B(p) > 0\}$.
\end{lemma}

\begin{proof}
It can be checked by applying derivation rules that:
\begin{equation}
\label{eq:hessianC}
    \frac{\partial^2 C}{\partial p^2} = \frac{C \frac{\partial^2 A}{\partial p^2} + B \frac{\partial^2 B}{\partial p^2}}{\sqrt{A^2+B^2}}{+}\frac{\left(A \frac{\partial B}{\partial p} {-} B\frac{\partial A}{\partial p}\right)\left(A \frac{\partial B}{\partial p} {-} B\frac{\partial A}{\partial p}\right)^\top}{(\sqrt{A^2+B^2})^3}.
\end{equation}   

    Note that the division by $\sqrt{A^2+B^2}$ never causes problems because $A$ and $B$ cannot simultaneously vanish. Furthermore, $C > 0$ when $p \in \mathcal{P}$. Thus, when $p \in \mathcal{P}$, the first term in \eqref{eq:hessianC} is a positive definite matrix since $B \geq 0$, $\frac{\partial^2 A}{\partial p^2} \geq 0$, $C > 0$ and $\frac{\partial^2 B}{\partial p^2} > 0$. In addition, the second term is also positive semidefinite (a matrix of the form $\alpha uu^\top$ for any vector $u \in \mathbb{R}^n$ and a nonnegative $\alpha$ is always positive semidefinite). Since the sum of a positive definite and a positive semidefinite matrix is always a positive definite matrix, the desired result follows.
\end{proof}

\begin{lemma} \label{lemma:convprop} If $U: \mathbb{R}^n \mapsto \mathbb{R}$ is convex, twice differentiable with $\|\frac{\partial^2 U}{\partial p^2}\| \leq \mu$, and $U_{\textsl{min}} = \min_q U(q)$ is finite, then:
\begin{equation}
    \left\|\frac{\partial U}{\partial p}(p)\right\|^2 \leq 2 \mu (U(p)-U_{\textsl{min}}) \ \ \ \forall p.
\end{equation}
\end{lemma}

\begin{proof} This is a simple application of Descent Lemma \cite{Bertsekas1999}: if  $U: \mathbb{R}^n \mapsto \mathbb{R}$ is convex, twice differentiable with $\|\frac{\partial^2 U}{\partial p^2}\| \leq \mu$, then, for any $q,p$, $U(q) \leq U(p) + (q-p)^\top \nabla U(p) + \frac{\mu}{2}\|p-q\|^2$. After minimizing both sides in $q$ and reorganizing, the result follows.
\end{proof}

\begin{lemma} \label{lemma:bounded} Let $A$ and $B$ be convex twice differentiable functions such that $\|\frac{\partial^2 A}{\partial p}\| \leq \alpha$ and $\|\frac{\partial^2 B}{\partial p}\| \leq \beta$ for constant  $\alpha, \beta > 0$. Furthermore, let $A_{\textsl{min}} = \min_p A(p)$, $B_{\textsl{min}} = \min_p B(p)$ and $V_{\textsl{min}} = \min_p \sqrt{A(p)^2+B(p)^2}$. Then, the Hessian in \eqref{eq:hessianC}  satisfies:
\begin{equation}
\label{eq:boundhessianC}
    \left\|\frac{\partial^2 C}{\partial p^2}\right\| \leq \alpha + \left(3{+}\frac{\sqrt{A_{\textsl{min}}^2+B_{\textsl{min}}^2}}{V_{\textsl{min}}} \right)\sqrt{\alpha^2+\beta^2}. 
\end{equation}

\end{lemma}

\begin{proof} Let $V = [A \ B]^{\top}$, $\nu = [\alpha \ \beta]^\top$, $M = [-\frac{\partial B}{\partial p} \ \frac{\partial A}{\partial p}]$ and $V_{\textsl{min}} = [A_{\textsl{min}} \ B_{\textsl{min}}]^{\top}$. We begin by noting that the rightmost element at the right-hand side of \eqref{eq:hessianC} can be written as $V^\top M M V$. Applying the norm in both sides of \eqref{eq:hessianC}, imposing the bounds  $\|\frac{\partial^2 A}{\partial p}\| \leq \alpha$ and $\|\frac{\partial^2 B}{\partial p}\| \leq \beta$ and applying Cauchy-Schwarz's inequality/ submultiplicativity of the spectral norm, we can bound  $\|V^\top M M V\| \leq \|M\|^2\|V\|^2$ and thus:

\begin{equation}
  \left\|\frac{\partial^2 C}{\partial p^2} \right\| \leq 
  \frac{C}{\|V\|}\alpha + \frac{B}{\|V\|} \beta + \frac{\|M\|^2}{\|V\|}.
\end{equation}
Since $C= A + \|V\|$, the previous equality can be written as:
\begin{equation}
  \left\|\frac{\partial^2 C}{\partial p^2} \right\| \leq 
  \alpha + \nu^\top \frac{V}{\|V\|} + \frac{\|M\|^2}{\|V\|}.
\end{equation}
Again applying Cauchy-Schwarz to $\nu^\top \frac{V}{\|V\|}$, we find that it is smaller or equal than than $\|\nu\| = \sqrt{\alpha^2+\beta^2}$, and thus:
\begin{equation}
  \left\|\frac{\partial^2 C}{\partial p^2} \right\| \leq 
  \alpha + \sqrt{\alpha^2+\beta^2} + \frac{\|M\|^2}{\|V\|}.
\end{equation}
We will bound $\frac{\|M\|^2}{\|V\|}$. We note that $\|M\| \leq \|M\|_F$, in which $\|M\|_F$ is the Frobenius norm \cite{Horn1990}, thus
\begin{equation}
   \|M\|^2 \leq \left\|\frac{\partial A}{\partial p} \right\|^2+\left \|\frac{\partial B}{\partial p}\right \|^2. 
\end{equation} From Lemma \ref{lemma:convprop}:
\begin{eqnarray}
&&\frac{\|M\|^2}{\|V\|} \leq 2\alpha\frac{A}{\|V\|}{+}2\beta\frac{B}{\|V\|} {-}2\alpha\frac{A_{\textsl{min}}}{\|V\|}{-}2\beta \frac{B_{\textsl{min}}}{\|V\|}= \nonumber \\
&& 2\frac{V^\top \nu}{\|V\|}-2\frac{V_{\textsl{min}}^\top \nu}{\|V\|}
\end{eqnarray}
Applying Cauchy-Schwarz in $V^\top \nu$ and $V_{\textsl{min}}^\top \nu$:
\begin{equation}
   \frac{\|M\|^2}{\|V\|} \leq \left(2+ \frac{\|V_{\textsl{min}}\|}{\|V\|}\right)\|\nu\| \leq \left(2+ \frac{\|V_{\textsl{min}}\|}{V_{\textsl{min}}}\right)\|\nu\|
\end{equation}
\noindent which concludes the proof.
\end{proof}

\textbf{Proof of Proposition \ref{prop:convexified}}:

We will prove each one of the properties in Definition \ref{def:kp2s}.

\underline{Property (1)}: comes easily from the expression in \eqref{eq:Efrome} and the fact that $\alpha > 0$ and $e^{\mathcal{S}}(p) \geq 0$.

\underline{Property (2)}: from Lemma \ref{lemma:ABsum} using $A = \varepsilon \rho$ and $B =  \sigma e^{\mathcal{S}}$, it is established that $\frac{\partial^2 E^{\mathcal{S}}}{\partial p^2}(p) > 0$. 

To show that $\sigma$ and $\varepsilon$ can be chosen so $I_{n \times n} > \frac{\partial^2 E^{\mathcal{S}}}{\partial p^2}(p)$, we use Lemma \ref{lemma:bounded}  again using $A =  \varepsilon \rho$ and $B = \sigma e^{\mathcal{S}}$. In this case, $\alpha = \varepsilon$ and $\beta = \sigma$ can be taken. It is clear that $\varepsilon$ and $\sigma$ can be taken sufficiently small to make the right hand side of \eqref{eq:boundhessianC} as small as necessary, eventually below $1$. Note that in this case, $A_{\textsl{min}}$ is a finite negative number, $B_{\textsl{min}} = 0$ and $V_{\textsl{min}}$ is a nonzero finite number (since $\varepsilon \rho$ and $\sigma e^{\mathcal{S}}$ cannot vanish simultaneously once $\rho$ needs to be zero when  $e^{\mathcal{S}}$ vanishes). 

\underline{Property (3)}: can be checked by inspection, provided that $e^{\mathcal{S}}$ and $\rho$ are $k$ times differentiable, and $e^{\mathcal{S}}$ and $\rho$ cannot vanish simultaneously.

\underline{Property (4)}:  from the expression in \eqref{eq:Efrome}, it is clear that it is zero only if $e^{\mathcal{S}}(p)=0$. Furthermore, since $\rho$ is negative when $e^{\mathcal{S}}(p)=0$, it indeed vanishes when $p \in \mathcal{S}$. $\square$

