\begin{tabular}{cccccc}
\toprule
       data access &  statistics & semantics & estimation \\
\hline
        $\sim$10ms & 1ms<  & \makecell{$\sim$2ms(GPUs) \\ $\sim$1.23s (CPUs) } & 1ms<\\
\bottomrule
