	\subsection{Lopsided version of Zarankiewicz's problem for two families of boxes} \label{sec:lopdidedbox}

	In this subsection we bound the number of edges in a $K_{t,gt}$-free intersection graph of two families of axis-parallel boxes in $\Re^d$. We prove the following:
	\begin{theorem}
	\label{cons:lopsided}
		Let $A,B$ be two multisets of boxes in $\Re^d$ where $|A|=n,|B|=m$ and $m=\mathrm{poly}(n)$. If their intersection graph $G_{A,B}$ is $K_{t,gt}$-free ($t$ on the side of $A$), then 
		\[
		|E(G_{A,B})| \leq O_d(gtn f_{d,t}(n) +  m f_{d,t}(m)),
		\]
		where $f_{d,t}(n)=t(\frac{\log n}{\log \log n})^{d-1}$.
	\end{theorem}
	Theorem~\ref{cons:lopsided} is a generalization and an improvement of the bound on intersections between two families of axis-parallel rectangles in $\Re^2$ proved in~\cite[Theorem~1.7]{KellerS24}. Compared to the result of~\cite{KellerS24}, Theorem~\ref{cons:lopsided} applies in $\Re^d$ for all $d \geq 2$, is not restricted to the symmetric case of $K_{t,t}$, and has a better dependence on $t$. 
		\begin{remark}
		We state the theorem in terms of the auxiliary function $f_{d,t}(n)$, as in the sequel it will be used in a blackbox manner. We note that an easy argument using biclique covers (see~\cite[Lemma~2.1]{Chan06}) allows replacing $f_{d,t}(n)$ with $(\log n)^d$. In this way, we get an inferior bound in terms of $n$, but an improved dependency on $t$, which amounts to a better overall bound for $t \gg \log n (\log \log n)^{d-1}$. We conjecture that $f_{d,t}(n)$ can be replaced with $(\frac{\log n}{\log \log n})^{d-1}$, which would lead to a bound of $O_{d,r}(tn^{r-1} (\frac{\log n}{\log \log n})^{d-1})$ for Zarankiewicz's problem for $r$-partite intersection hypergraphs of axis-parallel boxes in $\Re^d$, which is sharp in terms of both $n$ and $t$.
	\end{remark}

The proof of Theorem~\ref{cons:lopsided} is divided into two main cases, based on the following observation. Any intersection between two axis-parallel boxes belongs to one of two types:
\begin{enumerate}
	\item \emph{Vertex containment intersections}, in which a vertex of one box is contained in the other box;

	\item \emph{Facet intersections}, in which a facet of one box intersects a facet of the other box.
\end{enumerate}
We bound each type of intersections with a different divide-and-conquer argument, as presented below.

\subsubsection{Bounding vertex containment intersections}

Due to the lack of symmetry between the two sides, we have to consider separately two types of intersections:
\begin{itemize}
	\item Intersections in which a vertex of a box in $A$ is contained in a box in $B$;

	\item Intersections in which a vertex of a box in $B$ is contained in a box in $A$.
\end{itemize}
For each type, the problem reduces to bounding the number of edges in $K_{t,gt}$-free intersection graphs of points and axis-parallel boxes. Indeed, for the first case we can bound the number of intersections by $|E(G_{A',B})|$, where $A'$ is the set of vertices of the boxes in $A$. The second case can be handled similarly. We prove the following proposition, which is a lopsided version of the bound of~\cite[Theorem~4.5]{CH23} on the number of edges in $K_{t,t}$-free bipartite intersection graphs of points and axis-parallel boxes in $\Re^d$ (though, with a weaker dependence on $t$).  
\begin{proposition}\label{Prop:PtsBoxes}
	Let $A$ be a multiset of points in $\Re^d$ and let $B$ be a multiset of axis-parallel boxes, where $|A|=n$ and $|B|=m$. Then for any $\epsilon>0$,
	\begin{enumerate}
		\item If the bipartite intersection graph $G_{A,B}$ is $K_{t,gt}$-free ($t$ on the side of $A$) then it has \newline $O_{\epsilon} \left(gt^2 n (\frac{\log n}{\log \log n})^{d-1}+ tm (\frac{\log n}{\log \log n})^{d-2+\epsilon}\right)$ edges.

		\item If the bipartite intersection graph of $G_{A,B}$ is $K_{gt,t}$-free ($t$ on the side of $B$) then it has $O_{\epsilon} \left(t n (\frac{\log n}{\log \log n})^{d-1}+ gt^2 m (\frac{\log n}{\log \log n})^{d-2+\epsilon}\right)$ edges.
	\end{enumerate}
\end{proposition}
As we show below, this provides a sufficiently strong bound on the vertex containment intersections, for the needs of Theorem~\ref{cons:lopsided}. 

Due to space constraints, the proof of Proposition~\ref{Prop:PtsBoxes} is presented in Appendix~\ref{app:rect}.

\subsubsection{Bounding facet intersections}

We claim that for a large $n$, the number of facet intersections is significantly smaller than the number of vertex containment intersections. 
\begin{proposition}\label{Prop:Facet}
	Let $A,B$ be multisets of axis-parallel boxes in $\Re^d$, where $|A|=n$ and $|B|=m$. If the bipartite intersection graph $G_{A,B}$ is $K_{t,gt}$-free ($t$ on the side of $A$) then the number of facet intersections between a box in $A$ and a box in $B$ is
	$$O_d \left(gt^2 n (\log n)^{d-2} +tm (\log n)^{d-2} \right).$$
\end{proposition}

We use the following lemma.
\begin{proposition}\label{Prop:HorVer}
	Let $A$ be a multiset of horizontal segments in $\Re^2$ and let $B$ be a multiset of vertical segments in $\Re^2$, where $|A|=n$ and $|B|=m$. Let $g>0$. If the bipartite intersection graph $G_{A,B}$ is $K_{t,gt}$-free (where the $t$ is on the side of $A$) then it has $O(gt^2 n+ tm)$ edges.    
\end{proposition}

Due to space constraints, the proof of Proposition~\ref{Prop:HorVer} is presented in Appendix~\ref{app:rect}.

\begin{proof}[Proof of Proposition~\ref{Prop:Facet}]
	The proof is by induction on $d$. The base case $d=2$ amounts to bounding the number of edges in a $K_{2t,2gt}$-free bipartite intersection graph of a multiset $A$ of horizontal segments in $\Re^2$ and a multiset $B$ of vertical segments in $\Re^2$.
	Indeed, each `facet intersection' in the plane is either an intersection between a horizontal edge of a rectangle in $A$ with a vertical edge of a rectangle in $B$, or vice versa. We can bound the number of facet intersections of the first type by $|E(G_{A',B'})|$, where $A'$ is the multiset of horizontal edges of rectangles in $A$ and $B'$ is the multiset of vertical edges of rectangles in $B$. Note that this intersection graph is $K_{2t,2gt}$-free, as otherwise, $G_{A,B}$ would contain $K_{t,gt}$. The second type can be handled similarly. Hence, Proposition~\ref{Prop:HorVer} yields a bound of $O(gt^2 n +tm)$ in this setting, which proves the induction basis. 

	\medskip

%\medskip The case $d=2$ of Proposition~\ref{cons:lopsided} is the lopsided variant of the $O_t(n \frac{\log n}{\log \log n})$ upper bound for Zarankiewicz's problem for bipartite intersection graphs of two families of axis-parallel rectangles in the plane, proved in~\cite{KellerS24}. Our proof follows the strategy of~\cite{KellerS24}, but replaces a geometric argument used in~\cite{KellerS24} with a stronger charging argument. Due to space limits, the proof is presented in Appendix~\ref{app:rect}. We present below the inductive divide-and-conquer argument which leverages the result from $d=2$ to a general dimension. 
%The argument follows the proof strategy of~\cite[Theorem~4.5]{CH23}.

%\begin{proof}[Proof of Proposition~\ref{cons:lopsided} for $d>2$]
%	The proof is by induction on $d$. The induction basis is the case $d=2$ whose proof appears in Appendix~\ref{app:rect}. 

	In the induction step, we assume that for $(d-1)$-dimensional boxes, the number of facet intersections is bounded by 
	\[
	O_d(gt^2 n (\log n)^{d-3} +tm (\log n)^{d-3}).
	\]
	We bound the number of facet intersections between $x \in A$ and $y \in B$, such that the intersecting facets are othogonal to the $(d-1)$'th and the $d$'th axis, respectively. A bound on the total number of facet intersections clearly follows by multiplying with $d^2$. In the rest of the proof, we call such special intersections `good facet intersections', or just `intersections' for brevity. We make sure that in the dimension reductions in the induction process presented below, every time the first coordinate is the one that is removed, and thus, the good facet intersections are not affected.

	We use the following auxiliary notion. Let $I_d(n,m)$ be the maximum number of good facet intersections between multisets $A,B$ of axis-parallel boxes inside a `vertical strip' $\mathcal{U}=\{x \in \Re^d:u_L<x_1<u_R\}$ of $\Re^d$, where:
	\begin{enumerate}
		\item Each box in $A,B$ has either half of its vertices or all of its vertices in $\mathcal{U}$;

		\item The total number of vertices of boxes in $A$ (resp., boxes in $B$) inside $\mathcal{U}$ is $n \cdot 2^{d-1}$ (resp., $m \cdot 2^{d-1}$);

		\item The bipartite intersection graph of $A,B$ is $K_{t,gt}$-free.
	\end{enumerate}
	We shall prove that 
	\[
	I_d(n,m) \leq O_d(gt^2 n (\log n)^{d-2} +tm (\log n)^{d-2}).
	\] 
	This clearly implies the assertion of the proposition, as by considering a vertical strip $\mathcal{U}$ that fully contains all boxes in $A$ and $B$ (where $|A|=n$ and $|B|=m$), we get that the number of good facet intersections between $A$ and $B$ is at most $I_d(2n,2m)$. (Note that we neglect factors of $O_d(1)$). 

% (Note that we may assume w.l.o.g.~that each segment in $A_1$ has at least one endpoint in the minimal closed vertical strip $v$ that contains all segments of $B_2$. Indeed, truncation of all elements of $A_2$ to their intersections with $v$ does not change the number edges in the bipartite intersection graph).   

%	The proof uses induction on $d$. The induction basis is the assertion $I_2(n,m) \leq O(gtn f_{2,t}(n) +  m f_{2,t}(m))$. We claim that it follows from the case $d=2$ of Proposition~\ref{cons:lopsided}. Indeed, for any strip $\mathcal{U} \subset \Re^2$ and families $A,B$ of axis-parallel rectangles that satisfy Assumptions~(1)-(3) with respect to it, the total number of rectangles in $A$ (resp., $B$) is at most $n$ (resp., $m$). Thus, by Proposition~\ref{cons:lopsided}, their number of intersections is at most   
%	\[
%	O(gt(n) f_{2,t}(n) +  m f_{2,t}(m)).
%	\]
	Let $A,B$ be multisets of boxes that satisfy assumptions~(1)--(3) with respect to a strip $\mathcal{U} \subset \Re^d$. We divide $\mathcal{U}$ into two vertical sub-strips $\sigma_1=\{x \in \Re^d: u_L<x_1<u'\}$ and $\sigma_2=\{x \in \Re^d:u'<x_1<u_R\}$, such that each sub-strip contains $n \cdot 2^{d-2}$ vertices of boxes in $A$. For $i=1,2$, we denote by $A_i$ (resp., $B_i$) the boxes in $A$ (resp., $B$) that have at least one vertex in $\sigma_i$, and by $A'_i$ (resp., $B'_i$) the boxes in $A$ (resp., $B$) that intersect $\sigma_i$ but do not have vertices in it. Note that $A'_1 \subset A_2, A'_2 \subset A_1$, and similarly for $B$. We also denote the number of vertices of boxes in $B$ contained in $\sigma_i$ by $2^{d-1} \cdot m_i$.

	The number of good facet intersections in $\mathcal{U}$ between boxes in $A$ and boxes in $B$ is at most 
	\begin{equation}\label{Eq:Bound-boxes1}
	I(A_1,B_1)+I(A_2,B_2)+I(A_1,B'_1)+I(A'_2,B_2)+I(A_2,B'_2)+I(A'_1,B_1),
	\end{equation}
	where $I(X,Y)$ denotes the number of good facet intersections between an element of $X$ and an element of $Y$.

	Indeed, $I(A_1,B_1)$ (resp., $I(A_2,B_2)$) counts intersections between pairs of boxes that have at least one vertex in $\sigma_1$ (resp., $\sigma_2$). $I(A_1,B'_1)+I(A'_2,B_2)$ upper bounds the number of intersections between a box in $A$ that has a vertex in $\sigma_1$ and a box in $B$ that has a vertex in $\sigma_2$. $I(A_2,B'_2)+I(A'_1,B_1)$ upper bounds the number of intersections between a box in $A$ that has a vertex in $\sigma_2$ and a box in $B$ that has a vertex in $\sigma_1$.

	By the definitions, we have $I(A_1,B_1)\leq I_d(\frac{n}{2},m_1)$ (where $\sigma_1$ is taken as the vertical strip instead of $\mathcal{U}$). Similarly, $I(A_2,B_2) \leq I_d(\frac{n}{2},m_2)$. 

	To handle the other types of intersections, we observe that a box in $A_1$ intersects a box in $B'_1$ if and only if their projections on the hyperplane $\mathcal{H}=\{x \in \Re^d: x_1=u'\}$ (which are $(d-1)$-dimenstional boxes) intersect. Let $\bar{A}_1$ and $\bar{B}'_1$ denote the corresponding families of projections. We have $|\bar{A}_1|=|A_1|=\frac{n}{2}$ and $|\bar{B}'_1|=|B'_1|\leq m_2$. The multisets  $\bar{A}_1$ and $\bar{B}'_1$ are multisets of axis-parallel boxes in $\Re^{d-1}$ whose bipartite intersection graph is $K_{t,gt}$-free. Hence, by the induction hypothesis we have
	\begin{align*}
	\begin{split}
		I(A_1,B'_1)=I(\bar{A}_1,\bar{B}'_1) &\leq 
			O_d \left(gt^2 \tfrac{n}{2} \left(\log \tfrac{n}{2}\right)^{d-3} +tm_2 \left(\log \tfrac{n}{2}\right)^{d-3}\right) \\ 
			&\leq O_d\left(gt^2 \tfrac{n}{2} \left(\log n\right)^{d-3} +tm_2 \left(\log n\right)^{d-3}\right),
	\end{split}
	\end{align*}
	Applying the same argument to $I(A'_2,B_2), I(A'_1,B_1)$ and $I(A_2,B'_2)$, we get
	\begin{align*}
		\begin{split}
		I(A_1,B'_1)&+I(A'_2,B_2)+I(A_2,B'_2)+I(A'_1,B_1) \\ &\leq  
		O_d(4gt^2 \tfrac{n}{2} (\log n)^{d-3} +2tm_2 (\log n)^{d-3} + 2tm_1 (\log n)^{d-3}) \\
		&= O_d(2gt^2 n (\log n)^{d-3}+ 2tm (\log n)^{d-3}).
		\end{split}
	\end{align*}
	Combining this with the bounds on $I(A_1,B_1)$ and $I(A_2,B_2)$ and substituting to~\eqref{Eq:Bound-boxes1}, we obtain the recursive formula 
	\[
	I_d(n,m) \leq \max_{m_1+m_2=m} \left(I_d(\tfrac{n}{2},m_1)+I_d(\tfrac{n}{2},m_2)+
	O_d(2gt^2 n (\log n)^{d-3}+ 2tm (\log n)^{d-3}) \right),
	\]
	which solves to 
	\[
	I_d(n,m) \leq \log n \cdot O_d(gt^2 n (\log n)^{d-3}+ tm (\log n)^{d-3}) \leq O_d(gt^2 n (\log n)^{d-2}+ tm (\log n)^{d-2}).
	\]
	This completes the proof.
\end{proof}	

\subsubsection{Completing the proof of Theorem~\ref{cons:lopsided}}

Now we are ready to wrap up the proof of Theorem~\ref{cons:lopsided}.

\begin{proof}[Proof of Theorem~\ref{cons:lopsided}]
	Let $A,B$ be multisets of axis-parallel boxes in $\Re^d$ that satisfy the assumptions of the theorem. As written above, the intersections between $A$ and $B$ can be divided into \emph{vertex containment intersections} and \emph{facet intersections}. 

	To bound the number of vertex containment intersections, we apply Proposition~\ref{Prop:PtsBoxes}, with $\epsilon=\frac{1}{2}$. Specifically, we use Proposition~\ref{Prop:PtsBoxes}(1) to bound the number of intersections in which a vertex of $a \in A$ is contained in a box $b \in B$. Furthermore, we use Proposition~\ref{Prop:PtsBoxes}(2) \emph{with the roles of $n$ and $m$ reversed} to bound the number of intersections in which a vertex of $b \in B$ is contained in a box $a \in A$.   We get that the number of vertex containment intersections is at most
	$$O_d\left(gt^2 n (\tfrac{\log n}{\log \log n})^{d-1}+ tm (\tfrac{\log n}{\log \log n})^{d-1.5} + t m (\tfrac{\log m}{\log \log m})^{d-1}+ gt^2 n (\tfrac{\log m}{\log \log m})^{d-1.5}\right).$$ 
	By Proposition~\ref{Prop:Facet}, the number of facet intersections is at most 
	$$O_d(gt^2 n (\log n)^{d-2}+ tm (\log n)^{d-2}).$$ 
	Note that for a large $n$, we have $(\log n)^{d-2} = o((\frac{\log n}{\log \log n})^{d-1.5})$, and hence, the number of facet intersections is dominated by the number of vertex containment intersections. 

	Finally, since $m=\mathrm{poly(n)}$, the terms $tm (\frac{\log n}{\log \log n})^{d-1.5}$ and $gt^2 n (\frac{\log m}{\log \log m})^{d-1.5}$ are dominated by the two other terms. Therefore, we have
	\[
	|E(G_{A,B})| \leq O_d\left(gt^2 n (\tfrac{\log n}{\log \log n})^{d-1}+ t m (\tfrac{\log m}{\log \log m})^{d-1} \right) = O_d(gtn f_{d,t}(n)+m f_{d,t}(m)),
	\]  	  
	as asserted. This completes the proof.
\end{proof}


