%	Let us state the weaker variant of Theorems~\ref{thm:boxes} and~\ref{thm:rectangles-intro} that we prove in this section. In this variant, the logarithmic term $f_{d,t}(n)$ appears with a power of $r-1$ (instead of $1$ in the improved theorems).

We prove the following.	
	\begin{proposition}\label{thm:boxes_weaker}
		Let $A_1,A_2,\ldots,A_r$ be families of $n$ axis-parallel boxes in $\Re^d$, and let $H$ be their $r$-partite intersection hypergraph. 
		%(I.e., $V(H)=A_1 \cup A_2 \cup \ldots \cup A_r$ and $E(H)=\{(a_1,a_2,\ldots,a_r): a_1\in A_1,\ldots, a_r\in A_r, a_1\cap \ldots \cap a_r \neq \emptyset\}$). 
		If $H$ is $K_{t,t,\ldots,t}^r$-free, then $|\E(H)|=O_r\left(t \left(n f_{d,t}(n)\right)^{r-1} \right)$.
	\end{proposition}

	The proof of Proposition~\ref{thm:boxes_weaker} is by induction on $r$. For the sake of simplicity, we present here the proof for $r=3$, and complete the argument for a general $r$ in Appendix \ref{app:boxes_weaker}. 

	\begin{proof}[Proof of Proposition~\ref{thm:boxes_weaker} for $r=3$]
		Let $A_1=A,A_2=B,A_3=C$.
		Let $AB$ be the following multiset of axis-parallel boxes: $AB=\{a\cap b:a \in A, b\in B, a\cap b \neq \emptyset\}$. (Note that the intersection of two axis-parallel boxes is indeed an axis-parallel box). Let $G$ be the bipartite intersection graph of the families $C$ and $AB$. It is clear that $|E(G)|=|\E(H)|$, since there is a clear one-to-one correspondence between edges of $G$ and hyperedges of $H$.

		We claim that for a sufficiently large constant $M$, the graph $G$ is $K_{t,M tn f_{d,t}(n) }$-free. Indeed, assume to the contrary that $G$ contains a copy of $K_{t,Mtn  f_{d,t}(n)}$, for a `large' $M$. This means that there exist $t$ boxes $c_1,c_2,\ldots,c_t \in C$ which all have a non-empty intersection with certain 
		$Mtn  f_{d,t}(n)$ axis-parallel boxes of the form $a_i \cap b_i$, with $a_i \in A$, $b_i \in B$. Denote by $A'$ the set of all $a_i \in A$ that participate in such intersections, and by $B'$ the set of all $b_i \in B$ that participate in such intersections. Let $G'$ be the bipartite intersection graph of $A',B'$. We have $|E(G')|\geq Mtn  f_{d,t}(n)$, and hence, by Theorem~\ref{cons:lopsided} (applied with $m=n$ and $g=1$), it contains a $K_{t,t}$ (using the assumption that $M$ is sufficiently large). This means that there exist $a_1,a_2,\ldots,a_t \in A$ and $b_1,b_2,\ldots,b_t \in B$ such that for all $1 \leq i,j \leq t$, we have $a_i \cap b_j \neq \emptyset$, and both $a_i$ and $b_j$ have a non-empty intersection with each of $c_1,\ldots,c_t$ (since they participate in pairs whose intersection with each of $c_1,\ldots,c_t$ is non-empty). As any three pairwise intersecting axis-parallel boxes have a non-empty intersection, this implies that $a_i \cap b_j \cap c_k \neq \emptyset$ for all $1 \leq i,j,k \leq t$, and consequently, $H$ contains a $K_{t,t,t}$, a contradiction.

		We have thus concluded that $G$ is $K_{t,M tn  f_{d,t}(n)}$ free, for a sufficiently large constant $M$. By Theorem~\ref{cons:lopsided}, applied with $n$, $m=n^2$, and $g=M  n  f_{d,t}(n)$, this implies that 
		\[
		|\E(H)|=|E(G)| \leq O\left(t  \left(n  f_{d,t}(n)\right)^2 \right).
		\]
		This completes the proof.
	\end{proof}

	Note that in this proof, we used the fact that axis-parallel boxes in $\Re^d$ have \emph{Helly number 2}, namely, that any pairwise intersecting family of axis-parallel boxes has a non-empty intersection. Without this property, the existence of $K_{t,t}$ in $G'$ does not necessarily imply the existence of $K_{t,t,t}$ in $H$.

	The proof for a general $r$ is an inductive process, in which at the $\ell$'th step, one considers an auxiliary bipartite intersection graph of boxes, whose vertex sets are the multiset $A_1 A_2 \ldots A_{\ell+1} = 
	\{(a_1 \cap \ldots \cap a_{\ell+1}): \forall i, a_i \in A_i, \cap_{i=1}^{\ell+1} a_i \neq \emptyset \}$, where the multiplicity of each element is the number of $(a_1,\ldots,a_{\ell+1})$ tuples that lead to it, and $A_{\ell+2}$. At each step, Theorem~\ref{cons:lopsided} is applied once again, and the fact that axis-parallel boxes have Helly number 2 is deployed once again. As this part of the proof is a bit more cumbersome and is not needed for the proof of Theorem~\ref{thm:boxes} presented below, we provide it in Appendix \ref{app:boxes_weaker}.

	\subsubsection{Proof of Theorem~\ref{thm:boxes}} \label{sec:boxes}

	In Proposition~\ref{thm:boxes_weaker}, the polylogarithmic factor in the upper bound increases with $r$, since at each step of the inductive process we apply Theorem~\ref{cons:lopsided} and `pay' another $f_{d,t}(n)$-factor. In this subsection, we show how to avoid this dependency on $r$. Let us restate Theorem~\ref{thm:boxes}.

	\begin{theorem}[Theorem~\ref{thm:boxes} restated]
	\label{thm:unified}	
	Let $r,d,t \geq 2$ and let $H$ be the intersection hypergraph of $r$ families $A_1, \ldots, A_r$ of $n$ axis-parallel boxes in general position in $\Re^d$. If $H$ is $K_{t,\ldots,t}^r$-free, then $|\E(H)|=O_{r,d}(t n^{r-1} f_{d,t}(n) )$, where 
	$f_{d,t}(n) = t (\frac{\log n}{\log \log n})^{d-1}$.
	\end{theorem}
	%It is clear that Theorem~\ref{thm:unified} is a restatement of~\ref{thm:boxes} and~\ref{thm:rectangles-intro}.
	%\noindent Recall that the bound in {Theorem \ref{thm:boxes} is tight in terms of $n$ as was discussed in the introduction.

	In the proof, we use the following modification of the \emph{biclique cover theorem} (see~\cite{CES83}) for axis-parallel boxes, that may be of independent interest. We note that the relation between Zarankiewicz's problem and biclique covers was already observed in~\cite{CH23,Do19}.
	\begin{definition}
		A biclique cover of a graph $G=(V,E)$ is a collection of pairs of vertex subsets $\{(A_1,B_1),\ldots,(A_l,B_l)\} $ such that $E=\bigcup_{i=1}^l (A_i \times B_i)$. The size of the cover is $\Sigma_{i=1}^l \left(|A_i| + |B_i|\right)$.
	\end{definition}

	\begin{lemma}\label{lem:biclique}
		Let $n,m,b \in \mathbb{N}$ be such that $b \leq \min(n,m)$, and let $A,B$ be families of axis-parallel boxes in $\Re^d$, with $|A|=n$ and $|B|=m$. Then the bipartite intersection graph of $A,B$ can be partitioned into a union of $O(b \log^{d-1} b)$ bicliques (with no restriction on their size) and $O(b \log^{d-1} b)$ ``partial bicliques'' (namely, subgraphs of bicliques), each of size at most $\frac{n}{b} \cdot \frac{m}{b}$. 
	\end{lemma}
	Due to space constraints, the proof of the lemma is presented in Appendix~\ref{app:biclique}.

	\medskip The motivation behind our proof of Theorem~\ref{thm:boxes} is as follows: Assume that we add an additional assumption that the $(r-1)$-partite intersection graph of the families $A_1,\ldots,A_{r-1}$ is complete. Namely, that for all $1 \leq i<j \leq r-1$, any box in $A_i$ intersects any box in $A_j$. Furthermore, assume that by applying (only once!) Theorem~\ref{cons:lopsided}, we show that the bipartite intersection graph of the multiset $A_1 A_2 \ldots A_{r-1}= \{
	a_1 \cap \ldots\cap a_{r-1} : \forall i, a_i \in A_i, \cap_{i=1}^{r-1} a_i \neq \emptyset \}$ and the family $A_r$ contains $K_{gt,t}$, for $g=n^{r-2}$. This means that some $t$ boxes from $A_r$ intersect $gt=tn^{r-2}$ boxes of the type $\{a_1 \cap \ldots\cap a_{r-1} : a_i \in A_i\}$. These $gt$ boxes involve at least $t$ boxes from each $A_i$ ($1 \leq i \leq r-1$). Thus, by our additional assumption and by the fact that axis-parallel boxes admit Helly number 2, the existence of $K_{gt,t}$ in the bipartite intersection graph, implies the existence of $K_{t, \ldots,t}^r$ in the original $r$-partite intersection hypergraph. Therefore, the suggested additional assumption enables avoiding repeated applications of Theorem~\ref{cons:lopsided}, and hence obtaining a bound with a logarithmic factor that does not increase with $r$.

	In order to show that we can indeed make the additional assumption described above without affecting the final bound, we define a constraints graph $G$, not to be confused with the auxiliary graph $G$ from Section \ref{sec:boxes_weak}.

		\begin{definition}\label{def:constraint}
			For an $r$-tuple of set families $A_1,\ldots,A_r$, the \emph{constraints graph} $G=G_{A_1,\ldots,A_r}$ is defined as follows. The vertex set of $G$ is $V(G)=\{1,2,\ldots,r\}$, and $(i,j) \in G$ if $\exists a_i \in A_i, a_j \in A_j$ such that $a_i \cap a_j = \emptyset$.
		\end{definition}

		This graph $G$ represents the ``distance'' of the $r$-tuple of families $A_1,\ldots,A_r$ from the desired setting in which there exists $i$ such that any box from $A_i$ intersects any box from $A_j$, for all $j \neq i$. Our goal in the proof below is to remove all the edges from $G$, except for those emanating from a single vertex $i$. This will show that one can indeed make the additional assumption described above without affecting the final bound.

	\begin{proof}[Proof of Theorem~\ref{thm:unified}]
		Let $T_G(n_1, \ldots,n_r)$ be the maximum number of hyperedges in a $K_{t, \ldots,t}^r$-free $r$-partite intersection hypergraph $H$ of $r$ families $A_1, \ldots,A_r$ of axis-parallel boxes in $\Re^d$, where $|A_i|=n_i$, and the constraints graph of $r$-tuple $A_1,\ldots,A_r$ is $G$. Denote $T_G(n) = T_g(n,\ldots,n)$. In order to prove the theorem, it is clearly sufficient to prove that for any constraint graph $G$, we have 
		$T_G(n) \leq O(t n^{r-1} f_{d,t}(n))$.
		We prove this claim by induction on $|E(G)|$. 

%		\begin{claim}\label{cl:T_G}
%			In the above notations, if $H$ is $K_{t, \ldots,t}^r$-free, then $T_G(n) \leq O(t n^{r-1} f_{d,t}(n))$.
%		\end{claim}   

%		\begin{proof}[Proof of Claim \ref{cl:T_G}]

		If $E(G)=\emptyset$, then for all $i \neq j$, any $a_i \in A_i$ intersects any $a_j \in A_j$. Since $H$ is $K_{t, \ldots,t}^r$-free, this implies $n<t$ and we are done. 

		In the induction step, we assume that we have already proved the claim for any constraints graph with a smaller number of edges, and we now consider a constraints graph $G$. We consider three cases:
		\begin{itemize}
			\item Case A: $G$ contains two non-adjacent edges;

			\item Case B: $G$ is a triangle;

			\item Case C: $G$ is a star.
		\end{itemize} 	
		Clearly, any graph $G$ belongs to one of the three cases.

	\medskip \noindent \textbf{Case A: $G$ contains two non-adjacent edges.} 
	Say these two non-adjacent edges are $(1,2)$ and $(3,4)$. Our goal now is to `remove' the edge $(1,2)$ (and later, also the edge $(3,4)$) from $G$, by partitioning the intersection graph of $A_1$ and $A_2$ into bicliques.
	To this end, we use Lemma~\ref{lem:biclique} with a large constant $b$ to partition the entire hypergraph into smaller hypergraphs, induced by a partition of the bipartite intersection of $A_1$ and $A_2$ to `full' bicliques and `partial' bicliques. We obtain the recursion: 
			\begin{equation}\label{eq:1}
				T_G(n) \leq O(b \log^{d-1} b)T_G(\tfrac{n}{b},  \tfrac{n}{b}, n, \ldots, n)+ O(b \log^{d-1} b)O(tn^{r-1} f_{d,t}(n)),
			\end{equation}
	where the right term comes from applying the induction hypothesis on the hypergraphs induced by full bicliques, whose constraints graph is $G \setminus \{(1,2)\}$, and the left term comes from the partial bicliques.

	Now, in order to bound $T_G(\tfrac{n}{b},  \tfrac{n}{b}, n, \ldots, n)$, we do the same with the sets $A_3,A_4$ and obtain
			\begin{equation}\label{eq:2}
				T_G(\tfrac{n}{b},  \tfrac{n}{b}, n, \ldots, n) \leq O(b \log^{d-1} b)T_G(\tfrac{n}{b},  \tfrac{n}{b},\tfrac{n}{b},  \tfrac{n}{b}, n, \ldots, n)+ O(b \log^{d-1} b)O(tn^{r-1} f_{d,t}(n)).
			\end{equation}
			Combining (\ref{eq:1}) and (\ref{eq:2}) together, we get
			\begin{equation}\label{eq:3}
				T_G(n) \leq O(b^2 \log^{2d-2} b)   \left( T_G(\tfrac{n}{b},  \tfrac{n}{b},\tfrac{n}{b},  \tfrac{n}{b}, n, \ldots, n)+  O(tn^{r-1} f_{d,t}(n))  \right).
			\end{equation}
			To bound the left term in the right hand side, we partition the hypergraph into $b^{r-4}$ hypergraphs which $r$ sides of size $\tfrac{n}{b}$ by partitioning each of the sets $A_5,\ldots,A_r$ arbitrarily into $b$ parts, each of size $\tfrac{n}{b}$. We obtain  
			\begin{equation}\label{eq:4}
				T_G(n) \leq O(b^2 \log^{2d-2} b)   \left(b^{r-4}T_G(\tfrac{n}{b})+ O (tn^{r-1} f_{d,t}(n))  \right).
			\end{equation}
			The recursion~\eqref{eq:4} solves to $	T_G(n) =O(tn^{r-1} f_{d,t}(n)) $, and we are done.

			\begin{remark}
				Note that if we had started by partitioning arbitrarily each $A_i$ into $b$ parts, then the term $O(b^{r-2} \log^{2d-2}b) T_G(\frac{n}{b})$ in (\ref{eq:4}) would have been replaced by $O(b^{r}) T_G(\frac{n}{b})$, and the recursion would solve to $\Omega(n^r)$. The use of the biclique cover enables us to split two coordinates into $b$ parts at the cost of a factor of $O(b\log^{d-1} b)$, instead of $O(b^2)$. Performing one such split allows reducing the bound to $O(tn^{r-1}\log n f_{d,t}(n))$, and performing two splits allows obtaining the desired bound $O(tn^{r-1}f_{t,d}(n))$. 
			\end{remark}

			\medskip \noindent \textbf{Case B: $G$ is a triangle.} Say $E(G) = \{(1,2),(2,3),(1,3)\}$. In this case, we first split $A_1$ and $A_2$ by Lemma \ref{lem:biclique}, then we split $A_2$ and $A_3$ and then we split $A_1$ and $A_3$.

			Using the induction hypothesis, by splitting $A_1,A_2$ we obtain
			\begin{equation}\label{eq:5}
				T_G(n) \leq O(b \log^{d-1} b)  \left( T_G(\tfrac{n}{b},  \tfrac{n}{b}, n, \ldots, n)+  O(tn^{r-1} f_{d,t}(n)) \right).
			\end{equation}
			By splitting $A_2,A_3$, we get
			\begin{equation}\label{eq:6}
				T_G(\tfrac{n}{b},  \tfrac{n}{b}, n, \ldots, n) \leq O(b \log^{d-1} b)  \left( T_G(\tfrac{n}{b},  \tfrac{n}{b^2},\tfrac{n}{b}, n, \ldots, n)+  O(tn^{r-1} f_{d,t}(n)) \right),
			\end{equation}
			and by splitting $A_1,A_3$ we have
			\begin{equation}\label{eq:7}
				T_G(\tfrac{n}{b},  \tfrac{n}{b^2}, \tfrac{n}{b}, n, \ldots, n) \leq O(b \log^{d-1} b)  \left( 
				T_G(\frac{n}{b^2},  \frac{n}{b^2},\frac{n}{b^2}, n, \ldots, n)+  O(tn^{r-1} f_{d,t}(n)) \right).
			\end{equation}
			Combining (\ref{eq:5})-(\ref{eq:7}), we obtain 
			\begin{equation}\label{eq:8}
				T_G(n) \leq O(b^3 \log^{3d-3} b)   \left(T_G(\tfrac{n}{b^2},\tfrac{n}{b^2},\tfrac{n}{b^2},n,\ldots,n)+ O (tn^{r-1} f_{d,t}(n))  \right),
			\end{equation}
			and by partitioning each of $A_4,\ldots,A_r$ arbitrarily into $b$ equal parts, we get
			\begin{equation}\label{eq:9}
				T_G(n) \leq O(b^{2r-3} \log^{3d-3} b) T_G(\tfrac{n}{b^2}) +  O(b^3 \log^{3d-3} b)O (tn^{r-1} f_{d,t}(n)).   
			\end{equation}
			As above, this recursion solves to $	T_G(n) =O(tn^{r-1} f_{d,t}(n)) $.

			\medskip \noindent \textbf{Case C: $G$ is a star.} Say $G$ is a star centered at $A_r$. In this case we don't apply the induction hypothesis. Instead, we apply Theorem~\ref{cons:lopsided} (only once, in contrast to the argument in Section \ref{sec:boxes_weak}).

			Assume on the contrary that  $T_G(n) >Ctn^{r-1} f_{d,t}(n) $ for some large constant $C$. Consider the intersection graph between the multiset $A_1 A_2 \ldots A_{r-1}= \{
			a_1 \cap \ldots\cap a_{r-1} : \forall i, a_i \in A_i, \cap_{i=1}^{r-1} a_i \neq \emptyset \}$ and the family $A_r$. Since the number of edges in this graph is at least $\Omega(tn^{r-1} f_{d,t}(n))$, by Theorem~\ref{cons:lopsided} (with the parameters $n, m=n^{r-1}$ and $g=n^{r-2}$), this intersection graph contains $K_{gt,t}$.

			This means that some $t$ specific boxes from $A_r$ intersect $gt=n^{r-2}t$ boxes of the type $a_1 \cap \ldots \cap a_{r-1}$ ($a_i \in A_i$). These $gt$ boxes involve at least $t$ boxes from each $A_i$ ($1 \leq i \leq r-1$). Hence, there exist $A'_1 \subset A_1, \ldots, A'_r \subset A_r$, each of size $t$, such that any $a_1,\ldots,a_r$, where $a_1 \in A'_1, \ldots, a_r \in A'_r$, are pairwise intersecting. (Here we use the setting of case~C in which for all $1 \leq i<j \leq r-1$, any two boxes $a_i \in A_i$ and $a_j \in A_j$ intersect.) Since axis-parallel boxes have Helly number 2, this implies that for all  $a_1 \in A'_1, \ldots, a_r \in A'_r$ we have $a_1 \cap \ldots \cap a_r \neq \emptyset$, and hence, the restriction of $H$ to $A'_1 \cup \ldots \cup A'_r$ is a copy of $K^r_{t,t,\ldots,t}$, a contradiction.  This completes the proof of Theorem~\ref{thm:unified}, and thus of Theorem~\ref{thm:boxes}. 			
		\end{proof}


		\section{Intersection Hypergraphs of Pseudo-discs}
		\label{sec:pd}

%		Recall that a family of simple Jordan regions in the plane is a family of pseudo-discs if the boundaries of every two regions intersect at most twice. For technical reasons it is convenient to assume that the pseudo-discs are $y$-monotone, namely, that the intersection of any vertical line with a region from the family is either empty or an interval.

%		Given $r$ families $A_1, \ldots, A_r$ of pseudo-discs, recall that their intersection hypergraph is the $r$-partite hypergraph $H$ whose vertex set, $V(H)$, is $A_1 \cup \ldots \cup A_r$ and $ \{  \{ a_1, \ldots, a_r\} : a_i \in A_i \}$ is a hyperedge in $\E(H)$ if $a_1 \cap \ldots \cap a_r \neq \emptyset$. 

In this section we prove Theorem \ref{thm:pd}. Let us recall the statement of the theorem. 

\medskip \noindent \textbf{Theorem \ref{thm:pd}.} Let $r,t \geq 2$ and let $H$ be the $r$-partite intersection hypergraph of families $A_1, \ldots, A_r$ of $n$ $y$-monotone pseudo-discs in general position in the plane. If $H$ is $K_{t,\ldots,t}^r$-free, then $|\E(H)|=O(t^6 n^{r-1} (\log n)^{r-2} )$.

\medskip

A tool crucially used in the proof is a lopsided version of the following result from~\cite{CH23}.
\begin{theorem}\cite[Corollary~5.1]{CH23}
\label{thm:pdCH}
	Let $P$ be a set of $n$ points in the plane, and let $\F$ be a family of $m$ $y$-monotone pseudo-discs in general position in the plane. If the bipartite intersection graph $G(P,\F)$ is $K_{t,t}$-free ($t \geq 2$), then $$|E(G(P,\F))| = O(tn +tm \log \log m + \log t).$$
\end{theorem}

The lopsided variant of Theorem \ref{thm:pdCH} reads as follows. 

\begin{theorem}[Lopsided variant of Theorem \ref{thm:pdCH}]
\label{thm:pdls}
	Let $P$ be a multiset of $n$ points in the plane, and let $\F$ be a multiset of $m$ $y$-monotone pseudo-discs in general position in the plane. If the bipartite intersection graph $G(P,\F)$ is $K_{gt,t}$-free ($t,g \geq 2$, $gt$ on the side of the points), then $$|E(G(P,\F))| = O(tn +gtm \log m ).$$
\end{theorem}
Due to space constraints, the proof of Theorem~\ref{thm:pdls}, which uses the geometric technique of \emph{shallow cuttings}~\cite{Mat92}, is presented in Appendix \ref{app:pd}. Note that for $g=1$, the bound we obtain is weaker than the bound of Theorem~\ref{thm:pdCH}. The reason for this is explained in Remark \ref{rem:clip} below.

\medskip The proof of Theorem \ref{thm:pd} uses induction on $r$, where the induction basis ($r=2$) is the following theorem from \cite{KellerS24}:
\begin{theorem}\cite[Theorem 1.6]{KellerS24} \label{thm:pdr=2}
	Let $t \geq 2$ and let $G$ be the bipartite intersection graph of two families of pseudo-discs, each of size $n$. If $G$ is $K_{t,t}$-free then $|E(G)|=O(t^6n)$.
\end{theorem}

\begin{remark}
	Note that the lopsided Theorem~\ref{thm:pdls} builds upon Theorem~\ref{thm:pdCH}, rather than on  Theorem~\ref{thm:pdr=2} in which the dependence of the bound on $m$ is better. The reason for this is the dependence on $t$. While the linear dependence on $t$ in Theorem~\ref{thm:pdCH} allows leveraging the result to the lopsided setting with only a small overhead, the polynomial dependence on $t$ in Theorem~\ref{thm:pdr=2} leads to a worse bound (also in terms of the dependence on $n,m$) in the lopsided setting.
\end{remark}

\begin{proof}[Proof of Theorem \ref{thm:pd}]
	The proof is by induction on $r$, the base case being Theorem~\ref{thm:pdr=2} above. In the induction step, we use the following observation: If $r$ simple Jordan regions in $\Re^2$ intersect, then either
			\begin{itemize}
				\item There is a pair of regions $a_1,a_2$ such that an intersection point of their boundaries is contained in all other $r-2$ regions, or
				\item There is a region $a_1$ which is fully contained in all other $r-1$ regions. 
			\end{itemize}
	We call an intersection of the first type a \emph{type A} - intersection, and an intersection of the second type a \emph{type B} - intersection.
	%I removed the iffalse from here

	For each intersecting pair $\{a_1,a_2\}$ of pseudo-discs we define a special point $p(a_1,a_2)$ as follows: If the intersection of $a_1$ and $a_2$ is of type A, then $p(a_1,a_2)$ is the left intersection point of the boundaries of $a_1$ and $a_2$. If this intersection is of type B, where $a_1 \subset a_2$, then $p(a_1,a_2)$ is the leftmost point of $a_1$.

	Without loss of generality, both for Type A and for Type B, we count intersections of the type $a_1 \cap \ldots \cap a_r \neq \emptyset $ ($a_i \in A_i$), where  $p(a_1,a_2)$ is contained in $a_3 \cap \ldots \cap a_r$. This affects the final bound by a multiplicative factor of $O_r(1)$.

	Let $P$ be the multiset $P=\{ p(a_1,\ldots,a_{r-1}): a_i \in A_i \}$, where $p(a_1,\ldots,a_{r-1})$ is $p(a_1,a_2)$ with multiplicity which is determined by the number of other tuples of $a_i$'s whose intersection contains it. Clearly, $|P| \leq n^{r-1}$. Let $G$ be the bipartite intersection graph of the multiset of points $P$ and the family of pseudo-discs $A_r$. If $|\E(H)|> C_r t^6 n^{r-1} (\log n)^{r-2}$ (for a sufficiently large constant $C_r$), then by Theorem \ref{thm:pdls}, $G$ contains $K_{gt,t}$ for $g=C_{r-1} t^5 n^{r-2} (\log n)^{r-3}$ (where $C_{r-1}$ will be specified below, and $C_r$ is taken to be sufficiently large for the statement to hold by Theorem~\ref{thm:pdls}). This $K_{gt,t}$ comes from a set $S$ of $gt=C_{r-1}t^6 n^{r-2} (\log n)^{r-3}$ distinct tuples of the form $(a_1,\ldots,a_{r-1})$ where $a_i \in A_i$, and 			
	%			points of the type $p(a_1, \ldots, a_{r-1})$ where $|S|=\Omega(gt)=\Omega (t^6 n^{r-2} (\log n)^{r-3})$, and 
	a set $T$ of $t$ pseudo-discs from $A_r$. Let $Z=\bigcap\{a_r : a_r \in T\}$ be the intersection of all the pseudo-discs in $T$. Since all the elements of $T$ contain a common point (e.g., each point in $P$), $Z$ is non-empty, and it follows from properties of pseudo-discs families that $Z$ is connected. (For a proof of this geometric fact, see \cite[Theorem 4.4]{AKP20}).

	Now, we clip each pseudo-disc $s \in A_1 \cup \ldots \cup A_{r-1}$ to $s'=s \cap Z$, and slightly perturb the boundaries such that the family $\{s': s \in  A_1 \cup \ldots \cup A_{r-1}\}$ is still a family of pseudo-discs. This perturbation can be performed as follows: Define a partial ordering on $A_1 \cup \ldots \cup A_{r-1}$, by considering the intersection of each pseudo-disc with the boundary of $Z$ and ordering by inclusion. Extend the ordering into a linear ordering arbitrarily. Clip the pseudo-discs close to the boundary of $Z$ from the inside, in
	such a way that a ``smaller'' pseudo-disc (according to the linear ordering) is clipped closer to the boundary. In this way, an intersection is added only to pairs of 
	pseudo-discs whose boundaries have only one intersection point inside $Z$, and therefore, any two boundaries of $\{s': s \in  A_1 \cup \ldots \cup A_{r-1}\}$ intersect at most twice.

	Consider the $(r-1)$-partite intersection hypergraph $H'$ of the families $A_1', \ldots,A'_{r-1}$, where $A_i'=\{s':s\in A_i \}$. $H'$ has at least $|S|$ hyperedges, since for each $(a_1,\ldots,a_{r-1}) \in S$, the point $p(a_1,\ldots,a_{r-1})$ is contained in $Z$, and hence, $a'_1 \cap a'_2 \cap \ldots \cap a'_{r-1} \neq \emptyset$. Since $|S|> C_{r-1} t^6 n^{r-2} (\log n)^{r-3}$, by the induction hypothesis $H'$ contains a $K_{t,\ldots,t}^{r-1}$ all of whose elements are fully contained in $Z=\bigcap\{a:a \in T\}$. (Here, $C_3$ is chosen to be sufficiently large for applying the inductive hypothesis.) Together with the set $T \subset A_r$, we obtain $K_{t,\ldots,t}^{r}$ in $H$. This completes the proof.
	\end{proof}

\begin{remark} 
	The clipping process is needed since without it, the $K_{t, \ldots,t}^{r-1}$ constructed in the proof may stem from intersections $a_1 \cap \ldots \cap a_{r-1}$ ($a_i \in A_i$) that are not related to intersection with the pseudo-discs in $T$. The clipping forces all those pseudo-discs to be included in $Z$, and in particular, forces their intersection points to be contained in $Z$, thus implying that the vertices of the $K_{t, \ldots,t}^{r-1}$ together with $T$ form a $K_{t, \ldots,t}^{r}$. We showed that such a clipping can be performed without losing the `pseudo-disc family' property.
\end{remark}	








