		Now we are ready to prove Proposition~\ref{Prop:HorVer}. Let us recall its statement.

		\medskip \noindent \textbf{Proposition~\ref{Prop:HorVer}.}
			Let $A$ be a multiset of horizontal segments in $\Re^2$ and let $B$ be a multiset of vertical segments in $\Re^2$, where $|A|=n$ and $|B|=m$. Let $g>0$. If the bipartite intersection graph of $G_{A,B}$ is $K_{t,gt}$-free (where the $t$ is on the side of $A$) then it has $O(gt^2 n+ tm)$ edges.    

		\medskip

		\begin{proof}[Proof of Proposition~\ref{Prop:HorVer}]
			We say that a $t$-tuple of elements of $A$ is \emph{canonical} if there exists a vertical segment (not necessarily in $B$) whose intersection with $A$ is exactly that $t$-tuple. By Lemma~\ref{Prop:Canonical}, the number of canonical $t$-tuples is $O(t n)$.

			We denote $B=(v_1,v_2,\ldots,v_{m})$ (possibly with repetitions) and double-count the pairs of the form ($v_i$, a canonical $t$-tuple such that $v_i$ intersects all its members). On the one hand, as $G_{A,B}$ is $K_{t,gt}$ free, each canonical $t$-tuple is counted at most $gt-1$ times. On the other hand, if $v_i$ intersects $d_i$ elements of $A$ then it fully intersects at least $d_i-t+1$ canonical $t$-tuples. Therefore, we have
			\[
			\sum_{i=1}^{m} (d_i-t+1) \leq \sum_{i=1}^{m} (v_i, \mbox{ a canonical t-tuple fully intersected by } v_i) \leq (gt-1) \cdot O(t n).
			\]
			Hence, $|E(G_{A,B})|=\sum_{i=1}^{m} d_i$ satisfies 
			\[
			\sum_{i=1}^{m} d_i \leq O(gt^2 n + tm),
			\]
			as asserted.
		\end{proof}

		The following lemma is a lopsided version of the bound of~\cite{CH23} on the number of edges in $K_{t,t}$-free bipartite intersection graphs of points and bottomless rectangles.

		\begin{lemma}\label{Prop:Bottomless}
			Let $A$ be a multiset of points in $\Re^2$ and let $B$ be a multiset of bottomless rectangles, where $|A|=n$ and $|B|=m$. Let $g>0$. 
			\begin{enumerate}
				\item If $G_{A,B}$ is $K_{t,gt}$-free ($t$ on the side of $A$) then it has $O(gt^2 n+ tm)$ edges.

				\item If $G_{A,B}$ is $K_{gt,t}$-free ($t$ on the side of $B$) then it has $O(gt^2 m+ tn)$ edges. 
			\end{enumerate}
		\end{lemma}

		\begin{proof}
			We represent each bottomless rectangle by its `upper' edge (thus obtaining a family $B'$), and represent each point by a long segment emanating from it in the `upper' direction (thus obtaining a family $A'$). Clearly, if the segments are sufficiently long, the bipartite intersection graph $G_{A',B'}$ is isomorphic to $G_{A,B}$. Note that $A'$ and $B'$ are multisets of horizontal and vertical segments in the plane, respectively. Hence, (2) follows by applying Prop~\ref{Prop:HorVer} to $A',B'$, and (1) follows by rotating the plane by $\pi/2$ (so that the roles of vertical and horizontal segments are interchanged) and then applying Proposition~\ref{Prop:HorVer} to $B',A'$.  
		\end{proof}

		The following proposition is a lopsided version of the bound of~\cite[Lemma~4.4]{CH23} on the number of edges in $K_{t,t}$-free bipartite intersection graphs of points and rectangles (though, with a weaker dependence on $t$).

		\begin{proposition}\label{Prop:PtsRectangles}
			Let $A$ be a multiset of points in $\Re^2$ and let $B$ be a family of rectangles, where $|A|=n$ and $|B|=m$. Let $g,\epsilon>0$. 
			\begin{enumerate}
				\item If $G_{A,B}$ is $K_{t,gt}$-free ($t$ on the side of $A$) then it has $O_{\epsilon} \left(gt^2 n \frac{\log n}{\log \log n}+ tm \log^{\epsilon}n\right)$ edges.

				\item If $G_{A,B}$ is $K_{gt,t}$-free ($t$ on the side of $B$) then it has $O_{\epsilon} \left(t n \frac{\log n}{\log \log n}+ gt^2 m \log^{\epsilon}n\right)$ edges.
			\end{enumerate}
		\end{proposition}

		The proof uses a divide-and-conquer argument, with a parameter $b$. It is clearly sufficient to prove the following claim, where $b$ is a parameter that may depend on $n,m$.
		\begin{claim}\label{Claim:PtsRectangles}
			Let $A$ be a multiset of points in $\Re^2$ and let $B$ be a multiset of axis-parallel rectangles, where $|A|=n$ and $|B|=m$. Let $b$ be a parameter.
			\begin{enumerate}
				\item If $G_{A,B}$ is $K_{t,gt}$-free ($t$ on the side of $A$) then it has $O(gt^2 n \log_b n + btm)$ edges.

				\item If $G_{A,B}$ is $K_{gt,t}$-free ($t$ on the side of $B$) then it has $O \left(t n \log_b n+ bgt^2 m\right)$ edges.
			\end{enumerate}
		\end{claim}
		\medskip Indeed, substituting $b=(\log n)^{\epsilon}$ into the claim yields the assertion of Proposition~\ref{Prop:PtsRectangles}.

		\begin{proof}[Proof of Claim~\ref{Claim:PtsRectangles}]
			Let $A,B$ be multisets that satisfy the assumptions of the claim. We divide the plane into $b$ vertical strips $\sigma_1,\sigma_2,\ldots,\sigma_b$, such that each strip contains $\frac{n}{b}$ points of $A$. For each $1 \leq i \leq b$, we denote by $A_i$ the points of $A$ in $\sigma_i$, by $B_i$ the rectangles of $B$ which are fully included in $\sigma_i$, and by $B'_i$ the rectangles of $B$ which intersect $\sigma_i$ but are not included in it. Denote $|B_i|=m_i$, and $|\cup_i B_i'|=m_0$ (so $\sum_{i=0}^b m_i=m$). Clearly, we have 
			\[
			|E(G_{A,B})| = \sum_{i=1}^b I(A_i,B_i) + \sum_{i=1}^b I(A_i,B_i'),
			\]
			where for any $X,Y$, $I(X,Y):=|E(G_{X,Y})|$. 

			\medskip \noindent \emph{Proof of~(1).} Denote by $f(n,m)$ the maximum number of edges in such a bipartite intersection graph of a multiset of $n$ points and a multiset of $m$ rectangles. 

			For the terms $I(A_i,B_i)$, we clearly have
			\[
			\sum_{i=1}^b I(A_i,B_i) \leq \sum_{i=1}^b f \left(\tfrac{n}{b},m_i \right).
			\]
			To handle the terms $I(A_i,B'_i)$, we note that for each $i$ and each $y \in B'_i$, the intersection $y \cap \sigma_i$ is a `truncated rectangle' in which either the right side, the left side, or both are missing. We may assume w.l.o.g. that there are no $y$'s with both sides missing, by `closing up' one side close to the end of the strip, in a way that does not change $I(A_i,B'_i)$. We divide $B'_i$ into the multiset $B'_{i,L}$ of rectangles missing the left side and the multiset $B'_{i,r}$ of rectangles missing the right side. 

			The bipartite intersection graph $G_{A_i,B'_{i,L}}$ can be viewed as the bipartite intersection graph of a multiset of points and a multiset of bottomless rectangles (where the plane is rotated counterclockwise by $3\pi/2$). Hence, by Lemma~\ref{Prop:Bottomless}(1), we have
			\[
			I(A_i,B'_{i,L}) \leq O(gt^2 |A_i| + t |B'_{i,L}|).
			\]
			The same argument applies for the bipartite intersection graph $G_{A_i,B'_{i,R}}$, and hence, we have
			\[
			I(A_i,B'_i) = I(A_i,B'_{i,L}) + I(A_i,B'_{i,R}) \leq O(gt^2 |A_i| + t |B'_{i}|).
			\]
			Therefore,
			\[
			\sum_{i=1}^b I(A_i,B'_i) \leq \sum_{i=1}^b O(gt^2 |A_i| + t |B'_{i}|) \leq O(gt^2 n + tb m_0),
			\]
			where the last inequality holds since each $y \in B$ intersects at most $b$ strips. 

			Combining with the bound on the terms $I(A_i,B_i)$, we obtain
			\[
			I(A,B) = \sum_{i=1}^b I(A_i,B_i) + \sum_{i=1}^b I(A_i,B_i') \leq \sum_{i=1}^b f \left(\tfrac{n}{b},m_i \right) + O(gt^2 n + tb m_0).
			\]
			As this holds for any multisets $A,B$ that satisfy the assumptions of the claim, we get the recursive formula
			\begin{equation}
				f(n,m) \leq \max_{\{m_0,m_1,\ldots,m_b:m_0+\ldots+m_b=m\}} \sum_{i=1}^b f \left(\tfrac{n}{b},m_i \right) + O(gt^2 n + tb m_0),
			\end{equation}
%			By the same argument as in~\cite{CH23} (with $gt^2$ instead of $t$ on the side of the dependence on the first parameter), the solution of the recursion is 
			which solves to 
			\[
			f(n,m) = O(gt^2 n \log_b n + tbm),
			\]
			as asserted.
%			Substituting $b=\log^{\epsilon}k_3$, we obtain
%			\[
%			f(k_3,l_3)=O_{\epsilon} \left(gt^2 k_3 \frac{\log k_3}{\log \log k_3}+ tl_3 \log^{\epsilon}k_3\right),
%			\]
%			as asserted.

			\medskip \noindent \emph{Proof of~(2).} Denote by $g(n,m)$ the maximum number of edges in a bipartite intersection graph of a multiset of $n$ points and a multiset of $m$ rectangles that satisfy the assumptions.  The proof is similar to the proof of~(1), with Lemma~\ref{Prop:Bottomless}(2) replacing Lemma~\ref{Prop:Bottomless}(1). Specifically, for each $1 \leq i \leq b$, we may use Lemma~\ref{Prop:Bottomless}(2) to obtain
			\[
			I(A_i,B'_i) \leq O(t|A_i|+gt^2 |B'_i|), 
			\]
			and consequently,
			\[
			\sum_{i=1}^b I(A_i,B'_i) \leq O(tn+ gt^2 bm_0).
			\]
			This yields the recursive formula
			\begin{equation}
				g(n,m) \leq \max_{\{m_0,m_1,\ldots,m_b:m_0+\ldots+m_b=m\}} \sum_{i=1}^b g \left(\tfrac{n}{b},m_i \right) + O(tn+ gt^2 bm_0),
			\end{equation}
			which solves to
			\[
			g(n,m) = O(t n \log_b n + gt^2 b m),
			\]
			as asserted.
%			Substituting $b=\log^{\epsilon}k_3$, we obtain
%			\[
%			g(k_3,l_3) = O_{\epsilon} \left(t k_3 \frac{\log k_3}{\log \log k_3}+ gt^2 l_3 \log^{\epsilon}k_3\right),
%			\]
%			as asserted. 
		This completes the proof of Claim~\ref{Claim:PtsRectangles} and of Proposition~\ref{Prop:PtsRectangles}.
		\end{proof}

		Now we are ready to prove Proposition~\ref{Prop:PtsBoxes} which is a lopsided version of the bound of~\cite[Theorem~4.5]{CH23} on the number of edges in $K_{t,t}$-free bipartite intersection graphs of points and axis-parallel boxes in $\Re^d$ (though, with a weaker dependence on $t$). Let us recall the statement of the proposition. 

\medskip \noindent \textbf{Proposition~\ref{Prop:PtsBoxes}.}
	Let $A$ be a multiset of points in $\Re^d$ and let $B$ be a multiset of axis-parallel boxes, where $|A|=n$ and $|B|=m$. Then for any $\epsilon>0$,
	\begin{enumerate}
	 	\item If the bipartite intersection graph $G_{A,B}$ is $K_{t,gt}$-free ($t$ on the side of $A$) then it has \newline $O_{\epsilon} \left(gt^2 n (\frac{\log n}{\log \log n})^{d-1}+ tm (\frac{\log n}{\log \log n})^{d-2+\epsilon}\right)$ edges.

		\item If the bipartite intersection graph of $G_{A,B}$ is $K_{gt,t}$-free ($t$ on the side of $B$) then it has $O_{\epsilon} \left(t n (\frac{\log n}{\log \log n})^{d-1}+ gt^2 m (\frac{\log n}{\log \log n})^{d-2+\epsilon}\right)$ edges.
	\end{enumerate}

Like in the proof of Proposition~\ref{Prop:PtsRectangles} above, it is clearly sufficient to prove the following claim, where $b$ is a parameter that may depend on $n,m$.
\begin{claim}\label{Claim:PtsBoxes}
	Let $A$ be a multiset of points in $\Re^d$ and let $B$ be a multiset of axis-parallel boxes, where $|A|=n$ and $|B|=m$. Let $b$ be a parameter.
	\begin{enumerate}
		\item If $G_{A,B}$ is $K_{t,gt}$-free ($t$ on the side of $A$) then it has $O(gt^2 n (\log_b n)^{d-1} + tm b^{d-1} (\log_b n)^{d-2})$ edges.

		\item If $G_{A,B}$ is $K_{gt,t}$-free ($t$ on the side of $B$) then it has $O \left(t n (\log_b n)^{d-1}+ gt^2 m b^{d-1} (\log_b n)^{d-2}\right)$ edges.
	\end{enumerate}
\end{claim}

\medskip Indeed, substituting $b=(\log n)^{\frac{\epsilon}{d-1}}$ into the claim yields the assertion of Proposition~\ref{Prop:PtsRectangles}.

\begin{proof}[Proof of Claim~\ref{Claim:PtsBoxes}]
	The proof is by induction on $d$. The induction basis is the case $d=2$ proved in Claim~\ref{Claim:PtsRectangles}. 
	In the induction step, we assume that the claim holds for dimension $d-1$ and prove it for dimension $d$. 

\medskip \noindent \emph{Proof of~(1).}	We use the following auxiliary notion. Let $I_d(n,v)$ be the maximal number of intersections between a multiset $A$ of points and a multiset $B$ of axis-parallel boxes inside a `vertical strip' $\mathcal{U}=\{x \in \Re^d:u_L<x_1<u_R\}$ of $\Re^d$, where:
	\begin{enumerate}
		\item Each box in $B$ has either half of its vertices or all of its vertices in $\mathcal{U}$;

		\item The total number of vertices of boxes in $B$ inside $\mathcal{U}$ is $m \cdot 2^{d-1}$;

		\item The bipartite intersection graph of $A,B$ is $K_{t,gt}$-free.
	\end{enumerate}
	We shall prove that 
	\[
	I_d(n,m) \leq O(gt^2 n (\log_b n)^{d-1} +  tm b^{d-1} (\log_b n)^{d-2}).
	\] 
	This clearly implies the assertion, as by considering a vertical strip $\mathcal{U}$ that fully contains all points in $A$ and boxes in $B$ (where $|A|=n$ and $|B|=m$), we get $E(G_{A,B}) \leq I_d(n,2m)$. (Note that we neglect factors of $O_d(1)$). 

	Let $A,B$ be multisets that satisfy assumptions~(1)--(3) with respect to a strip $\mathcal{U} \subset \Re^d$. We divide $\mathcal{U}$ into $b$ vertical sub-strips $\sigma_1,\ldots,\sigma_d$ such that $\sigma_i=\{x \in \Re^d: u_i<x_1<u_{i+1}\}$ (where $u_0=u_L$ and $u_{d+1}=u_R$), in such a way that each sub-strip contains $\frac{n}{b}$ points in $A$. For $i=1,\ldots,b$, we denote by $A_i$ the points of $A$ in $\sigma_i$, by $B_i$ the boxes in $B$ that have at least one vertex in $\sigma_i$, and by $B'_i$ the boxes in $B$ that intersect $\sigma_i$ but do not have vertices in it. Note that each box of $B$ belongs to either one or two multisets $B_i$ and to at most $b$ multisets $B'_i$. We also denote the number of vertices of boxes in $B$ contained in $\sigma_i$ by $2^{d-1} \cdot m_i$.

	The number of intersections in $\mathcal{U}$ between points in $A$ and boxes in $B$ is clearly 
	\begin{equation}\label{Eq:Bound-boxes1}
		\sum_{i=1}^b I(A_i,B_i) + I(A_i,B'_i).
	\end{equation}
	By the definitions, for any $i$ we have $I(A_i,B_i)\leq I_d(\frac{n}{b},m_i)$ (where $\sigma_i$ is taken as the vertical strip instead of $\mathcal{U}$).  

	To handle the terms $I(A_i,B'_i)$, we observe that a point in $A_i$ intersects a box in $B'_i$ if and only if their projections on the hyperplane $\mathcal{H}=\{x \in \Re^d: x_1=u_i\}$ (which are a point and a $(d-1)$-dimenstional box) intersect. Let $\bar{A}_i$ and $\bar{B}'_i$ denote the corresponding multisets of projections. We have $|\bar{A}_i|=|A_i|=\frac{n}{b}$ and $|\bar{B}'_i|=|B'_i|\leq m$. The multisets $\bar{A}_i$ and $\bar{B}'_i$ are a multiset of points and a multiset of axis-parallel boxes in $\Re^{d-1}$ whose bipartite intersection graph is $K_{t,gt}$-free. Hence, by the induction hypothesis we have
	\begin{align*}
		\begin{split}
			I(A_i,B'_i)=I(\bar{A}_i,\bar{B}'_i) &\leq 
			O(gt^2 \tfrac{n}{b} (\log_b \tfrac{n}{b})^{d-2} +  tm b^{d-2} (\log_b \tfrac{n}{b})^{d-3}) \\
			&\leq O(gt^2  \tfrac{n}{b} (\log_b n)^{d-2} +  tm b^{d-2} (\log_b n)^{d-3}).
		\end{split}
	\end{align*}
	Combining the bounds on $I(A_i,B_i)$ and $I(A_i,B'_i)$, we obtain the recursive formula 
	\[
	I_d(n,m) \leq \max_{m_1+\ldots+m_b=m} \sum_{i=1}^b \left(I_d(\tfrac{n}{b},m_i)+O(gt^2  \tfrac{n}{b} (\log_b n)^{d-2} +  tm b^{d-2} (\log_b n)^{d-3}) \right), 
	\]
	which solves to
	\begin{align*}
		\begin{split}
			I_d(n,m) &\leq \log_b n \cdot O(gt^2 n (\log_b n)^{d-2} +  tm b^{d-2} (\log_b n)^{d-3}) \\ 
			&\leq O(gt^2 n (\log_b n)^{d-1} +  tm b^{d-1} (\log_b n)^{d-2}),
		\end{split}
	\end{align*}
	as asserted.

	\medskip \noindent \emph{Proof of~(2).} The proof is similar to the proof of~(1), with Claim~\ref{Claim:PtsRectangles}(2) replacing Claim~\ref{Claim:PtsRectangles}(1). Specifically, ~\eqref{Eq:Bound-boxes1} holds without change and we have 
	$I(A_i,B_i)\leq I_d(\tfrac{n}{b},m_i)$, exactly as in the proof of~(1). By the induction hypothesis, we get 
\begin{align*}
	\begin{split}	
	I(A_i,B'_i)=I(\bar{A}_i,\bar{B}'_i) &\leq 
	O \left(t \tfrac{n}{b} (\log_b \tfrac{n}{b})^{d-2}+ gt^2 m b^{d-2} (\log_b \tfrac{n}{b})^{d-3}\right) \\
	&\leq O \left(t \tfrac{n}{b} (\log_b n)^{d-2}+ gt^2 m b^{d-2} (\log_b n)^{d-3}\right).  
	\end{split}
\end{align*}
Combining the bounds on $I(A_i,B_i)$ and $I(A_i,B'_i)$, we obtain the recursive formula 
\[
I_d(n,m) \leq \max_{m_1+\ldots+m_b=m} \sum_{i=1}^b \left(I_d(\tfrac{n}{b},m_i)+ O \left(t \tfrac{n}{b} (\log_b n)^{d-2}+ gt^2 m b^{d-2} (\log_b n)^{d-3}\right) \right), 
\]
which solves to
\begin{align*}
\begin{split}
I_d(n,m) &\leq b \log_b n \cdot  O \left(t \tfrac{n}{b} (\log_b n)^{d-2}+ gt^2 m b^{d-2} (\log_b n)^{d-3}\right) \\ 
&\leq O(t n (\log_b n)^{d-1} +  gt^2 m b^{d-1} (\log_b n)^{d-2}),
\end{split}
\end{align*}
as asserted.
This completes the proof of Claim~\ref{Claim:PtsBoxes} and of Proposition~\ref{Prop:PtsBoxes}.
\end{proof}





