		\section{Proof of Proposition~\ref{thm:boxes_weaker}} \label{app:boxes_weaker}

		In this section we present the inductive step of the proof of Proposition~\ref{thm:boxes_weaker}.

		\begin{proof}[Proof of Proposition~\ref{thm:boxes_weaker} for $r>3$]
			The proof is by induction on $r$. The induction basis is the case $r=3$ proved in Section~\ref{sec:boxes_weak}. Now, assume we proved the assertion for $r-1$ and consider families $A_1,A_2,\ldots,A_r$ of $n$ axis-parallel boxes. 

			Let $A_1A_2 \ldots A_{r-1}$ be the multiset of axis-parallel boxes 
			\[
			A_1A_2 \ldots A_{r-1}=\{a_1\cap a_2\cap \ldots \cap a_{r-1}:a_1 \in A_1, \ldots, a_{r-1}\in A_{r-1}, a_1\cap \ldots \cap a_{r-1} \neq \emptyset\}.
			\]
			Let $G$ be the bipartite intersection graph of the families $A_r$ and $A_1A_2 \ldots A_{r-1}$. It is clear that $|E(G)|=|\E(H)|$.

			We claim that there exists $M_{r-1}$ such that $G$ is $K_{t,M_{r-1} t (n f_{d,t}(n))^{r-2}}$ free. Indeed, assume on the contrary that $G$ contains a copy of $K_{t,M_{r-1} t (n  f_{d,t}(n))^{r-2}}$, for a sufficiently large $M_{r-1}$. This means that there exist $a_{r_1},a_{r_2},\ldots,a_{r_t} \in A_r$ which all have non-empty intersection with certain 
			$M_{r-1} t (n  f_{d,t}(n))^{r-2}$ axis-parallel boxes of the form $a_{1_j} \cap \ldots \cap a_{(r-1)_j}$, with $a_{i_j} \in A_i$. Denote by $A_i'$ the set of all $a_{i_j} \in A_i$ that participate in such intersections, and let $H'$ be the $(r-1)$-partite intersection hypergraph of $A_1',\ldots,A'_{r-1}$. We have 
			\[
			|\E(H')|\geq M_{r-1} t  (n  f_{d,t}(n))^{r-2},
			\]
			and hence, by the induction hypothesis, it contains a $K_{t,t,\ldots,t}^{r-1}$, assuming $M_{r-1}$ is sufficiently large. This means that for any $1 \leq j \leq r-1$, there exist $a_{j_1},a_{j_2},\ldots,a_{j_t} \in A_j$ such that any intersection of the form $a_{1_{j,1}} \cap a_{2_{j,2}} \cap \ldots \cap a_{{r-1}_{j,r-1}}$ is non-empty, and all $a_{i_j}$'s have a non-empty intersection with each of $a_{r_1},\ldots,a_{r_t}$ (since they participate in $(r-1)$-tuples whose intersection with each of $a_{r_1},\ldots,a_{r_t}$ is non-empty). As any set of pairwise intersecting axis-parallel boxes has a non-empty intersection, this implies that $H$ contains a $K_{t,t,\ldots,t}^r$, a contradiction.

			We have thus concluded that $G$ is $K_{t,M_{r-1} t (n  f_{d,t}(n))^{r-2}}$ free, for a sufficiently large constant $M$. By Theorem~\ref{cons:lopsided}, applied with $n$, $n^{r-1}$, and $g=M_{r-1} t (n  f_{d,t}(n))^{r-2}$, this implies that 
			\[
			|\E(H)|=|E(G)| \leq O_r\left(t \left(n  f_{d,t}(n)\right)^{r-1} \right),
			\]
			as asserted. This completes the inductive proof (with the $O_r(\cdot)$ dependence exponential in $r$).
		\end{proof}

\section{Proof of Lemma~\ref{lem:biclique}}
\label{app:biclique}

In this appendix we present the proof of Lemma~\ref{lem:biclique}. Let us recall its statement.

\medskip \noindent \textbf{Lemma~\ref{lem:biclique}.}
	Let $n,m,b \in \mathbb{N}$ be such that $b \leq \min(n,m)$, and let $A,B$ be families of axis-parallel boxes in $\Re^d$, with $|A|=n$ and $|B|=m$. Then the bipartite intersection graph of $A,B$ can be partitioned into a union of $O(b \log^{d-1} b)$ bicliques (with no restriction on their size) and $O(b \log^{d-1} b)$ ``partial bicliques'' (namely, subgraphs of bicliques), each of size at most $\frac{n}{b} \cdot \frac{m}{b}$. 

\medskip \noindent It is clearly sufficient to prove that the following holds for any parameters $p,q \leq \min(n,m)$. 
\begin{claim}\label{Claim:Biclique}
	Let $n,m,p,q \in \mathbb{N}$ be such that $p,q \leq \min(n,m)$, and let $A,B$ be families of axis-parallel boxes in $\Re^d$, with $|A|=n$ and $|B|=m$. Then the bipartite intersection graph of $A,B$ can be partitioned into a union of $O((\frac{n}{p}+\frac{m}{q})\log^{d-1}(\frac{n}{p}))$ bicliques (with no restriction on their size) and $O((\frac{n}{p}+\frac{m}{q})\log^{d-1}(\frac{n}{p}))$ ``partial bicliques'' (namely, subgraphs of bicliques), each of size at most $p \cdot q$. 
\end{claim}	
Indeed, applying the claim with $p=\frac{n}{b}$ and $q=\frac{m}{b}$ yields the assertion of the lemma.

\begin{proof}[Proof of Claim~\ref{Claim:Biclique}]
	The proof uses a standard divide-and-conquer argument, like in the proof of Proposition~\ref{Prop:Facet}. We use the following auxiliary notion.

	Let $N_d(n,m)$ be the maximal total number of bicliques (with no restriction on their size) and partial bicliques, each of size at most $p\cdot q$, needed to cover the intersection graph of two multisets $A,B$ of axis-parallel boxes inside a `vertical strip' $\mathcal{U}=\{x \in \Re^d:u_L<x_1<u_R\}$ of $\Re^d$, where:
	\begin{enumerate}
		\item Each box in $A,B$ has either half of its vertices or all of its vertices in $\mathcal{U}$;

		\item The total number of vertices of boxes in $A$ (resp., boxes in $B$) inside $\mathcal{U}$ is $n \cdot 2^{d-1}$ (resp., $m \cdot 2^{d-1}$).
	\end{enumerate}
	We shall prove that 
	\[
	N_d(n,m) \leq O \left(\left(\tfrac{n}{p}+\tfrac{m}{q}\right)\log^{d-1}\left(\tfrac{n}{p}\right) \right).
	\] 
	This clearly implies the assertion of the claim, as by considering a vertical strip $\mathcal{U}$ that fully contains all boxes in $A$ and $B$ (where $|A|=n$ and $|B|=m$), we get that the number of bicliques (with no restriction on their size) and partial bicliques, each of size at most $p\cdot q$, needed to cover the intersection graph of $A,B$ is at most $N_d(2n,2m)$. 

	The proof is by induction on $n$ and $d$. 

	\medskip \noindent \textbf{Induction base.} The base cases are $n \leq p$ and $d=1$. If $n \leq p$ then for any $d,m$, we have
	$N_d(n,m) \leq \lceil m/q\rceil$, since  we can cover the intersection graph by $\lceil m/q\rceil$ partial bicliques of size at most $p \cdot q$. 

	For $d=1$, $A,B$ are multisets of intervals on a line, $|A|=n,|B|=m$. We divide the line into $\lceil \frac{2n}{p} \rceil$ segments $\sigma_i$ such that each segment contains at most $p$ endpoints of intervals in $A$. Denote the number of intervals in $B$ which have an endpoint in $\sigma_i$ by $m_i$. For each $i$, all intersections between intervals of $A$ and $B$ that have an endpoint in $\sigma_i$ can be covered by  $\lceil m_i/q\rceil$ partial bicliques of size at most $p \cdot q$. Furthermore, all intersections between intervals of $A$ that intersect $\sigma_i$ (and either have an endpoint in it or not) and intervals of $B$ that intersect $\sigma_i$ but do not have an endpoint in it can be covered by a single biclique, since they form a complete bipartite graph. Similarly, all intersections between intervals of $B$ that intersect $\sigma_i$ (and either have an endpoint in it or not) and intervals of $A$ that intersect $\sigma_i$ but do not have an endpoint in it can be covered by a single biclique, Hence, all intersections between intervals in $A$ and intervals in $B$ can be covered by $O(\frac{m}{q})$ partial bicliques of size at most $p \cdot q$ and $O(\frac{n}{p})$ complete bicliques, as asserted.

	\medskip \noindent \textbf{Induction step.}	We assume that the claim holds for dimension $d-1$ and prove it for dimension $d$.
	We divide $\mathcal{U} \subset \Re^d$ into two vertical sub-strips $\sigma_1=\{x \in \Re^d: u_L<x_1<u'\}$ and $\sigma_2=\{x \in \Re^d:u'<x_1<u_R\}$, such that each sub-strip contains $n \cdot 2^{d-2}$ vertices of boxes in $A$. For $i=1,2$, we denote by $A_i$ (resp., $B_i$) the boxes in $A$ (resp., $B$) that have at least one vertex in $\sigma_i$, and by $A'_i$ (resp., $B'_i$) the boxes in $A$ (resp., $B$) that intersect $\sigma_i$ but do not have vertices in it. Note that $A'_1 \subset A_2, A'_2 \subset A_1$, and similarly for $B$. We also denote the number of vertices of boxes in $B$ contained in $\sigma_i$ by $2^{d-1} \cdot m_i$.

	By the definition of $N_d(n,m)$, the number of bicliques and partial bicliques needed to cover the intersecting pairs
	between $A_1$ and $B_1$ (resp., between $A_2$ and $B_2$) is $N_d(\frac{n}{2},m_1)$ (resp., $N_d(\frac{n}{2},m_2))$.

	To cover the other types of intersecting pairs, we observe that a box in $A_1$ intersects a box in $B'_1$ if and only if their projections on the hyperplane $\mathcal{H}=\{x \in \Re^d: x_1=u'\}$ (which are $(d-1)$-dimensional boxes) intersect. Let $\bar{A}_1$ and $\bar{B}'_1$ denote the corresponding families of projections.  We recursively construct bicliques and partial bicliques
	to cover the intersecting pairs between $\bar{A}_1$ and $\bar{B}'_1$ (a $(d-1)$-dimensional subproblem). By definition, the number of bicliques and partial bicliques needed for this is at most $N_{d-1}(2 \cdot \frac{n}{2},2m_2)$. (The factor 2 is needed as the number of vertices of boxes in $\bar{A}_1$ is at most $2^{d-1} \cdot \frac{n}{2} = 2^{d-2} \cdot (2 \cdot \frac{n}{2})$, and similarly for $\bar{B}'_1$). Other types can be handled similarly.

	Combining all types of intersections between $A$ and $B$ inside the strip $\mathcal{U}$, we obtain the recursive formula
	\begin{equation}\label{Eq:Recursion}
	N_d(n,m) \leq \max_{m_1+m_2=m} \left(N_d(\tfrac{n}{2},m_1)+N_d(\tfrac{n}{2},m_2)+
	O(N_{d-1}(2n,2m)) \right).
	\end{equation}
	We apply the recurrence until we obtain $N_d(n',m')$ for $n' \leq p$ (thus, $\lceil \log \frac{n}{p} \rceil$ steps in total) and then we apply the induction basis. Using the induction hypothesis to handle the terms $N_{d-1}(n',m')$ we encounter in the process, we obtain 
	\[
	N_d(n,m)=O\left( \left(\tfrac{n}{p}+\tfrac{m}{q}\right)\log^{d-1}\left(\tfrac{n}{p}\right)\right),
	\]
	as asserted. This completes the proof of Claim~\ref{Claim:Biclique} and of Lemma~\ref{lem:biclique}.
\end{proof}   

	\section{Proof of Theorem \ref{thm:pdls}} \label{app:pd}
	In this appendix we prove Theorem  \ref{thm:pdls} which is a lopsided version of  \cite[Cor. 5.1]{CH23} - Theorem \ref{thm:pdCH} above. %Let us restate it:
		%\medskip
		%\noindent \textbf{Theorem \ref{thm:pdCH}.}
		%Let $P$ be a set of $n$ points in the plane, and let $\F$ be a set of $y$-monotone pseudo-discs in the plane. If the bipartite intersection graph $G(P,\F)$ is $K_{t,t}$-free ($t \geq 2$), then $$|E(G(P,\F))| = O(tn +tm \log \log m + \log t).$$	
		We use the following variant of Matou{\v{s}}ek's shallow cuttings~(\cite{Mat92}, see also~\cite{CCCH12}).		
		\begin{lemma}\cite[Theorem 5.1]{CH23} \label{lem:m/r}
			Let $F$ be a family of $y$-monotone pseudo-discs, $|F|=m$. Let $r,k \in N$. Then there exists an $\frac{1}{r}$-cutting of $F$, namely, a decomposition $\Xi$ of $\Re^d$ into $O(r^d)$ cells of constant descriptive complexity, such that the total weight of boundaries of shapes of $F$ intersecting a single cell is at most $m/r$.
		\end{lemma}		
		The following lemma is a lopsided version of \cite[Lemma 5.2]{CH23}:
		\begin{definition}
			Given a family $F$ of sets, the \emph{depth} of a point (with respect to $F$) is the number of elements of $F$ that contain it.
		\end{definition}
		\begin{lemma}\label{lem:depth}
			Let $P$ be a set of $n$ points in $\Re^2$, and let $F$ be a family of $m$ $y$-monotone pseudo-discs. Let $g,t \in N$. If the bipartite intersection graph $G(P,F)$ is $K_{gt,t}$-free, then for any $r \leq \frac{m}{2t}$, the number of points of $P$ having depth between $\frac{m}{r}$ and $\frac{2m}{r}$ is at most $O(gtr)$. 
		\end{lemma}

		\begin{proof}
			Let $\Xi$ be an $\frac{1}{2r}$-cutting whose existence is guaranteed by Lemma \ref{lem:m/r}. By the last part of Lemma \ref{lem:m/r}, the number of cells in $\Xi$ that contain at least one point of depth between $\frac{m}{r}$ to $\frac{2m}{r}$ is $O(r)$. Each such cell $\nabla$ contains a point with depth$\geq \frac{m}{r}$ and intersects the boundaries of at most $\frac{m}{2r}$ pseudo-discs (since $\Xi$ is an $\frac{1}{2r}$-cutting). 

			Therefore, $\nabla$ is fully contained in at least $\frac{m}{2r} \geq t$ pseudo-discs. Since $G(P,F)$ is $K_{gt,t}$-free, $|\nabla \cap P| <gt$. Hence, the number of cells with a point of depth between $\frac{m}{r}$ and $\frac{2m}{r}$ is $O(r)$, and each such a cell contains at most $gt$ points, and so we are done.
		\end{proof}		
		Now we are ready to prove Theorem \ref{thm:pdls}. Let us 
		restate it:

		\medskip

		\noindent \textbf{Theorem \ref{thm:pdls} -- Restatement.} Let $P$ be a multiset of $n$ points in the plane, and let $\F$ be a multiset of $m$ $y$-monotone pseudo-discs in general position in the plane. If the bipartite intersection graph $G(P,\F)$ is $K_{gt,t}$-free ($t,g \geq 2$, $gt$ on the side of the points), then $$|E(G(P,\F))| = O(tn +gtm \log m ).$$

		\begin{proof}[Proof of Theorem \ref{thm:pdls}]
			Let $2t=t_0<t_1< \ldots <t_{\ell}$ be parameters to be determined later, where $t_{\ell} \geq m$. We break $P$ into $O(\ell)$ classes as follows: $P_0 \subset P$ consists of the points whose depth (w.r.t. $F$) is below $t_0$, and for $i>0$, $P_i$ consists of the points whose depth is at least $t_{i-1}$ and smaller than $t_i$.

			By Lemma \ref{lem:depth} and by partitioning $P_i$ into the points with depth between $t_{i-1}$ to $2t_{i-1}$, between $2t_{i-1}$ to $4t_{i-1}$, etc., we can bound 
			$$|P_i| = O \left( gt  \left(  \frac{m}{t_{i-1}} + \frac{m}{2t_{i-1}}    + \frac{m}{4t_{i-1}} +\ldots  \right)  \right)  = O \left(  gt \frac{m}{t_{i-1}} \right).$$
			By Lemma~\ref{lem:m/r}, we compute a $\frac{t_i}{m}$-cutting and let $\Xi$ be the cells of the cutting that intersect $P_i$. By the last part of Lemma \ref{lem:m/r}, there are $O(\frac{m}{t_i})$ such cells. 

			Consider a cell $\nabla \in \Xi$. By the definition of $\Xi$, it contains a point of depth $\leq t_i$, and since $\Xi$ comes from a $\frac{t_i}{m}$-cutting, it intersects the boundaries of at most $t_i$ pseudo-discs. Hence, the total number of pseudo-discs intersecting or containing $\nabla$ is $O(t_i)$. 

			We can subdivide the simplices of $\Xi$ into $O(\frac{m}{t_i})$  subcells, such that each such subcell contains at most 
			$O \left(    \frac{ gt \frac{m}{t_{i-1}}  }{  \frac{m}{t_i} }   \right)  =  O \left( \frac{gt t_i}{t_{i-1}}     \right)$ points of $P_i$. 

			Define $I(x,y)$ to be the maximal possible value of $|E(G(P',F'))|$ for a set $P'$ of $x$ points and a family $F'$ of $y$ pseudo-discs. Using the above subdivision process, we obtain
			$$  I(|P_i|,|F|) \leq O\left(\frac{m}{t_i}\right) I  \left(   \frac{gtt_i}{t_{i-1}} , t_i \right).  
			$$
			For $i=0$, we use the trivial upper bound $  I(|P_0|,|F|) \leq O(|P_0| \cdot t_0) \leq O(nt)$ (the last inequality holds since $|P_0| \leq |P|=n$ and $t_0=2t$). The recursion obtained in this way is 
			$$  I(n,m) \leq \sum_{i=1}^{\ell}  O \left( \frac{m}{t_i} \right)   I  \left(  \frac{gtt_i}{t_{i-1}}  ,t_i \right)  +O(tn) .$$
			We choose the sequence $t_0=2t$ and $t_i=2t_{i-1}$ for $i>0$, and get 
			$$  I(n,m)  \leq \sum_{i=1}^{\log m}  O \left( \frac{m}{t_i} \right) I(2gt,t_i) +O(tn) 
			\leq \sum_{i=1}^{\log m}  O \left( \frac{m}{t_i} \right) O(gtt_i) +O(tn),$$
			where the right inequality holds since $I(2gt,t_i) \leq 2gtt_i$. Hence, $$I(n,m) = O(gtm \log m +tn),$$
			as asserted.
		\end{proof}

		\begin{remark} \label{rem:clip}
			The bound in Theorem \ref{thm:pdCH} is stronger than the bound in Theorem \ref{thm:pdls}. The improved bound in \cite{CH23} is obtained by choosing carefully the values of the sequence $\{t_i\}_{i=0,1,\ldots}$ to make this sequence very-fast increasing in its last $\log \log m$ elements. In the lopsided setting of Theorem \ref{thm:pdls}, we cannot use a similar choice of the sequence, since this will make the dependency on $g$ polynomial instead of linear.
		\end{remark}



