\section{Newton-Okounkov bodies}\label{sec:NewtonOkounkov}
One of the most important invariants of a graded, valued algebra $A$ is its Newton-Okounkov body \cite{KavehManon:2019,KavehKhovanskii:2012,Anderson:2013,BurrKhovanskiiHomotopies:2023}. 
This is a convex body which captures homological and geometric data of $A$. For instance, the normalized volume of the Newton-Okounkov body is the asymptotic growth rate of the Hilbert function for the algebra, see, for instance \cite[Theorem 2.23]{KavehManon:2019} and \cite[Theorem 4.9]{KavehKhovanskii:2012}.  We show how to compute the Newton-Okounkov body of a graded algebra using the constructions of the previous sections.

We follow the construction of the Newton-Okounkov body as in \cite{KavehManon:2019}. 
Consider a valued algebra $\nu ' : A ' \setminus \{ 0 \} \to \bZ^r$ satisfying the standing hypotheses, and a positively graded algebra $A=\bigoplus_{i\geq 0}A_i$ where $A_i \subseteq A'$ for all $i.$  
We extend $\nu '$ to valuation, which also satisfies the standing hypotheses, $\nu:A \setminus \{ 0 \} \to \bN \times \bZ^r$.
We decompose $f\in A \setminus \{ 0 \}$ into homogeneous components, $f=\sum_{i=0}^m f_i$ with $f_i\in A_i$ and $f_m\not=0$, and define $\nu(f)\vcentcolon=(m,\nu'(f_m))$. We order $\bN \times\bZ^r$ so that $(m,a)\succ (n,b)$ if $m<n$ or $m=n$ and $a\succ b$.
\begin{definition}
The {\em Newton-Okounkov body} associated to $A$ and $\nu '$ is the closed, convex set
% $$
% \overline{\conv\{\nu'(f)/i:f\in A_i\setminus\{0\}\}}.
% $$
\begin{align*}
\Delta (A, \nu)     &\coloneqq \overline{\conv\{\nu'(f)/i:f\in A_i\setminus\{0\}\}} .
\end{align*}
\end{definition}
When $A$ has a finite Khovanskii basis, we may assume, without loss of generality, that every basis element is homogeneous.  In other words, $\{g_1,\dots,g_m\}$ form a Khovanskii basis and $\deg(g_i) = d_i$, that is $g_i\in A_{d_i}$.  Then, the Newton-Okounkov body is $\conv\{\nu'(g_i)/d_i\}.$

Suppose that $A = \bigoplus_{i \geq 0} A_{i}$ is a positively graded and valued algebra with valuation $\nu'$ as above with a finite Khovanskii basis $\{g_1,\dots,g_m\}$.  Let $R$ be the presentation ring such that $\pi:R\rightarrow A$ has kernel $I$, and a monomial order $<$ induced by $\nu$.

\begin{theorem}
  \label{thm:NOBodyConstruction}
  Let \(\mu\) be the valuation on \(R/I\) defined above and let \( \vec{d} = \left(\deg(g_{i}) \colon 1 \leq i \leq m \right) \) be the vector of degrees of Khovanskii basis elements.  The Newton-Okounkov body of \(R/I\) is given by
  \begin{equation}\label{eq:NewtonOkounkovLattice}
   \Delta(R/I, \mu) = \conv\left\{\|\vec{d}\|^2\mu([x_{i}])/\mu([x_i])_1\right\}.
    %\Delta(R/I, \mu) = \overline{\conv\left\{\gcd(d_1,\dots,d_m)\mu([x_{i}])/\deg(g_{i})\right\}}.
  \end{equation}
\end{theorem}
\begin{proof}
  Fix a lattice basis \(\left(\vec{w}_{1}, \ldots, \vec{w}_{\ell}\right)\) for $K$, and set $\vec{w}_{\ell +1} = \vec{d}.$
  By construction, $\vec{w}_i$ and $\vec{w}_{\ell +1}$ are orthogonal for all $i$. Choose a set of vectors $\{\vec{w}_{\ell+2},\dots,\vec{w}_m\} \subseteq\bZ^m$ which extends $\{ \vec{w}_1,\dots,\vec{w}_{\ell +1}\}$ to a basis of the vector space $\bQ^m$ such that $\vec{w}_i$ and $\vec{w}_{\ell +1}$ are orthogonal for all $i \ne \ell +1$.  

  The valuation $\mu$ can be represented by $\mu:R/I\setminus\{0\}\rightarrow\bQ^{m-\ell}$ where $\mu([x^\alpha])$ are the coordinates of $\alpha$ with respect to the vectors $\{\vec{w}_{\ell+1},\dots,\vec{w}_m\}$ in the basis defined above.  This construction embeds $\torfree(\bZ^m/K)$ as a subset of $\bQ^{m-\ell}$.
  Let $L\simeq\bZ^{m-\ell}$ be the lattice generated by the images $\{\mu([x_1]),\dots,\mu([x_m])\}$, and the Newton-Okounkov body for $R/I$ is defined with respect to this lattice.  We observe that, since $\vec{w}_{\ell +1}$ is orthogonal to the other $\vec{w}_i$s, the first entry of $\mu([x^\alpha])$ is $\deg(\pi(x^\alpha))/\|\vec{d}\|^2$.
\end{proof}

Suppose $\{[x_1],\dots,[x_m]\}$ form a minimal subalgebra basis, then $\Delta(R/I, \mu)$ is $(m-\ell)$-dimensional.  When $\Delta(R/I, \mu)$ is full-dimensional, the normalized volume of the Newton-Okounkov body can be computed in terms of the standard volume on $\bQ^{m-\ell}$ (as opposed to computing the volume in terms of the integral lattice as in~\Cref{eq:NewtonOkounkovLattice}).  Since $\vec{w}_{\ell +1}$ is perpendicular to all other vectors, the multiplicative factor for the volume splits along this dimension.  In particular, the multiplicative factor for the volume is the length of a lattice generator of the first-coordinates of $\left(\mu([x_1]),\dots,\mu([x_m])\right)$ divided by the volume of a fundamental domain of $L$ in $\bQ^m$.  Since $\mu([x_i])_1=\frac{d_i}{\|\vec{d}\|}$, the length of the lattice generator of the first-coordinates is $\frac{\gcd(d_1,\dots,d_m)}{\|\vec{d}\|^2}$.

\begin{algorithm}[hbt]
  \caption{Calculating \(\vol(\Delta(R/I, \mu))\).}
  \label{alg:NOBodyVolume}
  \begin{algorithmic}[1]
    \Require a positively graded $k$-algebra and domain \(A\), valuation \(\nu\) satisfying the standing hypotheses, and finite Khovanskii basis \(\left\{g_{1}, \ldots, g_{m}\right\}\) for \((A, \nu)\).
    \Ensure the normalized volume of \(\Delta(R/I, \mu)\).
    \State Construct presentation ring \(R\) with presentation ring \(\pi: R \rightarrow A\), monomial order \(>\) induced by \(\nu\), and \(I \vcentcolon= \ker(\pi)\) (see Section~\ref{sec:KhovanskiitoSubalgebra}).
    \State Compute a Gr\"obner basis $G$ for $I$.
    \State Compute a basis $\{\vec{w}_1,\dots,\vec{w}_\ell\}$ of the lattice $K$ spanned by the toric exponents of $G$.
    \State Set \(\vec{w}_{\ell+1} = \vec{d} = \left(\deg(g_{i})\right) \in \bZ^{m}\) to be the vector of degrees of all Khovanskii basis elements.
    \State Extend $\bZ \{ \vec{w}_1, \ldots , \vec{w}_{\ell + 1} \}$ to a full-rank lattice $\bZ \{ \vec{w}_1, \ldots , \vec{w}_m \}$ such that $\vec{w}_{\ell+1} \in \{\vec{w}_{\ell+1}, \ldots , \vec{w}_m \}^{\perp }.$
    \State Set $W = (\begin{array}{c|c|c} \vec{w}_1 & \cdots & \vec{w}_m \end{array}) \in \bZ^{m\times m}.$
    \State Construct $V \in \bQ^{(m- \ell - 1) \times m}$ by selecting the last $m-\ell-1$ rows of $W^{-1}$ and scaling the $i$th column by $d_i^{-1}$ for $i=1,\ldots , m.$
    \State Construct the matrix $L'$ of minimal generators of the lattice generated by the last \(m - \ell\) rows of \(W^{-1}\).
    \State\Return $\frac{(m-\ell-1)!\gcd(d_1,\dots,d_m)\vol(\conv(V))}{\|\vec{d}\|^2\det(L')}.$
  \end{algorithmic}
\end{algorithm}

