\begin{figure}
\centering
\includegraphics[width=\linewidth]{new_img/scene1.pdf}
\caption{In disaster scenarios, UAVs can rapidly establish temporary multi-hop wireless networks in communication dead zone, thereby restoring connectivity for UEs.}
\label{intro figure}
