& \quad 
\forall_{k=0}^{K} \quad  \phi\bigl(m_k,\;\bm{x}_k^{[T]},\;\bm{u}_k^{[T]}\bigr) \;\le\; 0,
\label{eq:ineq_constraints}\\
& \quad 
\forall_{k=0}^{K} \quad  \psi\bigl(m_k,\;\bm{x}_k^{[T]},\;\bm{u}_k^{[T]}\bigr) \;=\; 0,
\label{eq:eq_constraints}\\
& \quad 
(m_0,\; \bm{x}_0^0) = (m_{\text{init}},\; \bm{x}_{\text{init}}),
% & \quad 
% \bigl(m_K,\;\bm{x}_K^T\bigr) \;\in\; \mathcal{X}_{\text{goal}}, \label{eq:terminal_cond}
\end{align}
where:
\begin{itemize}
