%It is not to be confused with a vector that is labeled with a subscript. 
Define the support set of $\mat{x}$ to be $\mbox{supp}(\mat{x}) = \bigl\{i : (\mat{x})_i \neq 0 \bigr\}$.  
%For instance, we have $(\mat{e}_i)_i = 1$ and $(\mat{e}_i)_j = 0$ whenever $j \neq i$. 
Given a matrix $\mat{M}$ and a vector $\mat{x}$, we use $\norm{\mat{M}}$ and $\norm{\mat{x}}$ to denote their $L_2$-norms, and we use $\norm{\mat{x}}_1$ and $\norm{\mat{x}}_\infty$ to denote the $L_1$-norm and $L_\infty$-norm of $\mat{x}$, respectively. Let $n$ be the total number input variables.  Let $s$ be the support set size of the optimal solution.



\section{Algorithm DWS}
\label{sec:alg}

Let $f(\mat{x}) = \frac{1}{2}\|\mat{Ax}-\mat{b}\|^2$.  Let $g(\mat{x}) = \eta\norm{\mat{x}}_1$.  The objective function is $F(\mat{x}) = f(\mat{x}) + g(\mat{x})$.  DWS calls a solver iteratively. In each iteration, some variables are free, forming the \emph{working set}, and the others are fixed at zero.  We use $\mat{x}_r$ to denote the solution returned by the solver in the $r$-th iteration. 




Algorithm~\ref{alg:1} gives the pseudocode of DWS.  We define $\mat{x}_{0} = \mat{0}$.  For $r \geq 0$, we extract a subset of variables 
\[
E_{r} = \left\{j \in [n] : \left|\frac{\partial f(\mat{x}_{r})}{\partial (\mat{x})_j}\right| > \eta \right\}.  
\]
We will prove that for all $j \in E_{r}$, if $\partial f(\mat{x}_{r})/\partial (\mat{x})_j < 0$, the $j$-th positive axis is a descent direction from $\mat{x}_{r}$; otherwise, if $\partial f(\mat{x}_{r})/\partial (\mat{x})_j > 0$, the $j$-th negative axis is a descent direction from $\mat{x}_{r}$.  The \emph{weight} of $j \in [n]$ is $\left|\partial f(\mat{x}_{r}/\partial (\mat{x})_j\right|$.  An element $j$ is \emph{heavier} than another if its weight is larger.  DWS uses a parameter $p_0$ to initialize the first working set $W_1$ to consist of  the $p_0$ elements of $[n]$ with the $p_0$ largest $\bigl|\partial f(\mat{x}_0)/\partial (\mat{x})_j\bigr|$.
When $p_0 \leq |E_0|$, $W_1$ consists of the $p_0$ heaviest elements of $E_0$, and the same initialization is done in Skglm. When $p_0 > |E_0|$, Skglm selects $p_0-|E_0|$ variables outside $E_0$ in some order and inserts them into $W_1$, which is similar to what we do. Celer also starts with a working set of size $p_0$ by some selection criterion.  The working set of DWS for the $(r+1)$-th iteration for $r \geq 1$ is $W_{r+1} = \supp(\mat{x}_{r}) \cup \{\text{the $\tau_{r+1}$ heaviest elements in $E_{r}$}\}$,
where $\tau_{r+1}$ is defined in lines~\ref{alg:tau-1}--\ref{alg:tau-3} of Algorithm~\ref{alg:1}.   DWS uses a basic step size $\tau$ for increasing the working set size, and $\tau_{r+1}$ is equal to $\min\{h^{a_r}\tau, k, |E_r|\}$ for some appropriate integer $a_r$.  By our assumption that $k > s$, we will not release more than $k$ variables from $E_{r}$ to $W_{r+1}$.  The variables in $W_r$ that are zero will be kicked out of $W_{r+1}$.  This can significantly reduce the running time of the next iteration. The rationale behind the setting of $a_r$ is:
\begin{itemize}

\item If $|\supp(\mat{x}_r)| \leq |\supp(\mat{x}_{r-1})| + \tau/h$, lines~\ref{alg:tau-1}--\ref{alg:tau-3} of Algorithm~\ref{alg:1} set $a_r = 0$, i.e., $\tau_{r+1} = \min\{\tau,k,|E_r|\}$.  The slow growth in the support set size suggests that the working set size may be close to the ideal.  We should not increase the working set size so much to slow down the next iteration.

\item Otherwise, let $m$ be the smallest non-negative integer such that $|\supp(\mat{x}_r)| \leq |\supp(\mat{x}_{r-1})| + h^m \tau$.  We can release $h^{m+1}\tau$ or $h^{a_{r-1}+1}\tau$ variables from $E_r$, i.e., a factor $h$ more.
%if we released $\tau_r = \min\{h^{a_{r-1}}\tau, k, |E_{r-1}|\}$ in the $r$-th  iteration,   
To avoid a large increase in the working set size, lines~\ref{alg:tau-1}--\ref{alg:tau-3} set $a_r = \min\{m+1,a_{r-1}+1\}$.
\end{itemize}

\begin{algorithm}
\caption{DWS}\label{alg:1}
\begin{algorithmic}[1]
        \STATE{$h \gets$ any constant in $(1,2]$} \hspace*{31pt} /* $h = 2$ in the experiments. */
        \STATE{$\tau \gets$ any integer in $[k]$} \hspace*{47pt} /* $\tau = \lfloor 4\ln^2 n \rfloor$ in the experiments */
        \STATE{$\mat{x}_0 \gets 0$}
        \STATE{compute $\nabla f(\mat{x}_{0}) = -\mat{A}^t\mat{b}$ to generate $E_0$}  
        \STATE{$W_1 \gets \left\{\text{the $p_0$ elements of $[n]$ with the $p_0$ largest $\bigl|\frac{\partial f(\mat{x}_0)}{\partial (\mat{x})_j}\bigr|$}\right\}$}  \hspace{10pt} /* $p_0=10$ in the experiments */
        \STATE{$a_0 \gets 0$; $r \gets 1$}
	\WHILE{$E_{r-1} \not= \emptyset$}
            \STATE{$\mat{A}_{r} \gets$ submatrix of $\mat{A}$ with columns corresponding to $W_{r}$}
	    \STATE{$\mat{x}_r \gets \text{optimal solution obtained by calling the solver with $\mat{A}_{r}$ and $\mat{b}$}$} \label{alg:qp}
            \STATE{$m \gets \text{the smallest integer in $[-1,\infty)$ s.t. $|\supp(\mat x_r)|\le h^m \tau+ |\supp(\mat x_{r-1})|$}$} \label{alg:tau-1}
            \STATE{$a_r \gets \min\{m+1,a_{r-1}+1\}$}
            \STATE{compute $\nabla f(\mat{x}_{r}) = \mat{A}^t\mat{A}\mat{x}_r -\mat{A}^t\mat{b}$ to generate $E_{r}$}
            \STATE{$\tau_{r+1} \gets \min\{h^{a_r}\tau, \, k, \, |E_r|\}$}   \label{alg:tau-3}
            \STATE{$W_{r+1} \gets \supp(\mat{x}_{r}) \cup \{\text{the $\tau_{r+1}$ heaviest elements in $E_{r}$}\}$} \label{alg:update}
            \STATE{$r \gets r+1$}
        \ENDWHILE
        \STATE{{\bf return} $\mat{x}_r$}
\end{algorithmic}
\end{algorithm}

\section{Experimental results}

In our experiments, we generate a random matrix as described in the introduction.  All non-zero singular values of $\mat{A}$ are equal to 1.  To generate a vector $\mat{b}$, we first generate a true signal $\mat{z} \in \mathbb{R}^n$ by sampling $s$ coordinates uniformly at random, setting each to $-1$ or $1$ with probability 1/2, and setting the other $n-s$ coordinates to zero.  Then, compute $\mat{b} = \mat{A}\mat{z} + \mat{n}$, where each entry of $\mat{n}$ is drawn independently from $\mathcal{N}(0,10^{-4})$.

%The compressed sensing problem is find $\mat{x}$ that minimizes $\frac{1}{2}\|\mat{A}\mat{x} - \mat{b}\|^2 + \eta \|\mat{x}\|_1$, where $\eta > 0$ is a 
We follow the experimental set up in GPSR~\cite{gpsr} to set $\eta = 0.1 \cdot \|\mat{A}^t \mat{b}\|_{\infty}$.  Note that if $\eta \geq \norm{\mat{A}^t\mat{b}}_{\infty}$, then $\mat{x}=0$ is the optimal solution~\cite{fuchs}.  We will report our experimental results with $n \in \{15000,\,30000,\,45000,\,60000\}$, $s \in \{0.01n, 0.04n, 0.08n\}$, and $k = 2s\ln(n/s)$.  
%Compressed sensing is mainly concerned with cases that $s$ is tiny relative to $n$.  
A similar range of $s$ has been used in previous 
works~\cite{fsso,gpsr,srfr} 
