\begin{lemma}
\label{g_subgradient-t}
\hspace*{10pt}
\begin{enumerate}[{\em (i)}]
\item Take any $\mat{x} \in \real^n$.
\begin{enumerate}[{\em (a)}]
\item $\forall\, \xi \in \partial g(\mat x), \, \forall\, i \in [n]$, if $(\mat x)_i = 0$, then $(\xi)_i \in [-\eta,\eta]$; otherwise, $(\xi)_i = \mathrm{sign}((\mat{x})_i) \cdot \eta$.

\item Every vector that satisfies the conditions in {\em (i)(a)} is a subgradient in $\partial g(\mat x)$.

\end{enumerate}

\item $\forall\, i \in E_r, \, \forall\, \gamma \in \partial F(\mat{x}_r)$, $\mathrm{sign}((\gamma)_i) = \mathrm{sign}((\nabla f(\mat{x}_r))_i) \in \{-1,1\}$.

\item $E_r = \bigl\{i \in [n] : \forall\, \gamma \in \partial F(\mat{x}_r), (\gamma)_i \not= 0 \bigr\}$.

\end{enumerate}
\end{lemma}
\begin{proof}
	Consider (i)(a).  Take any $\xi \in \partial g(\mat{x})$.
	By the definition of a subgradient, for all $\mat y \in\real^n$, $g(\mat y)-g(\mat x) \ge   \langle \xi, \mat y - \mat x \rangle$, which is equivalent to 
	\begin{equation}
		\eta \sum_{i=1}^n |(\mat y)_i| - \eta \sum_{i=1}^n |(\mat x)_i| \ge \sum_{i=1}^n  (\xi)_i \cdot (\mat y - \mat x)_i.
		\label{eq:g-1}
	\end{equation}

	Take any index $i \in [n]$.  Let $Y_i = \bigl\{ \mat{y} \in \real^n : \forall j \not= i , (\mat y)_j=(\mat x)_j \bigr\}$.  Clearly, for every $\mat{y} \in Y_i$, applying \eqref{eq:g-1} to $\mat{y}$ gives 
	\[
	\eta |(\mat y)_i| - \eta |(\mat x)_i| \ge (\xi)_i \cdot (\mat y - \mat x)_i.
	\]

	\begin{itemize}

		\item Case 1:~Suppose that $(\mat x)_i \geq 0$.  Choose $\mat{y} \in Y_i$ such that $(\mat y)_i > (\mat x)_i$. Then, $\eta(\mat y - \mat x)_i = \eta|(\mat y)_i|-\eta|(\mat x)_i| \ge (\xi)_i \cdot  (\mat y - \mat x)_i$.  Dividing both sides by $(\mat y- \mat x)_i$ gives $(\xi)_i\le \eta$. 

		\item Case 2:~Suppose that $(\mat x)_i \leq 0$.  Choose $\mat{y} \in Y_i$ such that $(\mat y)_i < (\mat x)_i$.  Then, $-\eta(\mat y - \mat x)_i =\eta|(\mat y)_i|-\eta|(\mat x)_i| \ge (\xi)_i \cdot  (\mat y - \mat x)_i$.  Dividing both sides by $(\mat y- \mat x)_i$ gives $(\xi)_i\ge -\eta$. 

	\end{itemize}

	Combining cases~1 and~2 gives $(\xi)_i \in [-\eta,\eta]$ when $(\mat{x})_i = 0$.  Suppose that $(\mat{x})_i > 0$.  We already have $(\xi)_i \leq \eta$ by case~1. Choose $\mat{y} \in Y_i$ such that $0 < (\mat{y})_i < (\mat x)_i$.  Then, $\eta(\mat y - \mat x)_i = \eta|(\mat y)_i|-\eta|(\mat x)_i|\ge (\xi)_i \cdot  (\mat y - \mat x)_i$.  Dividing both sides by $(\mat{y}-\mat{x})_i$ gives $(\xi)_i \geq \eta$.  As a result, $(\xi)_i= \eta$.  Suppose that $(\mat x)_i < 0$.  We already have $(\xi)_i \geq -\eta$ by case~2.  Choose $\mat{y} \in Y_i$ such that $(\mat{x}_r)_i < (\mat{y})_i < 0$.  Then, $-\eta(\mat{y} - \mat{x}_r)_i = \eta|(\mat y)_i|-\eta|(\mat x)_i| \ge (\xi)_i \cdot  (\mat y - \mat x)_i$.  Dividing both sides by $(\mat y- \mat x)_i$  gives $(\xi)_i \leq -\eta$.  In all, $(\xi)_i= -\eta$.  This completes the proof of (i)(a).

	Consider (i)(b).  Take any vector $\xi \in \real^n$ that satisfies the conditions in (i)(a).  Under these conditions, it is easy to verify that for every $\mat{y} \in \real^n$ and every $i \in [n]$, $\eta |(\mat y)_i| - \eta |(\mat x)_i| \ge (\xi)_i \cdot (\mat y - \mat x)_i$.  Then, for all $\mat{y} \in \real^n$, 
	\begin{align*}
		g(\mat{y}) - g(\mat{x}) = \eta \sum_{i=1}^n |(\mat y)_i| - \eta \sum_{i=1}^n |(\mat x)_i| \ge \sum_{i=1}^n (\xi)_i \cdot (\mat y - \mat x)_i = \langle \xi, \mat y - \mat x \rangle,
	\end{align*}
	which implies that $\xi$ is a subgradient in $\partial g(\mat{x})$.

	Consider (ii).  Take any $i \in E_r$.  By definition, $|(\nabla f(\mat{x}_r))_i| > \eta$. So $(\nabla f(\mat{x}_r))_i \not= 0$. It also follows from (i) that for every $\xi \in \partial g(\mat{x}_r)$, if $(\nabla f(\mat{x}_r))_i > 0$, then $(\nabla f(\mat{x}_r))_i + (\xi)_i > 0$, and if $(\nabla f(\mat{x}_r))_i < 0$, then $(\nabla f(\mat{x}_r))_i + (\xi)_i < 0$.  Note that $\partial F(\mat{x}_r) = \{ \nabla f(\mat{x}_r) + \xi : \xi \in \partial g(\mat{x}_r)\}$.  In other words, for every $i \in E_r$ and every $\gamma \in \partial F(\mat{x}_r)$, $\mathrm{sgn}((\gamma)_i) = \mathrm{sgn}((\nabla f(\mat{x}))_i) \in \{-1,1\}$.  This proves (ii).

	Consider (iii).   For all $i \not\in [n] \setminus (W_r \cup E_r)$, we have $(\mat{x}_r)_i = 0$ and $|(\nabla f(\mat{x}_r))_i| \leq \eta$.  By (i)(b), for all $i \not\in [n] \setminus (W_r \cup E_r)$, every value in $[-\eta,\eta]$ is a legitimate $i$-th coordinate for a subgradient of $g$ at $\mat{x}_r$, which includes $-(\nabla f(\mat{x}_r))_i$.  Hence, there exists $\gamma \in \partial F(\mat{x}_r)$ such that $(\gamma)_i = 0$ for all $i \not\in [n] \setminus (W_r \cup E_r)$.  Since $\mat{x}_r$ is the optimal solution with respect to the working set $W_r$, there exists $\gamma \in \partial F(\mat{x}_r)$ such that $(\gamma)_i = 0$ for all $i \in W_r$.  We conclude that for every $i \in [n] \setminus E_r$, there exists $\gamma \in \partial F(\mat{x}_r)$ such that $(\gamma)_i = 0$.  By the result in (ii), for every $i \in E_r$ and every $\gamma \in \partial F(\mat{x}_r)$, $(\gamma)_i \not = 0$.  This proves the correctness of (iii), i.e., $i \in E_r$ if and only if $(\gamma)_i \not= 0$ for all $\gamma \in \partial F(\mat{x}_r)$.\hfill\qed
\end{proof}


\begin{lemma}
\label{lem:32}
Let $\mat{e}_i$ be the unit vector in the direction of the positive $i$-th axis.  Every unit conical combination of $\{-\mathrm{sign}((\nabla f(\mat x_r))_i) \cdot \mat{e}_i : i \in E_r\}$ is a descent direction from $\mat{x}_r$.  If $E_r = \emptyset$, then $\mat{x}_r$ is the global minimum.
\end{lemma}
\begin{proof}
	Let $\rho = \min_{i \in E_r} |\nabla f(\mat{x}_r)_i| - \eta$ which is positive.  Take any $i \in E_r$ and any $\gamma \in \partial F(\mat{x}_r)$.  By Lemma~\ref{g_subgradient-t}(i), the $i$-th coordinate of any subgradient in $\partial g(\mat{x}_r)$ is in the range $[-\eta,\eta]$, which implies that $|(\gamma)_i| \geq \rho$.  Let $\mat{s}_i = -\mathrm{sign}((\nabla f(\mat{x}_r))_i) \cdot \mat{e}_i$.  By Lemma~\ref{g_subgradient-t}(ii), $\langle \gamma,\mat{s}_i \rangle = -|(\gamma)_i| \leq -\rho < 0$.  For every unit conical combination $\sum_{i \in E_r} \alpha_i \mat{s}_i$, some coefficient $\alpha_i$ is at least $1/\sqrt{n}$.  Thus, $\sup_{\gamma \in \partial F(\mat{x}_r)} \langle \gamma,\sum_{i \in E_r} \alpha_i \mat{s}_i\rangle \leq -\rho/\sqrt{n} < 0$, proving that $\sum_{i \in E_r} \alpha_i\mat{s}_i$ is a descent direction.  If $E_r$ is empty, by Lemma~\ref{g_subgradient-t}(iii), for every $i \in [n]$, there exists $\xi \in \partial g(\mat{x}_r)$ such that $(\xi)_i = -(\nabla f(\mat{x}_r))_i$, that is, $-(\nabla f(\mat{x}_r))_i$ is a legitimate $i$-th coordinate of a subgradient in $\partial g(\mat{x}_r)$.  It follows from Lemma~\ref{g_subgradient-t}(i)(b) that the zero vector belongs to $\partial F(\mat{x}_r)$, which implies that $\mat{x}_r$ is the global minimum.\hfill\qed
\end{proof}


%Let $\mat{n}_r$ be any unit conical combination of $\{-\mathrm{sign}((\nabla f(\mat x_r))_i) \cdot \mat{e}_i : i \in E_r\}$.  Let $\mat{y}_r$ be the point in direction $\mat{n}_r$ from $\mat{x}_r$ that minimizes $F$.  
Define a vector $\zeta_{\mat{x}_r} \in \real^n$ such that for all $i \in [n]$, if $i \not\in E_r$, then $(\zeta_{\mat x_r})_i=-(\nabla f(\mat x_r))_i$, and if $i \in E_r$, then $(\zeta_{\mat x_r})_i= - \mathrm{sign}((\nabla f(\mat x_r))_i)\cdot \eta$. Define $\gamma_{\mat x_r} = \nabla f(\mat x_r) + \zeta_{\mat x_r}$.   
%We prove in Lemma~\ref{lem:special} in Appendix~\ref{app:full-t} that $\zeta_{\mat{x}_r} \in \partial g(\mat{x}_r)$ and $\gamma_{\mat{x}_r} \in \partial F(\mat{x}_r)$.  
Let $\mat{x}_*$ denote the optimal solution that minimizes $F$.  Given a vector $\mat{v}$ and a subset $S \subseteq [n]$, $\mat{v}  \downarrow  S$ denotes the orthogonal projection of $\mat{v}$ in the subspace spanned by $\{\mat{e}_i : i \in S\}$.

\begin{lemma}
\label{lem:special}
$\zeta_{\mat{x}_r} \in \partial g(\mat{x}_r)$ and $\gamma_{\mat{x}_r} \in \partial F(\mat{x}_r)$.
\end{lemma}
\begin{proof}
	By Lemma~\ref{g_subgradient-t}(ii), for all $i \in E_r$, $(\zeta_{\mat x_r})_i \in \{-\eta,\eta\}$.   For all $i \in E_r$, $(\mat{x}_r)_i = 0$ as $E_r \cap W_r = \emptyset$. By Lemma~\ref{g_subgradient-t}(i)(b), for all $i \in E_r$, $(\zeta_{\mat{x}_r})_i$ is a legitimate $i$-th coordinate for a subgradient in $\partial g(\mat{x}_r)$.  By Lemma~\ref{g_subgradient-t}(iii), for all $i \not\in E_r$, there exists $\gamma \in \partial F(\mat{x}_r)$ such that $(\gamma)_i = 0$. It means that for all $i \not\in E_r$, $(\zeta_{\mat{x}_r})_i = -(\nabla f(\mat x_r))_i$ must a legitimate $i$-th coordinate for a subgradient in $\partial g(\mat x_r)$ so that it cancels $(\nabla f(\mat x_r))_i$.   Thus, $\zeta_{\mat{x}_r} \in \partial g(\mat{x}_r)$.  Then, $\gamma_{\mat{x}_r} \in \partial F(\mat{x}_r)$ by definition.\hfill\qed
\end{proof}


\begin{lemma}
\label{gfy_to_gamma_y-t}
Let $\mat{n}_r$ be any unit conical combination of $\{-\mathrm{sign}((\nabla f(\mat x_r))_i) \cdot \mat{e}_i : i \in E_r\}$.  Let $\mat{y}_r$ be the point in direction $\mat{n}_r$ from $\mat{x}_r$ that minimizes $F$. 
\begin{enumerate}[{\em (i)}]

\item There exists $\xi \in \partial g(\mat y_r)$ such that  $ \langle  \mat \nabla f(\mat y_r) + \xi, \mat y_r - \mat x_r\rangle  = 0$.

\item For every $\xi \in \partial g(\mat{y}_r)$, both $\langle \zeta_{\mat{x}_r} - \xi, \mat{x}_r \rangle$ and $\langle \zeta_{\mat{x}_r} - \xi, \mat{y}_r\rangle$ are zero.

\item For every $\mat z \in \real^n$, $F(\mat x_r)-F(\mat z) \le - \langle  \gamma_{\mat x_r}, \mat  z - \mat x_r\rangle$.

\item $F(\mat x_r)-F(\mat y_r) = - \frac{1}{2}\langle \gamma_{\mat x_r}, \mat y_r - \mat x_r\rangle$.
\end{enumerate}
\end{lemma}
\begin{proof}
	Since $\mat{n}_r$ is a descent direction by Lemma~\ref{lem:32}, the point $\mat{y}_r$ is well defined. Consider (i).  Let $L$ denote the line through $\mat{x}_r$ parallel to $\mat{n}_r$.  Since the minimum of $F$ in $L$ is achieved at $\mat{y}_r$, it is known that there exists $\gamma \in \partial F(\mat y_r)$ such that $\langle \gamma, \mat{z} - \mat{y}_r \rangle\ge 0$ for all $\mat z \in L$.  Note that $\mat{x}_r \in L$.  Choose the point $\mat{x} \in L$ such that $\mat{x}_r - \mat{y}_r = \mat{y}_r - \mat{x}$.  Then, we have $\langle \gamma, \mat{x}_r - \mat{y}_r \rangle \geq 0$ and $\langle \gamma, \mat{x} - \mat{y}_r \rangle \geq 0$.  The second inequality also implies that $\langle \gamma, \mat{x}_r - \mat{y}_r \rangle = -\langle \gamma, \mat{x}-\mat{y}_r\rangle \leq 0$.  It follows that $\langle \gamma, \mat{x}_r - \mat{y}_r \rangle = 0$, which implies that there exists $\xi \in \partial g(\mat{y}_r)$ such that $\langle \nabla f(\mat{y}_r) + \xi, \mat{x}_r - \mat{y}_r \rangle = 0$.  This proves (i).

	Consider (ii).  Take any $i \in \supp(\mat{n}_r)$.  As $i \in E_r$ by definition, we have $(\mat{x}_r)_i = 0$ and $(\zeta_{\mat{x}_r})_i = -\mathrm{sign}((\nabla f(\mat{x}_r))_i) \cdot \eta$.  Also, $\mathrm{sign}((\mat{y}_r)_i) = -\mathrm{sign}((\nabla f(\mat{x}_r)_i)$ because we descend from $\mat{x}_r$ in direction $\mat{n}_r$ to reach $\mat{y}_r$.  By Lemma~\ref{g_subgradient-t}(i)(a), $(\xi)_i = \mathrm{sign}((\mat{y}_r)_i) \cdot \eta = -\mathrm{sign}((\nabla f(\mat{x}_r)_i) \cdot \eta$.  Therefore, $(\zeta_{\mat{x}_r})_i = (\xi)_i$.  For any $i \not\in \supp(\mat{n}_r)$, we have $(\mat{x}_r)_i = (\mat{y}_r)_i$.  If they are not zero, then $(\zeta_{\mat{x}_r})_i$ and $(\xi)_i$ are identical by Lemma~\ref{g_subgradient-t}(i)(a).  We conclude that both $((\zeta_{\mat{x}_r})_i - (\xi)_i) \cdot (\mat{x}_r)_i$ and  $((\zeta_{\mat{x}_r})_i - (\xi)_i) \cdot (\mat{y}_r)_i$ are zero for all $i \in [n]$.  This proves (ii).

	Before proving (iii) and (iv), we first prove the following equation: $\forall \, \mat x, \mat z \in \mathbb{R}^n, \forall\, \zeta_1 \in \partial g(\mat x), \forall \, \zeta_2 \in \partial g(\mat z)$,
	\begin{equation}
		F(\mat x)-F(\mat z) = -\frac{1}{2}\|\mat A (\mat z - \mat x)\|^2- \langle  \mat \nabla f(\mat x) + \zeta_1, \mat z - \mat x\rangle +\langle  \zeta_1 - \zeta_2, \mat z \rangle.
		\label{eq:-1}
	\end{equation}
	Take any $i\in [n]$ and any $\zeta_1 \in \partial g(\mat{x})$. By Lemma~\ref{g_subgradient-t}(i)(a), $(\zeta_1)_i \cdot (\mat x)_i= \eta|(\mat x)_i|$.  Therefore, $\langle {\zeta}_1  , \mat x \rangle = \sum_{i=1}^n (\zeta_1)_i \cdot (\mat x)_i = \eta \|\mat x\|_1 = g(\mat x)$, which implies that
	\begin{equation}
		g(\mat x)-g(\mat z)= \langle {\zeta}_1  , \mat x \rangle -\langle \zeta_2  , \mat z \rangle.
		\label{eq:0}
	\end{equation}
	It has been proved in our unpublished manuscript~\cite{chengwongold} that $f(\mat x)-f(\mat z) = -\frac{1}{2}\|\mat A (\mat z - \mat x)\|^2 - \langle  \mat \nabla f(\mat x), \mat z - \mat x\rangle$.  We give the proof below for completeness.  For all $s \in [0,1]$, define $\mat{z}_s = \mat{x} + s(\mat{z}-\mat{x})$.  By the chain rule, we have $\frac{\partial f}{\partial s} = \bigl\langle \frac{\partial f}{\partial \mat{z}_s},\frac{\partial \mat{z}_s}{\partial s} \bigr\rangle
	= \bigl\langle \nabla f(\mat{z}_s), \, \mat{z} -\mat{x} \bigr\rangle$.
	We integrate along a linear movement from $\mat{x}$ to $\mat{z}$.  Using the fact that $\nabla f(\mat{z}_s) = \mat{A}^t\mat{A}(\mat{x} + s(\mat{z}-\mat{x})) - \mat{A}^t \mat b = \nabla f(\mat{x}) + s\mat{A}^t\mat{A}(\mat{z}-\mat{x})$, we obtain $f(\mat{z}) = f(\mat{x}) + \int_{0}^1 \langle \nabla f(\mat{z}_s),  \mat{z} -\mat{x} \rangle \, \mathtt{d}s = f(\mat{x}) + \int_0^1 \langle \nabla f(\mat{x}), \, \mat{z}-\mat{x} \rangle \, \mathtt{d}s + 
	\int_0^1 s\iprod{\mat{A}^t\mat{A}(\mat{z}-\mat{x}), \, \mat{z}-\mat{x}} \, \mathtt{d}s \nonumber = f(\mat{x}) + \bigl[\langle \nabla f(\mat{x}), \, \mat{z}-\mat{x} \rangle \cdot s\bigr]^1_0 + 
	\bigl[\frac{1}{2}\norm{\mat{A}(\mat{z}-\mat{x})}^2 \cdot s^2 \bigr]^1_0 = f(\mat{x}) + \langle \nabla f(\mat{x}), \, \mat{z}-\mat{x} \rangle + \frac{1}{2}\norm{\mat{A}(\mat{z}-\mat{x})}^2$.	It follows immediately that $f(\mat{x}) - f(\mat{z}) =  -\langle \nabla f(\mat{x}), \, \mat{z}-\mat{x} \rangle - \frac{1}{2}\norm{\mat{A}(\mat{z}-\mat{x})}^2$.  By~\eqref{eq:0}, we can add $g(\mat{x}) - g(\mat{z})$ to the left side of this equation and $\langle \zeta_1  , \mat x \rangle -\langle \zeta_2  , \mat z \rangle$ to the right side.  We get $F(\mat x)-F(\mat z) = -\frac{1}{2}\|\mat A (\mat z - \mat x)\|^2 - \langle  \mat \nabla f(\mat x), \mat z - \mat x\rangle +\langle \zeta_1  , \mat x \rangle -\langle \zeta_2  , \mat z \rangle  = -\frac{1}{2}\|\mat A (\mat z - \mat x)\|^2- \langle  \mat \nabla f(\mat x), \mat z - \mat x\rangle +\langle \zeta_1  , \mat x \rangle -\langle \zeta_2 , \mat z \rangle  -\langle \zeta_1  , \mat z \rangle +\langle \zeta_1  , \mat z \rangle = -\frac{1}{2}\|\mat A (\mat z - \mat x)\|^2- \langle  \mat \nabla f(\mat x) + \zeta_1, \mat z - \mat x\rangle +\langle  \mat \zeta_1 - \zeta_2  , \mat z \rangle$.  This completes the proof of \eqref{eq:-1}. 

	Consider (iii).  By \eqref{eq:-1} with $\mat{x} = \mat{x}_r$ and $\zeta_1 = \zeta_{\mat{x}_r}$, we get 
	\begin{align}
		F(\mat x_r)-F(\mat z) 
		&=~-\frac{1}{2}\|\mat A (\mat  z - \mat x_r)\|^2- \langle  \mat \nabla f(\mat x_r) + \zeta_{\mat{x}_r}, \mat  z - \mat x_r\rangle +\langle  \mat \zeta_{\mat x_r}- \zeta_2, \mat  z \rangle \nonumber \\
		&\le~-\langle  \mat \nabla f(\mat x_r) + \zeta_{\mat{x}_r}, \mat  z - \mat x_r\rangle +\langle  \mat \zeta_{\mat x_r}- \zeta_2  , \mat  z \rangle. \label{eq:1}
	\end{align}
	Take any $i\in [n]$. By Lemma~\ref{g_subgradient-t}(i)(a), if $(\mat{z})_i > 0$, then $(\zeta_2)_i = \eta \geq (\zeta_{\mat{x}_r})_i$, and if $(\mat{z})_i < 0$, then $(\zeta_2)_i = -\eta \leq (\zeta_{\mat{x}_r})_i$.  As a result, $(\zeta_{\mat{x}_r} - \zeta_2)_i \cdot (\mat{z})_i \leq 0$ for all~$i$, proving that $\langle \zeta_{\mat{x}_r} -\zeta_2, \mat{z} \rangle \leq 0$.  Substituting $\langle \zeta_{\mat{x}_r} -\zeta_2, \mat{z} \rangle \leq 0$ into \eqref{eq:1} gives $F(\mat x_r)-F(\mat z) \le - \langle  \mat \nabla f(\mat x_r) + \zeta_{\mat{x}_r}, \mat  z - \mat x_r\rangle = - \langle  \gamma_{\mat x_r}, \mat  z - \mat x_r\rangle$.  This proves (iii).

	Consider (iv). Let $\xi$ be any subgradient in $\partial g(\mat{y}_r)$ that satisfies Lemma~\ref{gfy_to_gamma_y-t}(i).  By \eqref{eq:-1} with $\mat x=\mat y_r$, $\zeta_1 = \xi$, $\mat z=\mat x_r$, and $\zeta_2 = \zeta_{\mat{x}_r}$, we have $F(\mat{x}_r) - F(\mat{y}_r) = \frac{1}{2}\norm{\mat{A}(\mat{x}_r - \mat{y}_r)}^2 + \langle \nabla f(\mat{y}_r) + \xi, \mat{x}_r - \mat{y}_r \rangle  - \langle \xi - \zeta_{\mat{x}_r}, \mat{x}_r\rangle$.
	The middle term vanishes by Lemma~\ref{gfy_to_gamma_y-t}(i).  Therefore,
	\begin{equation}
		F(\mat x_r)-F(\mat y_r) = \frac{1}{2}\|\mat A (\mat x_r - \mat y_r)\|^2 +\langle \mat \zeta_{\mat x_r}-\xi  , \mat x_r \rangle.  \label{eq:2}
	\end{equation}
	By \eqref{eq:-1} again with
	$\mat x=\mat x_r$, $\zeta_1 = \zeta_{\mat{x}_r}$, $\mat z=\mat y_r$, and $\zeta_2 = \xi$.  It gives
	$F(\mat x_r)-F(\mat y_r)  = -\frac{1}{2}\|\mat A (\mat x_r - \mat y_r)\|^2- \langle  \mat \nabla f(\mat x_r) + \zeta_{\mat{x}_r}, \mat y_r - \mat x_r\rangle +\langle  \mat \zeta_{\mat x_r}- \mat \xi  , \mat y_r \rangle$.
	Summing the above equation and (\ref{eq:2}) gives:
	\begin{align*}
		2F(\mat x_r)-2F(\mat y_r) 
		&= -\langle  \mat \nabla f(\mat x_r) + \zeta_{\mat{x}_r}, \mat y_r - \mat x_r\rangle +\langle  \mat \zeta_{\mat x_r}- \mat \xi  , \mat y_r \rangle  +\langle \mat \zeta_{\mat x_r}-\xi  , \mat x_r \rangle \\
		&= -\langle  \mat \nabla f(\mat x_r) + \zeta_{\mat{x}_r}, \mat y_r - \mat x_r\rangle \tag*{\text{($\because$ Lemma~\ref{gfy_to_gamma_y-t}(ii))}} \\
		&= -\langle \gamma_{\mat{x}_r},\mat{y}_r-\mat{x}_r \rangle.
	\end{align*}
	This completes the proof of (iv).\hfill\qed
\end{proof}


\begin{lemma}
\label{lem:full-t}
Let $\mat{n}_r$ be any unit conical combination of $\{-\mathrm{sign}((\nabla f(\mat x_r))_i) \cdot \mat{e}_i : i \in E_r\}$.  Let $\mat{y}_r$ be the point in direction $\mat{n}_r$ from $\mat{x}_r$ that minimizes $F$. 
Let $\mat{n}_* = (\mat{x}_* - \mat{x}_r)/\norm{\mat{x}_* - \mat{x}_r}$.  If $F(\mat{x}_r) > F(\mat{x}_*) + \eps\norm{\mat{x}_*-\mat{x}_r}^2$~~for some $\eps \in (0,1)$, then $\langle \gamma_{\mat x_r} , \mat{y}_r - \mat{x}_r \rangle / \langle \gamma_{\mat x_r} , \mat{x}_* - \mat{x}_r \rangle \geq   \eps \cdot \langle \gamma_{\mat x_r} , \mat{n}_r \rangle^2 / \langle \gamma_{\mat x_r} , \mat{n}_* \rangle^2$.
\end{lemma}	 
\begin{proof}
By Lemma~\ref{gfy_to_gamma_y-t}(i), there exists $\xi \in \partial g(\mat{y}_r)$ such that $\langle  \mat \nabla f(\mat y_r) + \xi, \mat{n}_r\rangle = 0$.  We have $\langle \zeta_{\mat{x}_r},\mat{y}_r - \mat{x}_r \rangle - \langle \xi,\mat{y}_r - \mat{x}_r \rangle = \langle \zeta_{\mat{x}_r} - \xi, \mat{y}_r \rangle - \langle \zeta_{\mat{x}_r} - \xi, \mat{x}_r \rangle$ which is zero by Lemma~\ref{gfy_to_gamma_y-t}(ii).  It implies that $\langle \zeta_{\mat{x}_r},\mat{n}_r \rangle = \langle \xi,\mat{n}_r\rangle$, and hence $\langle  \mat \nabla f(\mat y_r) + \zeta_{\mat{x}_r}, \mat{n}_r\rangle = 0$.  Substituting $\nabla f(\mat y_r)$ by $\mat A^t \mat A \mat y_r -  \mat A^t \mat b$, we obtain $\langle \mat{A}^t\mat{A} \mat{y}_r -\mat{A}^t\mat{b} + \zeta_{\mat{x}_r}, \mat{n}_r\rangle  = 0$. Rearranging terms gives $\langle \mat{A}^t\mat{A}(\mat{y}_r - \mat{x}_r), \mat{n}_r \rangle = \langle - \mat{A}^t\mat{A}\mat{x}_r + \mat{A}^t\mat{b} - \zeta_{\mat{x}_r},\mat{n}_r\rangle 
= \langle  -\nabla f(\mat x_r)- \zeta_{\mat x_r}, \mat{n}_r \rangle = \langle -\gamma_{\mat x_r} ,\mat{n}_r \rangle$.
Therefore, $\norm{\mat{y}_r-\mat{x}_r} \cdot \norm{\mat{A}\mat{n}_r}^2 = \langle \mat{A}^t\mat{A}(\mat{y}_r - \mat{x}_r), \mat{n}_r \rangle = \langle -\gamma_{\mat x_r} ,\mat{n}_r \rangle$.  Hence, $\norm{\mat{y}_r - \mat{x}_r} \geq \langle -\gamma_{\mat x_r} ,\mat{n}_r \rangle$ as $\norm{\mat{A}\mat{n}_r}^2 \leq \norm{\mat{A}}^2 \leq 1$.


By Lemma~\ref{gfy_to_gamma_y-t}(iii), $F(\mat{x}_r) - F(\mat{x}_*) \leq \norm{\mat{x}_*-\mat{x}_r} \cdot \langle -\gamma_{\mat{x}_r}, \mat{n}_*\rangle$.  If $\langle -\gamma_{\mat{x}_r}, \mat{n}_*\rangle < \eps\norm{\mat{x}_*-\mat{x}_r}$, then $F(\mat{x}_r) - F(\mat{x}_*) \leq \eps\norm{\mat{x}_*-\mat{x}_r}^2$, contradicting the assumption of the lemma.  Hence, $\langle -\gamma_{\mat{x}_r}, \mat{n}_*\rangle \geq \eps\norm{\mat{x}_*-\mat{x}_r}$.  Combining this inequality with $\norm{\mat{y}_r - \mat{x}_r} \geq \langle -\gamma_{\mat x_r} ,\mat{n}_r \rangle$ gives
$\frac{\langle \gamma_{\mat{x}_r}, \mat{y}_r - \mat{x}_r \rangle}{\langle \gamma_{\mat{x}_r}, \mat{x}_* - \mat{x}_r \rangle} = \frac{\norm{\mat{y}_r-\mat{x}_r}}{\norm{\mat{x}_*-\mat{x}_r}} \cdot \frac{\langle \gamma_{\mat{x}_r},\mat{n}_r\rangle}{\langle \gamma_{\mat{x}_r},\mat{n}_*\rangle} \geq \eps \cdot \frac{\langle \gamma_{\mat{x}_r},\mat{n}_r\rangle^2}{\langle \gamma_{\mat{x}_r},\mat{n}_*\rangle^2}$.\hfill\qed
\end{proof}

\begin{lemma}
\label{lem:zero}
Let $G_r$ be the set of the $\tau_{r+1}$ heaviest elements in $E_r$.  Let $H_r = G_r \cup (\supp(\mat{x}_*) \cap E_r)$.
Then, $\langle \gamma_{\mat{x}_r}, \mat{x}_* - \mat{x}_r \rangle = \langle \gamma_{\mat{x}_r} \! \downarrow \! H_r, \mat{x}_* - \mat{x}_r \rangle$.
\end{lemma}
\begin{proof}
	For any $i \in H_r$, $(\gamma_{\mat{x}_r})_i = (\gamma_{\mat{x}_r} \! \downarrow \! H_r)_i$ by definition.  Therefore, $(\gamma_{\mat{x}_r})_i \cdot (\mat{x}_* - \mat{x}_r)_i = (\gamma_{\mat{x}_r} \! \downarrow \! H_r)_i \cdot (\mat{x}_* - \mat{x}_r)_i$.

	Take any $i \not\in E_r$.  We have $(\gamma_{\mat{x}_r})_i = 0$ because $\gamma_{\mat{x}_r} = \zeta_{\mat{x}_r} + \nabla f(\mat{x}_r)$ and $(\zeta_{\mat{x}_r})_i = -(\nabla f(\mat{x}_r))_i$  by definition. Therefore, both $(\gamma_{\mat{x}_r})_i \cdot (\mat{x}_* - \mat{x}_r)_i$ and $(\gamma_{\mat{x}_r} \! \downarrow \! H_r)_i \cdot (\mat{x}_* - \mat{x}_r)_i$ are zero.

	For any $i \in E_r \setminus H_r$, $i \not\in \supp(\mat{x}_*)$ as $\supp(\mat{x}_*) \cap E_r \subseteq H_r$.  So $(\mat{x}_*)_i = 0$.  Also, $(\mat{x}_r)_i = 0$ as $i \in E_r$.  So $(\gamma_{\mat{x}_r})_i \cdot (\mat{x}_* - \mat{x}_r)_i$ and $(\gamma_{\mat{x}_r} \! \downarrow \! H_r)_i \cdot (\mat{x}_* - \mat{x}_r)_i$ are zero.\hfill\qed
\end{proof}

\begin{lemma}
\label{lem:full_cr-t}
If $F(\mat{x}_r) > F(\mat{x}_*) + \eps \norm{\mat{x}_*-\mat{x}_r}^2$, then 
\[
\frac{F(\mat{x}_{r+1}) - F(\mat{x}_*)}{F(\mat{x}_r) - F(\mat{x}_*)} \leq 1 - \frac{\eps\tau_{r+1}}{8(s+\tau_{r+1})\ln\tau_{r+1}}.
\]
\end{lemma}	
\begin{proof}
Let $G_r$ be the set of the $\tau_{r+1}$ heaviest elements in $E_r$.  Let $H_r = G_r \cup (\supp(\mat{x}_*) \cap E_r)$.
We prove in Lemma~\ref{lem:tech-nice} in Appendix~\ref{app:nice} 
that there exists a unit descent direction ${\mat{n}}_r$ from $\mat{x}_r$ such that $\mat{n}_r$ is a conical combination of $\{-\mathrm{sign}((\nabla f(\mat x_r))_i) \cdot \mat{e}_i : i \in G_r\}$ and $\langle -\gamma_{\mat x_r} ,{\mat{n}}_r \rangle \geq \norm{\gamma_{\mat x_r} \! \downarrow \! H_r} \cdot \sqrt{\frac{\tau_{r+1}}{4(s+\tau_{r+1})\ln\tau_{r+1}}}$.  Let $\mat{n}_* = (\mat{x}_* - \mat{x}_r)/\norm{\mat{x}_* - \mat{x}_r}$.   By Lemma~\ref{lem:zero}, $\langle -\gamma_{\mat x_r} ,\mat{n}_* \rangle =
\langle -\gamma_{\mat x_r} \! \downarrow \! H_r,\mat{n}_* \rangle$.  Then, $\langle -\gamma_{\mat x_r},\mat{n}_* \rangle \leq \norm{\gamma_{\mat x_r} \! \downarrow \! H_r}$.  Hence, 
$\frac{\langle \gamma_{\mat{x}_r},\mat{n}_r\rangle}{\langle \gamma_{\mat{x}_r},\mat{n}_*\rangle} \geq \sqrt{\frac{\tau_{r+1}}{4(s+\tau_{r+1})\ln\tau_{r+1}}}$.

Let $\mat{y}_r$ be the point in the direction $\mat{n}_r$ from $\mat{x}_r$ that minimizes $F$. We have
$\frac{F(\mat{x}_{r+1}) - F(\mat{x}_*)}{F(\mat{x}_r) - F(\mat{x}_*)} = 1 - \frac{F(\mat{x}_r) - F(\mat{x}_{r+1})}{F(\mat{x}_r) - F(\mat{x}_*)} 
\leq 1 - \frac{F(\mat{x}_r) - F(\mat{y}_r)}{F(\mat{x}_r) - F(\mat{x}_*)}$.   By Lemma~\ref{gfy_to_gamma_y-t}(iii) and (iv), $F(\mat{x}_r) - F(\mat{y}_r) = -\frac{1}{2}\langle \gamma_{\mat{x}_r}, \mat{y}_r - \mat{x}_r \rangle$ and $F(\mat{x}_r) - F(\mat{x}_*) \leq -\langle \gamma_{\mat{x}_r}, \mat{x}_* - \mat{x}_r \rangle$. Therefore, $\frac{F(\mat{x}_{r+1}) - F(\mat{x}_*)}{F(\mat{x}_r) - F(\mat{x}_*)} \leq 1 - \frac{1}{2} \cdot \frac{\langle \gamma_{\mat{x}_r},\mat{y}_r-\mat{x}_r\rangle}{\langle \gamma_{\mat{x}_r},\mat{x}_*-\mat{x}_r\rangle} \leq 1- \frac{\eps}{2} \cdot \frac{\langle \gamma_{\mat{x}_r},\mat{n}_r\rangle^2}{\langle \gamma_{\mat{x}_r},\mat{n}_*\rangle^2}$ by Lemma~\ref{lem:full-t}, which is at most $1 - \frac{\eps\tau_{r+1}}{8(s+\tau_{r+1})\ln\tau_{r+1}}$ by the lower bound on $\frac{\langle \gamma_{\mat{x}_r},\mat{n}_r\rangle}{\langle \gamma_{\mat{x}_r},\mat{n}_*\rangle}$.\hfill\qed
\end{proof}

