Recall the parameter $h \in (1,2]$ in Algorithm~\ref{alg:1}.  The next result bounds the working set sizes up to the first solution with an additive error at most $\eps/\eta^2$.

\begin{theorem}
\label{thm:tau-sum}
Suppose that $\norm{\mat{A}} \leq 1$ and $\eta = \alpha\norm{\mat{A}^t\mat{b}}_\infty$ for a fixed $\alpha \in (0,1)$.  Scale space such that $\norm{b} = 1$.
Let $\kappa+1$ be the minimum index such that $F(\mat{x}_{\kappa+1}) - F(\mat{x}_*) \leq \eps/\eta^2$.
\begin{itemize}
\item If $h \leq 2^{O(\eps/(\ln n \ln (\eta/\eps)))}$, then $\sum_{i=1}^\kappa \tau_i = O\left(\frac{1}{\eps}(s+\tau)\log (s+\tau)\log\frac{\eta}{\eps}\right)$.
\item Otherwise, $\sum_{i=1}^{\kappa} \tau_i = O\left(\frac{1}{\eps}k\log k\log\frac{\eta}{\eps}\right)$.
\end{itemize}
\end{theorem}
\begin{proof}
Take any constant $c \geq 1$.  Divide $[\kappa]$ into two disjoint subsets $I$ and $J$ such that for all $i \in I$, $\tau_i \leq cs$, and for all $i \in J$, $\tau_i > cs$.

For any $\mat{x}_r$, $\eta\norm{\mat{x}_r} \leq \eta\norm{\mat{x}_r}_1 \leq F(\mat{x}_r) \leq F(\mat{x}_0) = \frac{1}{2}\norm{\mat{b}}^2 = \frac{1}{2}$.   The same argument works for $\mat{x}_*$.  It means that $\eps\norm{\mat{x}_* - \mat{x}_r}^2 \leq \eps/\eta^2$.  Therefore, for any $r \in [\kappa]$, $F(\mat{x}_r) - F(\mat{x}_*) > \eps/\eta^2 \geq \eps\norm{\mat{x}_*-\mat{x}_r}^2$ by assumption, which makes Lemma~\ref{lem:full_cr-t} applicable for all $r \in [\kappa]$.

View $I$ as a chronological sequence.  Let $i$ be the largest index in $I$.   Note that $F(\mat{x}_0) - F(\mat{x}_*) \leq F(\mat{x}_0) \leq \frac{1}{2}\norm{\mat{b}}^2 = \frac{1}{2}$.  Then, by Lemma~\ref{lem:full_cr-t}, $F(\mat{x}_{i}) - F(\mat{x}_*) \leq \frac{1}{2}\prod_{i \in I} \bigl(1-\frac{\eps\tau_i}{8(s+\tau_i)\ln (cs)}\bigr)$, which is at most $\frac{1}{2}\prod_{i \in I} \bigl(1-\frac{\eps\tau_i}{8(c+1)s\ln(cs)}\bigr)$.  Let $\tau_{\text{avg}} = \sum_{i\in I} \tau_i/|I|$.  It is well known that the geometric mean is at most the arithmetic mean.  Therefore, $\frac{1}{2}\prod_{i \in I} \bigl(1-\frac{\eps\tau_i}{8(c+1)s\ln(cs)}\bigr) \leq 
\frac{1}{2}\bigl(1 - \frac{\eps\tau_{\text{avg}}}{8(c+1)s\ln(cs)}\bigr)^{|I|} \leq \frac{1}{2}e^{-\eps\tau_{\text{avg}}|I|/(8(c+1)s\ln(cs))}$. This upper bound is at least $\eps/\eta^2$ so that $\mat{x}_{\kappa+1}$ is the first solution that satisfies $F(\mat{x}_{\kappa+1}) - F(\mat{x}_*) \leq \eps/\eta^2$.  Hence, $\frac{\eps\tau_{\text{avg}}|I|}{8(c+1)s\ln(cs)} \leq \ln \frac{\eta^2}{2\eps}$, which implies that $\sum_{i\in I} \tau_i = \tau_{\text{avg}}|I| = O\left(\frac{1}{\eps}s\log s \log\frac{\eta}{\eps}\right)$.

View $J$ as a chronological sequence.  Let $\tau_{\max} = \max_{i \in J} \tau_i$.  Take a contiguous subsequence of $J$ of length $(16\ln \tau_{\max})/\eps$.  Let $i$ and $j$ be the minimum and maximum indices in this subsequence, respectively.  By Lemma~\ref{lem:full_cr-t}, $F(\mat{x}_j) - F(\mat{x}_*) \leq e^{-1} \cdot (F(\mat{x}_i) - F(\mat{x}_*))$.  Since $F(\mat{x}_0) - F(\mat{x}_*) \leq F(\mat{x}_0) = \frac{1}{2}\norm{\mat{b}}^2 = \frac{1}{2}$, we can divide $J$ into no more than $\ln \frac{\eta^2}{2\eps}$ contiguous subsequences of length $(16\ln \tau_{\max})/\eps$.  It follows that $|J| \leq \frac{16}{\eps}\ln \tau_{\max} \cdot \ln \frac{\eta^2}{2\eps}$.  
%
The algorithm ensures that $\tau_{i+1} \leq h\tau_i$.  Extract the longest subsequence of $J$ (not necessarily contiguous) in which $\tau_i$ strictly increases.  Every consecutive $\tau_i$'s in this subsequence differ by a factor $h$.  This subsequence starts with $\min_{i \in J} \tau_i \leq \max\{hcs,\tau\}$.  If $h\leq 2^{O(\eps/(\ln n \ln (\eta/\eps)))}$, then $\tau_{\max} \leq h^{|J|} \cdot \max\{hcs,\tau\} \leq 2^{O(1)} \cdot (s+\tau)$.  So $\sum_{i \in J} \tau_i \leq O(s+\tau) \cdot |J| = O\left(\frac{1}{\eps}(s+\tau)\log (s+\tau)\log\frac{\eta}{\eps}\right)$.
If $h > 2^{O(\eps/(\ln n \ln (\eta/\eps)))}$, we still have $\tau_{\max} \leq k$ and hence $\sum_{i \in J} \tau_i \leq k|J| = O\left(\frac{1}{\eps}k\log k \log\frac{\eta}{\eps}\right)$.\hfill\qed
%
%For (i), only the bound for $\sum_{i \in I} \tau_i$ matters as $J$ is empty.  For (ii), 
%The bound for $\sum_{i \in J} \tau_i$ dominates.
\end{proof}

%\noindent{\em Remark 1.}  Scale space so that $\norm{b}=1$. By Lemma~\ref{lem:gap-ratio-t}(ii), $\eps/\eta^2 \leq \frac{4\eps}{\eta^3}F(\mat{x}_*)$.  So $F(\mat{x}_{\kappa+1}) \leq (1+4\eps/\eta^3)F(\mat{x}_*)$.

