\noindent {\em Remark 1.}  Clearly $\kappa \leq \sum_{i=1}^\kappa \tau_i$.  One can work out the exact upper bound for $\sum_{i=1}^\kappa \tau$ and hence $\kappa$.  DWS can be stopped after $\kappa$ iterations to obtain an error at most $\eps/\eta^2$, although DWS has probably terminated earlier in practice. 

\vspace{6pt}

\noindent {\em Remark 2.} Starting from $p_0$, we add at most $\sum_{i=1}^\kappa \tau_i$ free variables to any working set before reaching $\mat{x}_{\kappa+1}$.  Suppose that we set $p_0$ and $\tau$ to be $O(1)$.  If $\eps$ is given beforehand, we can ensure that every working set has $O(\frac{1}{\eps} s\log s \log \frac{\eta}{\eps})$ variables before reaching $\mat{x}_{\kappa}$.  So each call of the solver runs provably faster than using all $n$ variables.  When $\eps$ is not given, if $k = \Theta(s \log (n/s))$ (sufficient for the true signal to be recovered with high probability), every working set still has only $O(\frac{1}{\eps} s \cdot \mathrm{polylog}(n))$ variables.
%, which enables the solver to run faster than using all $n$ variables.
%
%\vspace{6pt}
%
%\noindent {\em Remark 4.} 
Clearly, $|\supp(\mat{x}_r)| \leq |W_r|$.  It follows that $|\supp(\mat{x}_{r})| \leq p_0 + \sum_{i=1}^\kappa \tau_i$.  
%Suppose that we set $p_0$ and $\tau$ to be $O(1)$.  
We conclude that all solutions $\mat{x}_r$, $r \in [\kappa+1]$, are provably sparse if $\eps$ is given beforehand or $k = \Theta(s \log (n/s))$.

\vspace{6pt}

\noindent {\em Remark 3.}  Figure~\ref{fig:sota_supp_wss_12} shows that the working set sizes are at most $cs$ for some small constant $c$ in the experiments.  That is, $\max_{i \in [\kappa]} \tau_i = O(s)$.  Under this assumption, the proof of Theorem~\ref{thm:tau-sum} reveals that $\sum_{i=1}^\kappa \tau_i = O(\frac{1}{\eps} s \log s \log \frac{\eta}{\eps})$ even if $\eps$ is not given beforehand.  Then, the working set sizes and support set sizes can be bounded by $O(\frac{1}{\eps} s \log s \log \frac{\eta}{\eps})$ even if $\eps$ is not given beforehand. 

\vspace{6pt}

\noindent {\em Remark 4.} 
To prepare for the next iteration, we need to compute $\nabla f(\mat{x}_r) = \mat{A}^t\mat{A}\mat{x}_r - \mat{A}^t\mat{b}$. We precompute $\mat{A}^t\mat{b}$ in $O(kn)$ time. Let $w = |W_r| \leq \sum_{i=1}^\kappa \tau_i$.  Note that $|\supp(\mat{x}_r)| \leq w$.  To obtain $\mat{A}^t\mat{A}\mat{x}_r$, we use $\mat{A}_r \in \real^{k \times w}$ and $\supp(\mat{x}_r)$ to obtain $\mat{A}\mat{x}_r$ in $O(kw)$ time, and then we compute $\mat{A}^t (\mat{A}\mat{x}_r)$ in $O(kn)$ time.  We extract $\mat{A}_{r+1}$ from $\mat{A}$ corresponding to $W_{r+1}$ is $O(k|W_{r+1}|) = O(k \cdot \sum_{i=1}^\kappa \tau_i)$ time.

\vspace{6pt}

\noindent {\em Remark 5.}
		If $\norm{\mat{Ax}_*} \leq \norm{\mat{b}}/4$, then $F(\mat{x}_*) \geq \frac{1}{2}\norm{\mat{Ax} - \mat{b}}^2 \geq \frac{9}{32}\norm{\mat{b}}^2$.  If $\norm{\mat{Ax}_*} > \norm{\mat{b}}/4$, then $F(\mat{x}_*) \geq \eta\norm{\mat{x}_*}_1 \geq \eta\norm{\mat{x}_*} \geq \eta\norm{\mat{Ax}_*} > \eta\norm{\mat{b}}/4$.   Recall that $\eta < \norm{\mat{A}^t\mat{b}}_\infty \leq \norm{\mat{b}}$.   We conclude that $F(\mat{x}_*) \geq \eta\norm{b}/4$ which is at least $\eta/4$ after $\norm{\mat{b}}$ is scaled to 1.  Therefore, the additive error of $\eps/\eta^2$ in Theorem~\ref{thm:tau-sum} is at most $\frac{4\eps}{\eta^3} F(\mat{x}_*)$.








