\begin{lemma}\label{LemmaROG}
	The vectors $r_k$ generated by FCGLS given in Algorithm \ref{AlgorithmFCGLS} have the following orthogonality property 
	\[
	r_k \perp q_i,\ i=0,1,\ldots, k-1.
	\]
	\begin{proof}
		We give a proof by induction. Clearly $r_1 \perp q_0$. Assume $r_k\perp q_i$, $i=0,1,\ldots k-1$. From the construction of $r_{k+1}$, 
		obviously $(r_{k+1},q_k)=0$. Moreover, for $i=1,2 \ldots, k-1$, 
		\[
		(r_{k+1},q_i)=(r_k-\gamma_k q_k,q_i)=(r_k,q_i)-\gamma_k(q_k,q_i)=0,
		\]
		using orthogonality of the vectors $q_i$.
	\end{proof}
\end{lemma}
\begin{theorem}
	The vectors $s_k$ generated by FCGLS given in Algorithm \ref{AlgorithmFCGLS} have the following orthogonality property
	\[
	s_k \perp_{M^{-1}_{i+1}} s_i,\ i=0,1,\ldots, k-1.
	\]
	\begin{proof}	
		Let $i, k \in \N$, $0 \leq i< k$. Then
		\begin{align}\label{derivation_sksi}
			\begin{split}
				(s_k,M_{i+1}^{-1}s_{i})
				&=\left(A^Tr_k,M_{i+1}^{-1}s_{i}\right)\\
				&=\left(A^T(r_{k-1}-\gamma_{k-1}q_{k-1}),M_{i+1}^{-1}s_{i}\right)\\
				&=(A^Tr_{k-1},M_{i+1}^{-1}s_i)-\gamma_{k-1}(A^Tq_{k-1},\hat{s}_i)\\
				&=(s_{k-1},M_{i+1}^{-1}s_i)-\gamma_{k-1}(q_{k-1},A\hat{s}_i)\\
				&=(s_{k-1},M_{i+1}^{-1}s_i)-\gamma_{k-1}\left(q_{k-1},q_i-\sum_{j=0}^{i-1}\theta^{i-1}_{j}q_j \right).
			\end{split}
		\end{align}	
		For $i=(k-1)$, we have 
		\begin{align*}
			(s_{k-1},M_{k}^{-1}s_{k-1})&=(A^Tr_{k-1},\hat{s}_{k-1})=(r_{k-1},A\hat{s}_{k-1})\\
			&=\left(r_{k-1},q_{k-1}-\sum_{j=0}^{k-2}\theta^{k-2}_{j}q_j\right)= (r_{k-1},q_{k-1}) \\
			\gamma_{k-1}\left(q_{k-1},q_{k-1}-\sum_{j=0}^{k-2}\theta^{k-2}_{j}q_j \right)
			&=\left( (r_{k-1},q_{k-1})/\norm{q_{k-1}}^2 \right)(q_{k-1},q_{k-1})\\
			&= (r_{k-1},q_{k-1}),
		\end{align*}
		using the orthogonality of the vectors $q_i$ and Lemma \ref{LemmaROG}.					
		For $i<(k-1)$, we have 
		\begin{equation*}
			\gamma_{k-1}\left(q_{k-1},q_i-\sum_{j=0}^{i-1}\theta^{i-1}_{j}q_j \right)=0.
		\end{equation*}
		Substitution into \eqref{derivation_sksi} gives
		\begin{align}
			(s_k,M_{k}^{-1}s_{k-1})&= 0 \\
			(s_k,M^{-1}_{i+1}s_{i})&=(s_{k-1},M^{-1}_{i+1}s_{i}),\ i=0, \ldots, k-2. \label{expression_sksi}
		\end{align}			
		Now proceed by induction. For $k=1$, clearly $s_1\perp_{M_{1}^{-1}}s_0$. Assume that 
		$s_{k-1} \perp_{M^{-1}_i} s_i,\ i=0,1,\ldots, k-2$. Then \eqref{expression_sksi} immediately gives 
		\[
		s_k\perp_{M^{-1}_{i+1}}s_i, \ i=0, 1, \ldots k-1.
		\]
	\end{proof}	
\end{theorem}

