\section{Technical Results and Proof Outline}\label{sec:technical-results}
In this section, we present general results on the mixing times of reversible Markov chains over high-dimensional cubes. 
Let $E$ be a finite ground set and let $[q] = \{0,1,\ldots,q-1\}$ be a finite domain.
Consider a distribution $\mu$ over $[q]^E$, and let $\Omega = \Omega(\mu) \subseteq [q]^E$ denote its support.
Let $Q$ be a Markov chain that is reversible with respect to the stationary distribution $\mu$, meaning that for any $x, y \in \Omega$, the detailed balance equation holds:
$\mu(x)Q(x,y) = \mu(y)Q(y,x)$.
To bound the mixing time of $Q$, we analyze the Poincar\'e and log-Sobolev constants associated with the chain $Q$. 

%\subsection{Classical functional inequalities for mixing times}
%First, we introduce some necessary notation.

For any function $f:\Omega \to \mathbb{R}_{\geq 0}$, 
define the variance of $f$ under distribution $\mu$, denoted by $\Var[\mu]{f}$, as the variance of the random variable $F = f(X)$ where $X \sim \mu$, i.e.,
%we use $\Var[\mu]{f} \triangleq \Var{F}$ to denote the variance of the random variable $F = f(X)$ for $X \sim \mu$, i.e.,
\begin{align}\label{eq:def-variance}
\Var[\mu]{f} \triangleq \Var{F} \triangleq \E{F^2} - \E{F}^2.
\end{align}
Similarly, define the entropy of $f$ under distribution $\mu$, denoted by $\Ent[\mu]{f}$, as:
%Define $\Ent[\mu]{f} \triangleq \Ent{F}$ as the entropy-like quantity for the random variable $F = f(X)$ for $X \sim \mu$, 
\begin{align}\label{eq:def-entropy}
\Ent[\mu]{f}\triangleq\Ent{F} \triangleq  \E{F \log F} - \E{F} \log \E{F}.
\end{align}
For any two functions $f,g:\Omega \to \mathbb{R}$, the Dirichlet form associated with the chain $Q$ is given by:
\begin{align*}
  \+E_Q(f,g) \triangleq \frac{1}{2}\sum_{x \in \Omega, y \in \Omega} \mu(x) Q(x,y) \left( f(x) - f(y)\right) \left( g(x) - g(y)\right).
\end{align*}
The Poincar\'e constant $\gamma(Q)$ of $Q$ is defined as:
\begin{align*}
\gamma(Q) = \inf \left\{\frac{\+E_Q(f,f)}{\Var[\mu]{f}} \mid f :\Omega \to \mathbb{R} \land \Var[\mu]{f} > 0\right\}.
\end{align*}
The log-Sobolev constant $\rho(Q)$ of $Q$ is defined as:
\begin{align*}
\rho(Q) = \inf \left\{\frac{\+E_Q(f,f)}{\Ent[\mu]{f^2}} \mid f :\Omega \to \mathbb{R} \land \Ent[\mu]{f^2} > 0\right\}.
\end{align*}
The mixing time of $Q$ can be bounded using the Poincar\'e constant as follows:
\begin{align*}
T_{\mathrm{mix}}\tp{\frac{Q+I}{2},\epsilon} = O\tp{\frac{1}{\gamma(Q)}\tp{\log\frac{1}{\mu_{\min}} + \log\frac{1}{\epsilon}}},
\end{align*}
where $\mu_{\min} = \min_{x \in \Omega} \mu(x)$ and $\frac{Q+I}{2}$ corresponds to the $\frac{1}{2}$-lazied version of the chain $Q$. 
If $Q$ is positive semidefinite, this mixing time bound also holds for $Q$.

The log-Sobolev constant $\rho(Q)$ can provide a sharper bound on the mixing time, specifically: 
\begin{align*}
  T_{\mathrm{mix}}\tp{\frac{Q+I}{2}, \epsilon} = O\tp{\frac{1}{\rho(Q)}\tp{\log\log \frac{1}{\mu_{\min}} + \log\frac{1}{\epsilon}}}.
\end{align*}
This bound on the mixing time, derived from the log-Sobolev constant, also holds for $Q$.


\subsection{Rapid mixing via local functional inequalities}
Our results establish both the Poincar\'e and log-Sobolev inequalities by first introducing new local versions of these inequalities. We then develop a ``local-to-global'' argument to lift these functional inequalities from the local to the global setting.
%To present these results, we first define the notion of conditional distributions.
%We say $\tau \in [q]^{S}$ is an \emph{feasible pinning} if $S$ is a (possibly empty) subset of $E$ and $\mu_S(\tau) > 0$, where $\mu_S$ is the marginal distribution on $S$ projected from $\mu$.

Next, we introduce the new \emph{local} versions of functional inequalities for mixing times.
\begin{definition}[local functional inequalities] \label{def:HS-route}
  Let $\mu$ be a distribution supported over $\Omega \subseteq [q]^E$. 
  Let $Q$ be a reversible chain on $\Omega$ with stationary distribution $\mu$.
  \begin{itemize}
  \item (local Poincar\'e inequality) We say that ${Q}$ satisfies the $\alpha$-\emph{local Poincar\'e inequality} if 
  \begin{align} \label{eq:def-HS-route-V}
    \alpha \cdot \sum_{e\in E} \Var{\E{\*F \mid \*X_e}} \leq  \+E_{Q}(f,f),\quad \forall f: \Omega(\mu) \to \mathbb{R},
  \end{align}
  where $\*X \sim \mu$ and $\*F \triangleq  f(\*X)$.

  %Moreover, if for every feasible pinning $\tau$, $Q^\tau$ satisfies \HSRV{} with constant $\alpha$, then we say \emph{$Q$ satisfies \HSRV{} with rate $\alpha$ for all pinning}.
  \item   (local log-Sobolev inequality) We say $Q$ satisfies the \emph{$\alpha$-local log-Sobolev inequality} if 
  \begin{align} \label{eq:def-HS-route-E}
    \alpha \cdot \sum_{e\in E} \Ent{\E{\*F^2 \mid \*X_e}} \leq  \+E_{Q}(f,f),\quad \forall f: \Omega(\mu) \to \mathbb{R}.
  \end{align}
  where $\*X \sim \mu$ and $\*F \triangleq  f(\*X)$.
  \end{itemize}
\end{definition}
Note that in~\eqref{eq:def-HS-route-V} and~\eqref{eq:def-HS-route-E}, $\E{\*F \mid \*X_e}$ and $\E{\*F^2 \mid \*X_e}$ are both real-valued random variables. The operators $\Var{\cdot}$ and $\Ent{\cdot}$ are as defined in~\eqref{eq:def-variance} and~\eqref{eq:def-entropy}, respectively.


