\subsection{Local functional inequalities via transport flow}

%Let $Q$ be a Metropolis-Hasting dynamics for distribution $\mu$ with the operation set $\+O$. 
We develop a constructive approach for establishing the local functional inequalities in \Cref{def:HS-route} using a technique we call \emph{transport flow}, which extends the canonical path method.

Given a sequence of states $\gamma = (x_0,x_1,\ldots,x_{\ell})$  from the state space $\Omega$,
we denote its starting point as $s(\gamma) = x_0$ and its endpoint as $t(\gamma) = x_\ell$.
We call $\gamma$ a path in the transition graph of $Q$ if $Q(x_i,x_{i+1}) > 0$ for all $i < \ell$.
We denote the length (number of edges) of this path $\gamma$ by $\ell(\gamma)=\ell$.
For two states $x, y \in \Omega(\mu)$, if $Q(x,y) > 0$, we say there is a transition from $x$ to $y$, denoted as $(x \mapsto y)$.
Given a transition $(x \mapsto y)$, we write $(x \mapsto y) \in \gamma$  to indicate that there exists some $i < \ell$ such that $x = x_i$ and $y = x_{i+1}$.

\begin{definition}[transport flow]\label{def:transport-flow}
    Let $\nu$ and $\pi$ be two distributions over the state space $\Omega$, 
    and let $Q$ be a Markov chain on $\Omega$. 
    The \emph{transport flow} from $\nu$ to $\pi$ is a distribution $\Gamma$ over paths on the transition graph of $Q$ that satisfies:
    \begin{itemize}
    \item The starting point $s(\gamma)$ of a path $\gamma \sim \Gamma$ follows the distribution $\nu$;
    \item The endpoint $t(\gamma)$ of a path $\gamma \sim \Gamma$ follows the distribution $\pi$.
    \end{itemize}
\end{definition}

The random paths in $\Gamma$ transport the distribution $\nu$ to $\pi$ using the transitions of the Markov chain $Q$.
Given a random path $\gamma \sim \Gamma$, its starting point and endpoint $(s(\gamma),t(\gamma))$ naturally form a coupling of the two distributions $\nu$ and $\pi$.
%Suppose we first sample $X \sim \nu$ and then sample a random path $\gamma \sim \Gamma$ conditional on the starting point $X$. The endpoint of $\gamma$ follows the distribution $\pi$ and every step of $\gamma$ is a local move defined by the Markov chain $Q$. If we project $\Gamma$ to the distribution of two endpoints 

\begin{remark}[Canonical path and multicommodity flow as transport flow]\label{rem:canonical-path-as-transport-flow}
  The classical canonical path method, and more generally, multicommodity flow~\cite{diaconis1991geometric,sinclair1992improved}, can be interpreted as constructing a transport flow from $\mu$ to $\mu$ itself. 
  Specifically, these methods define a collection of paths $\+P$, where each path $\gamma \in \+P$ is assigned with a weight $w(\gamma)$,
  such that for any $x, y \in \Omega$, the total weight $w(\gamma)$ for all paths from $x$ to $y$ is precisely $\mu(x)\mu(y)$. 
  This corresponds to a transport flow $\Gamma$ from $\mu$ to $\mu$, where each path $\gamma \in \+P$ is sampled with probability $w(\gamma)$. 
  Thus, a random path $\gamma \sim \Gamma$ induces an \emph{independent coupling} with itself through its endpoints $(s(\gamma), t(\gamma))$.
\end{remark}



%Let $\Omega(\mu_e) \triangleq \set{c \in [q] \mid \mu_e(c) > 0}$ be the support of $\mu_e$. 

The following theorem establishes local functional inequalities based on the existence of a family of transport flows with bounded average congestion and average squared length.

For any $e \in E$ and $c \in [q]$, let $\mu^{e \gets c}$ denote the distribution of $\*X \sim \mu$ conditioned on $\*X_e = c$.


\begin{theorem}[\HSRV{} via transport flow] \label{thm:HS-route-via-congestion}
  Let $\kappa,L > 0$. 
  Let $\mu$ be a distribution over $[q]^E$ with support $\Omega$.
  Let $Q$ be a reversible Markov chain on $\Omega$ with stationary distribution $\mu$.
  Suppose there exists a family of transport flows $\{\Gamma_e^{a\to b}\}$ from $\mu^{e \gets a}$ to $\mu^{e \gets b}$ for all $e \in E$ and $a,b \in \Omega(\mu_e)$ with $a < b$, satisfying the following conditions:
  \begin{itemize}
  \item ($\kappa$-expected congestion) For any transition $(x \mapsto y)$, and any $a,b \in [q]$ with $a < b$,
    \begin{align} \label{eq:def-congestion}
    \sum_{e\in E:a,b\in \Omega(\mu_e)} \mu_e(a)\mu_e(b) \E[\gamma \sim \Gamma_e^{a\to b}]{\frac{\*1[(x \mapsto y) \in \gamma]}{\ell(\gamma)}} \leq \kappa \cdot \mu(x)Q(x,y).
    \end{align}
%    where $\ell(\gamma)$ denotes the length (number of edges) of the path $\gamma$.
    %where $d_e \triangleq \sum_{c,c'\in [q]:c \neq c'}\mu_e(c)\mu_e(c')$;
  \item ($L$-expected squared length)  For any $e \in E$, and any $a,b \in \Omega(\mu_e)$ with $a < b$,
  \begin{align*}
  \E[\gamma \sim \Gamma_e^{a\to b}]{\ell(\gamma)^2} \leq L.
  \end{align*}
  \end{itemize}
  Then, the Markov chain $Q$ satisfies the $\frac{1}{2q^2\kappa L}$-local Poincar\'e inequality.
\end{theorem}

\begin{theorem}[local log-Sobolev inequality via transport flow] \label{thm:log-Sob-HS-route-via-congestion}
  Let $\kappa > 0$. 
  Let $\mu$ be a distribution over $[q]^E$ with support $\Omega$.
  Let $Q$ be a reversible Markov chain on $\Omega$ with stationary distribution $\mu$.
  Suppose there exists a family of transport flows $\{\Gamma_e^{a\to b}\}$ from $\mu^{e \gets a}$ to $\mu^{e \gets b}$ for all $e \in E$ and $a,b \in \Omega(\mu_e)$ with $a < b$, satisfying the following condition:
  \begin{itemize}
  \item (strong $\kappa$-expected congestion) For any transition $(x \mapsto y)$, and any $a,b \in [q]$ with $a < b$,
    \begin{align} \label{eq:def-strong-congestion}
     \sum_{e\in E: a,b \in \Omega(\mu_e) } \mu_e(a) \mu_e(b) \E[\gamma \sim \Gamma^{a\to b}_e]{\ell(\gamma) \*1[(x \mapsto y) \in \gamma]} \leq \kappa \cdot \mu(x)Q(x,y).
    \end{align}
  %\item ($L$-expected length) for all $e \in E$, it holds that $\E[X,Y\sim \+C_e]{\ell(X,Y)} \leq L$.
  \end{itemize}
  Then, the Markov chain $Q$ satisfies the $\alpha$-local log-Sobolev inequality with
  \begin{align*}
  \alpha = \frac{1}{2 q^2 \kappa} \cdot \frac{{1-2 \phi}}{\log(\frac{1}{\phi} - 1)},
  \end{align*}
  where $\phi \le \min \set{\mu_e(c) \mid e \in E, c\in [q], \mu_e(c) \neq 0}$ is the marginal lower bound.
\end{theorem}

\Cref{thm:HS-route-via-congestion,thm:log-Sob-HS-route-via-congestion} are proved in \Cref{sec:transport-flow}.
Compared to the classical canonical path and multicommodity flow approaches, 
these theorems establish \emph{local} functional inequalities for mixing times based on the \emph{average} congestion and length of paths between \emph{coupled} pairs. 
%we construct transport flow between two conditional distributions, $\mu^{e \gets a}$ and $\mu^{e \gets b}$, rather than from $\mu$ to itself. 
%More importantly, our definition of transport flow allows the two endpoints of a path $\gamma \sim \Gamma$ to form a \emph{non-trivial coupling} of $\mu^{e \gets a}$ and $\mu^{e \gets b}$, providing significantly greater flexibility for optimizing congestion and path length than the \emph{independent coupling} inherent in canonical paths, as discussed in \Cref{rem:canonical-path-as-transport-flow}. 
In our applications, we carefully exploit this coupling induced by transport flow  to ensure that the congestion and length remain well bounded.

A similar coupling-based enhancement of the canonical path argument was recently used in \cite{CCFV25} to analyze the Glauber dynamics for edge colorings on trees. 
Our definition of transport flow is more general.
More importantly, we show that transport flow can be utilized to establish local functional inequalities that guarantee rapid mixing in general  Markov chains.



