\subsection{Application to the Jerrum-Sinclair chain}\label{sec:app-JS-chain}
We then apply our general approach to the Jerrum-Sinclair chain for the monomer-dimer model and establish the following result, which is a formal restatement of \Cref{thm:main-simple}.
\begin{theorem}\label{thm:main}
Let $G=(V,E)$ be a simple undirected graph with $n$ vertices, $m$ edges, and maximum degree $\Delta$.
Let $\mu$ be the monomer-dimer distribution on $G$ with edge weight $\lambda>0$, and define $\overline{\lambda} = \max\set{1,\lambda}$.
The Jerrum-Sinclair chain $P_{\mathrm{JS}}$ for $\mu$ has Poincar\'e constant $ \gamma(P_{\mathrm{JS}})$ and log-Sobolev constant $\rho(P_{\mathrm{JS}})$ satisfying:
\begin{align*}
    \gamma(P_{\mathrm{JS}}) = \Omega\tp{\frac{1}{\overline{\lambda}^{3}\log^2(1+\ol{\lambda}) \cdot  \Delta \cdot m}} \quad \text{and} \quad \rho(P_{\mathrm{JS}}) = \Omega\tp{\frac{1}{\overline{\lambda}^{4} \cdot \Delta^2 \log(\ol{\lambda} \Delta) \cdot m}}.
\end{align*}
%where $n = \abs{V}$, $m = \abs{E}$ and $\Delta$ is the maximum degree of the graph $G$.
As a consequence, the mixing time of the $1/2$-lazy Jerrum-Sinclair chain $P_{\mathrm{zz}}=\frac{1}{2}(P_{\mathrm{JS}}+I)$ satisfies
\begin{align*}
%    T_{\mathrm{mix}}(P_{\mathrm{lz\text{-}JS}}) &=\min\left\{O\left(\overline{\lambda}^{3}\log^2(1+\ol{\lambda}) \cdot  \Delta \cdot mn\right),O\left(\overline{\lambda}^{4} \cdot \Delta^2 \log \Delta \cdot m\log n\right)\right\}.\\
    T_{\mathrm{mix}}(P_{\mathrm{zz}}) &= O\left(\overline{\lambda}^{3} \Delta m\cdot  \min \left\{n\log^2(1+\ol{\lambda}),\,\, \overline{\lambda} \Delta \log(\ol{\lambda} \Delta)\cdot \log n \right\}\right).
\end{align*}
\end{theorem}
In comparison, the original bound by Jerrum and Sinclair \cite{jerrum1989approximating,sinclair1992improved,jerrum2003counting} was $O(\ol{\lambda}mn^2\log n)$, which remained the best known bound for general graphs with arbitrary maximum degree.

\paragraph{The Jerrum-Sinclair chain on monomer-dimers.}
%Let $\mu$ denote  the monomer-dimer distribution on $G=(V,E)$ with edge weight $\lambda > 0$. 
We can   interpret the monomer-dimer distribution $\mu$ on graph $G=(V,E)$, defined over $2^E$, equivalently as a distribution over $\{0,1\}^E$, where each subset $M \subseteq E$  corresponds to a configuration $\sigma_M \in \{0,1\}^E$, with $\sigma_M(e)$ indicating whether the edge $e$ is occupied in $M$.
% We will frequently use the two views interchangeably depending on which is more convenient.


Let $\mathfrak{Q}_\JS=\mathfrak{Q}_\JS(\mu)$ denote the family of Jerrum-Sinclair chains for the monomer-dimer distributions $\mu^{\tau}$ induced by $\mu$.
%
%To apply the general framework to Jerrum-Sinclair chain, we first introduce the family $\mathfrak{Q}$ of Markov chains for all conditional distributions. 
