% \end{enumerate}
\item Accept $M$ as $X_{t+1}$ with probability $\min\set{1,\frac{\mu^\tau(M)}{\mu^\tau(X_t)}}$; otherwise, set $X_{t+1}=X_{t}$.
\end{enumerate}

