\begin{construction}[transport flow for monomer-dimer distributions] \label{def:monomer-dimer-trans-path}
Let $G=(V,E)$ and $e \in E$.
The transport flow $\Gamma_e$ from $\mu^{e \gets 0}$ to $\mu^{e \gets 1}$ is constructed as follows: 
%
Sample $(X,Y)\sim\+C_e$ according to the local flipping coupling $\+C_e$ defined in \Cref{def:new-coupling-2}, 
and let $B =X\oplus Y\triangleq  \{f \in E \mid X_f \neq Y_f\}$ be the set of edges where $X$ and $Y$ disagree. 
\begin{enumerate}
\item If $B$ forms a path, let $w^*$ be the larger endpoint of the path $B$, and let $e_1 \in B$ be the unique edge incident to $w^*$. Number the remaining edges along the path as $e_2,e_3,\ldots,e_{|B|}$. 
\begin{enumerate}
\item If $X_{e_1} = 1$ (i.e., $e_1$ is in the matching $X$), 
first apply a down transition to remove $e_1$, 
then perform exchange transitions on each pair $(e_{2i},e_{2i+1})$ along the path for $1\leq i \leq \lfloor (|B|-1)/2 \rfloor$, 
and finally, apply an up transition on $e_{|B|}$ if $|B|$ is even. 
\item If $X_{e_1} = 0$ (i.e., $e_1$ is not in $X$), apply exchange transitions on each pair $(e_{2i-1},e_{2i})$ along the path for $1\leq i \leq \lfloor |B|/2 \rfloor$, and conclude with an up transition on $e_{|B|}$ if $|B|$ is odd.
\end{enumerate}

\item If $B$ forms an even-length cycle, 
let $w^*$ be the largest vertex in $B$, 
and let $e_1 = \{w,w^*\} \in X$ be the unique edge incident to $w^*$ in the matching $X$. 
Number the edges along the cycle in the direction $w^* \to w$ as $e_2,e_3,\ldots,e_{|B|}$, where $e_{|B|}$ is incident to $w^*$. 
Apply a down transition to remove $e_1$, 
perform exchange transitions on each pair $(e_{2i},e_{2i+1})$ along the cycle for $1\leq i \leq \frac{|B|}{2} - 1$,
and conclude with an up transition on $e_{|B|}$.
\end{enumerate}
\end{construction}

