The following theorem shows the effectiveness of the transport flow in \Cref{def:monomer-dimer-trans-path}.
\begin{theorem} \label{thm:effective-trans-flow}
    Let $G=(V,E)$ be a simple undirected graph with $m=|E|$ edges and maximum degree $\Delta$, 
    and let $\mu$ be the monomer-dimer distribution on graph $G$ with edge weight $\lambda > 0$. Define $\ol{\lambda}=\max\{1, \lambda\}$.
    For every edge $e\in E$, the transport flow $\Gamma_e$ in~\Cref{def:monomer-dimer-trans-path} satisfies the following conditions:
    \begin{enumerate}
    \item\label{thm:trans-flow-length} $O(\ol{\lambda}\Delta  \log^2(1+\ol{\lambda}))$-expected squared length;
    \item\label{thm:trans-flow-congestion} $O(\ol{\lambda}^2  m)$-expected congestion;
    \item\label{thm:trans-flow-strong-congestion} strong $O(\ol{\lambda}^4 \Delta^2 m)$-expected congestion;
    % \item $O(\log(\Delta(\lambda+\frac{1}{\lambda})))$-marginal coefficient $\frac{\log(\frac{1}{\phi} - 1)}{1-2\phi}$ (defined in~\Cref{thm:log-Sob-HS-route-via-congestion});
    \end{enumerate}
    as required in \Cref{thm:HS-route-via-congestion,thm:log-Sob-HS-route-via-congestion}.
