We prove \Cref{thm:general-results}, a ``local-to-global'' theorem for the Poincar\'e and log-Sobolev inequalities. 

A key step in the proof is a one-step comparison lemma.
Let $\mu$ be a distribution supported on $\Omega \subseteq [q]^E$. %and let $\mu^\tau$ denote the conditional distribution given a feasible pinning $\tau \in [q]^{E \setminus \Lambda}$.
Suppose $\mathfrak{Q}$ is a family of reversible Markov chains for the conditional distributions induced by $\mu$. 
Consider the chain $Q^\tau \in\mathfrak{Q}$ for $\mu^\tau$ with feasible pinning $\tau \in [q]^{E \setminus \Lambda}$.
The following lemma compares the chain $Q^\tau$ to the chains $Q^{\tau \land (e \gets c)}$ for all $\mu^{\tau \land (e \gets c)}$ with  $e \in  \Lambda$ and  $c \in \Omega(\mu_e^\tau)$.

\begin{lemma}[one-step comparison lemma]\label{lem:one-step-comparison}
Suppose the Dirichlet forms satisfy
\begin{align}\label{eq:lemma-Dirichlet}
 \frac{1}{|\Lambda|} \sum_{e \in \Lambda} \E[c \sim \mu_e^\tau ]{\+E_{Q^{\tau \land (e \gets c)}}(f,g)} \leq \+E_{Q^\tau}(f,g), \quad \forall f,g: \Omega \to \mathbb{R}.
\end{align}
Then, the following one-step comparison results hold:
\begin{itemize}
  \item (Poincar\'e inequality) Suppose the Poincaré constants satisfy   $\gamma(Q^{\tau \land (e \gets c)})\ge\gamma_0$ for all chains $Q^{\tau \land (e \gets c)}$, 
  and the chain $Q^\tau$ satisfies the $\alpha$-local Poincar\'e inequality.
  % i.e., for all $f: \Omega(\mu^\tau) \to \mathbb{R}$, 
  % $$\alpha \cdot \sum_{e\in \Lambda} \Var{\E{\*F \mid \*X_e}} \leq  \+E_{Q^\tau}(f,f),$$ 
  % where $X \sim \mu^\tau$ and $\*F =  f(\*X)$, 
  Then, the Poincar\'e constant of $Q^\tau$ satisfies 
  \[\frac{1}{\gamma(Q^\tau)}\leq \frac{1}{\gamma_0} + \frac{1}{|\Lambda|\alpha}.\]
  \item (log-Sobolev inequality) Suppose the log-Sobolev constants satisfy $\rho(Q^{\tau \land (e \gets c)})\ge\rho_0$ for all $Q^{\tau \land (e \gets c)}$, 
  and $Q^\tau$ satisfies the $\alpha$-local log-Sobolev inequality.
  % i.e., for all $f: \Omega(\mu^\tau) \to \mathbb{R}$, 
  % $$\alpha \cdot \sum_{e\in \Lambda} \Ent{\E{\*F^2 \mid \*X_e}} \leq  \+E_{Q^\tau}(f,f),$$ 
  Then, the log-Sobolev constant of $Q^\tau$ satisfies
 \[\frac{1}{\rho(Q^\tau)}\leq \frac{1}{\rho_0} + \frac{1}{|\Lambda|\alpha}.\]
\end{itemize}
\end{lemma}
\begin{proof}
  Let $\*X \sim \mu^\tau$ be a random configuration, and define $\*F \triangleq  f(\*X)$, where $f:\Omega \to \mathbb{R}$ is an arbitrary function.
  Since $\tau$ fixes the values on $E \setminus \Lambda$, 
  we apply the law of total variance for each free variable $e \in \Lambda$ and take the average, yielding
\begin{align}\label{eq:law-tot-var}
    \Var{\*F} 
    &= \frac{1}{|\Lambda|} \sum_{e\in \Lambda} \Var{\E{\*F \mid \*X_e}} + \frac{1}{|\Lambda|} \sum_{e \in \Lambda} \E{\Var{\*F \mid \*X_e}}.
\end{align}
Thus, to bound $\Var[\mu^\tau]{f} = \Var{\*F}$, it suffices to bound each term on the right-hand side separately.
Since $Q^\tau$ satisfies the $\alpha$-local Poincar\'e inequality, we have
\begin{align} \label{eq:IH-first-term}
    \sum_{e\in  \Lambda} \Var{\E{\*F \mid \*X_e}} \leq  \frac{1}{\alpha} \cdot \+E_{Q^\tau}(f, f).
\end{align}
For the second term, by the assumption on the Poincar\'e constants for all $Q^{\tau \land (e \gets c)}$ and~\eqref{eq:lemma-Dirichlet}, we get
\begin{align} \label{eq:IH-second-term}
    \sum_{e \in \Lambda}\E{\Var{\*F \mid \*X_e}} &= \sum_{e \in \Lambda} \sum_{c \in \Omega(\mu_e)} \mu^\tau_e(c) \cdot \Var[\*X \sim \mu^{\tau \land (e \gets c)}]{f(\*X)}\notag\\
    &\leq  \frac{1}{\gamma_0} \sum_{e \in \Lambda} \E[c \sim \mu^\tau_e]{\+E_{Q^{\tau \land (e \gets c)}}(f,f)}\notag\\
    &\leq \frac{|\Lambda|}{\gamma_0}\cdot \+E_{Q^\tau}(f, f).
\end{align}
Combining \eqref{eq:law-tot-var}, \eqref{eq:IH-first-term}, and \eqref{eq:IH-second-term}, we have
\begin{align*}
    \Var{\*F}
    &\leq \frac{1}{|\Lambda|} \cdot \frac{1}{\alpha} \cdot \+E_{Q^\tau}(f, f) + \frac{1}{\gamma_0} \cdot \+E_{Q^\tau}(f, f)
    = \tp{\frac{1}{\gamma_0} + \frac{1}{|\Lambda| \alpha}}\cdot \+E_{Q^\tau}(f, f).
\end{align*}
This establishes the bound on the Poincar\'e constant.

For the log-Sobolev constant, we apply the law of total entropy:
\begin{align*}
  \Ent{\*F^2} 
  &= \frac{1}{\abs{\Lambda}} \sum_{e\in \Lambda} \Ent{\E{\*F^2 \mid \*X_e}} + \frac{1}{\abs{\Lambda}} \sum_{e \in \Lambda} \E{\Ent{\*F^2 \mid \*X_e}}.
\end{align*}
The remaining steps follow analogously to the proof of Poincar\'e constant.
\end{proof}

\begin{proof}[Proof of~\Cref{thm:general-results}]
We begin with the first part of \Cref{thm:general-results}, concerning the Poincar\'e inequality.
Let $m = |E|$.
For any feasible pinning $\tau\in[q]^{E \setminus \Lambda}$, where $\Lambda \subseteq E$ is arbitrary, we aim to establish:
\begin{align} \label{eq:IH-half-ineq}
    \Var[\mu^\tau]{f} &\leq \sum_{i=1}^{|\Lambda|}\frac{1}{i\alpha_{i}} \cdot \+E_{Q^\tau}(f, f),
\end{align}
where $\alpha_i$ for $1 \leq i \leq m$ are the parameters of local Poincar\'e inequalities assumed in \Cref{thm:general-results}.

We proceed by induction on $|\Lambda|$.
For the base case $\Lambda = \emptyset$, $\mu^\tau$ is a Dirac measure, implying $\Var[\mu^\tau]{f} = 0$, so \eqref{eq:IH-half-ineq} holds trivially.

Now assume \eqref{eq:IH-half-ineq} holds for every $\Lambda' \subseteq E$ with $\abs{\Lambda'} < k$ and every $\tau' \in \Omega(\mu_{ E \setminus \Lambda'})$. 
We show that it also holds for every $\Lambda$ with $|\Lambda|=k$ and every $\tau \in \Omega(\mu_{E \setminus \Lambda})$. 
Applying the induction hypothesis, \Cref{def:HS-route-family}, \Cref{def:concave-Dirichlet-forms,lem:one-step-comparison} (with parameter $\alpha=\alpha_{k}$), 
we obtain
\begin{align*}
  \frac{1}{\gamma(Q^\tau)} \leq \sum_{i=1}^{k-1}\frac{1}{i\alpha_{i}} + \frac{1}{\alpha_k k} = \sum_{i=1}^{k} \frac{1}{i\alpha_{i}}.
\end{align*}
This completes the induction.

Setting $\Lambda = E$ and $\tau = \emptyset$, the inequality \eqref{eq:IH-half-ineq} implies that the Poincar\'e constant of $Q$ is at least $\tp{\sum_{i=1}^{m}\frac{1}{i\alpha_{i}}}^{-1}$. 
This proves the first part of \Cref{thm:general-results}.
%For the result considered in \Cref{rem:general-results-remark}, when $\alpha_i=\Omega(\frac{1}{i})$, it follows that $\gamma(Q)=\Omega(\frac{1}{m})$.

The second part of \Cref{thm:general-results}, concerning the log-Sobolev constant, follows similarly.
\end{proof}


\subsection{Local functional inequalities via transport flow}\label{sec:transport-flow}
We now prove \Cref{thm:HS-route-via-congestion} and \Cref{thm:log-Sob-HS-route-via-congestion}, establishing the local Poincar\'e and local log-Sobolev inequalities, respectively, by constructing transport flows with short paths and low congestion.

First, we establish the \HSRV{}.
Under the assumptions of bounded expected squared length and expected congestion, the \HSRV{} follows from an application of the Cauchy-Schwarz inequality, which also played a crucial role in the classic canonical path analysis by Jerrum and Sinclair \cite{jerrum2003counting}. 
However, unlike the canonical path method, which relies on the worst-case congestion and path length across all state pairs, our approach derives local functional inequalities based on the average congestion and path length between coupled pairs. 
This refinement allows for a significant improvement in the (local) Poincar\'e constant.

%With the bounded expected length and bounded expected congestion assumption, the \HSRV{} is established via a Cauchy-Schwarz inequality, which is similar to the canonical path method. However, compared to the canonical path method, the reliance on the expected length rather than maximum length of configuration path allows us to shave an factor of $n$ from the (local) Poincar\'e constant.

\begin{proof}[Proof of~\Cref{thm:HS-route-via-congestion}]
  Recall that $\mu$ is a distribution with support $\Omega \subseteq [q]^E$.
Let $f:\Omega \to \mathbb{R}$ be a function, let $X$ be drawn as $\*X \sim \mu$, and define $\*F = f(\*X)$.
  Fix an edge $e \in E$. Then, %variance $\Var{\E{\*F \mid \*X_e}}$ can be expressed as: 
\begin{align*}
  \Var{\E{\*F \mid \*X_e}}
  &= \sum_{a,b \in [q]: a < b} \mu_e(a)\mu_e(b) \tp{\E[]{\*F \mid \*X_e = a} - \E[]{\*F \mid \*X_e = b}}^2.
\end{align*}
We can restrict the summation to those $a,b \in \Omega(\mu_e)\subseteq [q]$, where $\Omega(\mu_e)$ is the support of $\mu_e$, since others contribute zero to the sum.
Recall that $\Gamma_{e}^{a\to b}$ is the transport flow from $\mu^{e \gets a}$ to $\mu^{e \gets b}$,
and let $\Omega(\Gamma_e^{a\to b})$ denote its support. 
Define $\textsf{CP}_e^{a\to b}(x, y)\triangleq \{\gamma \in \Omega(\Gamma_e^{a\to b}):(x \mapsto y) \in \gamma\}$.

For a random path $\gamma = (\gamma_0, \gamma_1, \cdots, \gamma_{\ell(\gamma)}) \sim \Gamma_e^{a\to b}$, 
we have $\gamma_0\sim\mu^{e \gets a}$ and  $\gamma_{\ell(\gamma)}\sim\mu^{e \gets b}$.
%
Fixing $a, b \in \Omega(\mu_e)$ with $a < b$, by the linearity of expectation, we have
\begin{align*}
  \E[]{\*F \mid \*X_e = a} - \E[]{\*F \mid \*X_e = b}
  =&\E[\gamma \sim \Gamma_e^{a\to b}]{f(s(\gamma)) - f(t(\gamma))}
  =\E[\gamma \sim \Gamma_e^{a\to b}]{\sum_{0 \leq i < \ell(\gamma)} f(\gamma_{i}) - f(\gamma_{i+1})}\\
  =&\sum_{x,y \in \Omega:Q(x,y)>0}\sum_{\gamma \in \textsf{CP}_e^{a\to b}(x, y)}\Gamma_e^{a\to b}(\gamma)(f(x) - f(y))
%  =&\sum_{x,y \in \Omega:Q(x,y)>0}\sum_{\gamma \in \textsf{CP}_e^{a\to b}(x, y)}\sqrt{\Gamma_e^{a\to b}(\gamma) \cdot \ell(\gamma)} \cdot \sqrt{\frac{\Gamma_e^{a\to b}(\gamma)}{\ell(\gamma)}}(f(x)-f(y))
\end{align*}
Applying the Cauchy-Schwarz inequality gives
\begin{align*}
  &\tp{\E[]{\*F \mid \*X_e = a} - \E[]{\*F \mid \*X_e = b}}^2\\
  \le\,&\tp{\sum_{x,y \in \Omega:Q(x,y)>0}\sum_{\gamma \in \textsf{CP}_e^{a\to b}(x, y)}\Gamma_e^{a\to b}(\gamma) \cdot \ell(\gamma)} \cdot \tp{\sum_{x,y \in \Omega:Q(x,y)>0}\sum_{\gamma \in \textsf{CP}_e^{a\to b}(x, y)}\frac{\Gamma_e^{a\to b}(\gamma)}{\ell(\gamma)}(f(x)-f(y))^2}\\
  =\,&\E[\gamma \sim \Gamma_e^{a\to b}]{\ell(\gamma)^2} \cdot \tp{\sum_{x,y \in \Omega:Q(x,y)>0}\E[\gamma \sim \Gamma_e^{a\to b}]{\frac{\*1[(x \mapsto y) \in \gamma]}{\ell(\gamma)}}(f(x)-f(y))^2}.
\end{align*}
By the assumption of bounded expected squared path length, we have 
$\E[\gamma \sim \Gamma_e^{a\to b}]{\ell(\gamma)^2} \le L$. 
%
Summing over all $a, b \in \Omega(\mu_e)$ with $a < b$ and over all $e\in E$ gives
\begin{align*}
  &\sum_{e \in E}\Var{\E{\*F \mid \*X_e}}\\
  \le\,&L\cdot\sum_{x,y \in \Omega:Q(x,y)>0}(f(x)-f(y))^2 \sum_{a,b \in [q]:a<b} \sum_{e \in E: a,b \in \Omega(\mu_e)} \mu_e(a)\mu_e(b) \cdot \E[\gamma \sim \Gamma_e^{a\to b}]{\frac{\*1[(x \mapsto y) \in \gamma]}{\ell(\gamma)}}
\end{align*}
By the assumption of bounded congestion, we have
\begin{align*}
  \sum_{e \in E}\Var{\E{\*F \mid \*X_e}} \leq q^2 \kappa L \cdot \sum_{x,y \in \Omega:Q(x,y)>0} \mu(x) Q(x,y) (f(x)-f(y))^2 = 2 q^2 \kappa L \cdot \+E_Q(f,f).
\end{align*}
This establishes the local Poincar\'e inequality.
\end{proof}

