\newcommand{\ptplus}{{\partial}\mspace{-3mu}}

Let $G=(V,E)$ be a simple, undirected graph with $n$ vertices, $m$ edges, and maximum degree $\Delta$.
Consider the monomer-dimer distribution $\mu$   on $G$ with edge weight $\lambda$, and define $\overline{\lambda} = \max\set{1,\lambda}$.
For each edge $e\in E$, let $\+C_e$ denote the local flipping coupling  of $\mu^{e \gets 0}$ and $\mu^{e \gets 1}$ in \Cref{def:new-coupling-2}; 
and let $\Gamma_e$ denote the transport flow from $\mu^{e \gets 0}$ to $\mu^{e \gets 1}$ in~\Cref{def:monomer-dimer-trans-path}. 

For any pair of configurations $x,y\in\Omega(\mu)$, where $\Omega(\cdot)$ denotes the support of a distribution, let $\gamma^{x,y}$ be the Jerrum-Sinclair canonical path from $x$ to $y$, as specified in \Cref{def:monomer-dimer-trans-path}. 
Then, for a random pair $(X,Y)\sim\+C_e$ generated according to the local flipping coupling $\+C_e$, the canonical path $\gamma^{X,Y}$ from $X$ to $Y$ follows the distribution of the transport flow $\Gamma_e$.

Additionally, we introduce some notation.
For any subset $S \subseteq E$  of edges,
we define the \emph{inclusive boundary} $\ol{\partial}S$ and the \emph{boundary} $\partial S$  as follows:
\begin{align*}
  \ol{\partial} S \triangleq \set{e \in E \mid \exists f \in S, e \cap f \neq \emptyset } \quad \text{and} \quad \partial S \triangleq \ol{\partial} S \setminus S.
\end{align*}
For any configurations $x,y\in\{0,1\}^E$, we denote by $x\oplus y$  the set of edges where $x$ and $y$ differ:
\[
x\oplus y\triangleq \{f\in E\mid x_f\neq y_f\}.
\]
As discussed in \Cref{sec:app-JS-chain}, we interpret each configuration $x\in\{0,1\}^E$ equivalently as the set of edges it indicates, i.e., $\{e\in E\mid x(e)=1\}$.
Thus, set operations, including union~($\cup$), intersection~($\cap$), set difference~($\setminus$), symmetric difference~($\triangle$), and cardinality~($|\cdot|$), can be applied to configurations in $\{0,1\}^E$ without ambiguity.

\subsection{Validity of the local flipping coupling}\label{sec:local-flipping-coupling}
The well-definedness of the transport flow follows from the fact that the local flipping coupling, as defined in \Cref{def:new-coupling-2}, provides a valid coupling of $\mu^{e \gets 0}$ and $\mu^{e \gets 1}$.


%Define the boundary of $B$ as 
%\begin{align*}
%  \partial B = \{e \in E \mid e \notin B \land  \exists f \in B, e \cap f \neq \emptyset \},
%\end{align*}
%and the inclusive boundary of $B$ as 
%\begin{align*}
%  \overline{\partial} B = B \cup \partial B.
%\end{align*}

\begin{proposition}\label{lem:explicit-formula}
  Fix an edge $e\in E$. The local flipping coupling $\+C_e$ defined in \Cref{def:new-coupling-2} is a valid coupling of $\mu^{e \gets 0}$ and $\mu^{e \gets 1}$. Furthermore, for $x,y \in \Omega(\mu)$, let $B=x\oplus y$ be the set of disagreement edges. 
  %Recall $\Omega(\mu)$ is the supporting set.
  \begin{enumerate}
        \item\label{case:path-cycle} If $B$ forms a path or a cycle of even length and $x_e=0,y_e=1$, the probability of $(x,y)$ in $\+C_e$ is 
        \begin{align}\label{eq:explicit-formula}
            \Pr[(X,Y) \sim \+C_e]{(X,Y) = (x,y)} = \mu_{{\overline{\partial}} B}^{e \gets 0}(x_{{\overline{\partial}} B}) \cdot\mu^{e \gets 1}(y).
            % = \mu_{{\overline{\partial}} B}^{e \gets 0}(x_{{\overline{\partial}} B}) \mu_{{\overline{\partial}} B}^{e \gets 1}(y_{{\overline{\partial}} B})\mu^{{\*0}_{{\overline{\partial}} B}}_{E \setminus {\overline{\partial}} B}(y_{E \setminus {\overline{\partial}} B}).
        \end{align}
        %where ${\overline{\partial}} B =\set{e \in E \mid \exists f \in B, e \cap f \neq \emptyset}$ denotes the inclusive boundary of $B$.
        % , and $\ptplus B ={\overline{\partial}} B\setminus B$ denotes the exclusive boundary of $B$.
        \item Otherwise, $\Pr[(X,Y) \sim \+C_e]{(X,Y) = (x,y)} = 0$.
    \end{enumerate}
\end{proposition}
\begin{proof}
  We first verify \eqref{eq:explicit-formula} for Case~1, noting that Case 2 is obvious.
  Let $X,Y,Z$  be the random configurations  generated in \Cref{def:new-coupling-2} and let $\boldsymbol{B}=X\oplus Y$.
  It holds that $X_f=Z_f \neq Y_f$ for any $f \in \boldsymbol{B}$, and $X_f = Y_f = Z_f = 0$ for any $f \in \partial \boldsymbol{B}$.
  Then, for any $x \in \Omega(\mu^{e \gets 0})$ and $y \in \Omega(\mu^{e \gets 1})$, the event $(X,Y)=(x,y)$ is equivalent to that $Y = y$ and $Z_{{\overline{\partial}} B} = x_{{\overline{\partial}} B}$, where $B=x\oplus y$. Therefore,
  \begin{align*}
      \Pr[(X,Y) \sim \+C_e]{(X,Y) = (x,y)} = \Pr[Z \sim \mu^{e \gets 0}]{Z_{{\overline{\partial}} B} = x_{{\overline{\partial}} B}} \cdot \Pr[Y \sim \mu^{e \gets 1}]{Y=y}  = \mu^{e \gets 0}_{{\overline{\partial}} B}(x_{{\overline{\partial}} B}) \cdot\mu^{e \gets 1}(y).
  \end{align*}
  Consider a sample $(X,Y) \sim \+C_e$ from the coupling $\+C_e$. The marginal distribution of $Y$ is clearly $\mu^{e \gets 1}$. To find the marginal distribution of $X$, we note 
  \begin{align*}
      \mu^{e \gets 0}_{{\overline{\partial}} B}(x_{{\overline{\partial}} B}) \cdot\mu^{e \gets 1}(y) &= \mu^{e \gets 0}_{{\overline{\partial}} B}(x_{{\overline{\partial}} B}) \cdot\mu^{e \gets 1}_{{\overline{\partial}} B}(y_{{\overline{\partial}} B}) \cdot\mu^{y_{{\overline{\partial}} B}}_{E \setminus {\overline{\partial}} B}(y_{E \setminus {\overline{\partial}} B})\\
      &\overset{(\star)}{=} \mu^{e \gets 0}_{{\overline{\partial}} B}(x_{{\overline{\partial}} B}) \cdot \mu^{e \gets 1}_{{\overline{\partial}} B}(y_{{\overline{\partial}} B}) \cdot \mu^{x_{{\overline{\partial}} B}}_{E \setminus {\overline{\partial}} B}(x_{E \setminus {\overline{\partial}} B}) = \mu^{e \gets 0}(x) \cdot \mu^{e \gets 1}_{{\overline{\partial}} B}(y_{{\overline{\partial}} B}),
  \end{align*}
  where the equality $(\star)$ follows from the conditional independence property of $\mu$, as $x_{\ptplus B} = y_{\ptplus B} = \*0_{\ptplus B}$ and $x_{E \setminus \ol{\partial} B} = y_{E \setminus \ol{\partial} B}$. 
  Therefore, we can consider a symmetric process $\+C_e'$ for generating $(X,Y)$, which first samples $X \sim \mu^{e \gets 0}$ and $Z \sim \mu^{e \gets 1}$,  identifies the path or cycle $B\subseteq X\oplus Z$ containing $e$, and sets $Y = Z_B \uplus X_{E \setminus B}$. The above calculation shows that $\+C_e'$ is identically distributed as $\+C_e$. Finally, it is easy to verify from the construction of $\+C_e'$ that $X$ follows the law of $\mu^{e \gets 0}$, as required.
\end{proof}
Note that \eqref{eq:explicit-formula} can be re-expressed as: 
$$\mu_e(0)\cdot\mu_e(1)\cdot\Pr[(X,Y) \sim \+C_e]{(X,Y) = (x,y)} = \mu_{{\overline{\partial}} B}(x_{{\overline{\partial}} B})\cdot \mu(y).$$ 
Observe that the quantity $\mu_{{\overline{\partial}} B}(x_{{\overline{\partial}} B})\cdot \mu(y)$ on the right-hand-side is independent of the fixed edge~$e$. This symmetry plays a vital role in the decoupling process (see~\Cref{lem:pre-decoupling}), which will be used later in the congestion analysis of the transport flow.

