%  (h\text{ is injective and~\Cref{eq:prob-cycle-path}})\quad \leq\,& \sum_{\text{path D}: D\ni e} \lambda \Pr{B = D}\E{\tp{\abs{P_u}+2}^2\cdot \*1[\abs{P_u}+2 \geq k\land P_v=\emptyset]\mid B = D}\\
  \le\,& \lambda \E{\*1[B \text{ is a path}] \cdot (\abs{P_u}+2)^2 \cdot \*1[P_v = \emptyset] \cdot \*1[\abs{P_u} + 2 \geq k]} \\ %\label{eq:Epath} \\
  \leq\,& \lambda \E{(\abs{P_u}+2)^2 \cdot \*1[\abs{P_u} + 2 \geq k] \mid B\text{ is a path} \wedge P_v = \emptyset} \\
  (\text{by \Cref{lem:path-length-geo-bound}})\quad 
  \leq\,& \lambda \E{(2L+2)^2\cdot \*1[2L+2\ge k]}\\
  % \leq\,& \lambda \sum_{t=k}^\infty q(1-q)^{t+2} \cdot t^2 
  \leq\,& O(\lambda \exp(-\theta/2) q^{-2} (\theta^2+1)).
\end{align*}
%For the first inequality, if $B$ is a path, then $P_u$ and $P_v$ are well-defined; otherwise, both sides equal~0.
