\subsubsection{Geometric decay of the discrepancy path}
In the following, we provide a proof of~\Cref{lem:path-length-geo-bound}.

\begin{proof}[Proof of~\Cref{lem:path-length-geo-bound}]
   Recall that we use ${\overline{\partial}} P_v$ to denote the inclusive boundary of the path $P_v$, which includes all edges incident to the path, as well as the edges that make up the path itself. 
   In the case where $P_v = \emptyset$,  we abuse notation and define ${\overline{\partial}} P_v = \{f \in E \mid v \in f\}$.
    Conditioned on $P_v$, the configurations $(X,Y)$ on the inclusive boundary ${\overline{\partial}} P_v$ are uniquely determined, and we have $X_{\partial P_v \setminus \{e\}} = Y_{\partial P_v \setminus \{e\}} = \*0_{\partial P_v \setminus \{e\}}$.  
    Therefore, for any $(x,y)\in\Omega(\+C_e)$ whose difference set  $B=x\oplus y$ forms  a path containing $P_v$, we have
    \begin{align*}
        &\Pr[(X,Y) \sim \+C_e]{(X,Y) = (x,y) \mid {X\oplus Y\text{ is a path } \wedge} P_v} \\
        = &\frac{\Pr[(X,Y) \sim \+C_e]{(X,Y) = (x,y)}}{\Pr[(X,Y) \sim \+C_e]{{X\oplus Y\text{ is a path }\wedge}X\oplus Y\supseteq P_v\wedge X_{\partial P_v \setminus \{e\}} = Y_{\partial P_v \setminus \{e\}} = \*0_{\partial P_v \setminus \{e\}}}}\\
        {(\text{\small by \Cref{lem:explicit-formula}})\atop(\text{\small by \Cref{def:new-coupling-2}})}\quad =&\frac{\mu_{{\overline{\partial}} B}^{e \gets 0}(x_{{\overline{\partial}} B})\cdot \mu^{e \gets 1}_{ {\overline{\partial}} B}(y_{ {\overline{\partial}} B}) \cdot\mu^{x_{{\overline{\partial}} B}}_{E \setminus {\overline{\partial}} B}(x_{E \setminus{\overline{\partial}} B})}{\mu^{e \gets 0}_{ {\overline{\partial}} P_v}(x_{ {\overline{\partial}} P_v}) \cdot\mu^{e \gets 1}_{ {\overline{\partial}} P_v}(y_{{\overline{\partial}} P_v})}\\
   \text{(by $P_v \subseteq B$)}\quad     =& \mu^{x_{{\overline{\partial}} P_v}}_{{\overline{\partial}} B}(x_{ {\overline{\partial}} B}) \cdot\mu^{y_{ {\overline{\partial}} P_v}}_{ {\overline{\partial}} B}(y_{{\overline{\partial}} B}) \cdot\mu^{x_{ {\overline{\partial}} B}}_{E \setminus  {\overline{\partial}} B}(x_{E \setminus {\overline{\partial}} B})\\
   \text{(by $e \in {\overline{\partial}} P_v$)}\quad     =&\mu^{\*0_{\partial P_v \setminus \{e\}} \wedge (e \gets 0)}_{ {\overline{\partial}} B \setminus \ol{\partial} P_v }(x_{{\overline{\partial}} B \setminus 
\ol{\partial} P_v }) \cdot\mu^{\*0_{\partial P_v \setminus \{e\}} \wedge (e \gets 1)}_{ {\overline{\partial}B \setminus \ol{\partial} P_v } }(y_{{\overline{\partial}} B \setminus \ol{\partial} P_v }) \cdot\mu^{x_{{\overline{\partial}} B}}_{E \setminus {\overline{\partial}} B}(x_{E \setminus {\overline{\partial}} B}).
    \end{align*}
%    
 Therefore,  conditioning on  $P_v$ is equivalent to considering the monomer-dimer distribution on a subgraph of $G$  obtained by removing all edges in ${\overline{\partial}} P_v \setminus \{e\}$.
    Formally, the distribution of $(X,Y) \sim \+C_e$ conditioned on $P_v$ and projected onto $E \setminus ({\overline{\partial}} P_v \setminus \{e\})$  follows the law of the local flipping coupling $\widetilde{\+C_e}$ of the distributions  $\widetilde{\mu}^{e \gets 0}$ and $\widetilde{\mu}^{e \gets 1}$, where $\widetilde{\mu}$ is the monomer-dimer distribution on the graph $\widetilde{G} \triangleq G\setminus ({\overline{\partial}} P_v \setminus \{e\})$. 
    Let $\widetilde{X} \sim \widetilde{\mu}^{e \gets 0}$ and $\widetilde{Y} \sim \widetilde{\mu}^{e \gets 1}$ be independent samples,
    %Let $(\widetilde{X},\widetilde{Y})\sim\widetilde{\+C_e}$, 
    and define $\widetilde{B}=\widetilde{X}\oplus\widetilde{Y}$ as the set of edges where $\widetilde{X}$ and $\widetilde{Y}$ disagree.
%   
    The following process traverses $\widetilde{B}$ by revealing the disagreement edges between $\widetilde{X}$ and $\widetilde{Y}$ one
     by one:
    \begin{enumerate}
    \item \emph{Initialization}:  Sample $\widetilde{X} \sim \widetilde{\mu}^{e \gets 0}$ and $\widetilde{Y} \sim \widetilde{\mu}^{e \gets 1}$ independently. Initialize $w^\star \gets u$, where $u$  is the   vertex (other than $v$) incident to the edge $e$.
    Initially, only the disagreement of $\widetilde{X}$ and $\widetilde{Y}$ at the edge $e$ are revealed.
    \item \emph{Self-avoiding walk}: 
    Reveal the partial configurations of $X$ and $Y$ on edges incident to $w^\star$. If a new disagreement $\{w^\star,w\} \in E$ between $\widetilde{X}$ and $\widetilde{Y}$ is encountered, update $w^\star \gets w$ (note that there can be at most one new disagreement). If no new disagreement is found, the process terminates.  The path of disagreements, $\widetilde{B}$, is given precisely by the trail of the vertex $w^\star$.
    \end{enumerate}

    Note that $e$ is a hanging edge in the new graph $\widetilde{G}$.
    Thus, intuitively, the above process should be exactly the same as the coupling used to construct the ``path tree'' (i.e., Godsil's self-avoiding walk tree for the monomer-dimer model, see~\cite{godsil1993algebratic,bayati2007simple}) rooted at $v$ on $\widetilde{G}$.

    We claim that at any point in the process,  it terminates within the next two steps with probability $q = \Omega(1/\sqrt{1+\lambda\Delta})$.
    Specifically, conditioned on any $w^\star$, with probability $q$, the process either terminates at the current $w^\star$, or $w^\star$ moves to a new neighbor $w$ and then terminates.
    This is consistent with the well-known decay of correlation  property for the monomer-dimer distributions in~\cite{bayati2007simple}. 
    For completeness, we include a proof of this result in our setting.
%    This is already hinted by the previous correlation decay analysis in~\cite{bayati2007simple}, we include a proof in our setting for the reader's convenience.

    Suppose $w^\star$ is the current disagreement vertex, and let $e'$ be the last revealed disagreement edge incident to $w^\star$. 
    Without loss of generality, assume $\widetilde{X}_{e'} = 1$ and $\widetilde{Y}_{e'} = 0$; the other case follows by symmetry. 
    By self-reducibility, remove all edges (including $e'$) revealed during the process and consider the monomer-dimer model on the remaining subgraph $G'$. 
    Let $N(w^\star)$ denote the set of neighbors of $w^\star$ in $G'$, and let $\mu'$ be the monomer-dimer distribution on $G'$.
    If the process does not terminate within next two steps, there must exist a neighbor $w \in N(w^\star)$ such that:
    \begin{enumerate}
        \item In the first step, $\widetilde{Y}_{\{w^\star, w\}} = 1$, which occurs with probability $\mu'(\{w,w^\star\} \text{ is occupied})$;
        \item In the next step, $w$ becomes saturated in $\widetilde{X}$, which occurs with probability 
        $$\mu'(\text{$w$ is saturated} \mid \text{$w^\star$ is not saturated}),$$ 
        since given $\widetilde{X}_e = 1$, no other edge in $\widetilde{X}$ is incident to $w^\star$, i.e., $w^\star$ is not saturated by $\widetilde{X}$ in $G'$;
    \end{enumerate}
    where the above probabilities are calculated by the \emph{principle of deferred decisions}.

    Let $\+B$ denote the event that the process does not terminate within the next two steps starting from $w^\star$.
    Since $\widetilde{X}$ and $\widetilde{Y}$ are independent, we have 
    \begin{align*}%\label{eq:two-step-contraction}
      \Pr{\+B} = 
        \sum_{w \in N(w^\star)} \mu'(\text{$\{w,w^\star\}$ is occupied}) \cdot \mu'(\text{$w$ is saturated} \mid \text{$w^\star$ is not saturated}).% \le 1-\frac{1}{1+\sqrt{1+\lambda \Delta}}.
    \end{align*}
    %To see why the above inequality is sufficient, suppose $w^\star$ is incident to an edge $e'$ such that $\widetilde{X}_{e'} = 1$ and $\widetilde{Y}_{e'} = 0$, where $e'$ is the disagreement edge generated by the previous step. 
    Define $p_w \triangleq \mu'(\text{$w$ is not saturated} \mid \text{$w^\star$ is not saturated})$. 
    The probability of the edge $\{w,w^\star\}$ being occupied in $\mu'$ is given by
    \begin{align*}
    \mu'(\text{$\{w,w^\star\}$ is occupied}) =\lambda\cdot\mu'(w \text{ and } w^\star \text{ are not saturated})= \frac{\lambda p_w}{1+\lambda \sum_{w' \in N(w^\star)} p_{w'}}.
    \end{align*}
    To verify this equation, we multiply both the numerator and denominator by the probability that $w^\star$ is not saturated and observe: 
    (1)~the event that $w^\star$ is saturated is equivalent to the event that no edge $\{w,w^\star\}$ is occupied;
    and (2)~in any monomer-dimer distribution, it always holds
    $\Pr[]{\{w,w^\star\} \text{ is occupied}}=\lambda\cdot  \Pr[]{w \text{ and } w^\star \text{ are not saturated}}$.

    Define $S \triangleq \sum_{w \in N(w^\star)} p_w$. The (two-step) non-termination probability  $\Pr{\+B}$ satisfies
    \begin{align*}
        \Pr{\+B} = \frac{\sum_{w \in N(w^\star)} \lambda p_w (1-p_w)}{1+\lambda \sum_{w \in N(w^\star)} p_w} =  \frac{\lambda S - \lambda \sum_{w \in N(w^\star)} p_w^2}{1+\lambda S} \leq \frac{\lambda (S-S^2/\Delta)}{1+\lambda S},
    \end{align*}
    where the last inequality follows the Cauchy-Schwarz. Setting $T = S/\Delta$, we have
    \begin{align*}
        \Pr{\+B} \le \max_{T \in [0,1]} \frac{\lambda \Delta \cdot (T-T^2)}{1+\lambda \Delta \cdot T} \le 1-\frac{2}{1+\sqrt{1+\lambda \Delta}}.
    \end{align*}
    Thus, the discrepancy $|\widetilde{B}|$ is stochastically dominated by $2L$, where $L\sim\-{Geo}(q)$ for $q = \frac{2}{1+\sqrt{1+\lambda \Delta}}$. 

    To construct a coupling between $L$ and $(X,Y)\sim \+C_e$, we perform a Bernoulli trial with success probability $q$ every two steps and terminate the revealing process when the trial succeeds.
\end{proof}








