\subsection{Bounded congestion of the transport flow} \label{sec:expect-conges}
%\leavevmode\par
%\todo{$\Omega_\mu\to \Omega(\mu)$}

Next, we analyze the congestion of the transport flow defined in~\Cref{def:monomer-dimer-trans-path} using an approach based on \DCP{} and measure-preserved flow encoding, proving \Cref{thm:effective-trans-flow}(\ref{thm:trans-flow-congestion})-(\ref{thm:trans-flow-strong-congestion}).
%Specifically, in \Cref{sec:expected-congestion}, we bound the expected congestion, thereby proving \Cref{thm:effective-trans-flow}(\ref{thm:trans-flow-congestion}); 
%and in \Cref{sec:expected-strong-cong}, we bound the expected strong congestion, thereby proving \Cref{thm:effective-trans-flow}(\ref{thm:trans-flow-strong-congestion}).


%\subsubsection{Expected congestion bound}\label{sec:expected-congestion}
%Consider a monomer-dimer distribution $\mu$
Let $Q$ denote the Jerrum-Sinclair chain for the monomer-dimer distribution $\mu$.
For any pair of configurations $X,Y\in\Omega(\mu)$ such that their difference $X\oplus Y\triangleq \{f\in E\mid X_f\neq Y_f\}$ forms a path or a cycle, let $\gamma^{X,Y}$ denote the unique canonical path from $X$ to $Y$ constructed according to \Cref{def:monomer-dimer-trans-path}.
It is obvious that if $(X,Y)\sim\+C_e$ is sampled from the local flipping coupling $\+C_e$, then $\gamma^{X,Y}\sim\Gamma_e$, following the law of the transport flow $\Gamma_e$ from $\mu^{e \gets 0}$ to $\mu^{e \gets 1}$.

% We can write $\gamma^{X,Y}$ with $(X,Y)\sim \+C_e$ to denote a random path from $X$ to $Y$ from $\Gamma_e$, where $\+C_e$ is the local flipping coupling defined in~\Cref{def:new-coupling-2}. 
%We use $\Omega(\mu)$ to denote the support of $\mu$. %and $\Omega(\+C_e)$ to denote the support of $\+C_e$.

%Define $\ol{\lambda}\triangleq\max\{1,\lambda\}$. 
%\Cref{thm:effective-trans-flow}(\ref{thm:trans-flow-congestion}) is implied by the following expected congestion bound.
\begin{lemma} \label{lem:expected-congestion}
%  Let $\mu$ be the distribution of  monomer-dimer model on graph $G=(V, E)$ with edge weight $\lambda$. 
%Define $\ol{\lambda}\triangleq \max\{1,\lambda\}$.
The transport flow $(\Gamma_e)_{e \in E}$ defined in~\Cref{def:monomer-dimer-trans-path} satisfies the following:
\begin{enumerate}
    \item \emph{($O(\ol{\lambda}^{2}m)$-expected congestion)} For any transition $(\alpha \mapsto \beta)$ with $Q(\alpha, \beta) > 0$, 
  \begin{align*}
    \sum_{e\in E} \mu_e(0)\mu_e(1)\E[(X,Y)\sim \+C_e]{\frac{\*1[(\alpha \mapsto \beta) \in \gamma^{X,Y}]}{\ell(\gamma^{X,Y})}} 
    &\leq O(\ol{\lambda}^{2} m) \cdot \mu(\alpha)Q(\alpha, \beta);
  \end{align*}
    \item \emph{(strong $O(\ol{\lambda}^{4}\Delta^2 m)$-expected congestion)} For any transition $(\alpha \mapsto \beta)$ with $Q(\alpha, \beta) > 0$, 
  \begin{align*}
	\sum_{e\in E} \mu_e(0)\mu_e(1)\E[(X,Y)\sim \+C_e]{\ell(\gamma^{X,Y})\cdot \*1[(\alpha \mapsto \beta) \in \gamma^{X,Y}]} 
    &\leq O(\ol{\lambda}^{4}\Delta^2 m) \cdot \mu(\alpha)Q(\alpha, \beta).    
  \end{align*}
\end{enumerate}
\end{lemma}

Although the definitions of congestion involve the local flipping couplings $\+C_e$ for all edges $e \in E$, 
it suffices to analyze the coupling $\+C_f$ for a single $f\in E$ using the following \emph{decoupling lemma}.

\begin{lemma}[decoupling lemma]\label{lem:pre-decoupling}
The local flipping coupling $(\+C_e)_{e\in E}$ defined in \Cref{def:new-coupling-2} satisfies the following property.
  Let $\phi:\Omega(\mu) \times \Omega(\mu)\to \mathbb{R}$ be a function. For any edge $f \in E$, it holds
  \begin{align}\label{lem:new-pre-decoupling-equ1}
    \sum_{e\in E}\mu_e(0) \mu_e(1) &\E[(X,Y)\sim \+C_e]{\phi(X,Y) \cdot \*1[X_f \neq Y_f]}\notag\\
    &\le
    \mu_f(0)\mu_f(1) \E[(X,Y)\sim \+C_f]{\tp{\phi(X,Y) +\phi(Y,X)}\cdot |{X \oplus Y}|}.
  \end{align}
%  where $X \oplus Y\triangleq \{f\in E\mid X_f\neq Y_f\}$ represents the set of edges on which $X$ and $Y$ disagree.  
\end{lemma}








%We have the following expected congestion bound via \emph{decoupling} lemma:





