The bounds on expected congestion and strong expected congestion in \eqref{eq:cong-decoupling} and \eqref{eq:cong-decoupling-strong} motivate us to establish the following lemma.
%Though in this section it suffices to analyze the probability that the transition $(\alpha \mapsto \beta)$ appears in $\gamma^{\set{X,Y}}$, we takes the $p$-th power of discrepancies into consideration, which will be helpful for proving local log-Sobolev inequalities.
\begin{lemma} \label{lem:powered-cong}
    Fix any constant $p \ge 0$. For any transition $(\alpha \mapsto \beta)$ and any edge $h\in E$ such that $\alpha_h \neq \beta_h$, 
    \begin{align}\label{eq:powered-cong}
        \mu_h(0) \mu_h(1) \E[(X,Y) \sim \+C_h]{|{X \oplus Y}|^p \cdot \*1[(\alpha \mapsto \beta) \in \gamma^{\set{X,Y}}]} \le O_p(\ol{\lambda}^{p+2} \Delta^p m) \cdot \mu(\alpha) Q(\alpha,\beta),
    \end{align}
    where $\gamma^{\set{X,Y}}\triangleq \gamma^{X,Y}\cup \gamma^{Y,X}$ denotes the set of transitions appearing in either $\gamma^{X,Y}$ or $\gamma^{Y,X}$. %and the big-O notation hides a constant depending on $p$.
\end{lemma}

With this general congestion bound, the expected congestion bound in \Cref{lem:expected-congestion} follows from \eqref{eq:cong-decoupling} and \Cref{lem:powered-cong} with $p=0$, while the strong expected congestion bound in \Cref{lem:expected-congestion} follows from \eqref{eq:cong-decoupling-strong} and \Cref{lem:powered-cong} with $p=2$.


\subsubsection{Measure-preserving flow encoding}
To complete the proof, it remains to prove \Cref{lem:pre-decoupling,lem:powered-cong}. 
We begin with \Cref{lem:powered-cong}, where we derive the general congestion bound \eqref{eq:powered-cong} by constructing a measure-preserving flow encoding.

\begin{proof}[Proof of~\Cref{lem:powered-cong}]
Fix a transition $(\alpha \mapsto \beta)$
of the Jerrum-Sinclair chain $Q$. By definition, $\alpha$ and $\beta$ differ on exactly one or two edges. We analyze each case separately.

\paragraph{Case 1: single disagreement.}
When $\abs{\alpha \oplus \beta}=1$, there is a unique edge $h$ where $\alpha_h \neq \beta_h$. 
We consider the up-transition case where $\alpha_h=0$ and $\beta_h=1$, while the down-transition case follows by symmetry. 
By the construction of the canonical path $\gamma^{x,y}$, the transition $\alpha \mapsto \beta$ can only occur in the final step of $\gamma^{x,y}$, meaning $y = \beta$. 
Moreover, since each discrepancy edge $f\in x\oplus y$ is flipped exactly once along $\gamma^{x,y}$, the transition $(\alpha \mapsto \beta) \in \gamma^{x,y}$ implies $x_h = 0$ and $y_h = 1$. 
Consequently, 
\begin{align}\label{eq:single-edge-1}
  \nonumber
  \E[(X,Y) \sim \+C_h]{\abs{X \oplus Y}^p \cdot \*1[(\alpha \mapsto \beta) \in \gamma^{\set{X,Y}}]}
  &= \E[(X,Y) \sim \+C_h]{\abs{X \oplus Y}^p \cdot \*1[(\alpha \mapsto \beta) \in \gamma^{X,Y}]}\\
  &\leq \E[(X,Y) \sim \+C_h]{\abs{X \oplus Y}^p \cdot \*1[Y = \beta]}. 
\end{align}
Applying~\Cref{lem:one-sided-CI}, there exists a constant $c_p >0$ depending on $p\ge 0$ such that the $p$-th moment of the one-sided discrepancies satisfies
\begin{align}\label{eq:one-sided-discrepancy}
    \E[(X,Y) \sim \+C_h]{\abs{X \oplus Y}^p \mid Y = \beta} \le c_p \ol{\lambda}^p \Delta^p.
\end{align}
Combining~\eqref{eq:single-edge-1} and~\eqref{eq:one-sided-discrepancy}, we obtain
\begin{align} \label{eq:bound-for-expectation-aux-1}
  \E[(X,Y) \sim \+C_h]{\abs{X \oplus Y}^p \cdot \*1[(\alpha \mapsto \beta) \in \gamma^{\set{X,Y}}]}
  &\leq c_p \ol{\lambda}^p \Delta^p \Pr[(X,Y) \sim \+C_h]{Y = \beta}
  = c_p \ol{\lambda}^p \Delta^p \mu^{h\gets 1}(y).
\end{align}
To conclude this case, we note that
\begin{align*}
  \mu_h(0)\mu_h(1) \cdot{c_p \ol{\lambda}^p \Delta^p \mu^{h\gets 1}(y)}
    =c_p \ol{\lambda}^p \Delta^p \cdot \mu_h(0) \mu(\beta)
    \le c_p \ol{\lambda}^{p+1} \Delta^p m \cdot \mu(\alpha) Q(\alpha,\beta),
\end{align*}
where the last inequality follows from the facts that $Q(\alpha,\beta)=\frac{1}{m}\min\set{1,\frac{\mu(\beta)}{\mu(\alpha)}}$ and $\mu(\beta)\le \ol{\lambda}\cdot\mu(\alpha)$.
