\begin{itemize}
  \item If $B$ is a path, $w$ (the vertex shared by $h=f$ and $g$) divides $B$ into two subpaths $B^h$ and $B^g$, where $B^h$ (resp.~$B^g$) contains $h$ (resp.~$g$).
  \item If $B$ is an even-length cycle, let $w^*$ be the largest vertex in $B$. By the construction of the canonical path $\gamma^{x,y}$, we must have $w^* \neq w$ whenever $(\alpha \mapsto \beta) \in \gamma^{x,y}$. The cycle is then divided into two subpaths $B^h$ and $B^g$ by $w$ and $w^*$, with $B^h$ (resp.~$B^g$) containing $h$ (resp.~$g$).
\end{itemize}
From \Cref{def:monomer-dimer-trans-path}, we observe that during the transition $(\alpha\mapsto\beta)$ within the canonical path $\gamma^{x, y}$, the edges in $B^{h}$ are flipped, while those in $B^{g}$ (except for $g$) remain unchanged.
Formally, this is described by the following condition:
  \begin{align}\label{eq:aorb}
    \alpha \cup \beta = x \triangle {B^{h}} = y \triangle {B^{g}},
  \end{align}
  where we slightly abuse the notation by interpreting the configurations $\alpha,\beta,x,y\in\{0,1\}^E$ as subsets of edges $\alpha,\beta,x,y\subseteq E$,
  with the corresponding configurations as indicator vectors.
  Therefore, the union $\alpha\cup\beta$ produces the same set of edges as the symmetric differences $x\triangle {B^{h}} = y \triangle {B^{g}}$.

  Note that $\alpha \cup \beta$ is no longer a matching in $G$, as both $h$ and $g$ are in $\alpha \cup \beta$. 
  To resolve this issue, we introduces a new graph $\wh{G}=(\wh{V},\wh{E})$.
  The graph $\wh{G}=(\wh{V},\wh{E})$ is constructed from $G$ by first removing every edge incident to $w$ except for $g$ and $h$, and then merging the two edges $g$ and $h$ into a single edge $h^{\star}$. This induces a natural mapping $\textsf{proj}$ that maps a configuration $x \in \{0,1\}^E$ with $x_h = x_g$ to a new configuration $\hat{x} \in \{0,1\}^{\wh{E}}$ as follows:
	\begin{align*}
	\forall e \in \hat{E},\quad	\textsf{proj}(x)_e \triangleq  \begin{cases}
			x_e,& \text{if $e\ne h^{\star}$}, \\
			x_h=x_g,& \text{if $e=h^{\star}$}.
		\end{cases}
	\end{align*}
    It is obvious that if $x_h = x_g=1$ and $g,h$ are the only edges that violate the constraint of $x$ being a matching, then $\textsf{proj}(x)$ is a matching in $\wh{G}$. 
	Let $\wh{\mu}$ be the monomer-dimer distribution on $\wh{G}$ with the same edge weight $\lambda$. We use the analogous natation $\wh{\+{C}}_{h^{\star}}$ to denote the local flipping coupling (as defined in \Cref{def:new-coupling-2}) with respect to the monomer-dimer distribution $\wh{\mu}$ at the edge $h^\star$.
	%We denote the support of $\wh{\+{C}}_{h^{\star}}$ by $\Omega(\wh{\+{C}}_{h^{\star}})$. %while $\Omega(\+{C}_h)$ remains to be the support of $\+C_h$ w.r.t. $\mu$.

	For $(x,y)\in\Omega(\+{C}_h)$ such that $(\alpha \mapsto \beta) \in \gamma^{x,y}$, if the disagreement set  $B=x\oplus y$ forms a cycle, let $e$ be the unique edge in $B^{h}$ that is incident to $w^*$. We define a \emph{measure-preserved flow encoding} that maps from $\Omega(\+{C}_h)$ to $\Omega({\wh{\+{C}}_{h^{\star}}})$ as follows: %recall $B=B(x,y)$ is the disagreement between $x$ and $y$,
% \begin{align} \label{eq:def-enc}
%   \textsf{enc}(x,y) \triangleq  \begin{cases}
%   \tp{\textsf{proj}(x\oplus\*1_{B^{g}}), \textsf{proj}(x\oplus\*1_{B^{h}})},& \text{if $B$ is a path;} \\
%   \tp{\textsf{proj}(x\oplus\*1_{B^{g}}\oplus\*1_{e}), \textsf{proj}(x\oplus\*1_{B^{h}})},& \text{if $B$ is an even-length cycle,} 
%   \end{cases}
% \end{align}
\begin{align} \label{eq:def-enc}
  \textsf{enc}(x,y) \triangleq  \begin{cases}
  \tp{\textsf{proj}(x\triangle{B^{g}}), \textsf{proj}(x\triangle{B^{h}})},& \text{if $B$ is a path;} \\
  \tp{\textsf{proj}(x\triangle{B^{g}}\triangle{\{e\}}), \textsf{proj}(x\triangle{B^{h}})},& \text{if $B$ is an even-length cycle;} 
  \end{cases}
\end{align}
%where $\*1_e \in \{0,1\}^E$ denotes the indicator vector that takes value 1 only at edge $e$. 
which is equivalent to the following by~\eqref{eq:aorb}:
%$\textsf{enc}(x,y)= \tp{\textsf{proj}(y\triangle{B^{h}}), \textsf{proj}(y\triangle{B^{g}})}$ if $B$ is a path, and $\textsf{enc}(x,y)= \tp{\textsf{proj}(y\triangle{B^{h}}\triangle{\{e\}}), \textsf{proj}(y\triangle{B^{g}})}$.
\begin{align*}
  \textsf{enc}(x,y) \triangleq  \begin{cases}
  \tp{\textsf{proj}(y\triangle{B^{h}}), \textsf{proj}(y\triangle{B^{g}})},& \text{if $B$ is a path;} \\
  \tp{\textsf{proj}(y\triangle{B^{h}}\triangle{\{e\}}), \textsf{proj}(y\triangle{B^{g}})},& \text{if $B$ is an even-length cycle.} 
  \end{cases}
\end{align*}

The encoding defined here is inspired by the injective mapping introduced in the original canonical path method by Jerrum and Sinclair~\cite{jerrum1989approximating}.
Specifically, our encoding function maps every $(x,y)\in\Omega(\+{C}_h)$ with $(\alpha\mapsto\beta)\in\gamma^{x,y}$ injectively to an $(\wh{x},\wh{y})\in\Omega({\wh{\+{C}}_{h^{\star}}})$ with $\wh{y}=\textsf{proj}(\alpha \cup \beta)$, and approximately preserves the relevant measure between the two couplings $\+{C}_h$ and ${\wh{\+{C}}_{h^{\star}}}$, as its name suggests. 
This is formalized by the following lemma.
\begin{lemma}\label{lem:enc}
  The function $\textsf{enc}$ defined in \eqref{eq:def-enc} is an injection from $\{(x,y)\in\Omega(\+{C}_h)\mid(\alpha\mapsto\beta)\in\gamma^{x,y}\}$ to $\{(\wh{x},\wh{y})\in\Omega(\wh{\+{C}}_{h^{\star}})\mid\wh{y}=\textsf{proj}(\alpha\cup\beta)\}$. 
  Furthermore, for any $(x,y)\in\Omega(\+{C}_h)$ such that $(\alpha\mapsto\beta)\in\gamma^{x,y}$, 
  \begin{align*}
    \mu_h(0)\mu_h(1)\cdot\Pr[(X,Y)\sim\+{C}_h]{(X,Y) = (x,y)} \le \eta\cdot\wh{\mu}_{h^{\star}}(0)\wh{\mu}_{h^{\star}}(1)\cdot \Pr[(\wh{X},\wh{Y}) \sim\wh{\+C}_{h^{\star}}]{(\wh{X},\wh{Y}) = \mathsf{enc}(x,y)},
  \end{align*}
  where $\eta\triangleq \tp{\wh{Z}/Z}^2\cdot\ol{\lambda}^2$, and $Z$ (resp.~$\wh{Z}$) denotes the partition function of $\mu$ (resp.~$\wh{\mu}$).
  %We write $\+C_h{(x,y)}$ for $\Pr[(X,Y)\sim \+C_e]{(X,Y)=(x,y)}$ in short and $\hat{\+C}_{h^\star}$ is similar.
\end{lemma}

As a direct corollary of \Cref{lem:enc}, we can rewrite the expectation on the left-hand side of \eqref{eq:powered-cong} in the new probability space of $\wh{\+C}_{h^\star}$, replacing the indicator for the non-trivial event $(\alpha\mapsto \beta) \in \gamma^{\set{X,Y}}$ with the indicator for the simpler event  $\wh{Y} = \textsf{proj}(\alpha \cup \beta)$.
We formalize this as follows:
\begin{corollary} \label{cor:enc}
  Let $\eta$ be the factor defined in \Cref{lem:enc}. Then, it holds that
  \begin{align*} 
    \mu_h(0)\mu_h(1)&\cdot\E[(X,Y)\sim {\+C}_h]{\abs{X\oplus Y}^{p} \cdot \*{1}[(\alpha\mapsto\beta)\in\gamma^{\set{X,Y}}]} \\
    &\leq \eta \cdot \wh{\mu}_{h^{\star}}(0)\wh{\mu}_{h^{\star}}(1) \E[(\wh{X},\wh{Y})\sim\wh{\+{C}}_{h^{\star}}]{\tp{\abs{\wh{X}\oplus\wh{Y}} + 2}^{p} \cdot \*{1}[\wh{Y}=\mathsf{proj}(\alpha\cup\beta)]}.
  \end{align*}
\end{corollary}
The proof of \Cref{cor:enc} is a straightforward calculation, which we will provide later. Now, assuming \Cref{cor:enc}, we can complete the proof of \Cref{lem:powered-cong} using the same argument as before.
