\begin{proof}[Proof of \Cref{cor:enc} assuming~\Cref{lem:enc}]
Assuming \Cref{lem:enc}, we now prove \Cref{cor:enc} using the bound on the $p$-th moment of the one-sided discrepancy (\Cref{lem:one-sided-CI}). Since $(\alpha \mapsto \beta) \in \gamma^{x,y}$ implies that $x_h = 0$ and $y_h = 1$  (as each disagreeing edge between $x$ and $y$ is flipped exactly once), it follows that
\begin{align*}
  \mu_h(0)\mu_h(1)&\cdot\E[(X,Y)\sim {\+C}_h]{\abs{X\oplus Y}^{p} \cdot \*{1}[(\alpha\mapsto\beta)\in\gamma^{\set{X,Y}}]} \\
    &= \mu_h(0)\mu_h(1)\cdot\E[(X,Y)\sim {\+C}_h]{\abs{X\oplus Y}^{p} \cdot \*{1}[(\alpha\mapsto\beta)\in\gamma^{X,Y}]}.
\end{align*}
By \Cref{lem:enc}, we have
\begin{align} \label{eq:congestion-1}
    \nonumber
    \mu_h(0) \mu_h(1) & \E[(X,Y)\sim {\+C}_h]{\abs{X\oplus Y}^{p} \cdot \*{1}[(\alpha\mapsto\beta)\in\gamma^{X,Y}]} \\
    \nonumber &= \sum_{(x,y)\in\Omega(\+{C}_h) \atop (\alpha\mapsto\beta)\in\gamma^{x,y}} \abs{x\oplus y}^{p}\cdot \mu_h(0) \mu_h(1) \cdot\Pr[(X,Y) \sim \+{C}_h]{(X,Y) = (x,y)}\\
    &\le \eta\cdot\wh{\mu}_{h^{\star}}(0)\wh{\mu}_{h^{\star}}(1)\cdot \sum_{(x,y)\in\Omega(\+{C}_h) \atop (\alpha\mapsto\beta)\in\gamma^{x,y}} \abs{x\oplus y}^{p}\cdot \Pr[(\wh{X},\wh{Y}) \sim \wh{\+C}_{h^{\star}}]{(\wh{X}, \wh{Y}) = \textsf{enc}(x,y)}.
\end{align}
Since $\textsf{enc}$ is an injection (by \Cref{lem:enc}),
 the summation over all configuration pairs $(x,y) \in \Omega(\+C_h)$ with $(\alpha \mapsto \beta) \in \gamma^{x,y}$ can be bounded by summing over all $(\hat{x},\hat{y}) \in \Omega(\hat{\+C}_{h^\star})$ with $\hat{y} = \textsf{proj}(\alpha\cup\beta)$. Specifically, 
\begin{align}\label{eq:congestion-2}
  \nonumber
  \sum_{(x,y)\in\Omega(\+{C}_h) \atop (\alpha\mapsto\beta)\in\gamma^{x,y}} & \abs{x\oplus y}^{p}\cdot\Pr[(\wh{X},\wh{Y})\sim \wh{\+C}_{h^{\star}}]{(\wh{X}, \wh{Y}) = \textsf{enc}(x,y)} \\
  &\le \sum_{(\wh{x},\wh{y})\in\Omega(\wh{\+{C}}_{h^{\star}}) \atop \wh{y}=\textsf{proj}(\alpha\cup\beta)}\tp{\abs{\wh{x}\oplus\wh{y}} + 2}^{p}\cdot\Pr[(\wh{X},\wh{Y}) \sim \wh{\+C}_{h^{\star}}]{(\wh{X}, \wh{Y}) = (\wh{x},\wh{y})}.
\end{align}
\Cref{cor:enc} follows immediately from~\eqref{eq:congestion-1} and~\eqref{eq:congestion-2}.
\end{proof}
