\paragraph{Property 3: Approximate measure-preserving.}
   By~\Cref{lem:explicit-formula}, the joint probabilities satisfy
  \begin{align}
    \label{eq:num}\mu_h(0)\mu_h(1)\cdot\Pr[(X,Y) \sim\+C_{h}]{(X, Y) = (x,y)} &= \mu_{{\overline{\partial}} B}(x_{{\overline{\partial}} B})\cdot\mu(y) \\
    \label{eq:denom}\wh{\mu}_{h^{\star}}(0)\wh{\mu}_{h^{\star}}(1)\cdot\Pr[(\wh{X},\wh{Y}) \sim\wh{\+C}_{h^{\star}}]{(\wh{X},\wh{Y}) = (\hat{x},\hat{y})} &= \wh{\mu}_{{\overline{\partial}}\wh{B}}(\wh{x}_{{\overline{\partial}}\wh{B}})\cdot\wh{\mu}(\wh{y})
  \end{align}
  Since $x$ and $\hat{x}$ (resp.~$y$ and $\hat{y}$) agree  over $E \setminus \ol{\partial} B = \hat{E} \setminus \ol{\partial} \hat{B}$, we have
  $$
\mu^{x_{{\overline{\partial}} B}}_{E\setminus{\overline{\partial}} B}(x_{E\setminus{\overline{\partial}} B})=\wh{\mu}^{\wh{x}_{{\overline{\partial}}\wh{B}}}_{\wh{E}\setminus{\overline{\partial}}\wh{B}}(\wh{x}_{\wh{E}\setminus{\overline{\partial}}\wh{B}}).$$
Therefore, taking the ratio of~\eqref{eq:num} and~\eqref{eq:denom}, we obtain
\begin{align*}
    \frac{\text{\eqref{eq:num}}}{\text{\eqref{eq:denom}}} = \frac{\mu(x) \mu(y)}{\hat{\mu}(\hat{x}) \hat{\mu} (\hat{y})} = \tp{\frac{\hat{Z}}{Z}}^2\cdot\frac{\lambda^{\norm{x}_1}\cdot\lambda^{\norm{y}_1}}{\lambda^{\norm{\wh{x}}_1}\cdot\lambda^{\norm{\wh{y}}_1}} &=\tp{\frac{\wh{Z}}{Z}}^2\cdot\frac{\lambda^{\norm{x_{{\overline{\partial}} B}}_1+\norm{y_{{\overline{\partial}} B}}_1}}{\lambda^{\norm{\wh{x}_{{\overline{\partial}} \wh{B}}}_1+\norm{\wh{y}_{{\overline{\partial}} \wh{B}}}_1}}\\
    &= \tp{\frac{\wh{Z}}{Z}}^2\cdot \lambda^{\abs{B} - \abs{\hat{B}}}
    \le \tp{\frac{\wh{Z}}{Z}}^2 \cdot \ol{\lambda}^2.
\end{align*}
Here, the 1-norm $\norm{\cdot}_1$ counts the number of 1's in a configuration, and the final inequality follows from the construction of $B=x\oplus y$ and $\wh{B}=\wh{x}\oplus\wh{y}$, where $(\wh{x},\wh{y})=\mathsf{enc}(x,y)$. 
\end{proof}

\subsubsection{Decoupling the local flipping coupling}\label{sec:proof-decoupling}
We now prove \Cref{lem:pre-decoupling}, the decoupling lemma for the local flipping coupling.
\begin{proof}[Proof of~\Cref{lem:pre-decoupling}]
  %Recall some properties of $\Omega(\+{C}_e)$, which are the corollaries of~\Cref{lem:explicit-formula}:
  By \Cref{lem:explicit-formula}, for every edge $e \in E$, the support $\Omega(\+{C}_e)$ of the local flipping coupling $\+{C}_e$ satisfies
  \begin{align*}
    \Omega(\+{C}_e)=\set{(\sigma,\tau)|\text{$\sigma\oplus\tau$ forms a path or an even-length cycle, and }\sigma(e)=0,\tau(e)=1}.
  \end{align*}
  This implies that for any $e,f \in E$ and any $(\sigma,\tau) \in \Omega(\+{C}_e)$, if $\sigma_{f} \ne \tau_{f}$, then either $(\sigma,\tau) \in \Omega(\+C_f)$ or $(\tau,\sigma) \in \Omega(\+C_f)$.
  Thus, we can split the right-hand side of \eqref{lem:new-pre-decoupling-equ1}  as follows:
  \begin{align*}
    \sum_{e\in E}\mu_e(0)\mu_e(1) & \E[(X,Y)\sim \+C_e]{\phi(X,Y)\cdot \*1[X_f \ne Y_f]} \\
    &\leq \sum_{e \in E}\mu_e(0)\mu_e(1)\E[(X,Y) \sim \+C_e]{\phi(X,Y)\tp{\*1[(X,Y) \in \Omega(\+C_f)] + \*1[(Y,X) \in \Omega(\+C_f)]}}.
  \end{align*}
To complete the proof, it suffices to show that
  \begin{align*}
    \sum_{e \in E}\mu_e(0)\mu_e(1)\E[(X,Y) \sim \+C_e]{\phi(X,Y)\cdot \*1[(X,Y) \in \Omega(\+C_f)]}
    \le \mu_f(0)\mu_f(1) \E[(X,Y)\sim \+C_f]{\phi(X,Y)\cdot \abs{X \oplus Y}}.
  \end{align*}
  The symmetric case with $(Y,X) \in \Omega(\+C_f)$ follows by symmetry.

  By \Cref{lem:explicit-formula}, there is a detailed identity between $\+C_e$ and $\+C_f$  for any $e,f \in E$. 
  Specifically, for every $(\sigma, \tau) \in \Omega(\+C_e) \cap \Omega(\+C_f)$, it holds
  \begin{align} \label{eq:relation-Ce-Cf}
    \mu_e(0)\mu_e(1)\Pr[(X,Y)\sim\+C_e]{(X,Y) = (\sigma,\tau)} &= \mu_f(0)\mu_f(1) \Pr[(X,Y)\sim\+C_f]{(X,Y)=(\sigma,\tau)}
  \end{align}
  Applying this identity, we have
  \begin{align*}
    \sum_{e \in E}&\mu_e(0)\mu_e(1) \E[(X,Y) \sim \+C_e]{\phi(X,Y)\cdot \*1[(X,Y) \in \Omega(\+C_f)]} \\
    &= \sum_{e\in E} \sum_{(\sigma,\tau) \in \Omega(\+{C}_e)\cap \Omega(\+{C}_f)} \phi(\sigma,\tau)\cdot  \mu_e(0)\mu_e(1) \Pr[(X,Y)\sim \+C_e]{(X,Y) = (\sigma,\tau)} \\
    &= \sum_{e\in E} \sum_{(\sigma,\tau) \in \Omega(\+C_e) \cap \Omega(\+C_f) } \phi(\sigma,\tau)\cdot  \mu_f(0)\mu_f(1) \Pr[(X,Y)\sim \+C_f]{(X,Y) = (\sigma,\tau)} \tag{by \eqref{eq:relation-Ce-Cf}} \\
    &= \mu_f(0)\mu_f(1)  \sum_{(\sigma,\tau) \in \Omega(\+C_f) }\sum_{e\in E}\*1[(\sigma,\tau)\in \Omega(\+C_e)] \cdot \phi(\sigma,\tau)\Pr[(X,Y)\sim \+C_f]{(X,Y) = (\sigma,\tau)} \\
    &\leq \mu_f(0)\mu_f(1) \sum_{(\sigma,\tau) \in \Omega(\+C_f)} \phi(\sigma,\tau)\cdot \abs{\sigma \oplus \tau} \Pr[(X,Y)\sim \+C_f]{(X,Y) = (\sigma,\tau)} \\
    &= \mu_f(0)\mu_f(1) \E[(X,Y)\sim \+C_f]{\phi(X,Y)\cdot \abs{X \oplus Y}}.
  \end{align*}
  This completes the proof.
\end{proof}

