\subsection{Congestion bounds under pinnings}\label{sec:length-and-congestion-analysis-for-conditional-distributions}
%\Cref{thm:effective-trans-flow} establishes bounds on the expected  squared length, expected congestion, and expected strong congestion of the transport flow constructed for the monomer-dimer model on a graph $G$ with distribution $\mu$. To prove \Cref{lem:local-functional-inequalities}, we must extend these results to all conditional distributions induced by $\mu$. While the self-reducibility property of the monomer-dimer model suggests a natural approach to generalize \Cref{thm:effective-trans-flow}, we cannot apply the theorem in a purely black-box way. Instead, some minor modifications are required to properly handle the conditional distributions.

We have established discrepancy and congestion bounds without pinning, as stated in \Cref{thm:effective-trans-flow}. 
To extend these bounds to the entire family $\mathfrak{Q}_{\JS}$ of Jerrum-Sinclair chains, we must address the general case that includes pinnings.
%
%Let $G=(V,E)$ be a simple undirected graph with maximum degree $\Delta$, 
%and let $\mu$ be the monomer-dimer distribution on graph $G$ with edge weight $\lambda > 0$.
Fix a subset of edges $\Lambda \subseteq E$ and a feasible pinning $\tau \in \{0,1\}^{E \setminus \Lambda}$. 
Consider the conditional distribution $\mu^\tau$ and the Jerrum-Sinclair chain $Q^\tau$ for $\mu^\tau$ as defined in \Cref{sec:app-JS-chain}.
Notably, this differs slightly from the Jerrum-Sinclair chain obtained via self-reduction under the pinning $\tau$.
To see this, define the subset $S \subseteq \Lambda$ of ``free'' edges under $\tau$ as
\begin{align*}
  S \triangleq \set{f \in \Lambda \mid \Omega(\mu^\tau_f) = \{0,1\}}.
\end{align*}
Let $\hat{G}$ be the subgraph of $G$ induced by the edge set $S$, and let $\hat{\mu}$ denote the monomer-dimer distribution on $\hat{G}$ with edge weight $\lambda$. It is easy to see that $\hat{\mu} = \mu^\tau_S$.
Now, let $\hat{Q}$ be the Jerrume-Sinclair chain for the monomer-distribution $\hat{\mu}$, which corresponds to the chain obtained via self-reduction.
Since \Cref{thm:effective-trans-flow} directly applies to $\hat{Q}$, our goal is to extend these bounds to $Q^\tau$.

% For any edge $e \in \Lambda$ with $\Omega(\mu^\tau_e) = \{0,1\}$, we need to construct a transport flow $\Gamma_e$ from  $\mu^{\tau \land e \gets 0}_\Lambda$ to  $\mu^{\tau \land e \gets 1}_\Lambda$. 
% To apply \Cref{def:monomer-dimer-trans-path}, we define the following subset $S \subseteq \Lambda$ such that

The only difference between $Q^\tau$ and $\hat{Q}$ is that $Q^\tau$ is a lazy version of $\hat{Q}$: when an edge $e\in\Lambda\setminus S$  is selected for an update in $Q^\tau$,  no change occurs, effectively introducing a lazy probability $1-\frac{|S|}{|\Lambda|}$.
%Note that for any $f \in \Lambda \setminus S$, there exists a neighboring edge $g \in E \setminus \Lambda$ such that $\tau_g = 1$ so that the value of $f$ is fixed to be $0$. Hence, the distribution $\mu^\tau_\Lambda$ is essentially the same as the distribution $\mu^{\tau}_S$. 
%Let $\hat{G}$ be the subgraph of $G$ induced by the edge set $S$. Let $\hat{\mu}$ denote the monomer-dimer distribution on $\hat{G}$ with edge weight $\lambda$. We have $\hat{\mu} = \mu^\tau_S$.
For any $e \in S$, we apply \Cref{def:monomer-dimer-trans-path} on $\hat{\mu}$ to construct the transport flow $\hat{\Gamma}_e$ from $\hat{\mu}^{e \gets 0} = \mu^{\tau \land e \gets 0}_S$ to $\hat{\mu}^{e \gets 1} = \mu^{\tau \land e \gets 1}_S$. 
Since the configuration on $E \setminus S$ remains fixed in $\mu^\tau$, we can extend $\hat{\Gamma}_e$ over $E \setminus S$ (as it is fixed in $\mu^\tau$) to obtain the transport flow $\Gamma_e$ from $\mu^{\tau \land e \gets 0}$ to $\mu^{\tau \land e \gets 1}$.

\filbreak

We now establish that  $\Gamma_e$ satisfies the following properties with respect to the chain $Q^\tau$:
\begin{enumerate}
  \item\label{lem:trans-flow-length} $O(\ol{\lambda}\Delta  \log^2(1+\ol{\lambda}))$-expected squared length;
  \item\label{lem:trans-flow-congestion}\label{lem:trans-flow-strong-congestion} $O(\ol{\lambda}^2  |\Lambda|)$-expected congestion, and
   strong $O(\ol{\lambda}^4 \Delta^2 |\Lambda|)$-expected congestion.
  % \item $O(\log(\Delta(\lambda+\frac{1}{\lambda})))$-marginal coefficient $\frac{\log(\frac{1}{\phi} - 1)}{1-2\phi}$ (defined in~\Cref{thm:log-Sob-HS-route-via-congestion});
  \end{enumerate}

Since the extension from $\hat{\Gamma}_e$ to ${\Gamma}_e$ does not alter path length, and \Cref{thm:effective-trans-flow} applies directly to $\hat{\Gamma}_e$ for $\hat{Q}$, the bound of $O(\ol{\lambda}\Delta  \log^2(1+\ol{\lambda}))$-expected squared length follows immediately. 

In contrast, $\hat{\Gamma}_e$ and ${\Gamma}_e$ may have different congestion because $Q^\tau$ is lazier than $\hat{Q}$.
To bound the congestion of $\Gamma_e$,
we apply \Cref{thm:effective-trans-flow} to $\hat{\Gamma}_e$ for $\hat{Q}$. 
For any transition $\hat{x} \mapsto \hat{y}$ in $\hat{Q}$,
\begin{align*}
  \sum_{e\in S} \hat{\mu}_e(0)\hat{\mu}_e(1) \E[\hat{\gamma} \sim \hat{\Gamma}_e]{\frac{\*1[(\hat{x} \mapsto \hat{y}) \in \hat{\gamma}]}{\ell(\hat{\gamma})}} \leq \hat{\kappa} \cdot \hat{\mu}(\hat{x})\hat{Q}(\hat{x},\hat{y}),\quad \text{where $\hat{\kappa} = O(\ol{\lambda}^2 |S|)$}.
\end{align*}
Now, consider the chain $Q^\tau$ for $\mu^\tau$. For any transition $x \mapsto y$ in $Q^\tau$ with $x \neq y$, we have:
\begin{itemize}
  \item $x_S \mapsto y_S$ is a transition in $\hat{Q}$;
  \item $\frac{|S|}{|\Lambda|}\cdot \hat{Q}(x_S,y_S) = Q^\tau(x,y)$, due to the laziness of $Q^\tau$ from selecting an $e\in\Lambda\setminus S$.
\end{itemize}
%To verify the second point, note that in each step, $Q^\tau$ picks a uniform random edge from $\Lambda$ while $\hat{Q}$ picks a uniform random edge from $S$.
%If $x \neq y$, then $Q^\tau$ must pick an edge in $S$ and two chains have the same probability to accept the candidate matching.
Thus, for any transition $(x \mapsto y)$ with $x \neq y$,
%(if $x = y$, then the congestion is 0 because the canonical path never stays in the same state), 
the expected congestion of $\Gamma_e$ satisfies
\begin{align*}
  &\sum_{e \in \Lambda:0,1 \in \Omega(\mu^\tau_e)} \mu^\tau_e(0)\mu^\tau_e(1) \E[\gamma \sim \Gamma_e]{\frac{\*1[(x \mapsto y) \in \gamma]}{\ell(\gamma)}} = \sum_{e \in S} \hat{\mu}_e(0)\hat{\mu}_e(1) \E[\gamma \sim {\Gamma}_e]{\frac{\*1[(x \mapsto y) \in {\gamma}]}{\ell({\gamma})}} \\
  =\,& \sum_{e \in S} \hat{\mu}_e(0)\hat{\mu}_e(1) \E[\hat{\gamma} \sim \hat{\Gamma}_e]{\frac{\*1[(x_S \mapsto y_S) \in \hat{\gamma}]}{\ell(\hat{\gamma})}} \leq \hat{\kappa} \cdot \hat{\mu}(x_S)\hat{Q}(x_S,y_S) = \frac{|\Lambda|}{|S|} \cdot O(\ol{\lambda}^2 |S|) \cdot \mu^\tau(x) Q^\tau(x,y)\\
  =\,& O(\ol{\lambda}^2 |\Lambda|) \cdot \mu^\tau(x) Q^\tau(x,y).
\end{align*}
This proves the bound of $O(\ol{\lambda}^2  |\Lambda|)$-expected congestion for the transport flow $\Gamma_e$ in the chain $Q^\tau$.
The bound of strong $O(\ol{\lambda}^4 \Delta^2 |\Lambda|)$-expected congestion follows by applying a similar argument.












