\subsection{Concavity of the Dirichlet forms and marginal bounds}\label{sec:concave-Dirichlet-forms}
We verify that the Jerrum-Sinclair chains satisfy the concavity condition stated in \Cref{def:concave-Dirichlet-forms}.

\begin{proof}[Proof of~\Cref{lem:concave-JS}]
  % Without loss of generality, we only prove for the case without pinning, i.e. $\Lambda = E$. 
  Let $\tau \in \{0,1\}^{E \setminus \Lambda}$ be a feasible pinning, and let $Q^{\tau}\in\mathfrak{Q}_{\JS}$ be the Jerrum-Sinclair chain for $\mu^\tau$.
  For any $\alpha,\beta \in \Omega(\mu^\tau)$, we claim the following inequality holds:
  \begin{align}\label{eq:assump-concave}
      \frac{1}{\abs{\Lambda}}\sum_{e \in \Lambda, c \in \{0,1\}} \*1[\alpha_e = \beta_e = c] \cdot  Q^{\tau \wedge (e \gets c)}(\alpha,\beta) \le Q^{\tau}(\alpha,\beta).
  \end{align}
  Assuming~\eqref{eq:assump-concave} holds, for any $f: \Omega \to \mathbb{R}$, 
  by a straightforward calculation, we obtain:
  \begin{align*}
      &\frac{1}{\abs{\Lambda}}\sum_{e \in \Lambda} \E[c \sim \mu^\tau_e]{\+E_{Q^{\tau \wedge (e \gets c)}}(f,f)} \\
      = &\frac{1}{2\abs{\Lambda}} \sum_{e \in \Lambda, c \in \{0,1\}} \mu^\tau_e(c) \sum_{\alpha,\beta \in \Omega(\mu^{\tau \wedge (e \gets c)})}\mu^{\tau \wedge (e \gets c)}(\alpha) \cdot Q^{\tau \wedge (e \gets c)}(\alpha,\beta) \cdot (f(\alpha)-f(\beta))^2\\
      = &\frac{1}{2\abs{\Lambda}} \sum_{\substack{e \in \Lambda, c \in \{0,1\}\\\alpha,\beta \in \Omega(\mu^\tau)}} \*1[\alpha_e = \beta_e = c] \cdot \mu^\tau(\alpha) \cdot Q^{\tau \wedge (e \gets c)}(\alpha,\beta) \cdot (f(\alpha)-f(\beta))^2\\
      \le &\frac{1}{2} \sum_{\alpha,\beta \in \Omega(\mu^\tau)} \mu^\tau (\alpha) \cdot Q^\tau(\alpha,\beta) \cdot (f(\alpha)-f(\beta))^2 = \+E_{Q^\tau}(f,f).
  \end{align*}
  It remains to verify~\eqref{eq:assump-concave}. We discuss all possible types of transition $(\alpha \mapsto \beta)$:
  \begin{enumerate}
  \item $\alpha \oplus \beta=\{f\}$ for an edge $f \in \Lambda$. In this case, for any edge $e \neq f$ and spin state $c = \alpha_e = \beta_e$, the transition happens in Markov chain $Q^{\tau \wedge (e \gets c)}$ with probability 
  \begin{align*}Q^{\tau \wedge (e \gets c)}(\alpha,\beta) &= \frac{1}{\abs{\Lambda}-1} \cdot \min \set{1,\frac{\mu^{\tau \wedge (e \gets c)}(
  \beta)}{\mu^{\tau \wedge (e \gets c)}(\alpha)}}\\
  &=\frac{1}{\abs{\Lambda}-1} \cdot \min \set{1,\frac{\mu^{\tau}(
  \beta)}{\mu^{\tau}(\alpha)}} =  \frac{\abs{\Lambda}}{\abs{\Lambda}-1} Q^{\tau}(\alpha,\beta),
  \end{align*}
  as  $Q^{\tau \wedge (e \gets c)}$ chooses an edge $\widetilde{e}$ in $\Lambda \setminus \{e\}$ uniformly at random. Hence,
  \begin{align*}
      \frac{1}{\abs{\Lambda}}\sum_{e \in \Lambda, c \in \{0,1\}} \*1[\alpha_e = \beta_e = c] \cdot  Q^{\tau \wedge (e \gets c)}(\alpha,\beta) = \frac{1}{\abs{\Lambda}} \sum_{e \in \Lambda, e\neq f} Q^{\tau \wedge (e \gets \alpha_e)}(\alpha,\beta) = Q^{\tau}(\alpha,\beta).
  \end{align*}
  \item $\alpha\oplus\beta=\{f,g\}$ and $\alpha_f = 0$ for distinct edges $f,g \in \Lambda$. In this case, for any edge $e \not\in \{f,g\}$ and $c = \alpha_e = \beta_e$, the transition happens in Markov chain $Q^{\tau \land (e \gets c)}$ with probability
  \begin{align*}
      Q^{\tau \wedge (e \gets c)}(\alpha,\beta) = \frac{1}{\abs{\Lambda}-1} \cdot \min\set{1,\frac{\mu^{\tau \wedge (e \gets c)}(\alpha)}{\mu^{\tau \wedge (e \gets c)}(\beta)}} = \frac{\abs{\Lambda}}{\abs{\Lambda}-1} Q^\tau(\alpha,\beta),
  \end{align*}
  as  $Q^{\tau \wedge (e \gets c)}$ chooses an edge $\widetilde{e}$ in $\Lambda \setminus \{e\}$ uniformly at random. Hence,
\begin{align*}
      \frac{1}{\abs{\Lambda}}\sum_{e \in \Lambda, c \in \{0,1\}} \*1[\alpha_e = \beta_e = c] \cdot  Q^{\tau \wedge (e \gets c)}(\alpha,\beta) = \frac{1}{\abs{\Lambda}} \sum_{e \in \Lambda, e\not\in \{f,g\} } Q^{\tau \wedge (e \gets \alpha_e)}(\alpha,\beta) \leq Q^{\tau}(\alpha,\beta).
  \end{align*}
  \end{enumerate}
  This concludes the proof of~\eqref{eq:assump-concave}.
\end{proof}

The following proposition verifies the marginal lower bound for monomer-dimer distributions.
\begin{proposition}\label{lem:marginal-coef}
Let $\mu$ be the monomer-dimer model on a graph $G=(V,E)$ with edge weight $\lambda>0$. 
The marginal lower bound satisfies $\phi\triangleq\min \set{\mu_e(c) \mid e \in E, c\in [q], \mu_e(c) \neq 0}=\Omega\tp{\frac{\lambda}{(1+\lambda\Delta)^2}}$.
\end{proposition}
\begin{proof}
  For edge $e = \{u,v\}$, it is well known that $\mu_e(0) \ge \frac{1}{1+\lambda}$.
  On the other hand, we have
  \begin{align*}
    \frac{\mu_e(1)}{\mu_e(0)} &= \frac{\Pr[X \sim \mu]{X_e=1}}{\Pr[X \sim \mu]{X_e=0}} \\
    &= \frac{\Pr[X \sim \mu]{X_e=1}}{\Pr[X \sim \mu]{u\text{ is not saturated in }X}} \cdot \frac{\Pr[X \sim \mu]{u\text{ is not saturated in }X}}{\Pr[X \sim \mu]{X_e=0}} \\
    &= \lambda \Pr[X \sim \mu_{G-u}]{v\text{ is not saturated in }X} \cdot \Pr[X \sim \mu_{G-e}]{u\text{ is not saturated in }X} \\
    &\ge \frac{\lambda}{(1+\lambda\Delta)^2}
  \end{align*}
  where we use $\mu_{G-u}$(resp.~$\mu_{G-e}$) to denote the monomer-dimer model with edge weight $\lambda$ on graph $G-u$(resp.~$G-e$).
  This implies that $\mu_e(1) \ge \frac{\lambda}{\lambda + (1+\lambda\Delta)^2}$.
%  Combining these together finishes the proof.
  % Therefore $\frac{1}{\phi}-1$ is bounded by $O(\frac{(1+\lambda\Delta)^2}{\lambda})$. Since the function $y = \frac{1-2x}{\log(1/x - 1)}$ is increasing on $(0,1/2)$, we conclude that $\frac{\log(\frac{1}{\phi} - 1)}{1-2\phi}=O(\log(\Delta(\lambda+\frac{1}{\lambda})))$.
\end{proof}
\begin{remark}
  The factor $\frac{1-2\phi}{\log(\frac{1}{\phi} - 1)}=\Omega(\frac{1}{\log\frac{1+\lambda\Delta}{\lambda}})$ in the log-Sobolev bound in \Cref{thm:log-Sob-HS-route-via-congestion} vanishes as $\lambda\to 0^+$. 
  However, when $\lambda=o(\frac{1}{\Delta})$, we can prove an $O(m\log m)$ mixing time for both Glauber dynamics and the Jerrum-Sinclair chain on monomer-dimers via a simple path coupling argument  (see, e.g.,~\cite[Corollary 18]{Dyer2007MatrixNA}).
  As a result, it is sufficient to focus on the case where  $\lambda=\Omega(\frac{1}{\Delta})$. 
  In this regime, the factor is  lower bounded as $\frac{1-2\phi}{\log(\frac{1}{\phi} - 1)}=\Omega(\frac{1}{\log(\ol{\lambda}\Delta)})$, where $\ol{\lambda}\triangleq\max\{1,\lambda\}$.
\end{remark}


\section{Faster Mixing of Monomer-Dimer Glauber Dynamics}\label{sec:faster-mixing-of-monomer-dimer-glauber-dynamics}
% \newcommand{\CK}{C_{\kappa}}
% \newcommand{\CL}{C_L}
\newcommand{\toJ}{\overset{\-{JS}}{\mapsto}}
\newcommand{\toG}{\overset{\-{GD}}{\mapsto}}
\newcommand{\PJ}{P_{\-{JS}}}
\newcommand{\PG}{P_{\-{GD}}}
In this section, we establish an upper bound on the mixing time of Glauber dynamics for the monomer-dimer model via a comparison argument.
\begin{theorem}\label{thm:main-Glauber}
  Let $G=(V,E)$ be a simple undirected graph with $n$ vertices, $m$ edges, and maximum degree~$\Delta$.
  Let $\mu$ be the monomer-dimer distribution on $G$ with edge weight $\lambda>0$, and define $\overline{\lambda} = \max\set{1,\lambda}$.
  The Glauber dynamics for $\mu$,  with transition matrix $\PG$, has Poincar\'e constant $ \gamma(\PG)$ and log-Sobolev constant $\rho(\PG)$ satisfying:
  \begin{align*}
    \gamma(\PG) = \Omega\tp{\frac{1}{\ol{\lambda}\Delta}}\cdot \gamma(P_{\mathrm{JS}}) \quad \text{and} \quad \rho(\PG) = \Omega\tp{\frac{1}{\ol{\lambda}\Delta}}\cdot\rho(P_{\mathrm{JS}}).
  \end{align*}
  As a consequence, the mixing time of the Glauber dynamics for the monomer-dimer model satisfies
  \begin{align*}
      T_{\mathrm{mix}}(\PG) &= O\left(\overline{\lambda}^{4} \Delta^2 m\cdot  \min \left\{n\log^2(1+\ol{\lambda}),\,\, \overline{\lambda} \Delta \log(\ol{\lambda} \Delta)\cdot \log n \right\}\right)=\widetilde{O}_{\lambda}(\Delta^3m).
  \end{align*}
  \end{theorem}
The Markov chain $\PG$ is similar to Jerrum-Sinclair chain $\PJ$,  but it updates at most one edge when transitioning from $X_t$ to $X_{t+1}$ according to the following rules: 
\begin{enumerate}
\item Select an edge $e\in E$ uniformly at random;
\item Set $X_{t+1}(e)$ to a random value sampled from the conditional marginal distribution $\mu^{{X_t}(N(e))}_e,$ where 
  $N(e)=\set{f\in E: f\text{ is incident to }e \text{ in }G}$.
\item  For all  edges $f\in E\setminus\set{e}$, set $X_{t+1}(f)=X_t(f)$.
\end{enumerate}
It can be verified that the Glauber dynamics defined above is ergodic and reversible with respect to the stationary distribution $\mu$. Moreover, $\PG$ is positive semi-definite.

We now prove the following key lemma that compares the Dirichlet forms of the monomer-dimer Glauber dynamics $\PG$ with those of the Jerrum-Sinclair chains $\PJ$.
\begin{lemma}\label{lem:comparing-Dirichlet}
  For any function $f:\Omega \to \mathbb{R}_{\geq 0}$, we have $\+E_{\PJ}(f,f) \le 4\Delta(\ol{\lambda}+1)\cdot \+E_{\PG}(f,f)$.
\end{lemma}
\Cref{thm:main-Glauber} then follows from the straightforward application of \Cref{lem:comparing-Dirichlet} to the definitions of the Poincaré constant and the log-Sobolev constant.
