Let $P_1, P_2$ be two ergodic Markov chains on the state space $\Omega$, both reversible with respect to the stationary distribution $\mu$. 
For each transition $x\mapsto y$ in $P_1$ with $P_1(x,y) > 0$, 
%$x,y \in \Omega$ such that $P_1(x,y) > 0$, 
we define a canonical path $\gamma^{x,y} = (x_0, x_1, \cdots, x_\ell)$ with length $\ell = \ell(\gamma^{x,y})$ from $x_0=x$ to $x_{\ell}=y$ using the transitions in~$P_2$, which means $P_2(x_i, x_{i+1}) > 0$ for all $i < \ell$.
%For convenience, we also represent $\gamma^{x,y}$ as the set of edges $\set{(x_i, x_{i+1})\mid 0\le i<\ell}$.

Given such a family of canonical paths, the \emph{congestion ratio} $B$ between $P_1$ and $P_2$ is defined as
\begin{align*}
  B \triangleq \max_{\alpha, \beta\in\Omega: \atop P_2(\alpha, \beta) > 0} B(\alpha,\beta),\quad \text{ where }\quad B(\alpha,\beta)\triangleq  
  %\max_{(\alpha, \beta): \atop P_2(\alpha, \beta) > 0} \tp{ 
  \frac{1}{\mu(\alpha)P_2(\alpha,\beta)} \sum_{x,y\in\Omega: \atop  (\alpha, \beta)\in\gamma^{x,y}} \mu(x) P_1(x,y) \ell(\gamma^{x,y}).
  %}.
\end{align*}



\begin{lemma}[comparing Dirichlet forms via paths \text{\cite[Theorem 13.20]{levin2017markov}}] \label{lem: comparison-via-congestion}
    If there exists a family of canonical paths with congestion ratio $B$ between $P_1$ and $P_2$, then for all functions $f:\Omega \to \=R$, it holds $$\+E_{P_1}(f,f) \leq B \cdot \+E_{P_2}(f,f).$$ %comparing paths from $\PJ$ to $\PG$ that satisfy a $B$-congestion ratio. Specifically, for any $ \alpha,\beta\in \Omega(\mu)$,
  %\begin{align*}
  %  \E[X\sim \mu,Y\sim \PJ(X\mapsto \cdot)]{\ell(\gamma^{X,Y})\*1[(\alpha\overset{\-{GD}}{\mapsto} \beta)\in \gamma^{X,Y}]}\le B\cdot \mu(\alpha)\PG(\alpha,\beta). %\quad \forall \alpha,\beta\in \Omega(\mu).
  %\end{align*}
  %Then, for any function $f:\Omega \to \mathbb{R}_{\geq 0}$, we have $\+E_{\PJ}(f,f)\le B \cdot \+E_{\PG}(f,f)$.
\end{lemma}

\begin{proof}[Proof of~\Cref{lem:comparing-Dirichlet}]
To apply \Cref{lem: comparison-via-congestion} with $P_1 = \PJ$ and $P_2 = \PG$,
%For convenience, we use $ \alpha \overset{\-{JS}}{\mapsto} \beta$ and $\alpha \overset{\-{GD}}{\mapsto} \beta$ to distinguish the transitions in the chains $\PJ$ and $\PG$, respectively.
we provide a  symmetric construction of canonical paths  $\gamma^{x,y}=\gamma^{x,y}$ with congestion ratio $B\le 4\Delta(\ol{\lambda}+1)$ between $P_1$ and~$P_2$. 
Depending on the size of the difference $x\oplus y\triangleq \{e\in E\mid x_e\neq x_e\}$,
the construction proceeds in two cases, ensuring that $\ell(\gamma^{x,y})\le 2$ in both cases.
\begin{enumerate}
  \item When $\abs{x\oplus y}=1$, $x$ and $y$ differ at exactly one edge. Thus, $(x, y)$ is a legal transition in $\PG$.
  We define $\gamma^{x,y}=\tp{x,y}$, which forms a path of length 1 in the transition graph of $\PG$.
  %Recall that $(x_0,x_1,\ldots,x_{\ell})$ denotes a sequence of states from the state space $\Omega$.
  \item When $\abs{x\oplus y}=2$, we have $x_g=0,y_g=1$ and $x_h=1,y_h=0$ for exactly two edges $g,h$, and $x=y$ elsewhere. 
  Then, $(x,z)$ and $(z,y)$ are legal transitions in $\PG$, where $z=x\triangle\{h\}$. We define $\gamma^{x,y}=\tp{x, z, y}$,  which forms a path of length 2 in the transition graph of $\PG$,  
  %Recall that $\*1_e \in \{0,1\}^E$ denotes the indicator vector that takes value 1 only at edge $e$.
\end{enumerate}
Next, observe the following simple properties of the canonical paths from the construction above.
%\begin{claim}\label{clm: properties-of-ck}
  Suppose $(\alpha, \beta)\in \gamma^{x,y}$ is an edge-removing transition in Glauber dynamics with $\alpha_e=1$ and $\beta_e=0$. Then:
  \begin{enumerate}
    \item If $\abs{x\oplus y}=1$, then $x=\alpha, y=\beta$.
    \item If $\abs{x\oplus y}=2$ with $x_g=0,y_g=1$, $x_h=1,y_h=0$, we have $e=h$, $x=\alpha$, and $y=\beta\triangle\{g\}$. %which is obtained by applying the symmetric difference between $\beta$ and $\{g\}$. 
    Note that $g$ is incident to $h$. Since $h=e$ is fixed in the transition $(\alpha,\beta)$, the number of possible choices for $g$ is at most $2(\Delta - 1)$. %, and vise versa.
  \end{enumerate}
%\end{claim}
  %For any edge-removing transition $\alpha\toG \beta$, we have the following bound for the congestion ratio:
  For any edge-removing transition $(\alpha, \beta)$ in Glauber dynamics, we bound the congestion ratio:
  \begin{align*}
    B(\alpha, \beta) %\frac{\E[X\sim \mu,Y\sim \PJ(X\mapsto \cdot)]{\ell(\gamma^{X,Y})\*1[(\alpha\overset{\-{GD}}{\mapsto} \beta)\in \gamma^{X,Y}]}}{\mu(\alpha)\PG(\alpha,\beta)} \\
    \le & 2\tp{\frac{\mu(\alpha)\PJ(\alpha,\beta)}{\mu(\alpha)\PG(\alpha,\beta)}+\sum_{g\text{ incident to }h} \frac{\mu(\alpha)\PJ(\alpha,\beta\triangle \{g\})}{\mu(\alpha)\PG(\alpha,\beta)}} \\
    \le & 2\tp{(\lambda+1)\min\tp{1,1/\lambda}+2(\Delta-1)\cdot (\lambda+1) }\\
    \le & 4\Delta(\ol{\lambda}+1).
  \end{align*}
  By symmetry, the same bound also applies to any edge-inserting transition in Glauber dynamics. The conclusion follows by applying \Cref{lem: comparison-via-congestion}.
\end{proof}

%\section{Conclusion and Future Directions}
%In this paper, we prove an $\widetilde{O}(\Delta^2 m)$ upper bound on the mixing time of the Jerrum-Sinclair chain for the monomer-dimer model with a constant edge weight $\lambda$ on any graph with $m$ edges and maximum degree $\Delta$. This improves upon the well-known $\widetilde{O}(n^2 m)$ bound established over three decades ago in the seminal works of Jerrum and Sinclair \cite{jerrum1989approximating,sinclair1992improved}.

\section{Concurrent Work and Future Directions}
We note that a concurrent work \cite{chen2025rapid}, which shares a subset of authors with the current paper, proves an $\widetilde{O}(\sqrt{\Delta}nm)$ mixing time for the Glauber dynamics for uniform sampling of matchings (with edge weight $\lambda=1$), among other results, by utilizing the trickle down method.

An important open question remains: What is the sharp bound for the mixing time of the Jerrum-Sinclair chain on matchings? A potential milestone to aim for is a bound of $\widetilde{O}(\sqrt{\Delta}m)$, where the $\Theta(\sqrt{\Delta})$ factor is motivated by the total influence bound for matchings~\cite{bayati2007simple}.

%An open problem remains: can the dependence on the maximum degree $\Delta$ be further improved? Specifically, can we prove an improved bound of $\widetilde{O}_\lambda(\sqrt{\Delta} m)$ for the mixing time? The square-root dependence is suggested by the decay factor of the monomer-dimer system~\cite{bayati2007simple}.

Beyond the monomer-dimer system, the canonical path method for analyzing mixing times has been applied to a variety of foundational problems, such as the permanent, the Ising model, and the switch/flip chain for generating random regular graphs.
A promising direction for future work is to extend the new techniques developed in this paper to these problems, with the goal of achieving improved mixing times.

As a final remark, 
it will be exciting to see how the key insights of this paper can be applied to overcome some long-standing challenges in current approaches to mixing times, such as the exponential dependence of mixing time on spectral independence.
