\section{A Generalization of Our Approach to Localization Schemes}\label{sec:localization-scheme}

%The mechanism in \Cref{thm:general-results} can be generalized to general localization schemes (a.k.a. noising or denoising process).
In the proof of \Cref{thm:general-results}, random pinnings are introduced to the distribution, progressively transforming it into a Dirac measure.
The concept of \emph{localization schemes}, introduced in \cite{chen2022localization}, generalizes random pinnings to more abstract localization processes.
This abstraction generalizes the local-to-global argument developed in \cite{anari2019logconcave, cryan2021modified}.
Inspired by this, we present a similar generalization of our local-to-global principle, as stated in \Cref{thm:general-results}, using localization schemes.


\paragraph{Noising and Denoising Process}
Let $(X_t)_{t\in [0,1]}$ be a Markov process that takes values in $\Omega$, with $X_0$ drawn from the target distribution $\mu$. The process starts at $X_0$ and progressively removes randomness until the law of $X_1$ becomes a Dirac distribution. We refer to this process $(X_t)_{t\in [0,1]}$ as a \emph{noising process}.
The \emph{denoising process} $(Y_t)_{t\in [0,1]}$ is then defined as the time-reversal of $(X_t)_{t\in [0,1]}$, i.e., $Y_t \triangleq X_{1-t}$.
It is straightforward to verify that $(Y_t)_{t\in [0,1]}$ is also a Markov process.
Since $Y_t \overset{\-d}{=} X_{1-t}$, we know that $Y_1 \sim \mu$ and the law of $Y_0$ is a Dirac distribution.
Next, let $(Q_t)_{t\in [0,1]}$ be a process of transition matrices (row stochastic matrices) in $\=R^{\Omega\times \Omega}$ that adapts to the same filtration as $(Y_t)_{t\in[0,1]}$.
In particular, the (random) stationary distribution of $Q_t$ is the conditional law of $Y_1$ given $Y_t$ (with $Q_0$ having stationary distribution $\mu$). 
We refer to $(Q_t)_{t\in [0,1]}$ as the associated \emph{chain process} with respect to $(Y_t)_{t\in [0,1]}$.

Typical examples of localization schemes include coordinate-by-coordinate localization and negative-field localization. We apply the coordinate-by-coordinate localization from \Cref{thm:general-results} in this framework.

\begin{example}[coordinate-by-coordinate localization]
    Let $\mu$ be a distribution supported over $[q]^n$, and let $\square$ be an auxiliary spin.
    The noising process $(X_t)_{t \in [0,1]}$ with initial distribution $X_0 \sim \mu$ is defined as follows. Initially, we select a total order $r_1 < r_2 < \ldots < r_n$ of all sites $[n]$ uniformly at random. For all $t \in [0,1]$, $X_t$ is obtained by replacing the spin of the first 
$\lfloor nt\rfloor$ sites, $r_1,r_2,\ldots,r_{\lfloor nt\rfloor}$ in $X_0$ with $\square$.
\end{example}
% {\color{red} todo, add examples here, discuss the name of $(Q_t)$}

\begin{example}[negative-field localization]
Let $\mu$ be a distribution supported over $2^{[n]}$. The noising process $(X_t)_{t \in [0,1]}$ with initial distribution $X_0 \sim \mu$ is defined as follows. Initially, we assign each site $i \in [n]$ with an independent random variable $r_i$ uniformly distributed on $[0,1]$. For all $t \in [0,1]$, $X_t$ is the set of sites $i \in X_0$ with $r_i \ge t$.
\end{example}

We can generalize the local functional inequalities defined in~\Cref{def:HS-route}.
\begin{definition}[local functional inequalities]
  Let $\mu$ be a distribution supported on $\Omega$ and let $(Y_t)_{t\in [0,1]}$ be a denoising process with $Y_1 \sim \mu$ and let $(Q_t)_{t\in [0,1]}$ be the chain process with respect to $(Y_t)_{t\in [0,1]}$. Let $\alpha:[0,1] \to \=R_{\geq 0}$ be a function.
  \begin{itemize}
  \item (local Poincar\'e inequality) We say that $((Y_t),(Q_t))$ satisfies the \emph{$\alpha$-local Poincar\'e inequality} if 
  \begin{align} \label{eq:def-local-poincare-general}
    \alpha(t) \cdot \lim_{h\to 0^+} \frac{1}{h} \Var{\E{f(Y_1) \mid Y_{t+h}} \mid Y_t} \leq  \+E_{Q_t}(f,f),\quad \forall f: \Omega(\mu) \to \mathbb{R}.
  \end{align}
  \item (local log-Sobolev inequality) We say $((Y_t),(Q_t))$ satisfies the \emph{$\alpha$-local log-Sobolev inequality} if 
  \begin{align} \label{eq:def-local-log-sobolev-general}
    \alpha(t) \cdot \lim_{h\to 0^+} \frac{1}{h} \Ent{\E{f^2(Y_1) \mid Y_{t+h}} \mid Y_t} \leq  \+E_{Q_t}(f,f),\quad \forall f: \Omega(\mu) \to \mathbb{R}.
  \end{align}
  \end{itemize}
\end{definition}
\begin{remark}
    For coordinate-by-coordinate localization, the variance $\Var{\E{f(Y_1) \mid Y_{t+h}} \mid Y_t}$ or entropy $\Ent{\E{f^2(Y_1) \mid Y_{t+h}} \mid Y_t}$ is not differentiable at $t = \frac{k}{n}$ for all $1 \le k \le n$. In this case, we use the finite difference instead, which is consistent with our previous definitions (\Cref{def:HS-route}).
\end{remark}

We can also generalize the notion of concave Dirichlet forms in terms of $(Q_t)_{t\in [0,1]}$.
\begin{definition}[concave Dirichlet forms]\label{def:concave-Dirichlet-forms-new}
  We say the process $(Q_t)_{t\in [0,1]}$ have has \emph{concave Dirichlet forms} if for any $t \in [0,1]$ and any function $f:\Omega \to \mathbb{R}$,
  \begin{align*}
    \E{\+E_{Q_t}(f,f)} \leq \+E_{Q_0}(f,f).
  \end{align*}
\end{definition}

The following presents a generalization of the ``local-to-global'' theorem (\Cref{thm:general-results}) for functional inequalities, extending it to the general context of localization schemes.
\begin{theorem}
  Let $\mu$ be a distribution over $\Omega$.
  Let $(Y_t)_{t\in [0,1]}$ be a denoising process for $\mu$ and let $(Q_t)_{t\in [0,1]}$ be the chain process with respect to $(Y_t)_{t\in [0,1]}$ such that $(Q_t)_{t\in [0,1]}$ has {concave Dirichlet forms}. Let $\alpha:[0,1] \to \=R_{\geq 0}$ be a function.
  \begin{itemize}
  \item If $((Y_t),(Q_t))$ satisfies the $\alpha$-local Poincar\'e inequality, then the Poincar\'e constant $\gamma(Q_0)$ satisfies
    \begin{align*}
      \gamma(Q_0) \geq \tp{\int_0^1 \alpha^{-1}(t) \;\-d t}^{-1}.
    \end{align*}
  \item If $((Y_t),(Q_t))$ satisfies the $\alpha$-local log-Sobolev inequality, then the log-Sobolev constant $\rho(Q_0)$ satisfies
    \begin{align*}
      \rho(Q_0) \geq \tp{\int_0^1 \alpha^{-1}(t) \;\-d t}^{-1}.
    \end{align*}
  \end{itemize}
\end{theorem}
\begin{proof}
  We give the proof for the Poincar\'e constant $\gamma(Q_0)$, the log-Sobolev constant follows by almost the same proof.
  Let $\oVar(t) \triangleq \E{\Var{f(Y_1) \mid Y_t}}$ as a function of $t \in [0,1]$.
  Hence, the derivative of this function can be bounded by
  \begin{align*}
    -\oVar(t)'
    &= \lim_{h\to 0^+} \frac{1}{h} \tp{\oVar(t) - \oVar(t+h)} \\
    &=  \lim_{h\to 0^+} \frac{1}{h} \E{ \Var{f(Y_1) \mid Y_t} - \E{\Var{f(Y_1) \mid Y_{t+h}} \mid Y_t} } \tag{law of total expectation} \\
    &=  \lim_{h\to 0^+} \frac{1}{h} \E{ \Var{\E{f(Y_1) \mid Y_{t+h}} \mid Y_t} } \tag{law of total variance} \\
    &=  \E{\lim_{h\to 0^+} \frac{1}{h} \Var{\E{f(Y_1) \mid Y_{t+h}} \mid Y_t} } \\
    &\leq  \alpha^{-1}(t) \E{\+E_{Q_t}(f,f)} \tag{$\alpha$-local Poincar\'e inequality} \\
    &\leq  \alpha^{-1}(t) \+E_{Q_0}(f,f) \tag{concave Dirichlet forms}.
  \end{align*}
  We finish the proof by taking an integration at both side and get
  \begin{align*}
    \Var{f(Y_1)} &= \oVar(0) - \oVar(1) = - \int_0^1 \oVar(t)' \-d t \leq \tp{\int_0^1 \alpha^{-1}(t) \-d t} \+E_{Q_0}(f,f). \qedhere
  \end{align*}
\end{proof}

