\subsection{System Definition}
We consider an Euler-Lagrange (EL) system $\mathcal{S}$ described by the dynamics:
\begin{align}
    \mathcal{S}: M(x)\Ddot{x} + V(x,\dot{x}) + G(x) = \tau + d(t), \label{eqn:sysdyn}
\end{align}
where $x(t) = [x_1(t), \ldots, x_n(t)]^\top \in X \subset \mathbb{R}^n$ is the system configuration, $\tau(t) \in \mathbb{R}^n$ is the control input and $d(t) \in \mathbb{D} \subset \R^n$ is an unknown external disturbance. $M(x) \in \R^{n \times n}$ denotes the mass matrix, $V(x, \dot{x}) \in \R^n$ represents the Coriolis and centrifugal terms, and $G(x) \in \R^n$ is the gravity vector. For the reader’s convenience, we simplify the notation by omitting arguments and parentheses when it is clear that a symbol represents a function. For example, $M(x), V(x,\dot{x}), G(x)$ and $d(t)$ are denoted as $M,V,G$ and $d$, respectively.

\begin{assumption}
    The mass matrix $M(x)$, the Coriolis and centrifugal terms $V(x, \dot{x})$, the gravity vector $G(x)$ and the external disturbance $d(t)$ are all unknown.
\end{assumption}

% \PJ{it is good to make it as assumption}
% , which is bounded by $-\overline{\tau} \preceq \tau \preceq \overline{\tau}$, with $\overline{\tau} \in \R^n$ being the known control limit. The mass matrix $M(x) \in \R^{n \times n}$, the Coriolis and centrifugal terms $V(x, \dot{x}) \in \R^n$, and the gravity vector $G(x) \in \R^n$ are all unknown \PJ{it is good to make it as assumption}. Additionally, $d(t) \in \mathbb{D} \subset \R^n$ denotes an unknown external disturbance. For the reader’s convenience, we simplify the notation by omitting arguments and parentheses when it is clear that a symbol represents a function. For example, $M(x), V(x,\dot{x}), G(x)$ and $d(t)$ are denoted as $M,V,G$ and $d$, respectively.

For the EL system $\mathcal{S}$, given control input bounds $\overline{\tau} \in \R^n$: $|\tau(t)| \preceq \overline{\tau},$ for all $t \in \R_0^+$, there are corresponding bounds on the norms of the system parameters \cite[Chapter 2]{ELbook}, \cite[Chapter 7]{ELbook2}, \cite{ELbounds}. Although disturbance $d(t)$ and system parameters $M(x), V(x,\dot{x}),$ and $G(x)$ are unknown, their boundedness can be utilized effectively for control synthesis. To facilitate analysis, we adopt the following assumptions concerning the parameters of the EL system:

\begin{assumption}\label{assum_d}
    The external disturbance $d$ satisfies $-\overline{d} \preceq d \preceq \overline{d},$ for all $t \in \R_0^+$, where $\overline{d} \in \R^n$ is a known bound.
\end{assumption}

\begin{assumption}\label{assum_tau}
    Given the control bound $\overline{\tau}$, there exists a positive constant $\underline{m} \in \R$, such that $\underline{m}\overline{\tau} \preceq M^{-1}\overline{\tau}$.
\end{assumption}

\begin{assumption}\label{assum_V}
The Coriolis and centrifugal terms $V$ and the gravity vector $G$ satisfy $\underline{V}_M \preceq V_M \preceq \overline{V}_M$, where $V_M := -M^{-1}(V+G)$ and $\underline{V}_M, \overline{V}_M \in \R^n$.
\end{assumption}

\begin{assumption}\label{assum_Md}
    The inverse of the mass matrix scales the disturbance as $-\|M^{-1}\| \overline{d} \preceq M^{-1}d \preceq \|M^{-1}\| \overline{d}$. This implies, there exists $\underline{m}_i \in \R^+$, such that $-\underline{m}_i \overline{d} \preceq M^{-1}d \preceq \underline{m}_i \overline{d}$.
\end{assumption}

The Assumptions \ref{assum_d}-\ref{assum_Md} provide the bounds on various system parameters, which are utilized for establishing the feasibility conditions in Section \ref{sec:feas}.

\subsection{Problem Statement}
The goal of this work is to design a feedback control law $\tau(t)$ such that the trajectory $x(t)$ of the unknown EL system, defined in \eqref{eqn:sysdyn}, tracks a given reference trajectory $x_{ref}(t) \in \R^n$, for all $t \in \R_0^+$. Furthermore, the control signal $\tau(t)$ must remain within the input bounds: $|\tau(t)| \preceq \overline{\tau}$, for all $t \in \R_0^+$. 

To ensure the feasibility of tracking the desired trajectory, $x_{ref}(t)$, the following assumption is adopted:
\begin{assumption}\label{assum_xref}
    The reference trajectory, $x_{ref}(t)$, is continuously differentiable, and there exists a constant $\overline{v}_r \in \R_0^+$, such that $-\overline{v}_r \preceq \dot{x}_{ref}(t) \preceq \overline{v}_r$, for all $t \in \R_0^+$.
\end{assumption}

The control problem is formally stated as follows:
\begin{problem}\label{prob}
    Given the EL system $\mathcal{S}$ in \eqref{eqn:sysdyn}, satisfying Assumptions \ref{assum_d}-\ref{assum_Md}, and the desired reference trajectory $x_{ref}(t)$ adhering to Assumption \ref{assum_xref}, design a model-free feedback control law $\tau(t)$, that satisfies the following objectives: 
    \begin{itemize}
        \item[(i)] the system configuration $x(t)$ tracks the reference signal $x_{ref}(t)$ for all $t \in \R_0^+$, and
        \item[(ii)] the control input remains bounded by $\overline{\tau}$, i.e., $|\tau(t)| \preceq \overline{\tau}$, for all $t \in \R_0^+$.
    \end{itemize}
\end{problem}

\section{Controller Design and Theoretical Analysis}\label{sec:con}
In this section, we derive the control law formulated to address Problem~\ref{prob}. The proposed controller is developed using a systematic two-step procedure inspired by a backstepping-like design approach, similar to that described in \cite{PPCfeedback} and \cite{hard_soft}. The first step focuses on satisfying the tracking specification by introducing a velocity-level control input as in \eqref{eqn:sysDyn_vel}. This is then extended to an acceleration-level control formulation in \eqref{eqn:sysDyn_acc}. For clarity, the EL system dynamics in \eqref{eqn:sysdyn} can be equivalently expressed as:
\begin{subequations}
    \begin{align}
    \dot{x} &= v, \label{eqn:sysDyn_vel}   \\
    \dot{v} &= M(x)^{-1} \left(-V(x, v) - G(x) + \tau + d \right) = V_M(x,v) + M(x)^{-1}\tau + M(x)^{-1}d, \label{eqn:sysDyn_acc}
    \end{align}
\end{subequations}
where $V_M(x,v) = -M(x)^{-1}(V(x,v)+G(x))$.
