\subsection{Tracking Error Analysis}
The theorem formally summarizes the approximation-free closed-form controller proposed in this paper.

\begin{theorem}\label{thm:bdcontrol}
    Consider the Euler-Lagrange system $\mathcal{S}$ in \eqref{eqn:sysdyn} with assumptions \ref{assum_d} - \ref{assum_Md} assigned a tracking task adhering to Assumption \ref{assum_xref}. If the initial state error $e_x(0)$ satisfies $|e_x(0)| \prec p_x,$, the initial velocity error follows $|e_{v}(0)| < p_v$, and if feasibility conditions \eqref{eqn:feas1} and \eqref{eqn:feas2} hold, then the closed-form controller $\tau(t)$ in \eqref{eqn:con} guarantees
    \begin{itemize}
        \item[(i)] The tracking error $e_x(t)$ and its derivative $e_v(t)$ evolve within the corresponding funnels:
        $$|e_x(t)| \prec \rho_x(t) \text{ and } |e_v(t)| \prec \rho_v(t), \ \forall t \in \R_0^+,$$
        \item[(ii)] The control input $\tau(t)$ and the velocity signal $v(t)$ are bounded within prescribed limits:
        $$|\tau(t)| \preceq \overline{\tau} \text{ and } |v(t)| \preceq \overline{v}, \ \forall t \in \R_0^+.$$
    \end{itemize}
\end{theorem}

\begin{proof}
    The proof is divided into two stages:

    \textbf{Stage I.} In stage I, we prove that the reference velocity vector $v_r(t)$ in \eqref{eqn:velcon} enforces the state error $e_x(t)$ to remain in the funnel $[-\rho_x(t),\rho_x(t)]$ for all time $t \in \R_0^+$ \eqref{eqn:fun}. 

    We will prove this via contradiction. Let $\tx$ be the first time instance when the state error $e_x(t)$, on the application of velocity input $v_r(t)$ \eqref{eqn:velcon}, violates \eqref{eqn:fun}:
    $$\exists i \in [1;n], e_{x,i}(\tx) \leq -\rho_{x,i}(\tx) \text{ or } e_{x,i}(\tx) \geq \rho_{x,i}(\tx).$$
Then,
\begin{gather}\label{Eq:inqe_tx}
    -\rho_{x,i}(t) < e_{x,i}(t) < \rho_{x,i}(t), \forall (t,i) \in [0, \tx) \times [1;n].
\end{gather}
We will consider the following two cases for $t \in [0,\tx)$.

\textbf{Case I.} There exists $i \in [1;n]$ such that $e_{x,i}(t)$ approaches the upper funnel constraint (Figure \ref{fig:case1}), i.e., $e_{x,i}(t) \rightarrow \rho_{x,i}(t) \implies e_{x,i}(t) - \rho_{x,i}(t) \rightarrow 0$. Following \eqref{Eq:inqe_tx}, we have the following implications:
\begin{align*}
    &e_{x,i}(t) < \rho_{x,i}(t) \implies (e_{x,i}(t) - \rho_{x,i}(t)) \uparrow 0 \\
    &\implies \lim_{(e_{x,i}(t) - \rho_{x,i}(t)) \uparrow 0} \frac{d}{dt} (e_{x,i}(t) - \rho_{x,i}(t)) > 0 \implies \lim_{(e_{x,i}(t) - \rho_{x,i}(t)) \uparrow 0} \dot{e}_{x,i}(t) > \lim_{(e_{x,i}(t) - \rho_{x,i}(t)) \uparrow 0} \dot{\rho}_{x,i}(t) \\
    &\implies \lim_{(e_{x,i}(t) - \rho_{x,i}(t)) \uparrow 0} \dot{e}_{x,i}(t) > -\mu_{x,i}(p_{x,i}-q_{x,i})e^{-\mu_{x,i}t} \implies \lim_{(e_{x,i}(t) - \rho_{x,i}(t)) \uparrow 0} \dot{e}_{x,i}(t) > -\mu_{x,i}(p_{x,i}-q_{x,i}) \\
    &\implies \lim_{(e_{x,i}(t) - \rho_{x,i}(t)) \uparrow 0} \dot{x}_{i}(t) > -\mu_{x,i}(p_{x,i}-q_{x,i}) + \dot{x}_{ref}(t) \implies \lim_{(e_{x,i}(t) - \rho_{x,i}(t)) \uparrow 0} \dot{x}_{i}(t) > -\mu_{x,i}(p_{x,i}-q_{x,i}) - \overline{v}_{r,i}.
\end{align*}
Therefore, there exists $i \in [1;n]$, such that 
\begin{gather}\label{eqn:dx_b1}
    \lim_{(e_{x,i}(t) - \rho_{x,i}(t)) \uparrow 0} \dot{x}_{i}(t) > -\mu_{x,i}(p_{x,i}-q_{x,i}) - \overline{v}_{r,i}.
\end{gather}

Now, let us look at the reference velocity vector $v_r(t) = [v_{r,1}(t), \ldots, v_{r,n}(t)]^\top$, for all $i \in [1;n]$
\begin{align*}
    \lim_{(e_{x,i}(t) - \rho_{x,i}(t)) \uparrow 0} \varepsilon_{x,i}(t) = 1
    \implies \lim_{(e_{x,i}(t) - \rho_{x,i}(t)) \uparrow 0} v_{r,i}(t) = -\overline{v}_{i}.
\end{align*}
Given the velocity-level system dynamics \eqref{eqn:sysDyn_vel} and feasibility constraint \eqref{eqn:feas1}, for all $i \in [1;n]$
\begin{align}\label{eqn:dx_b1c}
    \lim_{(e_{x,i}(t) - \rho_{x,i}(t)) \uparrow 0} \dot{x}_{i}(t) = -\overline{v}_{i}
    \implies \lim_{(e_{x,i}(t) - \rho_{x,i}(t)) \uparrow 0} \dot{x}_{i}(t) \leq -\mu_{x,i}(p_{x,i}-q_{x,i}) - \overline{v}_{r,i}.
\end{align}
Thus, \eqref{eqn:dx_b1} contradicts \eqref{eqn:dx_b1c}. Hence, $e_{x,i}(t) \nrightarrow \rho_{x,i}(t), \forall (t,i) \in [0,\tx) \times [1;n]$, i.e., the state error $e_x(t)$ never approaches the upper tube constraint over $t \in [0,\tx)$ in any dimension.

\textbf{Case II.} There exists $i \in [1;n]$ such that $e_{x,i}(t)$ approaches the lower tube constraint (Figure \ref{fig:case2}), i.e., $e_{x,i}(t) \rightarrow -\rho_{x,i}(t) \implies e_{x,i}(t)+\rho_{x,i}(t) \rightarrow 0$. Following \eqref{Eq:inqe_tx}, we have the following implications:
\begin{align*}
    &e_{x,i}(t) > -\rho_{x,i}(t) \implies (e_{x,i}(t)+\rho_{x,i}(t)) \downarrow 0 \\
    &\implies \lim_{(e_{x,i}(t)+\rho_{x,i}(t)) \downarrow 0} \frac{d}{dt} (e_{x,i}(t)+\rho_{x,i}(t)) < 0 \implies \lim_{(e_{x,i}(t)+\rho_{x,i}(t)) \downarrow 0} \dot{e}_{x,i}(t) < \lim_{(e_{x,i}(t)+\rho_{x,i}(t)) \downarrow 0} -\dot{\rho}_{x,i}(t) \\
    &\implies \lim_{(e_{x,i}(t) + \rho_{x,i}(t)) \downarrow 0} \dot{e}_{x,i}(t) < \mu_{x,i}(p_{x,i}-q_{x,i})e^{-\mu_{x,i}t} \implies \lim_{(e_{x,i}(t) + \rho_{x,i}(t)) \downarrow 0} \dot{e}_{x,i}(t) < \mu_{x,i}(p_{x,i}-q_{x,i}) \\
    &\implies \lim_{(e_{x,i}(t) + \rho_{x,i}(t)) \uparrow 0} \dot{x}_{i}(t) < \mu_{x,i}(p_{x,i}-q_{x,i}) + \dot{x}_{ref}(t) \implies \lim_{(e_{x,i}(t) + \rho_{x,i}(t)) \uparrow 0} \dot{x}_{i}(t) < \mu_{x,i}(p_{x,i}-q_{x,i}) + \overline{v}_{r,i}.
\end{align*}
Therefore, there exists $i \in [1;n]$, such that
\begin{gather}\label{eqn:dx_b2}
    \lim_{(e_{x,i}(t) - \rho_{x,i}(t)) \uparrow 0} \dot{x}_{i}(t) < \mu_{x,i}(p_{x,i}-q_{x,i}) + \overline{v}_{r,i}.
\end{gather}

Now, let us look at the reference velocity vector $v_r(t) = [v_{r,1}(t), \ldots, v_{r,n}(t)]^\top$, for all $i \in [1;n]$
\begin{align*}
    \lim_{(e_{x,i}(t)+\rho_{x,i}(t)) \downarrow 0} \varepsilon_{x,i}(t) = -1
    \implies \lim_{(e_{x,i}(t)+\rho_{x,i}(t)) \downarrow 0} v_{r,i}(t) = \overline{v}_i.
\end{align*}
Given the velocity-level system dynamics \eqref{eqn:sysDyn_vel} and feasibility constraint \eqref{eqn:feas2}
\begin{align}\label{eqn:dx_b2c}
    \lim_{(e_{x,i}(t)+\rho_{x,i}(t)) \downarrow 0} \dot{x}_{i}(t) = \overline{v}_i \geq \mu_{x,i}(p_{x,i}-q_{x,i}) 
    \implies \lim_{(e_{x,i}(t)+\rho_{x,i}(t)) \downarrow 0} \dot{x}_{i}(t) \geq \mu_{x,i}(p_{x,i}-q_{x,i}) + \overline{v}_{r,i}.
\end{align}
Thus, \eqref{eqn:dx_b2} contradicts \eqref{eqn:dx_b2c}. Hence, $e_{x,i}(t) \nrightarrow -\rho_{x,i}(t), \forall (t,i) \in [0,\tx) \times [1;n]$, i.e., the state error $e_x(t)$ never approaches the lower tube constraint over $t \in [0,\tx)$ in any dimension.

Thus, over $t \in [0, \tx])$, $e_{x,i}(t)$ never approaches the tube constraints $-\rho_{x,i}(t)$ and $\rho_{x,i}(t)$ for all $i \in [1;n]$.
Consequently, due to the continuity of $e_x(t)$, it can be concluded that there is no $\tx$ at which $e_{x,i}(t)$ violates the tube constraints $-\rho_{x,i}(t)$ and $\rho_{x,i}(t)$ for all $i \in [1;n]$.
Therefore, given a reference velocity vector \eqref{eqn:velcon},
\begin{gather*}
    -\rho_{x,i}(t) < e_{x,i}(t) < \rho_{x,i}(t), \forall (t,i) \in \R^+_0 \times [1;n].
\end{gather*}

\textbf{Stage II.} In stage II, we prove that the control law $\tau(t)$ in \eqref{eqn:con} enforces the velocity error $e_v(t)$ to remain in the funnel $[-\rho_v(t), \rho_v(t)]$ for all time $t \in \R_0^+$ \eqref{eqn:fun2}. 

    We will prove this via contradiction. Let $\tx$ be the first time instance when the velocity error $e_v(t)$, on the application of input $\tau(t)$ \eqref{eqn:con}, violates \eqref{eqn:fun2}, 
    $$\exists i \in [1;n], e_{v,i}(\tx) \leq -\rho_{v,i}(\tx) \text{ or } e_{v,i}(\tx) \geq \rho_{v,i}(\tx).$$
Then,
\begin{gather}\label{Eq:inqe_tv}
    -\rho_{v,i}(t) < e_{v,i}(t) < \rho_{v,i}(t), \forall (t,i) \in [0, \tx) \times [1;n].
\end{gather}
We will consider the following two cases for $t \in [0,\tx)$.

