\textbf{Case I.} There exists $i \in [1;n]$ such that$e_{v,i}(t)$ approaches the upper funnel constraint (Figure \ref{fig:case1}), i.e., $e_{v,i}(t) \rightarrow \rho_{v,i}(t) \implies e_{v,i}(t) - \rho_{v,i}(t) \rightarrow 0$. Following \eqref{Eq:inqe_tv}, we have the following implications:
\begin{align*}
    &e_{v,i}(t) < \rho_{v,i}(t) \implies (e_{v,i}(t) - \rho_{v,i}(t)) \uparrow 0 \\
    &\implies \lim_{(e_{v,i}(t) - \rho_{v,i}(t)) \uparrow 0} \frac{d}{dt} (e_{v,i}(t) - \rho_{v,i}(t)) > 0 \implies \lim_{(e_{v,i}(t) - \rho_{v,i}(t)) \uparrow 0} \dot{e}_{v,i}(t) > \lim_{(e_{v,i}(t) - \rho_{v,i}(t)) \uparrow 0} \dot{\rho}_{v,i}(t) \\
    &\implies \lim_{(e_{v,i}(t) - \rho_{v,i}(t)) \uparrow 0} \dot{e}_{v,i}(t) > -\mu_{v,i}(p_{v,i}-q_{v,i})e^{-\mu_{v,i}t} \implies \lim_{(e_{v,i}(t) - \rho_{v,i}(t)) \uparrow 0} \dot{e}_{v,i}(t) > -\mu_{v,i}(p_{v,i}-q_{v,i}) \\
    &\implies \lim_{(e_{v,i}(t) - \rho_{v,i}(t)) \uparrow 0} \dot{v}_{i}(t) > -\mu_{v,i}(p_{v,i}-q_{v,i}) + \dot{v}_r(t) \implies \lim_{(e_{v,i}(t) - \rho_{v,i}(t)) \uparrow 0} \dot{v}_{i}(t) > -\mu_{v,i}(p_{v,i}-q_{v,i}) - \overline{a}_{r,i}.
\end{align*}
Therefore, there exists $i \in [1;n]$, such that 
\begin{gather}\label{eqn:dv_b1}
    \lim_{(e_{v,i}(t) - \rho_{v,i}(t)) \uparrow 0} \dot{v}_{i}(t) > -\mu_{v,i}(p_{v,i}-q_{v,i}) - \overline{a}_{r,i}.
\end{gather}

Now, let us look at the control input vector $\tau(t) = [\tau_{1}(t), \ldots, \tau_{n}(t)]^\top$, for all $i \in [1;n]$
\begin{align*}
    \lim_{(e_{v,i}(t) - \rho_{v,i}(t)) \uparrow 0} \varepsilon_{v,i}(t) = 1
    \implies \lim_{(e_{v,i}(t) - \rho_{v,i}(t)) \uparrow 0} \tau_{i}(t) = -\overline{\tau}_{i}.
\end{align*}
Given the acceleration-level system dynamics \eqref{eqn:sysDyn_acc} and feasibility constraint \eqref{eqn:feas2}
\begin{align}\label{eqn:dv_b1c}
    \lim_{(e_{v,i}(t) - \rho_{v,i}(t)) \uparrow 0} \dot{v}_{i}(t) \leq \overline{V}_{M,i} - \underline{m} \overline{\tau}_i + \underline{m}_i\overline{d}_i
    \implies \lim_{(e_{v,i}(t) - \rho_{v,i}(t)) \uparrow 0} \dot{v}_{i}(t) \leq -\mu_{v,i}(p_{v,i}-q_{v,i}) - \overline{a}_{r,i}.
\end{align}
Thus, \eqref{eqn:dv_b1} contradicts \eqref{eqn:dv_b1c}. Hence, $e_{v,i}(t) \nrightarrow \rho_{v,i}(t), \forall (t,i) \in [0,\tx) \times [1;n]$, i.e., the velocity error $e_v(t)$ never approaches the upper tube constraint over $t \in [0,\tx)$ in any dimension.

