\textbf{Case II.} There exists $i \in [1;n]$ such that $e_{v,i}(t)$ approaches the lower tube constraint (Figure \ref{fig:case2}), i.e., $e_{v,i}(t) \rightarrow -\rho_{v,i}(t) \implies e_{v,i}(t)+\rho_{v,i}(t) \rightarrow 0$. Following \eqref{Eq:inqe_tx}, we have the following implications:
\begin{align*}
    &e_{v,i}(t) > -\rho_{v,i}(t) \implies (e_{v,i}(t)+\rho_{v,i}(t)) \downarrow 0 \\
    &\implies \lim_{(e_{v,i}(t)+\rho_{v,i}(t)) \downarrow 0} \frac{d}{dt} (e_{v,i}(t)+\rho_{v,i}(t)) < 0 \implies \lim_{(e_{v,i}(t)+\rho_{v,i}(t)) \downarrow 0} \dot{e}_{v,i}(t) < \lim_{(e_{v,i}(t)+\rho_{v,i}(t)) \downarrow 0} -\dot{\rho}_{v,i}(t) \\
    &\implies \lim_{(e_{v,i}(t) + \rho_{v,i}(t)) \downarrow 0} \dot{e}_{v,i}(t) < \mu_{v,i}(p_{v,i}-q_{v,i})e^{-\mu_{v,i}t} \implies \lim_{(e_{v,i}(t) + \rho_{v,i}(t)) \downarrow 0} \dot{e}_{v,i}(t) < \mu_{v,i}(p_{v,i}-q_{v,i}) \\
    &\implies \lim_{(e_{v,i}(t) + \rho_{v,i}(t)) \uparrow 0} \dot{v}_{i}(t) < \mu_{v,i}(p_{v,i}-q_{v,i}) + \dot{v}_r(t) \implies \lim_{(e_{v,i}(t) + \rho_{v,i}(t)) \uparrow 0} \dot{v}_{i}(t) < \mu_{v,i}(p_{v,i}-q_{v,i}) + \overline{a}_{r,i}.
\end{align*}
Therefore, there exists $i \in [1;n]$, such that
\begin{gather}\label{eqn:dv_b2}
    \lim_{(e_{v,i}(t) + \rho_{v,i}(t)) \uparrow 0} \dot{v}_{i}(t) < \mu_{v,i}(p_{v,i}-q_{v,i}) + \overline{a}_{r,i}.
\end{gather}

Now, let us look at the control input vector $\tau(t) = [\tau_{1}(t), \ldots, \tau_{n}(t)]^\top$, for all $i \in [1;n]$
\begin{align*}
    \lim_{(e_{v,i}(t)+\rho_{v,i}(t)) \downarrow 0} \varepsilon_{v,i}(t) = -1
    \implies \lim_{(e_{v,i}(t)+\rho_{v,i}(t)) \downarrow 0} \tau_{i}(t) = \overline{\tau}_i.
\end{align*}
Given the acceleration-level system dynamics \eqref{eqn:sysDyn_acc} and feasibility constraint \eqref{eqn:feas2}
\begin{align}\label{eqn:dv_b2c}
    \lim_{(e_{v,i}(t)+\rho_{v,i}(t)) \downarrow 0} \dot{v}_{i}(t) \geq \underline{V}_{M,i} + \underline{m} \overline{\tau}_i - \underline{m}_i\overline{d}_i
    \implies \lim_{(e_{v,i}(t)+\rho_{v,i}(t)) \downarrow 0} \dot{v}_{i}(t) \geq \mu_{v,i}(p_{v,i}-q_{v,i}) + \overline{a}_{r,i}.
\end{align}
Thus, \eqref{eqn:dv_b2} contradicts \eqref{eqn:dv_b2c}. Hence, $e_{v,i}(t) \nrightarrow -\rho_{v,i}(t), \forall (t,i) \in [0,\tx) \times [1;n]$, i.e., the velocity error $e_v(t)$ never approaches the lower tube constraint over $t \in [0,\tx)$ in any dimension.

Thus, over $t \in [0, \tx])$, $e_{v,i}(t)$ never approaches the tube constraints $-\rho_{v,i}(t)$ and $\rho_{v,i}(t)$ for all $i \in [1;n]$.
Consequently, due to the continuity of $e_v(t)$, it can be concluded that there is no $\tx$ at which $e_{v,i}(t)$ violates the tube constraints $-\rho_{v,i}(t)$ and $\rho_{v,i}(t)$ for all $i \in [1;n]$.
Therefore, given input \eqref{eqn:con},
\begin{gather*}
    -\rho_{v,i}(t) < e_{v,i}(t) < \rho_{v,i}(t), \forall (t,i) \in \R^+_0 \times [1;n].
\end{gather*}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%55

Hence, the bounded control input $\tau(t)$ in \eqref{eqn:con}, under feasibility conditions \eqref{eqn:feas1} and \eqref{eqn:feas2}, ensures the tracking of the reference trajectory $x_{ref}(t)$.
\end{proof}

\begin{remark}
    It is important to note that the assumptions \ref{assum_d} - \ref{assum_Md} on system dynamics, with known bounds, are strictly used for deriving feasibility conditions in equations \eqref{eqn:feas1} and \eqref{eqn:feas2}. These assumptions are not required for the design or implementation of the control law itself, as Equation \eqref{eqn:con} operates independently of the system dynamics.
\end{remark}

\begin{remark}
{Theorem \ref{thm:bdcontrol} implies that the feasibility conditions in \eqref{eqn:feas1} and \eqref{eqn:feas2}, derived from bounds on system dynamics, ensure that the tracking error remains within the funnel boundaries and satisfy the prescribed performance constraints. This is guaranteed using the input-constrained, closed-form, approximation-free control law in Equation \eqref{eqn:con}.
\\
However, these feasibility conditions are conservative and even if they are violated, the tracking error might still stay within the funnel. In the case the error exits the funnel, the system responds based on the chosen bounded transformation function for the control law. Specifically, the error will either aggressively attempt to re-enter the funnel at full throttle, or the system will halt entirely, preventing any further deviations or unforeseen actions.}
\end{remark}

\section{Simulation and Experimental Results}\label{sec:sim}

This section demonstrates the efficacy of the proposed results for tracking a reference trajectory under input constraints using three case studies: $(i)$ a two-link SCARA manipulator, $(ii)$ a 7-DOF FRANKA robot, and $(iii)$ an omnidirectional mobile robot. We also compare the two bounded transformation functions in Section \ref{sec:clamp} and evaluate the algorithm’s performance against state-of-the-art methods.

